        l = float(c.get("low"))
        cl = float(c.get("close"))
        denom = (h - l)
        bop = 0.0 if denom == 0 else (cl - o) / denom
        as_of_time = c.get("close_time") or c.get("open_time")

        fin = _utcnow()
        job["status"] = "succeeded"
