            "job_id": job["id"],
            "result_kind": "series",
            "as_of_time": as_of_time,
            "value": bop,
            "signal": None,
            "series": [{"t": as_of_time, "v": bop}],
            "multi_series": None,
            "metadata": {"limit": limit},
            "expires_at": expires_at,
            "created_at": _isoz(fin),
            "updated_at": _isoz(fin),
        }
        for i, rr in enumerate(results):
            if isinstance(rr, dict) and rr.get("job_id") == job["id"]:
                results[i] = result_row
                break
        else:
            results.append(result_row)
        _save_doc("computation_results.json", results_doc, results)

        _log("ok")
        return {"tool_name": endpoint, "cache_hit": False, "job": job, "result": result_row}
    except Exception as e:
        _log("error", "CONFLICT")
        return _err("CONFLICT", "Unexpected server error.", details=str(e), tool_name=endpoint)

def calculate_chande_forecast_oscillator(symbol, interval=None, limit=None, length=None, **_extra):
    import json, os, datetime, time, math, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0416000" if __import__("os").path.isdir("./environment_mix/0416000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    intervals = ["1m","3m","5m","15m","30m","1h","2h","4h","6h","8h","12h","1d","3d","1w","1M"]

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        return dt.replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        return f"{prefix}_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{os.urandom(6).hex()}"

    def _find_indicator(tool):
        defs = _load("indicator_definitions.json")
        for d in defs:
            if d.get("tool_name") == tool:
                return d
        return None

    def _resolve_pair(sym):
        pairs = _load("trading_pairs.json")
        candidates = [p for p in pairs if p.get("exchange") == "binance" and p.get("symbol") == sym]
        if not candidates:
            return None
        for st in ("active","disabled","delisted"):
            for p in candidates:
                if p.get("status") == st:
                    return p
        return candidates[0]

    def _load_candles(pair_id, interval_v):
        cs = _load("ohlcv_candles.json")
        out = []
        for c in cs:
            if c.get("pair_id") == pair_id and c.get("interval") == interval_v:
                dt = _parse_dt(c.get("open_time"))
                if dt is not None:
                    out.append((dt, c))
        out.sort(key=lambda x: x[0])
        return [c for _, c in out]

    def _record_failed(ind_def, pair, interval_v, candle_limit, fp, code, msg):
        jobs = _load("computation_jobs.json")
        job = {
            "id": _gen_id("job"),
            "indicator_id": ind_def["id"],
            "pair_id": pair["id"],
            "interval": interval_v,
            "candle_limit": candle_limit,
            "input_start_time": None,
            "input_end_time": None,
            "request_fingerprint": fp,
            "cache_hit": False,
            "status": "failed",
            "queued_at": now,
            "started_at": now,
            "finished_at": now,
            "error_code": code,
            "error_message": msg,
            "binance_request_count": 0,
            "compute_time_ms": None,
            "created_at": now,
            "updated_at": now
        }
        jobs.append(job)
        _save("computation_jobs.json", jobs)
        return job

    # validate
    if not isinstance(symbol, str) or symbol.strip() == "":
        return _err("VALIDATION_ERROR", "symbol must be a non-empty string")
    symbol = symbol.strip()

    tool_name = "calculate_chande_forecast_oscillator"
    ind = _find_indicator(tool_name)
    if not ind:
        return _err("NOT_FOUND", "indicator definition not found for tool", tool_name=tool_name)
    if not isinstance(ind.get("is_enabled"), bool) or not ind["is_enabled"] or ind.get("status") not in ("active","deprecated"):
        return _err("UNAUTHORIZED", "tool is not enabled", tool_name=tool_name)

    interval_v = interval if interval is not None else ind.get("default_interval")
    if interval_v not in intervals:
        return _err("VALIDATION_ERROR", "interval is not supported", interval=interval_v)

    limit_v = ind.get("default_limit") if limit is None else limit
    if not isinstance(limit_v, int) or limit_v <= 0:
        return _err("VALIDATION_ERROR", "limit must be a positive integer", limit=limit)

    length_v = 9 if length is None else length
    if not isinstance(length_v, int) or length_v <= 0:
        return _err("VALIDATION_ERROR", "length must be a positive integer", length=length)

    pair = _resolve_pair(symbol)
    if not pair:
        return _err("NOT_FOUND", "symbol not found on binance", symbol=symbol)

    norm = {"tool": tool_name, "pair_id": pair["id"], "interval": interval_v, "limit": limit_v, "length": length_v}
    fp = hashlib.sha256(json.dumps(norm, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()

    if pair.get("status") != "active":
        job = _record_failed(ind, pair, interval_v, limit_v, fp, "PAIR_DISABLED", "trading pair is not active")
        return {"job": job, "result": None}

    jobs = _load("computation_jobs.json")
    results = _load("computation_results.json")

    def _find_cached():
        for j in jobs:
            if j.get("request_fingerprint") == fp and j.get("status") == "succeeded" and j.get("finished_at") is not None:
                for r in results:
                    if r.get("job_id") == j.get("id"):
                        exp = _parse_dt(r.get("expires_at"))
                        if exp is None or exp >= datetime.datetime.utcnow():
                            return j, r
        return None, None

    cj, cr = _find_cached()
    if cj and cr:
        # record cache hit job
        jobs2 = _load("computation_jobs.json")
        job = {
            "id": _gen_id("job"),
            "indicator_id": ind["id"],
            "pair_id": pair["id"],
            "interval": interval_v,
            "candle_limit": limit_v,
            "input_start_time": None,
            "input_end_time": None,
            "request_fingerprint": fp,
            "cache_hit": True,
            "status": "succeeded",
            "queued_at": now,
            "started_at": now,
            "finished_at": now,
            "error_code": None,
            "error_message": None,
            "binance_request_count": 0,
            "compute_time_ms": 0,
            "created_at": now,
            "updated_at": now
        }
        jobs2.append(job)
        _save("computation_jobs.json", jobs2)
        return {"job": job, "result": cr, "metadata": {**norm, "cache_hit": True, "latency_ms": int((time.time()-t0)*1000)}}

    candles = _load_candles(pair["id"], interval_v)
    window = candles[-limit_v:] if limit_v <= len(candles) else candles[:]
    if len(window) < int(ind.get("min_lookback_candles", 1)) or len(window) < length_v:
        job = _record_failed(ind, pair, interval_v, limit_v, fp, "INSUFFICIENT_DATA", "not enough candles for requested length")
        return {"job": job, "result": None}

    look = window[-length_v:]
    closes = []
    for c in look:
        v = c.get("close")
        if not isinstance(v, (int, float)) or not math.isfinite(float(v)) or float(v) <= 0:
            return _err("VALIDATION_ERROR", "invalid candle close value in datastore")
        closes.append(float(v))

    # CFO: based on linear regression forecast of next (or current) value; common form:
    # CFO = 100 * (close - forecast) / close, where forecast is regression value at last point.
    n = length_v
    xs = list(range(n))
    x_mean = sum(xs) / float(n)
    y_mean = sum(closes) / float(n)
    num = sum((xs[i] - x_mean) * (closes[i] - y_mean) for i in range(n))
    den = sum((xs[i] - x_mean) ** 2 for i in range(n))
    slope = 0.0 if den == 0 else (num / den)
    intercept = y_mean - slope * x_mean
    forecast = intercept + slope * (n - 1)  # fitted value at last index
    last_close = closes[-1]
    cfo = 0.0 if last_close == 0 else 100.0 * (last_close - forecast) / last_close

    last_dt = _parse_dt(window[-1].get("close_time")) or _parse_dt(window[-1].get("open_time"))
    ttl = int(ind.get("cache_ttl_seconds", 0))
    expires_at = None
    if ttl > 0:
        expires_at = _iso(datetime.datetime.utcnow() + datetime.timedelta(seconds=ttl))

    job_id = _gen_id("job")
    job = {
        "id": job_id,
        "indicator_id": ind["id"],
        "pair_id": pair["id"],
        "interval": interval_v,
        "candle_limit": limit_v,
        "input_start_time": None,
        "input_end_time": None,
        "request_fingerprint": fp,
        "cache_hit": False,
        "status": "succeeded",
        "queued_at": now,
        "started_at": now,
        "finished_at": now,
        "error_code": None,
        "error_message": None,
        "binance_request_count": 0,
        "compute_time_ms": None,
        "created_at": now,
        "updated_at": now
    }
    result = {
        "id": _gen_id("res"),
        "job_id": job_id,
        "result_kind": "series",
        "as_of_time": _iso(last_dt) if last_dt else now,
        "value": float(cfo),
        "signal": None,
        "series": None,
        "multi_series": None,
        "metadata": {"indicator": "CFO", "length": length_v},
        "expires_at": expires_at,
        "created_at": now,
        "updated_at": now
    }

    # uniqueness on succeeded fingerprint
    for j in jobs:
        if j.get("status") == "succeeded" and j.get("finished_at") is not None and j.get("request_fingerprint") == fp:
            cj2, cr2 = _find_cached()
            if cj2 and cr2:
                jobs2 = _load("computation_jobs.json")
                job2 = {
                    "id": _gen_id("job"),
                    "indicator_id": ind["id"],
                    "pair_id": pair["id"],
                    "interval": interval_v,
                    "candle_limit": limit_v,
                    "input_start_time": None,
                    "input_end_time": None,
                    "request_fingerprint": fp,
                    "cache_hit": True,
                    "status": "succeeded",
                    "queued_at": now,
                    "started_at": now,
                    "finished_at": now,
                    "error_code": None,
                    "error_message": None,
                    "binance_request_count": 0,
                    "compute_time_ms": 0,
                    "created_at": now,
                    "updated_at": now
                }
                jobs2.append(job2)
                _save("computation_jobs.json", jobs2)
                return {"job": job2, "result": cr2, "metadata": {**norm, "cache_hit": True, "latency_ms": int((time.time()-t0)*1000)}}
            break

    jobs.append(job)
    results.append(result)
    _save("computation_jobs.json", jobs)
    _save("computation_results.json", results)

    return {"job": job, "result": result, "metadata": {**norm, "cache_hit": False, "latency_ms": int((time.time()-t0)*1000)}}

def calculate_commodity_channel_index(symbol, interval=None, limit=None, length=None, c=None, **_extra):
    import json, os, datetime, time, hashlib, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0416000" if __import__("os").path.isdir("./environment_mix/0416000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "calculate_commodity_channel_index"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v
        if not isinstance(v, str):
            return None
        s = v.strip()
        if s.endswith("Z"):
            s = s[:-1]
        try:
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _audit(status, credential_id=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + hashlib.sha256((endpoint + "|" + _now_iso() + "|" + str(len(logs))).encode("utf-8")).hexdigest()[:24],
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso()
        }
        if isinstance(meta, dict) and meta:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    # Resolve indicator definition (ambient auth)
    defs = _load("indicator_definitions.json")
    if not isinstance(defs, list):
        _audit("error")
        return _err("UNAUTHORIZED", "No enabled indicator definitions available.")
    idef = None
    for d in defs:
        if isinstance(d, dict) and d.get("tool_name") == endpoint:
            if d.get("is_enabled") is True and d.get("status") in ("active", "deprecated"):
                idef = d
            break
    if idef is None:
        _audit("error")
        return _err("UNAUTHORIZED", "Tool is not enabled or not available.")

    allowed_intervals = ["1m","3m","5m","15m","30m","1h","2h","4h","6h","8h","12h","1d","3d","1w","1M"]

    # Validate inputs
    if not isinstance(symbol, str) or not symbol.strip():
        _audit("error")
        return _err("VALIDATION_ERROR", "symbol must be a non-empty string.")
    symbol = symbol.strip().upper()

    if interval is None:
        interval = idef.get("default_interval")
    if interval not in allowed_intervals:
        _audit("error")
        return _err("VALIDATION_ERROR", "interval is not supported.", allowed=allowed_intervals)

    if limit is None:
        limit = idef.get("default_limit")
    if not isinstance(limit, int) or limit <= 0:
        _audit("error")
        return _err("VALIDATION_ERROR", "limit must be a positive integer.")

    if length is None:
        length = 20
    if not isinstance(length, int) or length <= 0:
        _audit("error")
        return _err("VALIDATION_ERROR", "length must be a positive integer.")

    if c is None:
        c = 0.015
    if not isinstance(c, (int, float)) or not math.isfinite(float(c)) or float(c) <= 0:
        _audit("error")
        return _err("VALIDATION_ERROR", "c must be a positive finite number.")

    min_lb = idef.get("min_lookback_candles")
    if not isinstance(min_lb, int) or min_lb < 1:
        min_lb = 1
    required_candles = max(min_lb, length)

    if limit < required_candles:
        _audit("error")
        return _err("VALIDATION_ERROR", "limit is too small for this computation.", required_candles=required_candles)

    # Resolve trading pair
    pairs = _load("trading_pairs.json")
    if not isinstance(pairs, list):
        _audit("error")
        return _err("NOT_FOUND", "Trading pair not found.")
    pair = None
    for p in pairs:
        if isinstance(p, dict) and p.get("exchange") == "binance" and str(p.get("symbol", "")).upper() == symbol:
            pair = p
            break
    if pair is None:
        _audit("error")
        return _err("NOT_FOUND", "Trading pair not found.", symbol=symbol, exchange="binance")
    if pair.get("status") != "active":
        _audit("error")
        return _err("INVALID_TRANSITION", "Trading pair is not active for new computations.", error_code="PAIR_DISABLED")

    pair_id = pair.get("id")
    if not isinstance(pair_id, str) or not pair_id:
        _audit("error")
        return _err("NOT_FOUND", "Trading pair not found.")

    # Select candles
    candles = _load("ohlcv_candles.json")
    if not isinstance(candles, list):
        candles = []
    scoped = []
    for r in candles:
        if not isinstance(r, dict):
            continue
        if r.get("pair_id") == pair_id and r.get("interval") == interval:
            ot = _parse_dt(r.get("open_time"))
            if ot is None:
                continue
            scoped.append((ot, r))
    scoped.sort(key=lambda x: x[0])
    if len(scoped) < required_candles:
        # Create failed job record
        jobs = _load("computation_jobs.json")
        if not isinstance(jobs, list):
            jobs = []
        now = _now_iso()
        norm = {
            "tool": endpoint,
            "indicator_id": idef.get("id"),
            "pair_id": pair_id,
            "interval": interval,
            "limit": int(limit),
            "params": {"length": int(length), "c": float(c)}
        }
        fp = hashlib.sha256(json.dumps(norm, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()
        job_id = "job_" + hashlib.sha256((fp + "|" + now).encode("utf-8")).hexdigest()[:24]
        job = {
            "id": job_id,
            "indicator_id": idef.get("id"),
            "pair_id": pair_id,
            "interval": interval,
            "candle_limit": int(limit),
            "input_start_time": None,
            "input_end_time": None,
            "request_fingerprint": fp,
            "cache_hit": False,
            "status": "failed",
            "queued_at": now,
            "started_at": now,
            "finished_at": now,
            "error_code": "INSUFFICIENT_DATA",
            "error_message": "Not enough candles to compute indicator.",
            "binance_request_count": 0,
            "compute_time_ms": 0,
            "created_at": now,
            "updated_at": now
        }
        jobs.append(job)
        _save("computation_jobs.json", jobs)
        _audit("error", meta={"error_code": "INSUFFICIENT_DATA"})
        return _err("CONFLICT", "Insufficient data to compute indicator.", error_code="INSUFFICIENT_DATA", required_candles=required_candles, available_candles=len(scoped))

    # Take last `limit` candles from scoped
    use = scoped[-int(limit):]
    # Must still satisfy required window for computation
    if len(use) < required_candles:
        _audit("error", meta={"error_code": "INSUFFICIENT_DATA"})
        return _err("CONFLICT", "Insufficient data to compute indicator.", error_code="INSUFFICIENT_DATA", required_candles=required_candles, available_candles=len(use))

    # Build fingerprint for caching
    norm = {
        "tool": endpoint,
        "indicator_id": idef.get("id"),
        "pair_id": pair_id,
        "interval": interval,
        "limit": int(limit),
        "params": {"length": int(length), "c": float(c)}
    }
    fp = hashlib.sha256(json.dumps(norm, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()

    jobs = _load("computation_jobs.json")
    if not isinstance(jobs, list):
        jobs = []
    results = _load("computation_results.json")
    if not isinstance(results, list):
        results = []

    # Cache check: succeeded job with same fingerprint, non-expired result
    cached_job = None
    cached_res = None
    now_dt = datetime.datetime.utcnow()
    for j in jobs:
        if not isinstance(j, dict):
            continue
        if j.get("request_fingerprint") == fp and j.get("status") == "succeeded" and j.get("finished_at") is not None:
            jid = j.get("id")
            if not jid:
                continue
            r = next((x for x in results if isinstance(x, dict) and x.get("job_id") == jid), None)
            if not r:
                continue
            exp = _parse_dt(r.get("expires_at"))
            if exp is None or exp >= now_dt:
                cached_job = j
                cached_res = r
                break

    if cached_job and cached_res:
        _audit("ok", meta={"cache_hit": True})
        return {
            "job": cached_job,
            "result": cached_res
        }

    # Create job (queued->running->succeeded)
    now = _now_iso()
    job_id = "job_" + hashlib.sha256((fp + "|" + now).encode("utf-8")).hexdigest()[:24]
    job = {
        "id": job_id,
        "indicator_id": idef.get("id"),
        "pair_id": pair_id,
        "interval": interval,
        "candle_limit": int(limit),
        "input_start_time": None,
        "input_end_time": None,
        "request_fingerprint": fp,
        "cache_hit": False,
        "status": "queued",
        "queued_at": now,
        "started_at": None,
        "finished_at": None,
        "error_code": None,
        "error_message": None,
        "binance_request_count": 0,
        "compute_time_ms": None,
        "created_at": now,
        "updated_at": now
    }
    jobs.append(job)

    # Transition queued -> running
    job["status"] = "running"
    job["started_at"] = _now_iso()
    job["updated_at"] = job["started_at"]

    # Compute CCI
    compute_start = time.time()
    points = []
    for ot, r in use:
        h = r.get("high"); l = r.get("low"); cl = r.get("close")
        if not isinstance(h, (int, float)) or not isinstance(l, (int, float)) or not isinstance(cl, (int, float)):
            continue
        tp = (float(h) + float(l) + float(cl)) / 3.0
        points.append({"t": ot, "tp": tp})
    if len(points) < required_candles:
        # Fail job
        fin = _now_iso()
        job["status"] = "failed"
        job["finished_at"] = fin
        job["updated_at"] = fin
        job["error_code"] = "INSUFFICIENT_DATA"
        job["error_message"] = "Not enough valid candles to compute indicator."
        job["binance_request_count"] = 0
        job["compute_time_ms"] = int((time.time() - compute_start) * 1000)
        _save("computation_jobs.json", jobs)
        _audit("error", meta={"error_code": "INSUFFICIENT_DATA"})
        return _err("CONFLICT", "Insufficient data to compute indicator.", error_code="INSUFFICIENT_DATA", required_candles=required_candles, available_candles=len(points))

    tps = [p["tp"] for p in points]
    # last length window
    win = tps[-length:]
    sma = sum(win) / float(length)
    md = sum(abs(x - sma) for x in win) / float(length)
    if md == 0:
        cci = 0.0
    else:
        cci = (win[-1] - sma) / (float(c) * md)

    compute_ms = int((time.time() - compute_start) * 1000)
    as_of = points[-1]["t"].replace(microsecond=0).isoformat() + "Z"

    # Succeed job
    fin = _now_iso()
    job["status"] = "succeeded"
    job["finished_at"] = fin
    job["updated_at"] = fin
    job["error_code"] = None
    job["error_message"] = None
    job["compute_time_ms"] = compute_ms

    # Persist result
    ttl = idef.get("cache_ttl_seconds")
    exp_iso = None
    if isinstance(ttl, int) and ttl > 0:
