        _audit("error")
        return _err("NOT_FOUND", "Trading pair not found.")
    pair = None
    for p in pairs:
        if isinstance(p, dict) and p.get("exchange") == "binance" and str(p.get("symbol", "")).upper() == symbol:
            pair = p
            break
