            "binance_request_count": 0,
            "compute_time_ms": 0,
            "created_at": now,
            "updated_at": now
        }
        jobs.append(job)
        _save("computation_jobs.json", jobs)
        _audit("error", meta={"error_code": "INSUFFICIENT_DATA"})
        return _err("CONFLICT", "Insufficient data to compute indicator.", error_code="INSUFFICIENT_DATA", required_candles=required_candles, available_candles=len(scoped))

    use = scoped[-int(limit):]
    if len(use) < required_candles:
        _audit("error", meta={"error_code": "INSUFFICIENT_DATA"})
        return _err("CONFLICT", "Insufficient data to compute indicator.", error_code="INSUFFICIENT_DATA", required_candles=required_candles, available_candles=len(use))

    norm = {"tool": endpoint, "indicator_id": idef.get("id"), "pair_id": pair_id, "interval": interval, "limit": int(limit), "params": {"length": int(length)}}
    fp = hashlib.sha256(json.dumps(norm, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()

    jobs = _load("computation_jobs.json")
    if not isinstance(jobs, list):
        jobs = []
    results = _load("computation_results.json")
    if not isinstance(results, list):
        results = []

    cached_job = None
    cached_res = None
    now_dt = datetime.datetime.utcnow()
    for j in jobs:
        if not isinstance(j, dict):
            continue
        if j.get("request_fingerprint") == fp and j.get("status") == "succeeded" and j.get("finished_at") is not None:
            jid = j.get("id")
            r = next((x for x in results if isinstance(x, dict) and x.get("job_id") == jid), None)
            if not r:
                continue
            exp = _parse_dt(r.get("expires_at"))
            if exp is None or exp >= now_dt:
                cached_job = j
                cached_res = r
                break
    if cached_job and cached_res:
        _audit("ok", meta={"cache_hit": True})
        return {"job": cached_job, "result": cached_res}

    now = _now_iso()
    job_id = "job_" + hashlib.sha256((fp + "|" + now).encode("utf-8")).hexdigest()[:24]
    job = {
        "id": job_id,
        "indicator_id": idef.get("id"),
        "pair_id": pair_id,
        "interval": interval,
        "candle_limit": int(limit),
        "input_start_time": None,
        "input_end_time": None,
        "request_fingerprint": fp,
        "cache_hit": False,
        "status": "queued",
        "queued_at": now,
        "started_at": None,
        "finished_at": None,
        "error_code": None,
        "error_message": None,
        "binance_request_count": 0,
        "compute_time_ms": None,
        "created_at": now,
        "updated_at": now
    }
    jobs.append(job)

    job["status"] = "running"
    job["started_at"] = _now_iso()
    job["updated_at"] = job["started_at"]

    compute_start = time.time()

    closes = []
    times = []
    for ot, r in use:
        cl = r.get("close")
        if isinstance(cl, (int, float)) and math.isfinite(float(cl)):
            closes.append(float(cl))
            times.append(ot)
    if len(closes) < required_candles:
        fin = _now_iso()
        job["status"] = "failed"
        job["finished_at"] = fin
        job["updated_at"] = fin
        job["error_code"] = "INSUFFICIENT_DATA"
        job["error_message"] = "Not enough valid candles to compute indicator."
        job["compute_time_ms"] = int((time.time() - compute_start) * 1000)
        _save("computation_jobs.json", jobs)
        _audit("error", meta={"error_code": "INSUFFICIENT_DATA"})
        return _err("CONFLICT", "Insufficient data to compute indicator.", error_code="INSUFFICIENT_DATA", required_candles=required_candles, available_candles=len(closes))

    alpha = 2.0 / (length + 1.0)

    def _ema(series):
        e = series[0]
        for x in series[1:]:
            e = alpha * x + (1.0 - alpha) * e
        return e

    # DEMA = 2*EMA(price) - EMA(EMA(price))
    # We compute last EMA over window, then build a synthetic EMA-series over the window for EMA(EMA)
    # by iterating the same EMA recurrence and collecting intermediate EMA values.
    ema_vals = []
    e = closes[0]
    ema_vals.append(e)
    for x in closes[1:]:
        e = alpha * x + (1.0 - alpha) * e
        ema_vals.append(e)

    ema1 = ema_vals[-1]
    ema2 = _ema(ema_vals)
    dema = 2.0 * ema1 - ema2

    compute_ms = int((time.time() - compute_start) * 1000)
    as_of = times[-1].replace(microsecond=0).isoformat() + "Z"

    fin = _now_iso()
    job["status"] = "succeeded"
    job["finished_at"] = fin
    job["updated_at"] = fin
    job["compute_time_ms"] = compute_ms

    ttl = idef.get("cache_ttl_seconds")
    exp_iso = None
    if isinstance(ttl, int) and ttl > 0:
        exp_dt = datetime.datetime.utcnow() + datetime.timedelta(seconds=ttl)
        exp_iso = exp_dt.replace(microsecond=0).isoformat() + "Z"

    res_id = "res_" + hashlib.sha256((job_id + "|result").encode("utf-8")).hexdigest()[:24]
    result = {
        "id": res_id,
        "job_id": job_id,
        "result_kind": "series",
        "as_of_time": as_of,
        "value": float(dema),
        "signal": None,
        "series": None,
        "multi_series": None,
        "metadata": {
            "symbol": symbol,
            "exchange": "binance",
            "interval": interval,
            "limit": int(limit),
            "length": int(length)
        },
        "expires_at": exp_iso,
        "created_at": fin,
        "updated_at": fin
    }

    results.append(result)
    _save("computation_jobs.json", jobs)
    _save("computation_results.json", results)
    _audit("ok", meta={"cache_hit": False})
    return {"job": job, "result": result}

