        "signal": None,
        "series": None,
        "multi_series": None,
        "metadata": {
            "symbol": symbol,
            "exchange": "binance",
            "interval": interval,
            "limit": int(limit),
            "length": int(length)
        },
        "expires_at": exp_iso,
        "created_at": fin,
        "updated_at": fin
    }

    results.append(result)
    _save("computation_jobs.json", jobs)
    _save("computation_results.json", results)
    _audit("ok", meta={"cache_hit": False})
    return {"job": job, "result": result}

def calculate_mass_index(symbol, interval=None, limit=None, length=None, ema_length=None, **_extra):
    import json, os, datetime, time, hashlib, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0416000" if __import__("os").path.isdir("./environment_mix/0416000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "calculate_mass_index"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v
        if not isinstance(v, str):
            return None
        s = v.strip()
        if s.endswith("Z"):
            s = s[:-1]
        try:
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _audit(status, credential_id=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + hashlib.sha256((endpoint + "|" + _now_iso() + "|" + str(len(logs))).encode("utf-8")).hexdigest()[:24],
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso()
        }
        if isinstance(meta, dict) and meta:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    defs = _load("indicator_definitions.json")
    if not isinstance(defs, list):
        _audit("error")
        return _err("UNAUTHORIZED", "No enabled indicator definitions available.")
    idef = None
    for d in defs:
        if isinstance(d, dict) and d.get("tool_name") == endpoint:
            if d.get("is_enabled") is True and d.get("status") in ("active", "deprecated"):
                idef = d
            break
    if idef is None:
        _audit("error")
        return _err("UNAUTHORIZED", "Tool is not enabled or not available.")

    allowed_intervals = ["1m","3m","5m","15m","30m","1h","2h","4h","6h","8h","12h","1d","3d","1w","1M"]

    if not isinstance(symbol, str) or not symbol.strip():
        _audit("error")
        return _err("VALIDATION_ERROR", "symbol must be a non-empty string.")
    symbol = symbol.strip().upper()

    if interval is None:
        interval = idef.get("default_interval")
    if interval not in allowed_intervals:
        _audit("error")
        return _err("VALIDATION_ERROR", "interval is not supported.", allowed=allowed_intervals)

    if limit is None:
        limit = idef.get("default_limit")
    if not isinstance(limit, int) or limit <= 0:
        _audit("error")
        return _err("VALIDATION_ERROR", "limit must be a positive integer.")

    if length is None:
        length = 25
    if not isinstance(length, int) or length <= 0:
        _audit("error")
        return _err("VALIDATION_ERROR", "length must be a positive integer.")

    if ema_length is None:
        ema_length = 9
    if not isinstance(ema_length, int) or ema_length <= 0:
        _audit("error")
        return _err("VALIDATION_ERROR", "ema_length must be a positive integer.")

    min_lb = idef.get("min_lookback_candles")
    if not isinstance(min_lb, int) or min_lb < 1:
        min_lb = 1

    # MI needs enough points to compute EMA(range, ema_length) and EMA(EMA(range), ema_length), then sum ratio over `length`.
    # Conservative requirement:
    required_candles = max(min_lb, length + 2 * ema_length)

    if limit < required_candles:
        _audit("error")
        return _err("VALIDATION_ERROR", "limit is too small for this computation.", required_candles=required_candles)

    pairs = _load("trading_pairs.json")
    if not isinstance(pairs, list):
        _audit("error")
        return _err("NOT_FOUND", "Trading pair not found.")
    pair = None
    for p in pairs:
        if isinstance(p, dict) and p.get("exchange") == "binance" and str(p.get("symbol", "")).upper() == symbol:
            pair = p
            break
    if pair is None:
        _audit("error")
        return _err("NOT_FOUND", "Trading pair not found.", symbol=symbol, exchange="binance")
    if pair.get("status") != "active":
        _audit("error")
        return _err("INVALID_TRANSITION", "Trading pair is not active for new computations.", error_code="PAIR_DISABLED")

    pair_id = pair.get("id")
    if not isinstance(pair_id, str) or not pair_id:
        _audit("error")
        return _err("NOT_FOUND", "Trading pair not found.")

    candles = _load("ohlcv_candles.json")
    if not isinstance(candles, list):
        candles = []
    scoped = []
    for r in candles:
        if not isinstance(r, dict):
            continue
        if r.get("pair_id") == pair_id and r.get("interval") == interval:
            ot = _parse_dt(r.get("open_time"))
            if ot is None:
                continue
            scoped.append((ot, r))
    scoped.sort(key=lambda x: x[0])

    if len(scoped) < required_candles:
        jobs = _load("computation_jobs.json")
        if not isinstance(jobs, list):
            jobs = []
        now = _now_iso()
        norm = {"tool": endpoint, "indicator_id": idef.get("id"), "pair_id": pair_id, "interval": interval, "limit": int(limit), "params": {"length": int(length), "ema_length": int(ema_length)}}
        fp = hashlib.sha256(json.dumps(norm, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()
        job_id = "job_" + hashlib.sha256((fp + "|" + now).encode("utf-8")).hexdigest()[:24]
        job = {
            "id": job_id,
            "indicator_id": idef.get("id"),
            "pair_id": pair_id,
            "interval": interval,
            "candle_limit": int(limit),
            "input_start_time": None,
            "input_end_time": None,
            "request_fingerprint": fp,
            "cache_hit": False,
            "status": "failed",
            "queued_at": now,
            "started_at": now,
            "finished_at": now,
            "error_code": "INSUFFICIENT_DATA",
            "error_message": "Not enough candles to compute indicator.",
            "binance_request_count": 0,
            "compute_time_ms": 0,
            "created_at": now,
            "updated_at": now
        }
        jobs.append(job)
        _save("computation_jobs.json", jobs)
        _audit("error", meta={"error_code": "INSUFFICIENT_DATA"})
        return _err("CONFLICT", "Insufficient data to compute indicator.", error_code="INSUFFICIENT_DATA", required_candles=required_candles, available_candles=len(scoped))

    use = scoped[-int(limit):]
    if len(use) < required_candles:
        _audit("error", meta={"error_code": "INSUFFICIENT_DATA"})
        return _err("CONFLICT", "Insufficient data to compute indicator.", error_code="INSUFFICIENT_DATA", required_candles=required_candles, available_candles=len(use))

    norm = {"tool": endpoint, "indicator_id": idef.get("id"), "pair_id": pair_id, "interval": interval, "limit": int(limit), "params": {"length": int(length), "ema_length": int(ema_length)}}
    fp = hashlib.sha256(json.dumps(norm, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()

    jobs = _load("computation_jobs.json")
    if not isinstance(jobs, list):
        jobs = []
    results = _load("computation_results.json")
    if not isinstance(results, list):
        results = []

    cached_job = None
    cached_res = None
    now_dt = datetime.datetime.utcnow()
    for j in jobs:
        if not isinstance(j, dict):
            continue
        if j.get("request_fingerprint") == fp and j.get("status") == "succeeded" and j.get("finished_at") is not None:
            jid = j.get("id")
            r = next((x for x in results if isinstance(x, dict) and x.get("job_id") == jid), None)
            if not r:
                continue
            exp = _parse_dt(r.get("expires_at"))
            if exp is None or exp >= now_dt:
                cached_job = j
                cached_res = r
                break
    if cached_job and cached_res:
        _audit("ok", meta={"cache_hit": True})
        return {"job": cached_job, "result": cached_res}

    now = _now_iso()
    job_id = "job_" + hashlib.sha256((fp + "|" + now).encode("utf-8")).hexdigest()[:24]
    job = {
        "id": job_id,
        "indicator_id": idef.get("id"),
        "pair_id": pair_id,
        "interval": interval,
        "candle_limit": int(limit),
        "input_start_time": None,
        "input_end_time": None,
        "request_fingerprint": fp,
        "cache_hit": False,
        "status": "queued",
        "queued_at": now,
        "started_at": None,
        "finished_at": None,
        "error_code": None,
        "error_message": None,
        "binance_request_count": 0,
        "compute_time_ms": None,
        "created_at": now,
        "updated_at": now
    }
    jobs.append(job)

    job["status"] = "running"
    job["started_at"] = _now_iso()
    job["updated_at"] = job["started_at"]

    compute_start = time.time()

    ranges = []
    times = []
    for ot, r in use:
        h = r.get("high"); l = r.get("low")
        if isinstance(h, (int, float)) and isinstance(l, (int, float)):
            rh = float(h); rl = float(l)
            if math.isfinite(rh) and math.isfinite(rl):
                ranges.append(rh - rl)
                times.append(ot)

    if len(ranges) < required_candles:
        fin = _now_iso()
        job["status"] = "failed"
        job["finished_at"] = fin
        job["updated_at"] = fin
        job["error_code"] = "INSUFFICIENT_DATA"
        job["error_message"] = "Not enough valid candles to compute indicator."
        job["compute_time_ms"] = int((time.time() - compute_start) * 1000)
        _save("computation_jobs.json", jobs)
        _audit("error", meta={"error_code": "INSUFFICIENT_DATA"})
        return _err("CONFLICT", "Insufficient data to compute indicator.", error_code="INSUFFICIENT_DATA", required_candles=required_candles, available_candles=len(ranges))

    alpha = 2.0 / (ema_length + 1.0)

    def _ema_series(series):
        out = []
        e = series[0]
        out.append(e)
        for x in series[1:]:
            e = alpha * x + (1.0 - alpha) * e
            out.append(e)
        return out

    ema1 = _ema_series(ranges)
    ema2 = _ema_series(ema1)

    ratios = []
    for a, b in zip(ema1, ema2):
        if b == 0:
            ratios.append(0.0)
        else:
            ratios.append(a / b)

    mi = sum(ratios[-length:])

    compute_ms = int((time.time() - compute_start) * 1000)
    as_of = times[-1].replace(microsecond=0).isoformat() + "Z"

    fin = _now_iso()
    job["status"] = "succeeded"
    job["finished_at"] = fin
    job["updated_at"] = fin
    job["compute_time_ms"] = compute_ms

    ttl = idef.get("cache_ttl_seconds")
    exp_iso = None
    if isinstance(ttl, int) and ttl > 0:
        exp_dt = datetime.datetime.utcnow() + datetime.timedelta(seconds=ttl)
        exp_iso = exp_dt.replace(microsecond=0).isoformat() + "Z"

    res_id = "res_" + hashlib.sha256((job_id + "|result").encode("utf-8")).hexdigest()[:24]
    result = {
        "id": res_id,
        "job_id": job_id,
        "result_kind": "series",
        "as_of_time": as_of,
        "value": float(mi),
        "signal": None,
        "series": None,
        "multi_series": None,
        "metadata": {
            "symbol": symbol,
            "exchange": "binance",
            "interval": interval,
            "limit": int(limit),
            "length": int(length),
            "ema_length": int(ema_length)
        },
        "expires_at": exp_iso,
        "created_at": fin,
        "updated_at": fin
    }

    results.append(result)
    _save("computation_jobs.json", jobs)
    _save("computation_results.json", results)
    _audit("ok", meta={"cache_hit": False})
    return {"job": job, "result": result}

def calculate_moving_average_convergence_divergence(symbol, interval=None, limit=None, start_time=None, end_time=None, fast_period=None, slow_period=None, signal_period=None, **_extra):
    import json, os, datetime, time, hashlib, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0416000" if __import__("os").path.isdir("./environment_mix/0416000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "calculate_moving_average_convergence_divergence"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            raise ValueError(f"{field} must be a string")
        ss = s.strip()
        if not ss:
            raise ValueError(f"{field} must be a non-empty ISO-8601 datetime string")
        try:
            if ss.endswith("Z"):
                dt = datetime.datetime.fromisoformat(ss[:-1] + "+00:00")
            else:
                dt = datetime.datetime.fromisoformat(ss)
        except Exception:
            raise ValueError(f"{field} must be a valid ISO-8601 datetime")
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _as_utc(dt_or_str, field):
        if isinstance(dt_or_str, datetime.datetime):
            dt = dt_or_str
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        return _parse_dt(dt_or_str, field)

    def _norm_symbol(s):
        return s.strip().upper()

    def _gen_id(prefix):
        return f"{prefix}_{hashlib.sha256((prefix + '|' + str(time.time_ns()) + '|' + os.urandom(8).hex()).encode('utf-8')).hexdigest()[:24]}"

    # request logging (best-effort; if no collection exists, it will still store to file if created)
    def _log(status, credential_used=None, extra=None):
        latency_ms = int((time.time() - t0) * 1000)
        row = {
            "id": _gen_id("req"),
            "endpoint": endpoint,
            "credential_used": credential_used,
            "status": status,
            "latency_ms": latency_ms,
            "timestamp": _now_iso()
        }
        if isinstance(extra, dict) and extra:
            row["extra"] = extra
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(row)
        _save("request_logs.json", logs)

    # Validate base params
    try:
        if not isinstance(symbol, str) or not symbol.strip():
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "symbol is required and must be a non-empty string")
        symbol_n = _norm_symbol(symbol)

        allowed_intervals = {"1m","3m","5m","15m","30m","1h","2h","4h","6h","8h","12h","1d","3d","1w","1M"}
        ind_defs = _load("indicator_definitions.json")
        ind_def = None
        for d in ind_defs:
            if isinstance(d, dict) and d.get("tool_name") == endpoint:
                ind_def = d
                break
        if not ind_def:
            _log("NOT_FOUND")
            return _err("NOT_FOUND", "Indicator definition not found for this tool")

        if not ind_def.get("is_enabled", False) or ind_def.get("status") not in ("active", "deprecated"):
            _log("UNAUTHORIZED")
            return _err("UNAUTHORIZED", "This tool is not enabled")

        if interval is None:
            interval = ind_def.get("default_interval")
        if not isinstance(interval, str) or interval not in allowed_intervals:
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "interval is not supported")

        if limit is None:
            limit = ind_def.get("default_limit")
        if not isinstance(limit, int) or limit < 1:
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit must be a positive integer")

        if fast_period is None:
            fast_period = 12
        if slow_period is None:
            slow_period = 26
        if signal_period is None:
            signal_period = 9
        for name, val in (("fast_period", fast_period), ("slow_period", slow_period), ("signal_period", signal_period)):
            if not isinstance(val, int) or val < 1:
                _log("VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"{name} must be a positive integer")
        if fast_period >= slow_period:
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "fast_period must be less than slow_period")

        st = _as_utc(start_time, "start_time") if start_time is not None else None
        et = _as_utc(end_time, "end_time") if end_time is not None else None
        if st and et and st > et:
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "start_time must be <= end_time")

    except ValueError as ve:
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", str(ve))

    # Resolve trading pair (must be active)
    pairs = _load("trading_pairs.json")
    pair = None
    for p in pairs:
        if isinstance(p, dict) and p.get("exchange") == "binance" and isinstance(p.get("symbol"), str) and p.get("symbol").upper() == symbol_n:
            pair = p
            break
    if not pair:
        _log("NOT_FOUND")
        return _err("NOT_FOUND", "Trading pair not found", symbol=symbol_n, exchange="binance")
    if pair.get("status") != "active":
        # per business rule: fail job with error_code PAIR_DISABLED
        pass

    # Build normalized request fingerprint (include indicator + pair + interval + bounds + periods)
    fp_payload = {
        "tool": endpoint,
        "indicator_id": ind_def.get("id"),
        "pair_id": pair.get("id"),
        "interval": interval,
        "limit": limit,
        "start_time": (st.isoformat() if st else None),
        "end_time": (et.isoformat() if et else None),
        "fast_period": fast_period,
        "slow_period": slow_period,
        "signal_period": signal_period
    }
    fp = hashlib.sha256(json.dumps(fp_payload, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()

    jobs = _load("computation_jobs.json")
    results = _load("computation_results.json")

    def _find_result_by_job(job_id):
        for r in results:
            if isinstance(r, dict) and r.get("job_id") == job_id:
                return r
        return None

    # Cache hit: succeeded job with same fingerprint and valid result not expired
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    for j in jobs:
        if not isinstance(j, dict):
            continue
        if j.get("request_fingerprint") != fp:
            continue
        if j.get("status") != "succeeded" or not j.get("finished_at"):
            continue
        r = _find_result_by_job(j.get("id"))
        if not r:
            continue
        exp = r.get("expires_at")
        exp_dt = None
        if isinstance(exp, str) and exp.strip():
            try:
                exp_dt = _as_utc(exp, "expires_at")
            except ValueError:
                exp_dt = None
        if exp_dt is None or exp_dt > now_dt:
            # mark cache hit on a new job row? business rule: subsequent requests must set cache_hit = true and return stored result without recomputation.
            # We'll create a new succeeded job record pointing to the same result is not allowed because results are unique(job_id).
            # Instead, we create a new job row with cache_hit=true and status=succeeded but without creating a result would violate expected behavior.
            # Better: return cached computation_result and also record a new job in succeeded with its own result copied (real service likely returns cached result directly without new job).
            # Here, we reuse same result and also log cache_hit in response metadata; do not mutate stored succeeded job.
            _log("OK", extra={"cache_hit": True})
            return {
                "job": j,
                "result": r,
                "cache_hit": True
            }

    # Create a new job (queued -> running -> terminal)
    job_id = _gen_id("job")
    now_iso = _now_iso()

    pair_disabled = (pair.get("status") != "active")
    job = {
        "id": job_id,
        "indicator_id": ind_def.get("id"),
        "pair_id": pair.get("id"),
        "interval": interval,
        "candle_limit": int(limit),
        "input_start_time": (st.isoformat() if st else None),
        "input_end_time": (et.isoformat() if et else None),
        "request_fingerprint": fp,
        "cache_hit": False,
        "status": "queued",
        "queued_at": now_iso,
        "started_at": None,
        "finished_at": None,
        "error_code": None,
        "error_message": None,
        "binance_request_count": 0,
        "compute_time_ms": None,
        "created_at": now_iso,
        "updated_at": now_iso
    }
    jobs.append(job)
    _save("computation_jobs.json", jobs)

    def _update_job(fields):
        nonlocal jobs, job
        for k, v in fields.items():
            job[k] = v
        job["updated_at"] = _now_iso()
        # persist in array
        for i, jj in enumerate(jobs):
            if isinstance(jj, dict) and jj.get("id") == job_id:
                jobs[i] = job
                break
        _save("computation_jobs.json", jobs)

    def _terminal(status, error_code=None, error_message=None, compute_time_ms=None):
        fin = _now_iso()
        fields = {
            "status": status,
            "finished_at": fin,
            "error_code": error_code,
            "error_message": error_message,
            "compute_time_ms": compute_time_ms
        }
        _update_job(fields)
        # ensure updated_at >= finished_at (string compare not safe); set updated_at to finished_at
        job["updated_at"] = job["finished_at"]
        for i, jj in enumerate(jobs):
            if isinstance(jj, dict) and jj.get("id") == job_id:
                jobs[i] = job
                break
        _save("computation_jobs.json", jobs)

    # Transition queued -> running
    _update_job({"status": "running", "started_at": _now_iso()})

    if pair_disabled:
        _terminal("failed", error_code="PAIR_DISABLED", error_message="Trading pair is not active")
        _log("OK", extra={"job_status": "failed", "error_code": "PAIR_DISABLED"})
        return {
            "job": job,
            "result": None,
            "cache_hit": False
        }

    # Load and filter candles
    candles = _load("ohlcv_candles.json")
    selected = []
    for c in candles:
        if not isinstance(c, dict):
            continue
        if c.get("pair_id") != pair.get("id"):
            continue
        if c.get("interval") != interval:
            continue
        ot = c.get("open_time")
        if not isinstance(ot, str):
            continue
        try:
            ot_dt = _as_utc(ot, "open_time")
        except ValueError:
            continue
        if st and ot_dt < st:
            continue
        if et and ot_dt > et:
            continue
        selected.append((ot_dt, c))
    selected.sort(key=lambda x: x[0])

    # apply limit most recent
    if len(selected) > limit:
        selected = selected[-limit:]

    # ensure ordered and enough candles
    min_lookback = ind_def.get("min_lookback_candles")
    if not isinstance(min_lookback, int) or min_lookback < 1:
        min_lookback = 1

    if len(selected) < min_lookback:
        _terminal("failed", error_code="INSUFFICIENT_DATA", error_message=f"Need at least {min_lookback} candles, found {len(selected)}")
        _log("OK", extra={"job_status": "failed", "error_code": "INSUFFICIENT_DATA"})
        return {"job": job, "result": None, "cache_hit": False}

    closes = []
    times = []
    for ot_dt, c in selected:
        cv = c.get("close")
        if not isinstance(cv, (int, float)) or not math.isfinite(float(cv)) or float(cv) <= 0:
            continue
        closes.append(float(cv))
        times.append(ot_dt)

    if len(closes) < min_lookback:
        _terminal("failed", error_code="INSUFFICIENT_DATA", error_message=f"Need at least {min_lookback} valid candles, found {len(closes)}")
        _log("OK", extra={"job_status": "failed", "error_code": "INSUFFICIENT_DATA"})
        return {"job": job, "result": None, "cache_hit": False}

    # compute EMA series
    def _ema(vals, period):
        k = 2.0 / (period + 1.0)
        out = []
        ema_prev = None
        for v in vals:
            if ema_prev is None:
                ema_prev = v
            else:
                ema_prev = (v - ema_prev) * k + ema_prev
            out.append(ema_prev)
        return out

    compute_start = time.time()
    ema_fast = _ema(closes, fast_period)
    ema_slow = _ema(closes, slow_period)
    macd_line = [a - b for a, b in zip(ema_fast, ema_slow)]
    signal_line = _ema(macd_line, signal_period)
    hist = [m - s for m, s in zip(macd_line, signal_line)]
    compute_ms = int((time.time() - compute_start) * 1000)

    latest_idx = len(closes) - 1
    as_of = times[latest_idx].isoformat()
    latest_macd = macd_line[latest_idx]
    latest_signal = signal_line[latest_idx]
    latest_hist = hist[latest_idx]

    # Create result (multi_series)
    res_id = _gen_id("res")
    created_at = _now_iso()
    ttl = ind_def.get("cache_ttl_seconds", 0)
    expires_at = None
    if isinstance(ttl, int) and ttl > 0:
        expires_at = (now_dt + datetime.timedelta(seconds=ttl)).isoformat()

    series_points_macd = [{"t": times[i].isoformat(), "v": macd_line[i]} for i in range(len(times))]
    series_points_signal = [{"t": times[i].isoformat(), "v": signal_line[i]} for i in range(len(times))]
    series_points_hist = [{"t": times[i].isoformat(), "v": hist[i]} for i in range(len(times))]

    result = {
        "id": res_id,
        "job_id": job_id,
        "result_kind": "multi_series",
        "as_of_time": as_of,
        "value": None,
        "signal": None,
        "series": None,
        "multi_series": {
            "macd": series_points_macd,
            "signal": series_points_signal,
            "histogram": series_points_hist
        },
        "metadata": {
            "symbol": symbol_n,
            "exchange": "binance",
            "interval": interval,
            "limit": limit,
            "start_time": (st.isoformat() if st else None),
            "end_time": (et.isoformat() if et else None),
            "fast_period": fast_period,
            "slow_period": slow_period,
            "signal_period": signal_period,
            "latest": {
                "macd": latest_macd,
                "signal": latest_signal,
                "histogram": latest_hist
            }
        },
        "expires_at": expires_at,
        "created_at": created_at,
        "updated_at": created_at
    }

    # enforce unique(job_id)
    for r in results:
        if isinstance(r, dict) and r.get("job_id") == job_id:
            _terminal("failed", error_code="CONFLICT", error_message="Result already exists for job_id")
            _log("CONFLICT")
            return _err("CONFLICT", "Result already exists for this job")

    results.append(result)
    _save("computation_results.json", results)

    # Terminal succeed; also enforce unique(request_fingerprint) for succeeded jobs
    for j in jobs:
        if not isinstance(j, dict) or j.get("id") == job_id:
            continue
        if j.get("status") == "succeeded" and j.get("request_fingerprint") == fp and j.get("finished_at"):
            # check that existing result for that job is not expired; if not expired, we should have hit cache earlier
            _terminal("failed", error_code="CONFLICT", error_message="Succeeded job with same request_fingerprint already exists")
            _log("CONFLICT")
            return _err("CONFLICT", "Duplicate succeeded job fingerprint")

    _terminal("succeeded", compute_time_ms=compute_ms)
    _log("OK", extra={"cache_hit": False})
    return {
        "job": job,
        "result": result,
        "cache_hit": False
    }

def calculate_moving_max(symbol, interval=None, limit=None, start_time=None, end_time=None, length=None, **_extra):
    import json, os, datetime, time, hashlib, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0416000" if __import__("os").path.isdir("./environment_mix/0416000") else "/app/database")
