        r = _find_result_by_job(j.get("id"))
        if not r:
            continue
        exp = r.get("expires_at")
        exp_dt = None
        if isinstance(exp, str) and exp.strip():
            try:
                exp_dt = _as_utc(exp, "expires_at")
            except ValueError:
                exp_dt = None
        if exp_dt is None or exp_dt > now_dt:
            _log("OK", extra={"cache_hit": True})
            return {"job": j, "result": r, "cache_hit": True}

    job_id = _gen_id("job")
    now_iso = _now_iso()

    job = {
        "id": job_id,
        "indicator_id": ind_def.get("id"),
        "pair_id": pair.get("id"),
        "interval": interval,
        "candle_limit": int(limit),
        "input_start_time": (st.isoformat() if st else None),
        "input_end_time": (et.isoformat() if et else None),
        "request_fingerprint": fp,
        "cache_hit": False,
        "status": "queued",
        "queued_at": now_iso,
        "started_at": None,
        "finished_at": None,
        "error_code": None,
        "error_message": None,
        "binance_request_count": 0,
        "compute_time_ms": None,
        "created_at": now_iso,
        "updated_at": now_iso
    }
    jobs.append(job)
    _save("computation_jobs.json", jobs)

    def _update_job(fields):
        nonlocal jobs, job
        for k, v in fields.items():
            job[k] = v
        job["updated_at"] = _now_iso()
        for i, jj in enumerate(jobs):
            if isinstance(jj, dict) and jj.get("id") == job_id:
                jobs[i] = job
                break
        _save("computation_jobs.json", jobs)

    def _terminal(status, error_code=None, error_message=None, compute_time_ms=None):
        fin = _now_iso()
        _update_job({
            "status": status,
            "finished_at": fin,
            "error_code": error_code,
            "error_message": error_message,
            "compute_time_ms": compute_time_ms
        })
        job["updated_at"] = job["finished_at"]
        for i, jj in enumerate(jobs):
            if isinstance(jj, dict) and jj.get("id") == job_id:
                jobs[i] = job
                break
        _save("computation_jobs.json", jobs)

    _update_job({"status": "running", "started_at": _now_iso()})

    if pair.get("status") != "active":
        _terminal("failed", error_code="PAIR_DISABLED", error_message="Trading pair is not active")
        _log("OK", extra={"job_status": "failed", "error_code": "PAIR_DISABLED"})
        return {"job": job, "result": None, "cache_hit": False}

    candles = _load("ohlcv_candles.json")
    selected = []
    for c in candles:
        if not isinstance(c, dict):
            continue
        if c.get("pair_id") != pair.get("id") or c.get("interval") != interval:
            continue
        ot = c.get("open_time")
        if not isinstance(ot, str):
            continue
        try:
            ot_dt = _as_utc(ot, "open_time")
        except ValueError:
            continue
        if st and ot_dt < st:
            continue
        if et and ot_dt > et:
            continue
        selected.append((ot_dt, c))
    selected.sort(key=lambda x: x[0])
    if len(selected) > limit:
        selected = selected[-limit:]

    min_lookback = ind_def.get("min_lookback_candles")
    if not isinstance(min_lookback, int) or min_lookback < 1:
        min_lookback = 1
    if len(selected) < min_lookback:
        _terminal("failed", error_code="INSUFFICIENT_DATA", error_message=f"Need at least {min_lookback} candles, found {len(selected)}")
        _log("OK", extra={"job_status": "failed", "error_code": "INSUFFICIENT_DATA"})
        return {"job": job, "result": None, "cache_hit": False}

    closes = []
    times = []
    for ot_dt, c in selected:
        cv = c.get("close")
        if not isinstance(cv, (int, float)) or not math.isfinite(float(cv)):
            continue
        closes.append(float(cv))
        times.append(ot_dt)

    if len(closes) < max(min_lookback, length):
        _terminal("failed", error_code="INSUFFICIENT_DATA", error_message=f"Need at least {max(min_lookback, length)} candles, found {len(closes)}")
        _log("OK", extra={"job_status": "failed", "error_code": "INSUFFICIENT_DATA"})
        return {"job": job, "result": None, "cache_hit": False}

    compute_start = time.time()
    mmin = []
    for i in range(len(closes)):
        if i + 1 < length:
            mmin.append(None)
        else:
            window = closes[i + 1 - length:i + 1]
            mmin.append(min(window))
    compute_ms = int((time.time() - compute_start) * 1000)

    latest_idx = len(mmin) - 1
    latest_val = mmin[latest_idx]
    as_of = times[latest_idx].isoformat()

    res_id = _gen_id("res")
    created_at = _now_iso()
    ttl = ind_def.get("cache_ttl_seconds", 0)
    expires_at = None
    if isinstance(ttl, int) and ttl > 0:
        expires_at = (now_dt + datetime.timedelta(seconds=ttl)).isoformat()

    series_points = [{"t": times[i].isoformat(), "v": mmin[i]} for i in range(len(times)) if mmin[i] is not None]
    result = {
        "id": res_id,
        "job_id": job_id,
        "result_kind": "series",
        "as_of_time": as_of,
        "value": latest_val,
        "signal": None,
        "series": series_points,
        "multi_series": None,
        "metadata": {
            "symbol": symbol_n,
            "exchange": "binance",
            "interval": interval,
            "limit": limit,
            "start_time": (st.isoformat() if st else None),
            "end_time": (et.isoformat() if et else None),
            "length": length
        },
        "expires_at": expires_at,
        "created_at": created_at,
        "updated_at": created_at
    }

    for r in results:
        if isinstance(r, dict) and r.get("job_id") == job_id:
            _terminal("failed", error_code="CONFLICT", error_message="Result already exists for job_id")
            _log("CONFLICT")
            return _err("CONFLICT", "Result already exists for this job")

    results.append(result)
    _save("computation_results.json", results)

    for j in jobs:
        if not isinstance(j, dict) or j.get("id") == job_id:
            continue
        if j.get("status") == "succeeded" and j.get("request_fingerprint") == fp and j.get("finished_at"):
            _terminal("failed", error_code="CONFLICT", error_message="Succeeded job with same request_fingerprint already exists")
            _log("CONFLICT")
            return _err("CONFLICT", "Duplicate succeeded job fingerprint")

    _terminal("succeeded", compute_time_ms=compute_ms)
    _log("OK", extra={"cache_hit": False})
    return {"job": job, "result": result, "cache_hit": False}

