def calculate_parabolic_sar(symbol, interval=None, limit=None, start_time=None, end_time=None, af=None, max_af=None, **_extra):
    import json, os, datetime, time, hashlib, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0416000" if __import__("os").path.isdir("./environment_mix/0416000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "calculate_parabolic_sar"
    jobs_f = "computation_jobs.json"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except ValueError:
            return None

    def _to_dt(x):
        if x is None:
            return None
        if isinstance(x, datetime.datetime):
            return x
        if isinstance(x, str):
            return _parse_dt(x)
        return None

    def _norm_dt(dt):
        if dt is None:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _lat_ms():
        return int((time.time() - t0) * 1000)

    def _log_job(job_row):
        jobs = _load(jobs_f)
        jobs.append(job_row)
        _save(jobs_f, jobs)

    def _update_job(job_id, patch):
        jobs = _load(jobs_f)
        updated = False
        for r in jobs:
            if r.get("id") == job_id:
                r.update(patch)
                updated = True
                break
        if updated:
            _save(jobs_f, jobs)
        return updated

    def _gen_id(prefix):
        return f"{prefix}_{datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%d%H%M%S%f')}_{os.getpid()}"

    def _fingerprint(obj):
        b = json.dumps(obj, sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return hashlib.sha256(b).hexdigest()

    allowed_intervals = {"1m","3m","5m","15m","30m","1h","2h","4h","6h","8h","12h","1d","3d","1w","1M"}

    # Basic validation
    if not isinstance(symbol, str) or not symbol.strip():
        return _err("VALIDATION_ERROR", "symbol is required and must be a non-empty string")
    symbol_n = symbol.strip().upper()

    if interval is not None and (not isinstance(interval, str) or interval not in allowed_intervals):
        return _err("VALIDATION_ERROR", "interval is invalid", allowed=sorted(allowed_intervals))
    if limit is not None and (not isinstance(limit, int) or limit < 1):
        return _err("VALIDATION_ERROR", "limit must be an integer >= 1")
    st = _to_dt(start_time)
    et = _to_dt(end_time)
    if start_time is not None and st is None:
        return _err("VALIDATION_ERROR", "start_time must be an ISO-8601 datetime string")
    if end_time is not None and et is None:
        return _err("VALIDATION_ERROR", "end_time must be an ISO-8601 datetime string")
    st = _norm_dt(st)
    et = _norm_dt(et)
    if st and et and st > et:
        return _err("VALIDATION_ERROR", "start_time must be <= end_time")

    if af is not None and (not isinstance(af, (int, float)) or not (af > 0)):
        return _err("VALIDATION_ERROR", "af must be a number > 0")
    if max_af is not None and (not isinstance(max_af, (int, float)) or not (max_af > 0)):
        return _err("VALIDATION_ERROR", "max_af must be a number > 0")
    if af is not None and max_af is not None and af > max_af:
        return _err("VALIDATION_ERROR", "af must be <= max_af")

    # Resolve indicator definition
    defs = _load("indicator_definitions.json")
    idef = None
    for d in defs:
        if d.get("tool_name") == endpoint:
            idef = d
            break
    if not idef:
        return _err("NOT_FOUND", "indicator definition not found for tool", tool_name=endpoint)
    if not idef.get("is_enabled", False) or idef.get("status") not in ("active", "deprecated"):
        return _err("CONFLICT", "tool is disabled", tool_name=endpoint, status=idef.get("status"))

    # Resolve trading pair (binance + symbol)
    pairs = _load("trading_pairs.json")
    pair = None
    for p in pairs:
        if p.get("exchange") == "binance" and isinstance(p.get("symbol"), str) and p.get("symbol").upper() == symbol_n:
            pair = p
            break
    if not pair:
        return _err("NOT_FOUND", "trading pair not found", exchange="binance", symbol=symbol_n)
    if pair.get("status") != "active":
        # Create failed job with PAIR_DISABLED
        now = _now_iso()
        job_id = _gen_id("job")
        interval_use = interval or idef.get("default_interval")
        candle_limit = int(limit or idef.get("default_limit") or idef.get("min_lookback_candles") or 1)
        fp = _fingerprint({
            "tool": endpoint,
            "indicator_id": idef.get("id"),
            "pair_id": pair.get("id"),
            "interval": interval_use,
            "limit": candle_limit,
            "start_time": st.isoformat() if st else None,
            "end_time": et.isoformat() if et else None,
            "params": {"af": af, "max_af": max_af},
        })
        job = {
            "id": job_id,
            "indicator_id": idef.get("id"),
            "pair_id": pair.get("id"),
            "interval": interval_use,
            "candle_limit": candle_limit,
            "input_start_time": st.isoformat() if st else None,
            "input_end_time": et.isoformat() if et else None,
            "request_fingerprint": fp,
            "cache_hit": False,
            "status": "failed",
            "queued_at": now,
            "started_at": now,
            "finished_at": now,
            "error_code": "PAIR_DISABLED",
            "error_message": "Trading pair is not active",
            "binance_request_count": 0,
            "compute_time_ms": 0,
            "created_at": now,
            "updated_at": now,
        }
        _log_job(job)
        return _err("CONFLICT", "pair is disabled", error_code="PAIR_DISABLED", job_id=job_id, pair_status=pair.get("status"))

    interval_use = interval or idef.get("default_interval")
    if interval_use not in allowed_intervals:
        return _err("VALIDATION_ERROR", "interval is invalid", allowed=sorted(allowed_intervals))
    candle_limit = int(limit or idef.get("default_limit") or idef.get("min_lookback_candles") or 1)
    if candle_limit < 1:
        return _err("VALIDATION_ERROR", "limit must be >= 1")

    # Prepare fingerprint and caching
    fp = _fingerprint({
        "tool": endpoint,
        "indicator_id": idef.get("id"),
        "pair_id": pair.get("id"),
        "interval": interval_use,
        "limit": candle_limit,
        "start_time": st.isoformat() if st else None,
        "end_time": et.isoformat() if et else None,
        "params": {"af": float(af) if af is not None else None, "max_af": float(max_af) if max_af is not None else None},
    })

    jobs = _load(jobs_f)
    results = _load("computation_results.json")
    now_dt = datetime.datetime.now(datetime.timezone.utc)

    # Check cache
    cached_job = None
    for j in jobs:
        if j.get("status") == "succeeded" and j.get("request_fingerprint") == fp and j.get("finished_at") is not None:
            # Find its result
            jr = None
            for r in results:
                if r.get("job_id") == j.get("id"):
                    jr = r
                    break
            if jr:
                exp = _to_dt(jr.get("expires_at"))
                exp = _norm_dt(exp)
                if exp is None or exp > now_dt:
                    cached_job = (j, jr)
                    break

    if cached_job:
        j, jr = cached_job
        # Record a new succeeded job row with cache_hit true (observability) without recompute
        now = _now_iso()
        job_id = _gen_id("job")
        job = {
            "id": job_id,
            "indicator_id": idef.get("id"),
            "pair_id": pair.get("id"),
            "interval": interval_use,
            "candle_limit": candle_limit,
            "input_start_time": st.isoformat() if st else None,
            "input_end_time": et.isoformat() if et else None,
            "request_fingerprint": fp,
            "cache_hit": True,
            "status": "succeeded",
            "queued_at": now,
            "started_at": now,
            "finished_at": now,
            "error_code": None,
            "error_message": None,
            "binance_request_count": 0,
            "compute_time_ms": 0,
            "created_at": now,
            "updated_at": now,
        }
        _log_job(job)
        return {
            "job": job,
            "pair": {"id": pair.get("id"), "exchange": pair.get("exchange"), "symbol": pair.get("symbol")},
            "indicator": {"id": idef.get("id"), "tool_name": idef.get("tool_name"), "status": idef.get("status")},
            "cache": {"hit": True, "source_job_id": j.get("id"), "result_id": jr.get("id")},
            "result": jr,
        }

    # Create queued job then run inline (running->succeeded/failed)
    now = _now_iso()
    job_id = _gen_id("job")
    job = {
        "id": job_id,
        "indicator_id": idef.get("id"),
        "pair_id": pair.get("id"),
        "interval": interval_use,
        "candle_limit": candle_limit,
        "input_start_time": st.isoformat() if st else None,
        "input_end_time": et.isoformat() if et else None,
        "request_fingerprint": fp,
        "cache_hit": False,
        "status": "queued",
        "queued_at": now,
        "started_at": None,
        "finished_at": None,
        "error_code": None,
        "error_message": None,
        "binance_request_count": 0,
        "compute_time_ms": None,
        "created_at": now,
        "updated_at": now,
    }
    _log_job(job)

    # Transition queued -> running
    start_iso = _now_iso()
    if not _update_job(job_id, {"status": "running", "started_at": start_iso, "updated_at": start_iso}):
        return _err("NOT_FOUND", "job disappeared", job_id=job_id)

    candles = _load("ohlcv_candles.json")
    # Filter candles by pair/interval and time bounds
    csel = []
    for c in candles:
        if c.get("pair_id") != pair.get("id") or c.get("interval") != interval_use:
            continue
        ot = _to_dt(c.get("open_time"))
        if ot is None:
            continue
        ot = _norm_dt(ot)
        if st and ot < st:
            continue
        if et and ot > et:
            continue
        csel.append((ot, c))
    csel.sort(key=lambda x: x[0])

    # Apply limit as most-recent candles
    if candle_limit is not None and len(csel) > candle_limit:
        csel = csel[-candle_limit:]

    min_needed = int(idef.get("min_lookback_candles") or 1)
    if len(csel) < min_needed:
        fin = _now_iso()
        _update_job(job_id, {
            "status": "failed",
            "finished_at": fin,
            "updated_at": fin,
            "error_code": "INSUFFICIENT_DATA",
            "error_message": f"Need at least {min_needed} candles, found {len(csel)}",
            "compute_time_ms": 0,
        })
        return _err("CONFLICT", "insufficient data", error_code="INSUFFICIENT_DATA", job_id=job_id, required=min_needed, found=len(csel))

    # Compute PSAR
    af_step = float(af) if af is not None else 0.02
    af_max = float(max_af) if max_af is not None else 0.2
    if af_step <= 0 or af_max <= 0:
        fin = _now_iso()
        _update_job(job_id, {
            "status": "failed",
            "finished_at": fin,
            "updated_at": fin,
            "error_code": "VALIDATION_ERROR",
            "error_message": "af/max_af must be > 0",
            "compute_time_ms": 0,
        })
        return _err("VALIDATION_ERROR", "af/max_af must be > 0", job_id=job_id)
    if af_step > af_max:
        fin = _now_iso()
        _update_job(job_id, {
            "status": "failed",
            "finished_at": fin,
            "updated_at": fin,
            "error_code": "VALIDATION_ERROR",
            "error_message": "af must be <= max_af",
            "compute_time_ms": 0,
        })
        return _err("VALIDATION_ERROR", "af must be <= max_af", job_id=job_id)

    # Extract highs/lows
    highs = []
    lows = []
    closes = []
    times = []
    for ot, c in csel:
        try:
            h = float(c["high"]); l = float(c["low"]); cl = float(c["close"])
        except Exception:
            h = l = cl = None
        if h is None or l is None or cl is None:
            continue
        highs.append(h); lows.append(l); closes.append(cl); times.append(ot)
    if len(times) < min_needed:
        fin = _now_iso()
        _update_job(job_id, {
            "status": "failed",
            "finished_at": fin,
            "updated_at": fin,
            "error_code": "INSUFFICIENT_DATA",
            "error_message": "Candle rows missing numeric OHLC fields",
            "compute_time_ms": 0,
        })
        return _err("CONFLICT", "insufficient data", error_code="INSUFFICIENT_DATA", job_id=job_id)

    # Initialize trend from first two closes
    if len(closes) < 2:
        fin = _now_iso()
        _update_job(job_id, {
            "status": "failed",
            "finished_at": fin,
            "updated_at": fin,
            "error_code": "INSUFFICIENT_DATA",
            "error_message": "Need at least 2 candles to initialize PSAR",
            "compute_time_ms": 0,
        })
        return _err("CONFLICT", "insufficient data", error_code="INSUFFICIENT_DATA", job_id=job_id)

    uptrend = closes[1] >= closes[0]
    ep = highs[0] if uptrend else lows[0]
    sar = lows[0] if uptrend else highs[0]
    a = af_step
    psar_series = []

    # First point uses initial sar at first candle close time
    psar_series.append({"t": times[0].isoformat(), "v": sar})

    for i in range(1, len(times)):
        prev_sar = sar
        # Calculate next sar
        sar = prev_sar + a * (ep - prev_sar)

        # Clamp SAR to prior two lows/highs
        if uptrend:
            if i >= 2:
                sar = min(sar, lows[i-1], lows[i-2])
            else:
                sar = min(sar, lows[i-1])
        else:
            if i >= 2:
                sar = max(sar, highs[i-1], highs[i-2])
            else:
                sar = max(sar, highs[i-1])

        # Check reversal
        reversed_now = False
        if uptrend:
            if lows[i] < sar:
                uptrend = False
                reversed_now = True
                sar = ep  # set sar to prior EP
                ep = lows[i]
                a = af_step
        else:
            if highs[i] > sar:
                uptrend = True
                reversed_now = True
                sar = ep
                ep = highs[i]
                a = af_step

        if not reversed_now:
            # Update EP and AF
            if uptrend:
                if highs[i] > ep:
                    ep = highs[i]
                    a = min(a + af_step, af_max)
            else:
                if lows[i] < ep:
                    ep = lows[i]
                    a = min(a + af_step, af_max)

        psar_series.append({"t": times[i].isoformat(), "v": sar})

    latest = psar_series[-1]
    as_of = latest["t"]
    latest_val = latest["v"]

    # Persist result
    compute_ms = _lat_ms()
    res_id = _gen_id("res")
    expires_at = None
    ttl = idef.get("cache_ttl_seconds")
    if isinstance(ttl, int) and ttl > 0:
        expires_at = (datetime.datetime.now(datetime.timezone.utc) + datetime.timedelta(seconds=ttl)).isoformat()

    res = {
        "id": res_id,
        "job_id": job_id,
        "result_kind": "series",
        "as_of_time": as_of,
        "value": latest_val,
        "signal": None,
        "series": psar_series,
        "multi_series": None,
        "metadata": {"af": af_step, "max_af": af_max, "interval": interval_use, "limit": candle_limit},
        "expires_at": expires_at,
        "created_at": _now_iso(),
        "updated_at": _now_iso(),
    }

    # Enforce unique(job_id)
    results = _load("computation_results.json")
    for r in results:
        if r.get("job_id") == job_id:
            fin = _now_iso()
            _update_job(job_id, {
                "status": "failed",
                "finished_at": fin,
                "updated_at": fin,
                "error_code": "CONFLICT",
                "error_message": "Result already exists for job_id",
                "compute_time_ms": compute_ms,
            })
            return _err("CONFLICT", "result already exists for job", job_id=job_id)

    results.append(res)
    _save("computation_results.json", results)

    fin = _now_iso()
    _update_job(job_id, {
        "status": "succeeded",
        "finished_at": fin,
        "updated_at": fin,
        "compute_time_ms": compute_ms,
        "error_code": None,
        "error_message": None,
    })

    return {
        "job": {**job, "status": "succeeded", "started_at": start_iso, "finished_at": fin, "updated_at": fin, "compute_time_ms": compute_ms},
        "pair": {"id": pair.get("id"), "exchange": pair.get("exchange"), "symbol": pair.get("symbol")},
        "indicator": {"id": idef.get("id"), "tool_name": idef.get("tool_name"), "status": idef.get("status")},
        "cache": {"hit": False},
        "latest": {"t": as_of, "value": latest_val},
        "result": res,
    }

def calculate_qstick(symbol, interval=None, limit=None, start_time=None, end_time=None, length=None, **_extra):
    import json, os, datetime, time, hashlib, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0416000" if __import__("os").path.isdir("./environment_mix/0416000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "calculate_qstick"
    jobs_f = "computation_jobs.json"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except ValueError:
            return None

    def _to_dt(x):
        if x is None:
            return None
        if isinstance(x, datetime.datetime):
            return x
        if isinstance(x, str):
            return _parse_dt(x)
        return None

    def _norm_dt(dt):
        if dt is None:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _lat_ms():
        return int((time.time() - t0) * 1000)

    def _log_job(job_row):
        jobs = _load(jobs_f)
        jobs.append(job_row)
        _save(jobs_f, jobs)

    def _update_job(job_id, patch):
        jobs = _load(jobs_f)
        updated = False
        for r in jobs:
            if r.get("id") == job_id:
                r.update(patch)
                updated = True
                break
        if updated:
            _save(jobs_f, jobs)
        return updated

    def _gen_id(prefix):
        return f"{prefix}_{datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%d%H%M%S%f')}_{os.getpid()}"

    def _fingerprint(obj):
        b = json.dumps(obj, sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return hashlib.sha256(b).hexdigest()

    allowed_intervals = {"1m","3m","5m","15m","30m","1h","2h","4h","6h","8h","12h","1d","3d","1w","1M"}

    if not isinstance(symbol, str) or not symbol.strip():
        return _err("VALIDATION_ERROR", "symbol is required and must be a non-empty string")
    symbol_n = symbol.strip().upper()

    if interval is not None and (not isinstance(interval, str) or interval not in allowed_intervals):
        return _err("VALIDATION_ERROR", "interval is invalid", allowed=sorted(allowed_intervals))
    if limit is not None and (not isinstance(limit, int) or limit < 1):
        return _err("VALIDATION_ERROR", "limit must be an integer >= 1")
    if length is not None and (not isinstance(length, int) or length < 1):
        return _err("VALIDATION_ERROR", "length must be an integer >= 1")

    st = _to_dt(start_time)
    et = _to_dt(end_time)
    if start_time is not None and st is None:
        return _err("VALIDATION_ERROR", "start_time must be an ISO-8601 datetime string")
    if end_time is not None and et is None:
        return _err("VALIDATION_ERROR", "end_time must be an ISO-8601 datetime string")
    st = _norm_dt(st)
    et = _norm_dt(et)
    if st and et and st > et:
        return _err("VALIDATION_ERROR", "start_time must be <= end_time")

    defs = _load("indicator_definitions.json")
    idef = None
    for d in defs:
        if d.get("tool_name") == endpoint:
            idef = d
            break
    if not idef:
        return _err("NOT_FOUND", "indicator definition not found for tool", tool_name=endpoint)
    if not idef.get("is_enabled", False) or idef.get("status") not in ("active", "deprecated"):
        return _err("CONFLICT", "tool is disabled", tool_name=endpoint, status=idef.get("status"))

    pairs = _load("trading_pairs.json")
    pair = None
    for p in pairs:
        if p.get("exchange") == "binance" and isinstance(p.get("symbol"), str) and p.get("symbol").upper() == symbol_n:
            pair = p
            break
    if not pair:
        return _err("NOT_FOUND", "trading pair not found", exchange="binance", symbol=symbol_n)

    interval_use = interval or idef.get("default_interval")
    if interval_use not in allowed_intervals:
        return _err("VALIDATION_ERROR", "interval is invalid", allowed=sorted(allowed_intervals))
    candle_limit = int(limit or idef.get("default_limit") or idef.get("min_lookback_candles") or 1)
    if candle_limit < 1:
        return _err("VALIDATION_ERROR", "limit must be >= 1")

    if pair.get("status") != "active":
        now = _now_iso()
        job_id = _gen_id("job")
        fp = _fingerprint({
            "tool": endpoint,
            "indicator_id": idef.get("id"),
            "pair_id": pair.get("id"),
            "interval": interval_use,
            "limit": candle_limit,
            "start_time": st.isoformat() if st else None,
            "end_time": et.isoformat() if et else None,
            "params": {"length": int(length) if length is not None else None},
        })
        job = {
            "id": job_id,
            "indicator_id": idef.get("id"),
            "pair_id": pair.get("id"),
            "interval": interval_use,
            "candle_limit": candle_limit,
            "input_start_time": st.isoformat() if st else None,
            "input_end_time": et.isoformat() if et else None,
            "request_fingerprint": fp,
            "cache_hit": False,
            "status": "failed",
            "queued_at": now,
            "started_at": now,
            "finished_at": now,
            "error_code": "PAIR_DISABLED",
            "error_message": "Trading pair is not active",
            "binance_request_count": 0,
            "compute_time_ms": 0,
            "created_at": now,
            "updated_at": now,
        }
        jobs = _load(jobs_f); jobs.append(job); _save(jobs_f, jobs)
        return _err("CONFLICT", "pair is disabled", error_code="PAIR_DISABLED", job_id=job_id, pair_status=pair.get("status"))

    # Compute fingerprint and cache
    qlen = int(length) if length is not None else 10
    if qlen < 1:
        return _err("VALIDATION_ERROR", "length must be >= 1")

    fp = _fingerprint({
        "tool": endpoint,
        "indicator_id": idef.get("id"),
        "pair_id": pair.get("id"),
        "interval": interval_use,
        "limit": candle_limit,
        "start_time": st.isoformat() if st else None,
        "end_time": et.isoformat() if et else None,
        "params": {"length": qlen},
    })

    jobs = _load(jobs_f)
    results = _load("computation_results.json")
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    cached_job = None
    for j in jobs:
        if j.get("status") == "succeeded" and j.get("request_fingerprint") == fp and j.get("finished_at") is not None:
            jr = None
            for r in results:
                if r.get("job_id") == j.get("id"):
                    jr = r
                    break
            if jr:
                exp = _norm_dt(_to_dt(jr.get("expires_at")))
                if exp is None or exp > now_dt:
                    cached_job = (j, jr)
                    break

    if cached_job:
        j, jr = cached_job
        now = _now_iso()
        job_id = _gen_id("job")
        job = {
            "id": job_id,
            "indicator_id": idef.get("id"),
            "pair_id": pair.get("id"),
            "interval": interval_use,
            "candle_limit": candle_limit,
            "input_start_time": st.isoformat() if st else None,
            "input_end_time": et.isoformat() if et else None,
            "request_fingerprint": fp,
            "cache_hit": True,
            "status": "succeeded",
            "queued_at": now,
            "started_at": now,
            "finished_at": now,
            "error_code": None,
            "error_message": None,
            "binance_request_count": 0,
            "compute_time_ms": 0,
            "created_at": now,
            "updated_at": now,
        }
        _log_job(job)
        return {
            "job": job,
            "pair": {"id": pair.get("id"), "exchange": pair.get("exchange"), "symbol": pair.get("symbol")},
            "indicator": {"id": idef.get("id"), "tool_name": idef.get("tool_name"), "status": idef.get("status")},
            "cache": {"hit": True, "source_job_id": j.get("id"), "result_id": jr.get("id")},
            "result": jr,
        }

    # Create job queued -> running
    now = _now_iso()
    job_id = _gen_id("job")
    job = {
        "id": job_id,
        "indicator_id": idef.get("id"),
        "pair_id": pair.get("id"),
        "interval": interval_use,
        "candle_limit": candle_limit,
        "input_start_time": st.isoformat() if st else None,
        "input_end_time": et.isoformat() if et else None,
        "request_fingerprint": fp,
        "cache_hit": False,
        "status": "queued",
        "queued_at": now,
        "started_at": None,
        "finished_at": None,
        "error_code": None,
        "error_message": None,
        "binance_request_count": 0,
        "compute_time_ms": None,
        "created_at": now,
        "updated_at": now,
    }
    _log_job(job)

    start_iso = _now_iso()
    if not _update_job(job_id, {"status": "running", "started_at": start_iso, "updated_at": start_iso}):
        return _err("NOT_FOUND", "job disappeared", job_id=job_id)

    candles = _load("ohlcv_candles.json")
    csel = []
    for c in candles:
        if c.get("pair_id") != pair.get("id") or c.get("interval") != interval_use:
            continue
        ot = _norm_dt(_to_dt(c.get("open_time")))
        if ot is None:
            continue
        if st and ot < st:
            continue
        if et and ot > et:
            continue
        csel.append((ot, c))
    csel.sort(key=lambda x: x[0])
    if len(csel) > candle_limit:
        csel = csel[-candle_limit:]

    min_needed = int(idef.get("min_lookback_candles") or 1)
    if len(csel) < min_needed:
        fin = _now_iso()
        _update_job(job_id, {
            "status": "failed",
            "finished_at": fin,
            "updated_at": fin,
            "error_code": "INSUFFICIENT_DATA",
            "error_message": f"Need at least {min_needed} candles, found {len(csel)}",
            "compute_time_ms": 0,
        })
        return _err("CONFLICT", "insufficient data", error_code="INSUFFICIENT_DATA", job_id=job_id, required=min_needed, found=len(csel))

    # Qstick: SMA of (close-open) over length
    diffs = []
    times = []
    for ot, c in csel:
        try:
            o = float(c["open"]); cl = float(c["close"])
        except Exception:
            continue
        diffs.append(cl - o)
        times.append(ot)

    if len(diffs) < max(min_needed, qlen):
        fin = _now_iso()
        _update_job(job_id, {
            "status": "failed",
            "finished_at": fin,
            "updated_at": fin,
            "error_code": "INSUFFICIENT_DATA",
            "error_message": f"Need at least {max(min_needed, qlen)} candles for length={qlen}, found {len(diffs)}",
            "compute_time_ms": 0,
        })
        return _err("CONFLICT", "insufficient data", error_code="INSUFFICIENT_DATA", job_id=job_id, required=max(min_needed, qlen), found=len(diffs))

    q_series = []
    window_sum = 0.0
    for i, d in enumerate(diffs):
        window_sum += d
        if i >= qlen:
            window_sum -= diffs[i - qlen]
        if i >= qlen - 1:
            qv = window_sum / qlen
            q_series.append({"t": times[i].isoformat(), "v": qv})

    latest = q_series[-1]
    as_of = latest["t"]
    latest_val = latest["v"]

    compute_ms = _lat_ms()
    res_id = _gen_id("res")
    ttl = idef.get("cache_ttl_seconds")
    expires_at = None
    if isinstance(ttl, int) and ttl > 0:
        expires_at = (datetime.datetime.now(datetime.timezone.utc) + datetime.timedelta(seconds=ttl)).isoformat()

    res = {
        "id": res_id,
        "job_id": job_id,
        "result_kind": "series",
        "as_of_time": as_of,
        "value": latest_val,
        "signal": None,
        "series": q_series,
        "multi_series": None,
        "metadata": {"length": qlen, "interval": interval_use, "limit": candle_limit},
        "expires_at": expires_at,
        "created_at": _now_iso(),
        "updated_at": _now_iso(),
    }

    results = _load("computation_results.json")
    for r in results:
        if r.get("job_id") == job_id:
            fin = _now_iso()
            _update_job(job_id, {
                "status": "failed",
                "finished_at": fin,
                "updated_at": fin,
                "error_code": "CONFLICT",
                "error_message": "Result already exists for job_id",
                "compute_time_ms": compute_ms,
            })
            return _err("CONFLICT", "result already exists for job", job_id=job_id)

    results.append(res)
    _save("computation_results.json", results)

    fin = _now_iso()
    _update_job(job_id, {
        "status": "succeeded",
        "finished_at": fin,
        "updated_at": fin,
        "compute_time_ms": compute_ms,
        "error_code": None,
        "error_message": None,
    })

    return {
        "job": {**job, "status": "succeeded", "started_at": start_iso, "finished_at": fin, "updated_at": fin, "compute_time_ms": compute_ms},
        "pair": {"id": pair.get("id"), "exchange": pair.get("exchange"), "symbol": pair.get("symbol")},
        "indicator": {"id": idef.get("id"), "tool_name": idef.get("tool_name"), "status": idef.get("status")},
        "cache": {"hit": False},
        "latest": {"t": as_of, "value": latest_val},
        "result": res,
    }

def calculate_kdj(symbol, interval=None, limit=None, start_time=None, end_time=None, length=None, signal=None, **_extra):
    import json, os, datetime, time, hashlib, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0416000" if __import__("os").path.isdir("./environment_mix/0416000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "calculate_kdj"
    jobs_f = "computation_jobs.json"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except ValueError:
            return None

    def _to_dt(x):
        if x is None:
            return None
        if isinstance(x, datetime.datetime):
            return x
        if isinstance(x, str):
            return _parse_dt(x)
        return None

    def _norm_dt(dt):
        if dt is None:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _lat_ms():
        return int((time.time() - t0) * 1000)

    def _log_job(job_row):
        jobs = _load(jobs_f)
        jobs.append(job_row)
        _save(jobs_f, jobs)

    def _update_job(job_id, patch):
        jobs = _load(jobs_f)
        updated = False
        for r in jobs:
            if r.get("id") == job_id:
                r.update(patch)
                updated = True
                break
        if updated:
            _save(jobs_f, jobs)
        return updated

    def _gen_id(prefix):
        return f"{prefix}_{datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%d%H%M%S%f')}_{os.getpid()}"

    def _fingerprint(obj):
        b = json.dumps(obj, sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return hashlib.sha256(b).hexdigest()

    allowed_intervals = {"1m","3m","5m","15m","30m","1h","2h","4h","6h","8h","12h","1d","3d","1w","1M"}

    if not isinstance(symbol, str) or not symbol.strip():
        return _err("VALIDATION_ERROR", "symbol is required and must be a non-empty string")
    symbol_n = symbol.strip().upper()

    if interval is not None and (not isinstance(interval, str) or interval not in allowed_intervals):
        return _err("VALIDATION_ERROR", "interval is invalid", allowed=sorted(allowed_intervals))
    if limit is not None and (not isinstance(limit, int) or limit < 1):
        return _err("VALIDATION_ERROR", "limit must be an integer >= 1")
    if length is not None and (not isinstance(length, int) or length < 1):
        return _err("VALIDATION_ERROR", "length must be an integer >= 1")
    if signal is not None and (not isinstance(signal, int) or signal < 1):
        return _err("VALIDATION_ERROR", "signal must be an integer >= 1")

    st = _to_dt(start_time)
    et = _to_dt(end_time)
    if start_time is not None and st is None:
        return _err("VALIDATION_ERROR", "start_time must be an ISO-8601 datetime string")
    if end_time is not None and et is None:
        return _err("VALIDATION_ERROR", "end_time must be an ISO-8601 datetime string")
    st = _norm_dt(st)
    et = _norm_dt(et)
    if st and et and st > et:
        return _err("VALIDATION_ERROR", "start_time must be <= end_time")

    defs = _load("indicator_definitions.json")
    idef = None
    for d in defs:
        if d.get("tool_name") == endpoint:
            idef = d
            break
    if not idef:
        return _err("NOT_FOUND", "indicator definition not found for tool", tool_name=endpoint)
    if not idef.get("is_enabled", False) or idef.get("status") not in ("active", "deprecated"):
        return _err("CONFLICT", "tool is disabled", tool_name=endpoint, status=idef.get("status"))

    pairs = _load("trading_pairs.json")
    pair = None
    for p in pairs:
        if p.get("exchange") == "binance" and isinstance(p.get("symbol"), str) and p.get("symbol").upper() == symbol_n:
            pair = p
            break
    if not pair:
        return _err("NOT_FOUND", "trading pair not found", exchange="binance", symbol=symbol_n)

    interval_use = interval or idef.get("default_interval")
    if interval_use not in allowed_intervals:
        return _err("VALIDATION_ERROR", "interval is invalid", allowed=sorted(allowed_intervals))
    candle_limit = int(limit or idef.get("default_limit") or idef.get("min_lookback_candles") or 1)
    if candle_limit < 1:
        return _err("VALIDATION_ERROR", "limit must be >= 1")

    klen = int(length) if length is not None else 9
    slen = int(signal) if signal is not None else 3

    if pair.get("status") != "active":
        now = _now_iso()
        job_id = _gen_id("job")
        fp = _fingerprint({
            "tool": endpoint,
            "indicator_id": idef.get("id"),
            "pair_id": pair.get("id"),
            "interval": interval_use,
            "limit": candle_limit,
            "start_time": st.isoformat() if st else None,
            "end_time": et.isoformat() if et else None,
            "params": {"length": klen, "signal": slen},
        })
        job = {
            "id": job_id,
            "indicator_id": idef.get("id"),
            "pair_id": pair.get("id"),
            "interval": interval_use,
            "candle_limit": candle_limit,
            "input_start_time": st.isoformat() if st else None,
            "input_end_time": et.isoformat() if et else None,
            "request_fingerprint": fp,
            "cache_hit": False,
            "status": "failed",
            "queued_at": now,
            "started_at": now,
            "finished_at": now,
            "error_code": "PAIR_DISABLED",
            "error_message": "Trading pair is not active",
            "binance_request_count": 0,
            "compute_time_ms": 0,
            "created_at": now,
            "updated_at": now,
        }
        jobs = _load(jobs_f); jobs.append(job); _save(jobs_f, jobs)
        return _err("CONFLICT", "pair is disabled", error_code="PAIR_DISABLED", job_id=job_id, pair_status=pair.get("status"))

    fp = _fingerprint({
        "tool": endpoint,
        "indicator_id": idef.get("id"),
        "pair_id": pair.get("id"),
        "interval": interval_use,
        "limit": candle_limit,
        "start_time": st.isoformat() if st else None,
        "end_time": et.isoformat() if et else None,
        "params": {"length": klen, "signal": slen},
    })

    jobs = _load(jobs_f)
    results = _load("computation_results.json")
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    cached_job = None
    for j in jobs:
        if j.get("status") == "succeeded" and j.get("request_fingerprint") == fp and j.get("finished_at") is not None:
            jr = None
            for r in results:
                if r.get("job_id") == j.get("id"):
                    jr = r
                    break
            if jr:
                exp = _norm_dt(_to_dt(jr.get("expires_at")))
                if exp is None or exp > now_dt:
                    cached_job = (j, jr)
                    break

    if cached_job:
        j, jr = cached_job
        now = _now_iso()
        job_id = _gen_id("job")
        job = {
            "id": job_id,
            "indicator_id": idef.get("id"),
            "pair_id": pair.get("id"),
            "interval": interval_use,
            "candle_limit": candle_limit,
            "input_start_time": st.isoformat() if st else None,
            "input_end_time": et.isoformat() if et else None,
            "request_fingerprint": fp,
            "cache_hit": True,
            "status": "succeeded",
            "queued_at": now,
            "started_at": now,
            "finished_at": now,
            "error_code": None,
            "error_message": None,
            "binance_request_count": 0,
            "compute_time_ms": 0,
            "created_at": now,
            "updated_at": now,
        }
        _log_job(job)
        return {
            "job": job,
            "pair": {"id": pair.get("id"), "exchange": pair.get("exchange"), "symbol": pair.get("symbol")},
            "indicator": {"id": idef.get("id"), "tool_name": idef.get("tool_name"), "status": idef.get("status")},
            "cache": {"hit": True, "source_job_id": j.get("id"), "result_id": jr.get("id")},
            "result": jr,
        }

    # Create job and run
    now = _now_iso()
    job_id = _gen_id("job")
    job = {
        "id": job_id,
        "indicator_id": idef.get("id"),
        "pair_id": pair.get("id"),
        "interval": interval_use,
        "candle_limit": candle_limit,
        "input_start_time": st.isoformat() if st else None,
        "input_end_time": et.isoformat() if et else None,
        "request_fingerprint": fp,
        "cache_hit": False,
        "status": "queued",
        "queued_at": now,
        "started_at": None,
        "finished_at": None,
        "error_code": None,
        "error_message": None,
        "binance_request_count": 0,
        "compute_time_ms": None,
        "created_at": now,
        "updated_at": now,
    }
    _log_job(job)

    start_iso = _now_iso()
    if not _update_job(job_id, {"status": "running", "started_at": start_iso, "updated_at": start_iso}):
        return _err("NOT_FOUND", "job disappeared", job_id=job_id)

    candles = _load("ohlcv_candles.json")
    csel = []
    for c in candles:
        if c.get("pair_id") != pair.get("id") or c.get("interval") != interval_use:
            continue
        ot = _norm_dt(_to_dt(c.get("open_time")))
        if ot is None:
            continue
        if st and ot < st:
            continue
        if et and ot > et:
            continue
        csel.append((ot, c))
    csel.sort(key=lambda x: x[0])
    if len(csel) > candle_limit:
        csel = csel[-candle_limit:]

    min_needed = int(idef.get("min_lookback_candles") or 1)
    required = max(min_needed, klen)
    if len(csel) < required:
        fin = _now_iso()
        _update_job(job_id, {
            "status": "failed",
            "finished_at": fin,
            "updated_at": fin,
            "error_code": "INSUFFICIENT_DATA",
            "error_message": f"Need at least {required} candles, found {len(csel)}",
            "compute_time_ms": 0,
        })
        return _err("CONFLICT", "insufficient data", error_code="INSUFFICIENT_DATA", job_id=job_id, required=required, found=len(csel))

    highs, lows, closes, times = [], [], [], []
    for ot, c in csel:
        try:
            highs.append(float(c["high"]))
            lows.append(float(c["low"]))
            closes.append(float(c["close"]))
            times.append(ot)
        except Exception:
            continue

    if len(times) < required:
        fin = _now_iso()
        _update_job(job_id, {
            "status": "failed",
            "finished_at": fin,
            "updated_at": fin,
            "error_code": "INSUFFICIENT_DATA",
            "error_message": "Candle rows missing numeric OHLC fields",
            "compute_time_ms": 0,
        })
        return _err("CONFLICT", "insufficient data", error_code="INSUFFICIENT_DATA", job_id=job_id)

    # KDJ: RSV then smoothed K and D; J = 3K - 2D
    # Typical initialization: K0=50, D0=50
    K = 50.0
    D = 50.0
    alpha = 1.0 / float(slen)

    multi = {"K": [], "D": [], "J": []}
    for i in range(len(times)):
        if i < klen - 1:
            continue
        lo = min(lows[i - klen + 1:i + 1])
        hi = max(highs[i - klen + 1:i + 1])
        if hi - lo == 0:
            rsv = 50.0
        else:
            rsv = (closes[i] - lo) / (hi - lo) * 100.0
        K = (1 - alpha) * K + alpha * rsv
        D = (1 - alpha) * D + alpha * K
        J = 3 * K - 2 * D
        ti = times[i].isoformat()
        multi["K"].append({"t": ti, "v": K})
        multi["D"].append({"t": ti, "v": D})
        multi["J"].append({"t": ti, "v": J})

    if not multi["K"]:
        fin = _now_iso()
        _update_job(job_id, {
            "status": "failed",
            "finished_at": fin,
            "updated_at": fin,
            "error_code": "INSUFFICIENT_DATA",
            "error_message": "Not enough candles to compute KDJ series",
            "compute_time_ms": 0,
        })
        return _err("CONFLICT", "insufficient data", error_code="INSUFFICIENT_DATA", job_id=job_id)

    latest_t = multi["K"][-1]["t"]
    latest_k = multi["K"][-1]["v"]
    latest_d = multi["D"][-1]["v"]
    latest_j = multi["J"][-1]["v"]

    compute_ms = _lat_ms()
    res_id = _gen_id("res")
    ttl = idef.get("cache_ttl_seconds")
    expires_at = None
    if isinstance(ttl, int) and ttl > 0:
        expires_at = (datetime.datetime.now(datetime.timezone.utc) + datetime.timedelta(seconds=ttl)).isoformat()

    res = {
        "id": res_id,
        "job_id": job_id,
        "result_kind": "multi_series",
        "as_of_time": latest_t,
        "value": None,
        "signal": None,
        "series": None,
        "multi_series": multi,
        "metadata": {"length": klen, "signal": slen, "interval": interval_use, "limit": candle_limit},
        "expires_at": expires_at,
        "created_at": _now_iso(),
        "updated_at": _now_iso(),
    }

    results = _load("computation_results.json")
    for r in results:
        if r.get("job_id") == job_id:
            fin = _now_iso()
            _update_job(job_id, {
                "status": "failed",
                "finished_at": fin,
                "updated_at": fin,
                "error_code": "CONFLICT",
                "error_message": "Result already exists for job_id",
                "compute_time_ms": compute_ms,
            })
            return _err("CONFLICT", "result already exists for job", job_id=job_id)

    results.append(res)
    _save("computation_results.json", results)

    fin = _now_iso()
    _update_job(job_id, {
        "status": "succeeded",
        "finished_at": fin,
        "updated_at": fin,
        "compute_time_ms": compute_ms,
        "error_code": None,
        "error_message": None,
    })

    return {
        "job": {**job, "status": "succeeded", "started_at": start_iso, "finished_at": fin, "updated_at": fin, "compute_time_ms": compute_ms},
        "pair": {"id": pair.get("id"), "exchange": pair.get("exchange"), "symbol": pair.get("symbol")},
        "indicator": {"id": idef.get("id"), "tool_name": idef.get("tool_name"), "status": idef.get("status")},
        "cache": {"hit": False},
        "latest": {"t": latest_t, "K": latest_k, "D": latest_d, "J": latest_j},
        "result": res,
    }

