            break
    if not idef:
        return _err("NOT_FOUND", "indicator definition not found for tool", tool_name=endpoint)
    if not idef.get("is_enabled", False) or idef.get("status") not in ("active", "deprecated"):
        return _err("CONFLICT", "tool is disabled", tool_name=endpoint, status=idef.get("status"))

    pairs = _load("trading_pairs.json")
    pair = None
    for p in pairs:
        if p.get("exchange") == "binance" and isinstance(p.get("symbol"), str) and p.get("symbol").upper() == symbol_n:
            pair = p
            break
    if not pair:
        return _err("NOT_FOUND", "trading pair not found", exchange="binance", symbol=symbol_n)

    interval_use = interval or idef.get("default_interval")
    if interval_use not in allowed_intervals:
        return _err("VALIDATION_ERROR", "interval is invalid", allowed=sorted(allowed_intervals))
    candle_limit = int(limit or idef.get("default_limit") or idef.get("min_lookback_candles") or 1)
    if candle_limit < 1:
        return _err("VALIDATION_ERROR", "limit must be >= 1")

    rlen = int(length) if length is not None else 14
    if rlen < 1:
        return _err("VALIDATION_ERROR", "length must be >= 1")

    if pair.get("status") != "active":
        now = _now_iso()
        job_id = _gen_id("job")
        fp = _fingerprint({
            "tool": endpoint,
            "indicator_id": idef.get("id"),
            "pair_id": pair.get("id"),
            "interval": interval_use,
            "limit": candle_limit,
            "start_time": st.isoformat() if st else None,
            "end_time": et.isoformat() if et else None,
            "params": {"length": rlen},
        })
        job = {
            "id": job_id,
            "indicator_id": idef.get("id"),
            "pair_id": pair.get("id"),
            "interval": interval_use,
            "candle_limit": candle_limit,
            "input_start_time": st.isoformat() if st else None,
            "input_end_time": et.isoformat() if et else None,
            "request_fingerprint": fp,
            "cache_hit": False,
            "status": "failed",
            "queued_at": now,
            "started_at": now,
            "finished_at": now,
            "error_code": "PAIR_DISABLED",
            "error_message": "Trading pair is not active",
            "binance_request_count": 0,
            "compute_time_ms": 0,
            "created_at": now,
            "updated_at": now,
        }
        jobs = _load(jobs_f); jobs.append(job); _save(jobs_f, jobs)
        return _err("CONFLICT", "pair is disabled", error_code="PAIR_DISABLED", job_id=job_id, pair_status=pair.get("status"))

    fp = _fingerprint({
        "tool": endpoint,
        "indicator_id": idef.get("id"),
        "pair_id": pair.get("id"),
        "interval": interval_use,
        "limit": candle_limit,
        "start_time": st.isoformat() if st else None,
        "end_time": et.isoformat() if et else None,
        "params": {"length": rlen},
    })

    jobs = _load(jobs_f)
    results = _load("computation_results.json")
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    cached_job = None
    for j in jobs:
        if j.get("status") == "succeeded" and j.get("request_fingerprint") == fp and j.get("finished_at") is not None:
            jr = None
            for r in results:
                if r.get("job_id") == j.get("id"):
                    jr = r
                    break
            if jr:
                exp = _norm_dt(_to_dt(jr.get("expires_at")))
                if exp is None or exp > now_dt:
                    cached_job = (j, jr)
                    break

    if cached_job:
        j, jr = cached_job
        now = _now_iso()
        job_id = _gen_id("job")
        job = {
            "id": job_id,
            "indicator_id": idef.get("id"),
            "pair_id": pair.get("id"),
            "interval": interval_use,
            "candle_limit": candle_limit,
            "input_start_time": st.isoformat() if st else None,
            "input_end_time": et.isoformat() if et else None,
            "request_fingerprint": fp,
            "cache_hit": True,
            "status": "succeeded",
            "queued_at": now,
            "started_at": now,
            "finished_at": now,
            "error_code": None,
            "error_message": None,
            "binance_request_count": 0,
            "compute_time_ms": 0,
            "created_at": now,
            "updated_at": now,
        }
        _log_job(job)
        return {
            "job": job,
            "pair": {"id": pair.get("id"), "exchange": pair.get("exchange"), "symbol": pair.get("symbol")},
            "indicator": {"id": idef.get("id"), "tool_name": idef.get("tool_name"), "status": idef.get("status")},
            "cache": {"hit": True, "source_job_id": j.get("id"), "result_id": jr.get("id")},
            "result": jr,
        }

    # Create and run job
    now = _now_iso()
    job_id = _gen_id("job")
    job = {
        "id": job_id,
        "indicator_id": idef.get("id"),
        "pair_id": pair.get("id"),
        "interval": interval_use,
        "candle_limit": candle_limit,
        "input_start_time": st.isoformat() if st else None,
        "input_end_time": et.isoformat() if et else None,
        "request_fingerprint": fp,
        "cache_hit": False,
        "status": "queued",
        "queued_at": now,
        "started_at": None,
        "finished_at": None,
        "error_code": None,
        "error_message": None,
        "binance_request_count": 0,
        "compute_time_ms": None,
        "created_at": now,
        "updated_at": now,
    }
    _log_job(job)

    start_iso = _now_iso()
    if not _update_job(job_id, {"status": "running", "started_at": start_iso, "updated_at": start_iso}):
        return _err("NOT_FOUND", "job disappeared", job_id=job_id)

    candles = _load("ohlcv_candles.json")
    csel = []
    for c in candles:
        if c.get("pair_id") != pair.get("id") or c.get("interval") != interval_use:
            continue
        ot = _norm_dt(_to_dt(c.get("open_time")))
        if ot is None:
            continue
        if st and ot < st:
            continue
        if et and ot > et:
            continue
        csel.append((ot, c))
    csel.sort(key=lambda x: x[0])
    if len(csel) > candle_limit:
        csel = csel[-candle_limit:]

    min_needed = int(idef.get("min_lookback_candles") or 1)
    required = max(min_needed, rlen)
    if len(csel) < required:
        fin = _now_iso()
        _update_job(job_id, {
            "status": "failed",
            "finished_at": fin,
            "updated_at": fin,
            "error_code": "INSUFFICIENT_DATA",
            "error_message": f"Need at least {required} candles, found {len(csel)}",
            "compute_time_ms": 0,
        })
        return _err("CONFLICT", "insufficient data", error_code="INSUFFICIENT_DATA", job_id=job_id, required=required, found=len(csel))

    closes = []
    times = []
    for ot, c in csel:
        try:
            closes.append(float(c["close"]))
            times.append(ot)
        except Exception:
            continue

    if len(closes) < required:
        fin = _now_iso()
        _update_job(job_id, {
            "status": "failed",
            "finished_at": fin,
            "updated_at": fin,
            "error_code": "INSUFFICIENT_DATA",
            "error_message": "Candle rows missing numeric close field",
            "compute_time_ms": 0,
        })
        return _err("CONFLICT", "insufficient data", error_code="INSUFFICIENT_DATA", job_id=job_id)

    # RMA (Wilder): rma_t = (rma_{t-1}*(len-1) + x_t)/len, seed with SMA over first len points
    rma_series = []
    seed = sum(closes[:rlen]) / float(rlen)
    rma = seed
    rma_series.append({"t": times[rlen-1].isoformat(), "v": rma})
    for i in range(rlen, len(closes)):
        rma = (rma * (rlen - 1) + closes[i]) / float(rlen)
        rma_series.append({"t": times[i].isoformat(), "v": rma})

    latest = rma_series[-1]
    as_of = latest["t"]
    latest_val = latest["v"]

    compute_ms = _lat_ms()
    res_id = _gen_id("res")
    ttl = idef.get("cache_ttl_seconds")
    expires_at = None
    if isinstance(ttl, int) and ttl > 0:
        expires_at = (datetime.datetime.now(datetime.timezone.utc) + datetime.timedelta(seconds=ttl)).isoformat()

    res = {
        "id": res_id,
        "job_id": job_id,
        "result_kind": "series",
        "as_of_time": as_of,
        "value": latest_val,
        "signal": None,
        "series": rma_series,
        "multi_series": None,
        "metadata": {"length": rlen, "interval": interval_use, "limit": candle_limit},
        "expires_at": expires_at,
        "created_at": _now_iso(),
        "updated_at": _now_iso(),
    }

    results = _load("computation_results.json")
    for r in results:
        if r.get("job_id") == job_id:
            fin = _now_iso()
            _update_job(job_id, {
                "status": "failed",
                "finished_at": fin,
                "updated_at": fin,
                "error_code": "CONFLICT",
                "error_message": "Result already exists for job_id",
                "compute_time_ms": compute_ms,
            })
            return _err("CONFLICT", "result already exists for job", job_id=job_id)

    results.append(res)
    _save("computation_results.json", results)

    fin = _now_iso()
    _update_job(job_id, {
        "status": "succeeded",
        "finished_at": fin,
        "updated_at": fin,
        "compute_time_ms": compute_ms,
        "error_code": None,
        "error_message": None,
    })

    return {
        "job": {**job, "status": "succeeded", "started_at": start_iso, "finished_at": fin, "updated_at": fin, "compute_time_ms": compute_ms},
        "pair": {"id": pair.get("id"), "exchange": pair.get("exchange"), "symbol": pair.get("symbol")},
        "indicator": {"id": idef.get("id"), "tool_name": idef.get("tool_name"), "status": idef.get("status")},
        "cache": {"hit": False},
        "latest": {"t": as_of, "value": latest_val},
        "result": res,
    }

def calculate_awesome_oscillator(symbol, interval=None, limit=None, **_extra):
    import json, os, datetime, hashlib, time, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0416000" if __import__("os").path.isdir("./environment_mix/0416000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "calculate_awesome_oscillator"
    allowed_intervals = ["1m","3m","5m","15m","30m","1h","2h","4h","6h","8h","12h","1d","3d","1w","1M"]

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _isoz(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            dt = v
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        if not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _get_rows(doc):
        if isinstance(doc, dict) and isinstance(doc.get("rows"), list):
            return doc["rows"]
        if isinstance(doc, list):
            return doc
        return []

    def _save_doc(fname, original, rows):
        if isinstance(original, dict) and isinstance(original.get("rows"), list):
            original["rows"] = rows
            _save(fname, original)
        else:
            _save(fname, rows)

    def _new_id(prefix):
        ts = datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%d%H%M%S%f")
        return f"{prefix}_{ts}_{os.urandom(3).hex()}"

    def _fingerprint(obj):
        s = json.dumps(obj, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _log(status, error_code=None, extra=None):
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            return
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": _new_id("req"),
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _isoz(_utcnow()),
        }
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save("request_logs.json", logs)

    try:
        if not isinstance(symbol, str) or not symbol.strip():
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "symbol must be a non-empty string", field="symbol")
        symbol_n = symbol.strip().upper()

        if interval is None:
            interval = "1d"
        if not isinstance(interval, str) or interval not in allowed_intervals:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "interval must be one of the supported Binance intervals", field="interval", allowed=allowed_intervals)

        if limit is None:
            limit = 200
        if not isinstance(limit, int) or limit < 1:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit must be an integer >= 1", field="limit")

        defs_doc = _load("indicator_definitions.json")
        defs_rows = _get_rows(defs_doc)
        idef = None
        for r in defs_rows:
            if isinstance(r, dict) and r.get("tool_name") == endpoint:
                idef = r
                break
        if not idef:
            _log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "indicator definition not found for tool", tool_name=endpoint)
        if not idef.get("is_enabled", False) or idef.get("status") not in ("active", "deprecated"):
            _log("error", "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Tool is not enabled or not available.", tool_name=endpoint, status=idef.get("status"), is_enabled=idef.get("is_enabled"))

        pairs_doc = _load("trading_pairs.json")
        pairs = _get_rows(pairs_doc)
        pair = None
        for p in pairs:
            if isinstance(p, dict) and p.get("exchange") == "binance" and str(p.get("symbol", "")).upper() == symbol_n:
                pair = p
                break
        if not pair:
            _log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "Trading pair symbol not found on exchange.", symbol=symbol_n, exchange="binance")
        if pair.get("status") != "active":
            _log("error", "INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", "Trading pair is not active; refusing new computation job.", error_code="PAIR_DISABLED", pair_id=pair.get("id"), status=pair.get("status"))

        norm = {"tool_name": endpoint, "pair_id": pair.get("id"), "interval": interval, "limit": int(limit)}
        fp = _fingerprint(norm)

        jobs_doc = _load("computation_jobs.json")
        jobs = _get_rows(jobs_doc)
        results_doc = _load("computation_results.json")
        results = _get_rows(results_doc)

        def _find_result_by_job(job_id):
            for rr in results:
                if isinstance(rr, dict) and rr.get("job_id") == job_id:
                    return rr
            return None

        now = _utcnow()
        cached_job = None
        cached_result = None
        for j in jobs:
            if not isinstance(j, dict):
                continue
            if j.get("request_fingerprint") != fp:
                continue
            if j.get("status") != "succeeded" or not j.get("finished_at"):
                continue
            r = _find_result_by_job(j.get("id"))
            if not r:
                continue
            exp = _parse_dt(r.get("expires_at"))
            if exp is not None and exp < now:
                continue
            cached_job = j
            cached_result = r
            break

        if cached_job and cached_result:
            new_job = {
                "id": _new_id("cijob"),
                "indicator_id": idef.get("id"),
                "pair_id": pair.get("id"),
                "interval": interval,
                "candle_limit": int(limit),
                "input_start_time": None,
                "input_end_time": None,
                "request_fingerprint": fp,
                "cache_hit": True,
                "status": "succeeded",
                "queued_at": _isoz(now),
                "started_at": _isoz(now),
                "finished_at": _isoz(now),
                "error_code": None,
                "error_message": None,
                "binance_request_count": 0,
                "compute_time_ms": 0,
                "created_at": _isoz(now),
                "updated_at": _isoz(now),
            }
            jobs.append(new_job)
            _save_doc("computation_jobs.json", jobs_doc, jobs)
            _log("ok", extra={"cache_hit": True})
            return {"tool_name": endpoint, "cache_hit": True, "job": new_job, "result": cached_result}

        job = {
            "id": _new_id("cijob"),
            "indicator_id": idef.get("id"),
            "pair_id": pair.get("id"),
            "interval": interval,
            "candle_limit": int(limit),
            "input_start_time": None,
            "input_end_time": None,
            "request_fingerprint": fp,
            "cache_hit": False,
            "status": "queued",
            "queued_at": _isoz(now),
            "started_at": None,
            "finished_at": None,
            "error_code": None,
            "error_message": None,
            "binance_request_count": 0,
            "compute_time_ms": None,
            "created_at": _isoz(now),
            "updated_at": _isoz(now),
        }
        jobs.append(job)
        _save_doc("computation_jobs.json", jobs_doc, jobs)

        job["status"] = "running"
        job["started_at"] = _isoz(_utcnow())
        job["updated_at"] = job["started_at"]
        _save_doc("computation_jobs.json", jobs_doc, jobs)

        candles_doc = _load("ohlcv_candles.json")
        candles = _get_rows(candles_doc)
        rows = [c for c in candles if isinstance(c, dict) and c.get("pair_id") == pair.get("id") and c.get("interval") == interval]
        rows.sort(key=lambda x: str(x.get("open_time") or ""))
        rows = rows[-int(limit):]

        required = int(idef.get("min_lookback_candles") or 1)
        if len(rows) < required:
            fin = _utcnow()
            job["status"] = "failed"
            job["finished_at"] = _isoz(fin)
            job["updated_at"] = _isoz(fin)
            job["error_code"] = "INSUFFICIENT_DATA"
            job["error_message"] = f"Need {required} lookback candles for interval {interval}; only {len(rows)} available."
            _save_doc("computation_jobs.json", jobs_doc, jobs)
            _log("error", "CONFLICT", extra={"error_code": "INSUFFICIENT_DATA"})
            return _err("CONFLICT", "Insufficient data to compute indicator.", error_code="INSUFFICIENT_DATA", required_candles=required, available_candles=len(rows), job_id=job["id"])

        # AO: difference between 5-period SMA and 34-period SMA of median price (high+low)/2
        med = [(float(c.get("high")) + float(c.get("low"))) / 2.0 for c in rows]
        times = [c.get("close_time") or c.get("open_time") for c in rows]

        def _sma(vals, p):
            p = int(p)
            if p <= 0 or len(vals) < p:
                return []
            out = []
            s = sum(vals[:p])
            out.append(s / p)
            for i in range(p, len(vals)):
                s += vals[i] - vals[i - p]
                out.append(s / p)
            return out

        sma5 = _sma(med, 5)
        sma34 = _sma(med, 34)
        # align: sma5 corresponds to med[4:], sma34 to med[33:]
        if not sma34:
            fin = _utcnow()
            job["status"] = "failed"
            job["finished_at"] = _isoz(fin)
            job["updated_at"] = _isoz(fin)
            job["error_code"] = "INSUFFICIENT_DATA"
            job["error_message"] = "Need at least 34 candles to compute Awesome Oscillator."
            _save_doc("computation_jobs.json", jobs_doc, jobs)
            _log("error", "CONFLICT", extra={"error_code": "INSUFFICIENT_DATA"})
            return _err("CONFLICT", "Insufficient data to compute indicator.", error_code="INSUFFICIENT_DATA", required_candles=max(required, 34), available_candles=len(rows), job_id=job["id"])

        start_idx = (34 - 1) - (5 - 1)  # offset into sma5 to align with sma34 index 0
        overlap_len = min(len(sma34), len(sma5) - start_idx)
        ao_series = []
        base_candle_index = 34 - 1
        for i in range(overlap_len):
            v = sma5[start_idx + i] - sma34[i]
            candle_idx = base_candle_index + i
            t = times[candle_idx] if 0 <= candle_idx < len(times) else times[-1]
            ao_series.append({"t": t, "v": v})

        latest = ao_series[-1]
        as_of_time = latest["t"]
        latest_value = latest["v"]

        fin = _utcnow()
        job["status"] = "succeeded"
        job["finished_at"] = _isoz(fin)
        job["updated_at"] = _isoz(fin)
        job["compute_time_ms"] = max(0, int((time.time() - t0) * 1000))
        _save_doc("computation_jobs.json", jobs_doc, jobs)

        ttl = idef.get("cache_ttl_seconds")
        expires_at = None
        if isinstance(ttl, int) and ttl > 0:
            expires_at = _isoz(fin + datetime.timedelta(seconds=int(ttl)))

        result_row = {
            "id": _new_id("cires"),
            "job_id": job["id"],
            "result_kind": "series",
            "as_of_time": as_of_time,
            "value": latest_value,
            "signal": None,
            "series": ao_series,
            "multi_series": None,
            "metadata": {"limit": limit, "fast_sma": 5, "slow_sma": 34},
            "expires_at": expires_at,
            "created_at": _isoz(fin),
            "updated_at": _isoz(fin),
        }
        for i, rr in enumerate(results):
            if isinstance(rr, dict) and rr.get("job_id") == job["id"]:
                results[i] = result_row
                break
        else:
            results.append(result_row)
        _save_doc("computation_results.json", results_doc, results)

        _log("ok")
        return {"tool_name": endpoint, "cache_hit": False, "job": job, "result": result_row}
    except Exception as e:
        _log("error", "CONFLICT")
        return _err("CONFLICT", "Unexpected server error.", details=str(e), tool_name=endpoint)

def calculate_ichimoku_cloud(symbol, interval=None, limit=None, **_extra):
    import json, os, datetime, time, hashlib, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0416000" if __import__("os").path.isdir("./environment_mix/0416000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "calculate_ichimoku_cloud"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(x):
        if x is None:
            return None
        if isinstance(x, (int, float)):
            try:
                return datetime.datetime.fromtimestamp(float(x), tz=datetime.timezone.utc)
            except Exception:
                return None
        if isinstance(x, str):
            s = x.strip()
            if not s:
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        return None

    def _dt_to_iso(dt):
        if dt is None:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat()

    def _new_id(prefix):
        return f"{prefix}_{datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%d%H%M%S%f')}"

    def _fingerprint(obj):
        s = json.dumps(obj, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _append_request_log(status, error_code=None):
        for fname in ("request_logs.json", "usage_logs.json", "audit_logs.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                logs = _load(fname)
                logs.append({
                    "id": _new_id("req"),
                    "endpoint": endpoint,
                    "status": status,
                    "error_code": error_code,
                    "latency_ms": int((time.time() - t0) * 1000),
                    "timestamp": _now_iso()
                })
                _save(fname, logs)
                break

    intervals = ["1m","3m","5m","15m","30m","1h","2h","4h","6h","8h","12h","1d","3d","1w","1M"]

    if not isinstance(symbol, str) or symbol.strip() == "":
        _append_request_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "symbol must be a non-empty string")
    symbol = symbol.strip()

    if interval is not None:
        if not isinstance(interval, str) or interval not in intervals:
            _append_request_log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "interval is not supported", allowed_intervals=intervals)
    if limit is not None:
        if not isinstance(limit, int) or limit < 1:
            _append_request_log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit must be an integer >= 1")

    trading_pairs = _load("trading_pairs.json")
    pair = next((r for r in trading_pairs if r.get("exchange") == "binance" and r.get("symbol") == symbol), None)
    if not pair:
        _append_request_log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "symbol could not be resolved", symbol=symbol, exchange="binance")
    if pair.get("status") != "active":
        indicator_defs = _load("indicator_definitions.json")
        idef = next((d for d in indicator_defs if d.get("tool_name") == endpoint), None)
        jobs = _load("computation_jobs.json")
        now = _now_iso()
        if idef:
            use_interval = interval or idef.get("default_interval")
            use_limit = limit or idef.get("default_limit")
            fp = _fingerprint({"tool": endpoint, "indicator_id": idef.get("id"), "pair_id": pair.get("id"), "interval": use_interval, "limit": int(use_limit), "start": None, "end": None})
            job_id = _new_id("job")
            jobs.append({
                "id": job_id,
                "indicator_id": idef.get("id"),
                "pair_id": pair.get("id"),
                "interval": use_interval,
                "candle_limit": int(use_limit),
                "input_start_time": None,
                "input_end_time": None,
                "request_fingerprint": fp,
                "cache_hit": False,
                "status": "failed",
                "queued_at": now,
                "started_at": now,
                "finished_at": now,
                "error_code": "PAIR_DISABLED",
                "error_message": "Trading pair is not active",
                "binance_request_count": 0,
                "compute_time_ms": 0,
                "created_at": now,
                "updated_at": now
            })
            _save("computation_jobs.json", jobs)
        _append_request_log("error", "PAIR_DISABLED")
        return _err("CONFLICT", "trading pair is not active for new computations", error_code="PAIR_DISABLED", pair_status=pair.get("status"))

    indicator_defs = _load("indicator_definitions.json")
    idef = next((d for d in indicator_defs if d.get("tool_name") == endpoint), None)
    if not idef:
        _append_request_log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "indicator definition not found", tool_name=endpoint)
    if not idef.get("is_enabled", False) or idef.get("status") not in ("active", "deprecated"):
        _append_request_log("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "tool is not enabled", tool_name=endpoint, status=idef.get("status"), is_enabled=idef.get("is_enabled"))

    use_interval = interval or idef.get("default_interval")
    if use_interval not in intervals:
        _append_request_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "interval is not supported", allowed_intervals=intervals)
    use_limit = limit if limit is not None else idef.get("default_limit")
    if not isinstance(use_limit, int) or use_limit < 1:
        _append_request_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer >= 1")

    min_lookback = idef.get("min_lookback_candles")
    if not isinstance(min_lookback, int) or min_lookback < 1:
        _append_request_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "indicator definition has invalid min_lookback_candles")

    fp = _fingerprint({"tool": endpoint, "indicator_id": idef.get("id"), "pair_id": pair.get("id"), "interval": use_interval, "limit": int(use_limit), "start": None, "end": None})

    jobs = _load("computation_jobs.json")
    results = _load("computation_results.json")

    cached_result = None
    for j in jobs:
        if j.get("request_fingerprint") == fp and j.get("status") == "succeeded" and j.get("finished_at") is not None:
            r = next((rr for rr in results if rr.get("job_id") == j.get("id")), None)
            if not r:
                continue
            exp = _parse_dt(r.get("expires_at"))
            nowdt = datetime.datetime.now(datetime.timezone.utc)
            if exp is None or exp > nowdt:
                cached_result = r
                break

    now = _now_iso()
    job_id = _new_id("job")
    jobs.append({
        "id": job_id,
        "indicator_id": idef.get("id"),
        "pair_id": pair.get("id"),
        "interval": use_interval,
        "candle_limit": int(use_limit),
        "input_start_time": None,
        "input_end_time": None,
        "request_fingerprint": fp,
        "cache_hit": bool(cached_result),
        "status": "queued",
        "queued_at": now,
        "started_at": None,
        "finished_at": None,
        "error_code": None,
        "error_message": None,
        "binance_request_count": 0,
        "compute_time_ms": None,
        "created_at": now,
        "updated_at": now
    })
    _save("computation_jobs.json", jobs)

    if cached_result:
        jobs = _load("computation_jobs.json")
        for jj in jobs:
            if jj.get("id") == job_id:
                jj["status"] = "succeeded"
                jj["started_at"] = now
                jj["finished_at"] = now
                jj["compute_time_ms"] = 0
                jj["updated_at"] = now
                break
        _save("computation_jobs.json", jobs)
        _append_request_log("ok", None)
        return {
            "tool": endpoint,
            "symbol": symbol,
            "interval": use_interval,
            "limit": int(use_limit),
            "job": {"id": job_id, "cache_hit": True, "status": "succeeded"},
            "result": cached_result
        }

    # running
    jobs = _load("computation_jobs.json")
    for jj in jobs:
        if jj.get("id") == job_id:
            jj["status"] = "running"
            jj["started_at"] = _now_iso()
            jj["updated_at"] = jj["started_at"]
            break
    _save("computation_jobs.json", jobs)

    candles = _load("ohlcv_candles.json")
    scoped = [c for c in candles if c.get("pair_id") == pair.get("id") and c.get("interval") == use_interval]
    parsed = []
    for c in scoped:
        ot = _parse_dt(c.get("open_time"))
        if ot is None:
            continue
        parsed.append((ot, c))
    parsed.sort(key=lambda x: x[0])
    if not parsed:
        now2 = _now_iso()
        jobs = _load("computation_jobs.json")
        for jj in jobs:
            if jj.get("id") == job_id:
                jj["status"] = "failed"
                jj["finished_at"] = now2
                jj["updated_at"] = now2
                jj["error_code"] = "NOT_FOUND"
                jj["error_message"] = "No candle data available for symbol/interval"
                jj["compute_time_ms"] = 0
                break
        _save("computation_jobs.json", jobs)
        _append_request_log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "candle data for the interval cannot be retrieved", symbol=symbol, interval=use_interval)

    window = [c for _, c in parsed[-int(use_limit):]]
    if len(window) < int(min_lookback):
        now2 = _now_iso()
        jobs = _load("computation_jobs.json")
        for jj in jobs:
            if jj.get("id") == job_id:
                jj["status"] = "failed"
                jj["finished_at"] = now2
                jj["updated_at"] = now2
                jj["error_code"] = "INSUFFICIENT_DATA"
                jj["error_message"] = f"Need at least {min_lookback} candles, have {len(window)}"
                jj["compute_time_ms"] = 0
                break
        _save("computation_jobs.json", jobs)
        _append_request_log("error", "INSUFFICIENT_DATA")
        return _err("CONFLICT", "insufficient candle data to compute indicator", error_code="INSUFFICIENT_DATA", required=min_lookback, available=len(window))

    # Ichimoku (standard): tenkan=9, kijun=26, senkouA=(tenkan+kijun)/2 shifted +26, senkouB=52 mid shifted +26, chikou=close shifted -26
    start_compute = time.time()
    highs = []
    lows = []
    closes = []
    ts = []
    for c in window:
        h = c.get("high"); l = c.get("low"); cl = c.get("close")
        if not all(isinstance(x, (int, float)) for x in (h, l, cl)):
            continue
        highs.append(float(h)); lows.append(float(l)); closes.append(float(cl))
        ts.append(c.get("close_time") or c.get("open_time"))

    def mid_of_hl(hs, ls, i, n):
        if i + 1 < n:
            return None
        hh = max(hs[i-n+1:i+1])
        ll = min(ls[i-n+1:i+1])
        return (hh + ll) / 2.0

    tenkan = [mid_of_hl(highs, lows, i, 9) for i in range(len(highs))]
    kijun = [mid_of_hl(highs, lows, i, 26) for i in range(len(highs))]
    senkou_b_raw = [mid_of_hl(highs, lows, i, 52) for i in range(len(highs))]
    shift = 26
    senkou_a = [None] * len(highs)
    senkou_b = [None] * len(highs)
    chikou = [None] * len(highs)
    for i in range(len(highs)):
        if tenkan[i] is not None and kijun[i] is not None:
            j = i + shift
            if j < len(highs):
                senkou_a[j] = (tenkan[i] + kijun[i]) / 2.0
        if senkou_b_raw[i] is not None:
            j = i + shift
            if j < len(highs):
                senkou_b[j] = senkou_b_raw[i]
        j2 = i - shift
        if j2 >= 0:
            chikou[j2] = closes[i]

    # latest available values at the end of window
    def latest_non_none(arr):
        for i in range(len(arr)-1, -1, -1):
            v = arr[i]
            if v is not None and isinstance(v, (int, float)) and math.isfinite(v):
                return i, v
        return None, None

    i_t, v_t = latest_non_none(tenkan)
    i_k, v_k = latest_non_none(kijun)
    i_sa, v_sa = latest_non_none(senkou_a)
    i_sb, v_sb = latest_non_none(senkou_b)
    i_c, v_c = latest_non_none(chikou)

    # Require at least some meaningful outputs; otherwise insufficient data
    if all(v is None for v in (v_t, v_k, v_sa, v_sb, v_c)):
        now2 = _now_iso()
        jobs = _load("computation_jobs.json")
        for jj in jobs:
            if jj.get("id") == job_id:
                jj["status"] = "failed"
                jj["finished_at"] = now2
                jj["updated_at"] = now2
                jj["error_code"] = "INSUFFICIENT_DATA"
                jj["error_message"] = "Not enough data to compute Ichimoku components"
                jj["compute_time_ms"] = int((time.time() - start_compute) * 1000)
                break
        _save("computation_jobs.json", jobs)
        _append_request_log("error", "INSUFFICIENT_DATA")
        return _err("CONFLICT", "insufficient candle data to compute indicator", error_code="INSUFFICIENT_DATA")

    as_of_time = ts[-1] if ts else _now_iso()
    compute_ms = int((time.time() - start_compute) * 1000)

    def to_series(arr, name):
        pts = []
        for i, v in enumerate(arr):
            if v is None:
                continue
            pts.append({"t": ts[i], "v": v})
        return pts

    multi = {
        "tenkan_sen": to_series(tenkan, "tenkan_sen"),
        "kijun_sen": to_series(kijun, "kijun_sen"),
        "senkou_span_a": to_series(senkou_a, "senkou_span_a"),
        "senkou_span_b": to_series(senkou_b, "senkou_span_b"),
        "chikou_span": to_series(chikou, "chikou_span")
    }

    latest_values = {
        "tenkan_sen": v_t,
        "kijun_sen": v_k,
        "senkou_span_a": v_sa,
        "senkou_span_b": v_sb,
        "chikou_span": v_c
    }

    now2 = _now_iso()
    ttl = idef.get("cache_ttl_seconds")
    expires_at = None
    if isinstance(ttl, int) and ttl > 0:
        expdt = datetime.datetime.now(datetime.timezone.utc) + datetime.timedelta(seconds=int(ttl))
        expires_at = _dt_to_iso(expdt)

    results = _load("computation_results.json")
    res_id = _new_id("res")
    res_row = {
        "id": res_id,
        "job_id": job_id,
        "result_kind": "multi_series",
        "as_of_time": as_of_time,
        "value": None,
        "signal": None,
        "series": None,
        "multi_series": multi,
        "metadata": {"name": "Ichimoku", "params": {"tenkan": 9, "kijun": 26, "senkou_b": 52, "shift": 26}, "latest": latest_values, "source": "custom"},
        "expires_at": expires_at,
        "created_at": now2,
        "updated_at": now2
    }
    results.append(res_row)
    _save("computation_results.json", results)

    jobs = _load("computation_jobs.json")
    for jj in jobs:
        if jj.get("id") == job_id:
            jj["status"] = "succeeded"
            jj["finished_at"] = now2
            jj["updated_at"] = now2
            if jj.get("started_at") is None:
                jj["started_at"] = now2
            jj["compute_time_ms"] = compute_ms
            break
    _save("computation_jobs.json", jobs)

    _append_request_log("ok", None)
    return {
        "tool": endpoint,
        "symbol": symbol,
        "interval": use_interval,
        "limit": int(use_limit),
        "job": {"id": job_id, "cache_hit": False, "status": "succeeded"},
        "result": res_row
    }

def calculate_percentage_price_oscillator(symbol, interval=None, limit=None, **_extra):
    import json, os, datetime, time, hashlib, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0416000" if __import__("os").path.isdir("./environment_mix/0416000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "calculate_percentage_price_oscillator"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(x):
        if x is None:
            return None
        if isinstance(x, (int, float)):
            try:
                return datetime.datetime.fromtimestamp(float(x), tz=datetime.timezone.utc)
            except Exception:
                return None
        if isinstance(x, str):
            s = x.strip()
            if not s:
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        return None

    def _dt_to_iso(dt):
        if dt is None:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat()

    def _new_id(prefix):
        return f"{prefix}_{datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%d%H%M%S%f')}"

    def _fingerprint(obj):
        s = json.dumps(obj, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _append_request_log(status, error_code=None):
        for fname in ("request_logs.json", "usage_logs.json", "audit_logs.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                logs = _load(fname)
                logs.append({
                    "id": _new_id("req"),
                    "endpoint": endpoint,
                    "status": status,
                    "error_code": error_code,
                    "latency_ms": int((time.time() - t0) * 1000),
                    "timestamp": _now_iso()
                })
                _save(fname, logs)
                break

    intervals = ["1m","3m","5m","15m","30m","1h","2h","4h","6h","8h","12h","1d","3d","1w","1M"]

    if not isinstance(symbol, str) or symbol.strip() == "":
        _append_request_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "symbol must be a non-empty string")
    symbol = symbol.strip()

    if interval is not None:
        if not isinstance(interval, str) or interval not in intervals:
            _append_request_log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "interval is not supported", allowed_intervals=intervals)
    if limit is not None:
        if not isinstance(limit, int) or limit < 1:
            _append_request_log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit must be an integer >= 1")

    trading_pairs = _load("trading_pairs.json")
    pair = next((r for r in trading_pairs if r.get("exchange") == "binance" and r.get("symbol") == symbol), None)
    if not pair:
        _append_request_log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "symbol could not be resolved", symbol=symbol, exchange="binance")
    if pair.get("status") != "active":
        indicator_defs = _load("indicator_definitions.json")
        idef = next((d for d in indicator_defs if d.get("tool_name") == endpoint), None)
        jobs = _load("computation_jobs.json")
        now = _now_iso()
        if idef:
            use_interval = interval or idef.get("default_interval")
            use_limit = limit or idef.get("default_limit")
            fp = _fingerprint({"tool": endpoint, "indicator_id": idef.get("id"), "pair_id": pair.get("id"), "interval": use_interval, "limit": int(use_limit), "start": None, "end": None})
            job_id = _new_id("job")
            jobs.append({
                "id": job_id,
                "indicator_id": idef.get("id"),
                "pair_id": pair.get("id"),
                "interval": use_interval,
                "candle_limit": int(use_limit),
                "input_start_time": None,
                "input_end_time": None,
                "request_fingerprint": fp,
                "cache_hit": False,
                "status": "failed",
                "queued_at": now,
                "started_at": now,
                "finished_at": now,
                "error_code": "PAIR_DISABLED",
                "error_message": "Trading pair is not active",
                "binance_request_count": 0,
                "compute_time_ms": 0,
                "created_at": now,
                "updated_at": now
            })
            _save("computation_jobs.json", jobs)
        _append_request_log("error", "PAIR_DISABLED")
        return _err("CONFLICT", "trading pair is not active for new computations", error_code="PAIR_DISABLED", pair_status=pair.get("status"))

    indicator_defs = _load("indicator_definitions.json")
    idef = next((d for d in indicator_defs if d.get("tool_name") == endpoint), None)
    if not idef:
        _append_request_log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "indicator definition not found", tool_name=endpoint)
    if not idef.get("is_enabled", False) or idef.get("status") not in ("active", "deprecated"):
        _append_request_log("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "tool is not enabled", tool_name=endpoint, status=idef.get("status"), is_enabled=idef.get("is_enabled"))

    use_interval = interval or idef.get("default_interval")
    if use_interval not in intervals:
        _append_request_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "interval is not supported", allowed_intervals=intervals)
    use_limit = limit if limit is not None else idef.get("default_limit")
    if not isinstance(use_limit, int) or use_limit < 1:
        _append_request_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer >= 1")

    min_lookback = idef.get("min_lookback_candles")
    if not isinstance(min_lookback, int) or min_lookback < 1:
        _append_request_log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "indicator definition has invalid min_lookback_candles")

    fp = _fingerprint({"tool": endpoint, "indicator_id": idef.get("id"), "pair_id": pair.get("id"), "interval": use_interval, "limit": int(use_limit), "start": None, "end": None})

    jobs = _load("computation_jobs.json")
    results = _load("computation_results.json")

    cached_result = None
    for j in jobs:
        if j.get("request_fingerprint") == fp and j.get("status") == "succeeded" and j.get("finished_at") is not None:
            r = next((rr for rr in results if rr.get("job_id") == j.get("id")), None)
            if not r:
                continue
            exp = _parse_dt(r.get("expires_at"))
            nowdt = datetime.datetime.now(datetime.timezone.utc)
            if exp is None or exp > nowdt:
                cached_result = r
                break

    now = _now_iso()
    job_id = _new_id("job")
    jobs.append({
        "id": job_id,
        "indicator_id": idef.get("id"),
        "pair_id": pair.get("id"),
        "interval": use_interval,
        "candle_limit": int(use_limit),
        "input_start_time": None,
        "input_end_time": None,
        "request_fingerprint": fp,
        "cache_hit": bool(cached_result),
        "status": "queued",
        "queued_at": now,
        "started_at": None,
        "finished_at": None,
        "error_code": None,
        "error_message": None,
        "binance_request_count": 0,
        "compute_time_ms": None,
        "created_at": now,
        "updated_at": now
    })
    _save("computation_jobs.json", jobs)

    if cached_result:
        jobs = _load("computation_jobs.json")
        for jj in jobs:
            if jj.get("id") == job_id:
                jj["status"] = "succeeded"
                jj["started_at"] = now
                jj["finished_at"] = now
                jj["compute_time_ms"] = 0
                jj["updated_at"] = now
                break
        _save("computation_jobs.json", jobs)
        _append_request_log("ok", None)
        return {
            "tool": endpoint,
            "symbol": symbol,
            "interval": use_interval,
            "limit": int(use_limit),
            "job": {"id": job_id, "cache_hit": True, "status": "succeeded"},
            "result": cached_result
        }

    # running
    jobs = _load("computation_jobs.json")
    for jj in jobs:
        if jj.get("id") == job_id:
            jj["status"] = "running"
            jj["started_at"] = _now_iso()
            jj["updated_at"] = jj["started_at"]
            break
    _save("computation_jobs.json", jobs)

    candles = _load("ohlcv_candles.json")
    scoped = [c for c in candles if c.get("pair_id") == pair.get("id") and c.get("interval") == use_interval]
    parsed = []
    for c in scoped:
        ot = _parse_dt(c.get("open_time"))
        if ot is None:
            continue
        parsed.append((ot, c))
    parsed.sort(key=lambda x: x[0])
    if not parsed:
        now2 = _now_iso()
        jobs = _load("computation_jobs.json")
        for jj in jobs:
            if jj.get("id") == job_id:
                jj["status"] = "failed"
                jj["finished_at"] = now2
                jj["updated_at"] = now2
                jj["error_code"] = "NOT_FOUND"
                jj["error_message"] = "No candle data available for symbol/interval"
                jj["compute_time_ms"] = 0
                break
        _save("computation_jobs.json", jobs)
        _append_request_log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "candle data for the interval cannot be retrieved", symbol=symbol, interval=use_interval)

    window = [c for _, c in parsed[-int(use_limit):]]
    if len(window) < int(min_lookback):
        now2 = _now_iso()
        jobs = _load("computation_jobs.json")
        for jj in jobs:
            if jj.get("id") == job_id:
                jj["status"] = "failed"
                jj["finished_at"] = now2
                jj["updated_at"] = now2
                jj["error_code"] = "INSUFFICIENT_DATA"
                jj["error_message"] = f"Need at least {min_lookback} candles, have {len(window)}"
                jj["compute_time_ms"] = 0
                break
        _save("computation_jobs.json", jobs)
        _append_request_log("error", "INSUFFICIENT_DATA")
        return _err("CONFLICT", "insufficient candle data to compute indicator", error_code="INSUFFICIENT_DATA", required=min_lookback, available=len(window))

    # PPO: ((EMA_fast - EMA_slow)/EMA_slow) * 100, typical defaults 12/26
    fast = 12
    slow = 26

    start_compute = time.time()
    closes = []
    ts = []
    for c in window:
        cl = c.get("close")
        if not isinstance(cl, (int, float)):
            continue
        closes.append(float(cl))
        ts.append(c.get("close_time") or c.get("open_time"))

    def ema(vals, n):
        if len(vals) < n:
            return [None] * len(vals)
        out = [None] * len(vals)
        k = 2.0 / (n + 1.0)
        seed = sum(vals[:n]) / n
        out[n-1] = seed
        prev = seed
        for i in range(n, len(vals)):
            prev = (vals[i] - prev) * k + prev
            out[i] = prev
        return out

    ema_f = ema(closes, fast)
    ema_s = ema(closes, slow)
    ppo = []
    for i in range(len(closes)):
        if ema_f[i] is None or ema_s[i] is None:
            ppo.append(None)
        else:
            denom = ema_s[i]
            if denom == 0:
                ppo.append(None)
            else:
                ppo.append(((ema_f[i] - ema_s[i]) / denom) * 100.0)

    latest_idx = None
    for i in range(len(ppo)-1, -1, -1):
        if ppo[i] is not None and isinstance(ppo[i], (int, float)) and math.isfinite(ppo[i]):
            latest_idx = i
            break
    if latest_idx is None:
        now2 = _now_iso()
        jobs = _load("computation_jobs.json")
        for jj in jobs:
            if jj.get("id") == job_id:
                jj["status"] = "failed"
                jj["finished_at"] = now2
                jj["updated_at"] = now2
                jj["error_code"] = "INSUFFICIENT_DATA"
                jj["error_message"] = f"Not enough data to compute PPO({fast},{slow})"
                jj["compute_time_ms"] = int((time.time() - start_compute) * 1000)
                break
        _save("computation_jobs.json", jobs)
        _append_request_log("error", "INSUFFICIENT_DATA")
        return _err("CONFLICT", "insufficient candle data to compute indicator", error_code="INSUFFICIENT_DATA")

    series = [{"t": ts[i], "v": ppo[i]} for i in range(len(ppo)) if ppo[i] is not None]
    as_of_time = ts[latest_idx]
    latest_value = ppo[latest_idx]

    now2 = _now_iso()
    compute_ms = int((time.time() - start_compute) * 1000)

    ttl = idef.get("cache_ttl_seconds")
    expires_at = None
    if isinstance(ttl, int) and ttl > 0:
        expdt = datetime.datetime.now(datetime.timezone.utc) + datetime.timedelta(seconds=int(ttl))
        expires_at = _dt_to_iso(expdt)

    results = _load("computation_results.json")
    res_id = _new_id("res")
    res_row = {
        "id": res_id,
        "job_id": job_id,
        "result_kind": "series",
        "as_of_time": as_of_time,
        "value": latest_value,
        "signal": None,
        "series": series,
        "multi_series": None,
        "metadata": {"name": "PPO", "params": {"fast": fast, "slow": slow}, "source": "custom"},
        "expires_at": expires_at,
        "created_at": now2,
        "updated_at": now2
    }
    results.append(res_row)
    _save("computation_results.json", results)

    jobs = _load("computation_jobs.json")
    for jj in jobs:
        if jj.get("id") == job_id:
            jj["status"] = "succeeded"
            jj["finished_at"] = now2
            jj["updated_at"] = now2
            if jj.get("started_at") is None:
                jj["started_at"] = now2
            jj["compute_time_ms"] = compute_ms
            break
    _save("computation_jobs.json", jobs)

    _append_request_log("ok", None)
    return {
        "tool": endpoint,
        "symbol": symbol,
        "interval": use_interval,
        "limit": int(use_limit),
        "job": {"id": job_id, "cache_hit": False, "status": "succeeded"},
        "result": res_row
    }

def calculate_williams_r(symbol, interval=None, limit=None, period=None, as_of_time=None, return_kind=None, use_cache=None, **_extra):
    import json, os, datetime, time, hashlib, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0416000" if __import__("os").path.isdir("./environment_mix/0416000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "calculate_williams_r"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return None
        try:
            # Accept trailing Z
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    def _to_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            dt = v
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        if isinstance(v, str):
            return _parse_dt(v)
        return None

    def _audit(status, credential_used=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + hashlib.sha256(f"{endpoint}:{_now_iso()}:{len(logs)}".encode("utf-8")).hexdigest()[:16],
            "endpoint": endpoint,
            "credential_used": credential_used,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
        })
        _save("request_logs.json", logs)

    allowed_intervals = ["1m","3m","5m","15m","30m","1h","2h","4h","6h","8h","12h","1d","3d","1w","1M"]
    allowed_return = ["value","series","latest"]

    # Validate inputs
    if not isinstance(symbol, str) or symbol.strip() == "":
        _audit("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "symbol must be a non-empty string")

    if interval is not None and interval not in allowed_intervals:
        _audit("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "interval is not allowed", allowed=allowed_intervals)

    if return_kind is not None and return_kind not in allowed_return:
        _audit("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "return_kind is not allowed", allowed=allowed_return)

    if limit is not None and (not isinstance(limit, int) or limit < 1):
        _audit("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer >= 1")

    if period is not None and (not isinstance(period, int) or period < 1):
        _audit("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "period must be an integer >= 1")

    as_of_dt = None
    if as_of_time is not None:
        as_of_dt = _parse_dt(as_of_time)
        if as_of_dt is None:
            _audit("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "as_of_time must be a valid date-time string")

    if use_cache is not None and not isinstance(use_cache, bool):
        _audit("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "use_cache must be a boolean")

    # Resolve indicator definition for this tool
    defs = _load("indicator_definitions.json")
    idef = None
    if isinstance(defs, list):
        for d in defs:
            if d.get("tool_name") == endpoint:
                idef = d
                break
    if not idef:
        _audit("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "indicator definition not found for tool", tool_name=endpoint)

    if not idef.get("is_enabled", False) or idef.get("status") not in ("active", "deprecated"):
        _audit("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "tool is not enabled")

    interval_eff = interval or idef.get("default_interval")
    if interval_eff not in allowed_intervals:
        _audit("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "effective interval is not allowed", allowed=allowed_intervals)

    min_lookback = idef.get("min_lookback_candles")
    if not isinstance(min_lookback, int) or min_lookback < 1:
        _audit("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "indicator definition has invalid min_lookback_candles")

    limit_eff = limit if limit is not None else idef.get("default_limit")
    if not isinstance(limit_eff, int) or limit_eff < 1:
        _audit("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "effective limit must be >= 1")

    # Require enough candles for the indicator definition lookback; also need >= period for meaningful WILLR
    period_eff = period if period is not None else 14
    if limit_eff < 1 or period_eff < 1:
        _audit("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit and period must be >= 1")
    required_candles = max(min_lookback, period_eff)

    # Find trading pair by symbol on binance
    pairs = _load("trading_pairs.json")
    pair = None
    if isinstance(pairs, list):
        for p in pairs:
            if p.get("exchange") == "binance" and p.get("symbol") == symbol:
                pair = p
                break
    if not pair:
        _audit("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "trading pair not found", symbol=symbol, exchange="binance")

    if pair.get("status") != "active":
        # Create failed job row per rules
        jobs = _load("computation_jobs.json")
        if not isinstance(jobs, list): jobs = []
        now = _now_iso()
        job_id = "job_" + hashlib.sha256(f"{endpoint}:{symbol}:{interval_eff}:{now}".encode("utf-8")).hexdigest()[:16]
        jobs.append({
            "id": job_id,
            "indicator_id": idef.get("id"),
            "pair_id": pair.get("id"),
            "interval": interval_eff,
            "candle_limit": limit_eff,
            "input_start_time": None,
            "input_end_time": as_of_dt.isoformat() if as_of_dt else None,
            "request_fingerprint": hashlib.sha256(f"{endpoint}|{pair.get('id')}|{interval_eff}|{limit_eff}|{period_eff}|{as_of_dt.isoformat() if as_of_dt else ''}|{return_kind or ''}".encode("utf-8")).hexdigest(),
            "cache_hit": False,
            "status": "failed",
            "queued_at": now,
            "started_at": now,
            "finished_at": now,
            "error_code": "PAIR_DISABLED",
            "error_message": "Trading pair is not active",
            "binance_request_count": 0,
            "compute_time_ms": 0,
            "created_at": now,
            "updated_at": now,
        })
        _save("computation_jobs.json", jobs)
        _audit("error", error_code="PAIR_DISABLED")
        return _err("INVALID_TRANSITION", "trading pair is not active for new computations", error_code="PAIR_DISABLED")

    # Compute request fingerprint (normalized)
    fp_obj = {
        "tool": endpoint,
        "indicator_id": idef.get("id"),
        "pair_id": pair.get("id"),
        "interval": interval_eff,
        "limit": limit_eff,
        "period": period_eff,
        "as_of_time": as_of_dt.isoformat() if as_of_dt else None,
        "return_kind": return_kind or None,
    }
    fp = hashlib.sha256(json.dumps(fp_obj, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()

    # Cache check
    if use_cache is None:
        use_cache_eff = True
    else:
        use_cache_eff = use_cache

    jobs = _load("computation_jobs.json")
    results = _load("computation_results.json")
    if not isinstance(jobs, list): jobs = []
    if not isinstance(results, list): results = []

    def _result_by_jobid(jid):
        for r in results:
            if r.get("job_id") == jid:
                return r
        return None

    if use_cache_eff:
        # Find a succeeded job with same fingerprint and a non-expired result
        now_dt = datetime.datetime.now(datetime.timezone.utc)
        cached_job = None
        cached_res = None
        for j in jobs:
            if j.get("request_fingerprint") == fp and j.get("status") == "succeeded" and j.get("finished_at"):
                r = _result_by_jobid(j.get("id"))
                if not r:
                    continue
                exp = _to_dt(r.get("expires_at"))
                if exp is None or exp > now_dt:
                    cached_job = j
                    cached_res = r
                    break
        if cached_job and cached_res:
            payload = {
                "job": cached_job,
                "cached": True,
                "result_kind": cached_res.get("result_kind"),
                "as_of_time": cached_res.get("as_of_time"),
                "value": cached_res.get("value"),
                "series": cached_res.get("series"),
                "metadata": cached_res.get("metadata"),
            }
            rk = return_kind or "value"
            # shape response per return_kind
            out = {"symbol": symbol, "interval": interval_eff, "indicator": "williams_r", "cache_hit": True, "job_id": cached_job.get("id")}
            if rk == "value":
                out["value"] = cached_res.get("value")
                out["as_of_time"] = cached_res.get("as_of_time")
            elif rk == "series":
                out["series"] = cached_res.get("series") or []
                out["as_of_time"] = cached_res.get("as_of_time")
            else:  # latest
                out["value"] = cached_res.get("value")
                out["series"] = cached_res.get("series") or []
                out["as_of_time"] = cached_res.get("as_of_time")
            _audit("ok")
            return out

    # Create job queued -> running -> terminal
    now = _now_iso()
    job_id = "job_" + hashlib.sha256(f"{fp}:{now}".encode("utf-8")).hexdigest()[:16]
    job = {
        "id": job_id,
        "indicator_id": idef.get("id"),
        "pair_id": pair.get("id"),
        "interval": interval_eff,
        "candle_limit": limit_eff,
        "input_start_time": None,
        "input_end_time": as_of_dt.isoformat() if as_of_dt else None,
        "request_fingerprint": fp,
        "cache_hit": False,
        "status": "queued",
        "queued_at": now,
        "started_at": None,
        "finished_at": None,
        "error_code": None,
        "error_message": None,
        "binance_request_count": 0,
        "compute_time_ms": None,
        "created_at": now,
        "updated_at": now,
    }
    jobs.append(job)
    _save("computation_jobs.json", jobs)

    # Transition queued -> running
    for j in jobs:
        if j.get("id") == job_id:
            j["status"] = "running"
            j["started_at"] = _now_iso()
            j["updated_at"] = j["started_at"]
            break
    _save("computation_jobs.json", jobs)

    # Load candles
    candles = _load("ohlcv_candles.json")
    if not isinstance(candles, list):
        candles = []

    # filter by pair_id interval, optional as_of_time (close_time <= as_of)
    pid = pair.get("id")
    filtered = []
    for c in candles:
        if c.get("pair_id") != pid or c.get("interval") != interval_eff:
            continue
        ct = _to_dt(c.get("close_time"))
        ot = _to_dt(c.get("open_time"))
        if ct is None or ot is None:
            continue
        if as_of_dt and ct > as_of_dt:
            continue
        filtered.append(c)

    # order by open_time asc
    filtered.sort(key=lambda x: (_to_dt(x.get("open_time")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)))

    # take most recent limit_eff
    if len(filtered) > limit_eff:
        filtered = filtered[-limit_eff:]

    # Ensure enough candles
    if len(filtered) < required_candles:
        # fail job
        now2 = _now_iso()
        for j in jobs:
            if j.get("id") == job_id:
                j["status"] = "failed"
                j["finished_at"] = now2
                j["updated_at"] = now2
                j["error_code"] = "INSUFFICIENT_DATA"
                j["error_message"] = f"Need at least {required_candles} candles, got {len(filtered)}"
                j["compute_time_ms"] = int((time.time() - t0) * 1000)
                break
        _save("computation_jobs.json", jobs)
        _audit("error", error_code="INSUFFICIENT_DATA")
        return _err("CONFLICT", "insufficient candles to compute indicator", error_code="INSUFFICIENT_DATA", required=required_candles, available=len(filtered))

    # Compute WILLR series (aligned to candle close_time)
    start_compute = time.time()
    highs = [float(c["high"]) for c in filtered]
    lows = [float(c["low"]) for c in filtered]
    closes = [float(c["close"]) for c in filtered]
    times = [(_to_dt(c.get("close_time")) or _to_dt(c.get("open_time"))).isoformat() for c in filtered]

    series = []
    latest_val = None
    for i in range(len(filtered)):
        if i + 1 < period_eff:
            continue
        window_high = max(highs[i+1-period_eff:i+1])
        window_low = min(lows[i+1-period_eff:i+1])
        denom = (window_high - window_low)
        if denom == 0:
            val = 0.0
        else:
            val = -100.0 * ((window_high - closes[i]) / denom)
        latest_val = val
        series.append({"t": times[i], "v": val})

    as_of_out = series[-1]["t"] if series else times[-1]
    ttl = idef.get("cache_ttl_seconds", 0)
    expires_at = None
    if isinstance(ttl, int) and ttl > 0:
        expires_at = (datetime.datetime.now(datetime.timezone.utc) + datetime.timedelta(seconds=ttl)).isoformat()

    # Succeed job and write result
    now3 = _now_iso()
    for j in jobs:
        if j.get("id") == job_id:
            j["status"] = "succeeded"
            j["finished_at"] = now3
            j["updated_at"] = now3
            j["error_code"] = None
            j["error_message"] = None
            j["compute_time_ms"] = int((time.time() - start_compute) * 1000)
            break
    _save("computation_jobs.json", jobs)

    # unique(job_id)
    for r in results:
        if r.get("job_id") == job_id:
            _audit("error", error_code="CONFLICT")
            return _err("CONFLICT", "result already exists for job", job_id=job_id)

    res_id = "res_" + hashlib.sha256(f"{job_id}:{now3}".encode("utf-8")).hexdigest()[:16]
    res_row = {
        "id": res_id,
        "job_id": job_id,
        "result_kind": "series",
        "as_of_time": as_of_out,
        "value": latest_val,
        "signal": None,
        "series": series,
        "multi_series": None,
        "metadata": {"period": period_eff, "limit": limit_eff},
        "expires_at": expires_at,
        "created_at": now3,
        "updated_at": now3,
    }
    results.append(res_row)
    _save("computation_results.json", results)

    rk = return_kind or "value"
    out = {"symbol": symbol, "interval": interval_eff, "indicator": "williams_r", "cache_hit": False, "job_id": job_id}
    if rk == "value":
        out["value"] = latest_val
        out["as_of_time"] = as_of_out
    elif rk == "series":
        out["series"] = series
        out["as_of_time"] = as_of_out
    else:  # latest
        out["value"] = latest_val
        out["series"] = series
        out["as_of_time"] = as_of_out

    _audit("ok")
    return out

def calculate_acceleration_bands(symbol, interval=None, limit=None, period=None, as_of_time=None, return_kind=None, use_cache=None, **_extra):
    import json, os, datetime, hashlib, time, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0416000" if __import__("os").path.isdir("./environment_mix/0416000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "calculate_acceleration_bands"
    allowed_intervals = ["1m","3m","5m","15m","30m","1h","2h","4h","6h","8h","12h","1d","3d","1w","1M"]
    allowed_return_kinds = ["multi_series", "latest"]

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _isoz(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            dt = v
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        if not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _get_rows(doc):
        if isinstance(doc, dict) and isinstance(doc.get("rows"), list):
            return doc["rows"]
        if isinstance(doc, list):
            return doc
        return []

    def _save_doc(fname, original, rows):
        if isinstance(original, dict) and isinstance(original.get("rows"), list):
            original["rows"] = rows
            _save(fname, original)
        else:
            _save(fname, rows)

    def _new_id(prefix):
        ts = datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%d%H%M%S%f")
        return f"{prefix}_{ts}_{os.urandom(3).hex()}"

    def _fingerprint(obj):
        s = json.dumps(obj, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _log(status, error_code=None, extra=None):
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            return
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": _new_id("req"),
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _isoz(_utcnow()),
        }
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save("request_logs.json", logs)

    try:
        if not isinstance(symbol, str) or not symbol.strip():
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "symbol must be a non-empty string", field="symbol")
        symbol_n = symbol.strip().upper()

        if interval is None:
            interval = "1d"
        if not isinstance(interval, str) or interval not in allowed_intervals:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "interval must be one of the supported Binance intervals", field="interval", allowed=allowed_intervals)

        if limit is None:
            limit = 200
        if not isinstance(limit, int) or limit < 1:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit must be an integer >= 1", field="limit")

        if period is None:
            period = 20
        if not isinstance(period, int) or period < 1:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "period must be an integer >= 1", field="period")

        if return_kind is None:
            return_kind = "multi_series"
        if not isinstance(return_kind, str) or return_kind not in allowed_return_kinds:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "return_kind must be one of the supported values", field="return_kind", allowed=allowed_return_kinds)

        if use_cache is None:
            use_cache = True
        if not isinstance(use_cache, bool):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "use_cache must be a boolean", field="use_cache")

        as_of_dt = None
        if as_of_time is not None:
            as_of_dt = _parse_dt(as_of_time)
            if as_of_dt is None:
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "as_of_time must be an ISO 8601 date-time string", field="as_of_time")

        defs_doc = _load("indicator_definitions.json")
        defs_rows = _get_rows(defs_doc)
        idef = None
        for r in defs_rows:
            if isinstance(r, dict) and r.get("tool_name") == endpoint:
                idef = r
                break
        if not idef:
            _log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "indicator definition not found for tool", tool_name=endpoint)
        if not idef.get("is_enabled", False) or idef.get("status") not in ("active", "deprecated"):
            _log("error", "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Tool is not enabled or not available.", tool_name=endpoint, status=idef.get("status"), is_enabled=idef.get("is_enabled"))

        pairs_doc = _load("trading_pairs.json")
        pairs = _get_rows(pairs_doc)
        pair = None
        for p in pairs:
            if isinstance(p, dict) and p.get("exchange") == "binance" and str(p.get("symbol", "")).upper() == symbol_n:
                pair = p
                break
        if not pair:
            _log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "Trading pair symbol not found on exchange.", symbol=symbol_n, exchange="binance")
        if pair.get("status") != "active":
            _log("error", "INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", "Trading pair is not active; refusing new computation job.", error_code="PAIR_DISABLED", pair_id=pair.get("id"), status=pair.get("status"))

        norm = {
            "tool_name": endpoint,
            "pair_id": pair.get("id"),
            "interval": interval,
            "limit": int(limit),
            "period": int(period),
            "as_of_time": _isoz(as_of_dt) if as_of_dt else None,
            "return_kind": return_kind,
        }
        fp = _fingerprint(norm)

        jobs_doc = _load("computation_jobs.json")
        jobs = _get_rows(jobs_doc)
        results_doc = _load("computation_results.json")
        results = _get_rows(results_doc)

        def _find_result_by_job(job_id):
            for rr in results:
                if isinstance(rr, dict) and rr.get("job_id") == job_id:
                    return rr
            return None

        now = _utcnow()
        if use_cache:
            for j in jobs:
                if not isinstance(j, dict):
                    continue
                if j.get("request_fingerprint") != fp:
                    continue
                if j.get("status") != "succeeded" or not j.get("finished_at"):
                    continue
                r = _find_result_by_job(j.get("id"))
                if not r:
                    continue
                exp = _parse_dt(r.get("expires_at"))
                if exp is not None and exp < now:
                    continue
                new_job = {
                    "id": _new_id("cijob"),
                    "indicator_id": idef.get("id"),
                    "pair_id": pair.get("id"),
                    "interval": interval,
                    "candle_limit": int(limit),
                    "input_start_time": None,
                    "input_end_time": _isoz(as_of_dt) if as_of_dt else None,
                    "request_fingerprint": fp,
                    "cache_hit": True,
                    "status": "succeeded",
                    "queued_at": _isoz(now),
                    "started_at": _isoz(now),
                    "finished_at": _isoz(now),
                    "error_code": None,
                    "error_message": None,
                    "binance_request_count": 0,
                    "compute_time_ms": 0,
                    "created_at": _isoz(now),
                    "updated_at": _isoz(now),
                }
                jobs.append(new_job)
                _save_doc("computation_jobs.json", jobs_doc, jobs)
                _log("ok", extra={"cache_hit": True})
                return {"tool_name": endpoint, "cache_hit": True, "job": new_job, "result": r}

        job = {
            "id": _new_id("cijob"),
            "indicator_id": idef.get("id"),
            "pair_id": pair.get("id"),
            "interval": interval,
            "candle_limit": int(limit),
            "input_start_time": None,
            "input_end_time": _isoz(as_of_dt) if as_of_dt else None,
            "request_fingerprint": fp,
            "cache_hit": False,
            "status": "queued",
            "queued_at": _isoz(now),
            "started_at": None,
            "finished_at": None,
            "error_code": None,
            "error_message": None,
            "binance_request_count": 0,
            "compute_time_ms": None,
            "created_at": _isoz(now),
            "updated_at": _isoz(now),
        }
        jobs.append(job)
        _save_doc("computation_jobs.json", jobs_doc, jobs)

        job["status"] = "running"
        job["started_at"] = _isoz(_utcnow())
        job["updated_at"] = job["started_at"]
        _save_doc("computation_jobs.json", jobs_doc, jobs)

        candles_doc = _load("ohlcv_candles.json")
        candles = _get_rows(candles_doc)
        rows = [c for c in candles if isinstance(c, dict) and c.get("pair_id") == pair.get("id") and c.get("interval") == interval]
        # Apply as_of_time: close_time <= as_of_time
        if as_of_dt:
            filt = []
            for c in rows:
                ct = _parse_dt(c.get("close_time")) or _parse_dt(c.get("open_time"))
                if ct is None or ct <= as_of_dt:
                    filt.append(c)
            rows = filt
        rows.sort(key=lambda x: str(x.get("open_time") or ""))
        rows = rows[-int(limit):]

        required = int(idef.get("min_lookback_candles") or 1)
        if len(rows) < required:
            fin = _utcnow()
            job["status"] = "failed"
            job["finished_at"] = _isoz(fin)
            job["updated_at"] = _isoz(fin)
            job["error_code"] = "INSUFFICIENT_DATA"
            job["error_message"] = f"Need {required} lookback candles for interval {interval}; only {len(rows)} available."
            _save_doc("computation_jobs.json", jobs_doc, jobs)
            _log("error", "CONFLICT", extra={"error_code": "INSUFFICIENT_DATA"})
            return _err("CONFLICT", "Insufficient data to compute indicator.", error_code="INSUFFICIENT_DATA", required_candles=required, available_candles=len(rows), job_id=job["id"])

        # Acceleration Bands (simplified classic):
        # upper = high*(1 + 4*(high-low)/(high+low))
        # lower = low*(1 - 4*(high-low)/(high+low))
        # middle = SMA(close, period)
        highs = [float(c.get("high")) for c in rows]
        lows = [float(c.get("low")) for c in rows]
        closes = [float(c.get("close")) for c in rows]
        times = [c.get("close_time") or c.get("open_time") for c in rows]

        upper_raw = []
        lower_raw = []
        for h, l in zip(highs, lows):
            denom = (h + l)
            mult = 0.0 if denom == 0 else 4.0 * (h - l) / denom
            upper_raw.append(h * (1.0 + mult))
            lower_raw.append(l * (1.0 - mult))

        def _sma_series(vals, p):
            p = int(p)
            if p <= 0 or len(vals) < p:
                return []
            out = []
            s = sum(vals[:p])
            out.append(s / p)
            for i in range(p, len(vals)):
                s += vals[i] - vals[i - p]
                out.append(s / p)
            return out

        up = _sma_series(upper_raw, period)
        mid = _sma_series(closes, period)
        low = _sma_series(lower_raw, period)

        if not up or not mid or not low:
            fin = _utcnow()
            job["status"] = "failed"
            job["finished_at"] = _isoz(fin)
            job["updated_at"] = _isoz(fin)
            job["error_code"] = "INSUFFICIENT_DATA"
            job["error_message"] = f"Need at least {period} candles to compute Acceleration Bands series."
            _save_doc("computation_jobs.json", jobs_doc, jobs)
            _log("error", "CONFLICT", extra={"error_code": "INSUFFICIENT_DATA"})
            return _err("CONFLICT", "Insufficient data to compute indicator.", error_code="INSUFFICIENT_DATA", required_candles=max(required, period), available_candles=len(rows), job_id=job["id"])

        # align times: SMA outputs correspond to times[period-1:]
        t_aligned = times[period - 1:]
        ms = [{"t": t_aligned[i], "v": mid[i]} for i in range(len(mid))]
        us = [{"t": t_aligned[i], "v": up[i]} for i in range(len(up))]
        ls = [{"t": t_aligned[i], "v": low[i]} for i in range(len(low))]

        as_of = t_aligned[-1]
        latest = {"upper": up[-1], "middle": mid[-1], "lower": low[-1]}

        fin = _utcnow()
        job["status"] = "succeeded"
        job["finished_at"] = _isoz(fin)
        job["updated_at"] = _isoz(fin)
        job["compute_time_ms"] = max(0, int((time.time() - t0) * 1000))
        _save_doc("computation_jobs.json", jobs_doc, jobs)

        ttl = idef.get("cache_ttl_seconds")
        expires_at = None
        if isinstance(ttl, int) and ttl > 0:
            expires_at = _isoz(fin + datetime.timedelta(seconds=int(ttl)))

        if return_kind == "latest":
            result_kind = "multi_series"
            multi = {
                "upper": [{"t": as_of, "v": latest["upper"]}],
                "middle": [{"t": as_of, "v": latest["middle"]}],
                "lower": [{"t": as_of, "v": latest["lower"]}],
            }
        else:
            result_kind = "multi_series"
            multi = {"upper": us, "middle": ms, "lower": ls}

        result_row = {
            "id": _new_id("cires"),
            "job_id": job["id"],
            "result_kind": result_kind,
            "as_of_time": as_of,
            "value": None,
            "signal": None,
            "series": None,
            "multi_series": multi,
            "metadata": {"period": period, "limit": limit, "return_kind": return_kind, "as_of_time": _isoz(as_of_dt) if as_of_dt else None},
            "expires_at": expires_at,
            "created_at": _isoz(fin),
            "updated_at": _isoz(fin),
        }
        results.append(result_row)
        _save_doc("computation_results.json", results_doc, results)

        _log("ok")
        return {"tool_name": endpoint, "cache_hit": False, "job": job, "result": result_row}
    except Exception as e:
        _log("error", "CONFLICT")
        return _err("CONFLICT", "Unexpected server error.", details=str(e), tool_name=endpoint)

