                    "created_at": _isoz(now),
                    "updated_at": _isoz(now),
                }
                jobs.append(new_job)
                _save_doc("computation_jobs.json", jobs_doc, jobs)
                _log("ok", extra={"cache_hit": True})
                return {"tool_name": endpoint, "cache_hit": True, "job": new_job, "result": r}

        job = {
            "id": _new_id("cijob"),
            "indicator_id": idef.get("id"),
            "pair_id": pair.get("id"),
            "interval": interval,
            "candle_limit": int(limit),
            "input_start_time": None,
            "input_end_time": _isoz(as_of_dt) if as_of_dt else None,
            "request_fingerprint": fp,
            "cache_hit": False,
            "status": "queued",
            "queued_at": _isoz(now),
            "started_at": None,
            "finished_at": None,
            "error_code": None,
            "error_message": None,
            "binance_request_count": 0,
            "compute_time_ms": None,
            "created_at": _isoz(now),
            "updated_at": _isoz(now),
        }
        jobs.append(job)
        _save_doc("computation_jobs.json", jobs_doc, jobs)

        job["status"] = "running"
        job["started_at"] = _isoz(_utcnow())
        job["updated_at"] = job["started_at"]
        _save_doc("computation_jobs.json", jobs_doc, jobs)

        candles_doc = _load("ohlcv_candles.json")
        candles = _get_rows(candles_doc)
        rows = [c for c in candles if isinstance(c, dict) and c.get("pair_id") == pair.get("id") and c.get("interval") == interval]
        if as_of_dt:
            filt = []
            for c in rows:
                ct = _parse_dt(c.get("close_time")) or _parse_dt(c.get("open_time"))
                if ct is None or ct <= as_of_dt:
                    filt.append(c)
            rows = filt
        rows.sort(key=lambda x: str(x.get("open_time") or ""))
        rows = rows[-int(limit):]

        required = int(idef.get("min_lookback_candles") or 1)
        if len(rows) < required or len(rows) < (period + 1):
            fin = _utcnow()
            job["status"] = "failed"
            job["finished_at"] = _isoz(fin)
            job["updated_at"] = _isoz(fin)
            job["error_code"] = "INSUFFICIENT_DATA"
            job["error_message"] = f"Need {max(required, period+1)} lookback candles for interval {interval}; only {len(rows)} available."
            _save_doc("computation_jobs.json", jobs_doc, jobs)
            _log("error", "CONFLICT", extra={"error_code": "INSUFFICIENT_DATA"})
            return _err("CONFLICT", "Insufficient data to compute indicator.", error_code="INSUFFICIENT_DATA", required_candles=max(required, period + 1), available_candles=len(rows), job_id=job["id"])

        highs = [float(c.get("high")) for c in rows]
        lows = [float(c.get("low")) for c in rows]
        closes = [float(c.get("close")) for c in rows]
        times = [c.get("close_time") or c.get("open_time") for c in rows]

        # True range series (len = n-1, starting at index 1)
        tr = []
        tr_times = []
        for i in range(1, len(rows)):
            h = highs[i]
            l = lows[i]
            pc = closes[i - 1]
            tr_val = max(h - l, abs(h - pc), abs(l - pc))
            tr.append(tr_val)
            tr_times.append(times[i])

        # ATR: SMA of TR over period (simplified)
        def _sma(vals, p):
            p = int(p)
            if p <= 0 or len(vals) < p:
                return []
            out = []
            s = sum(vals[:p])
            out.append(s / p)
            for i in range(p, len(vals)):
                s += vals[i] - vals[i - p]
                out.append(s / p)
            return out

        atr = _sma(tr, period)
        if not atr:
            fin = _utcnow()
            job["status"] = "failed"
            job["finished_at"] = _isoz(fin)
            job["updated_at"] = _isoz(fin)
            job["error_code"] = "INSUFFICIENT_DATA"
            job["error_message"] = f"Need at least {period+1} candles to compute ATR."
            _save_doc("computation_jobs.json", jobs_doc, jobs)
            _log("error", "CONFLICT", extra={"error_code": "INSUFFICIENT_DATA"})
            return _err("CONFLICT", "Insufficient data to compute indicator.", error_code="INSUFFICIENT_DATA", required_candles=max(required, period + 1), available_candles=len(rows), job_id=job["id"])

        # atr corresponds to tr_times[period-1:]
        atr_times = tr_times[period - 1:]
        atr_series = [{"t": atr_times[i], "v": atr[i]} for i in range(len(atr))]
        latest_point = atr_series[-1]
        as_of = latest_point["t"]
        latest_val = latest_point["v"]

        fin = _utcnow()
        job["status"] = "succeeded"
        job["finished_at"] = _isoz(fin)
        job["updated_at"] = _isoz(fin)
        job["compute_time_ms"] = max(0, int((time.time() - t0) * 1000))
        _save_doc("computation_jobs.json", jobs_doc, jobs)

        ttl = idef.get("cache_ttl_seconds")
        expires_at = None
        if isinstance(ttl, int) and ttl > 0:
            expires_at = _isoz(fin + datetime.timedelta(seconds=int(ttl)))

        if return_kind == "value":
            store_series = None
        elif return_kind in ("series", "latest"):
            store_series = atr_series
        else:
            store_series = atr_series

        result_row = {
            "id": _new_id("cires"),
            "job_id": job["id"],
            "result_kind": "series",
            "as_of_time": as_of,
            "value": latest_val,
            "signal": None,
            "series": store_series,
            "multi_series": None,
            "metadata": {"period": period, "limit": limit, "return_kind": return_kind, "as_of_time": _isoz(as_of_dt) if as_of_dt else None},
            "expires_at": expires_at,
            "created_at": _isoz(fin),
            "updated_at": _isoz(fin),
        }
        results.append(result_row)
        _save_doc("computation_results.json", results_doc, results)

        _log("ok")
        if return_kind == "series":
            return {"tool_name": endpoint, "cache_hit": False, "job": job, "value": latest_val, "series": atr_series}
        if return_kind == "value":
            return {"tool_name": endpoint, "cache_hit": False, "job": job, "value": latest_val}
        return {"tool_name": endpoint, "cache_hit": False, "job": job, "value": latest_val, "series": atr_series[-min(len(atr_series), 200):], "result": result_row}
    except Exception as e:
        _log("error", "CONFLICT")
        return _err("CONFLICT", "Unexpected server error.", details=str(e), tool_name=endpoint)

def calculate_bollinger_bands(symbol, interval=None, limit=None, period=None, stddev=None, as_of_time=None, return_kind=None, use_cache=None, **_extra):
    import json, os, datetime, time, hashlib, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0416000" if __import__("os").path.isdir("./environment_mix/0416000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "calculate_bollinger_bands"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return None
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    def _to_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            dt = v
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        if isinstance(v, str):
            return _parse_dt(v)
        return None

    def _audit(status, credential_used=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + hashlib.sha256(f"{endpoint}:{_now_iso()}:{len(logs)}".encode("utf-8")).hexdigest()[:16],
            "endpoint": endpoint,
            "credential_used": credential_used,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
        })
        _save("request_logs.json", logs)

    allowed_intervals = ["1m","3m","5m","15m","30m","1h","2h","4h","6h","8h","12h","1d","3d","1w","1M"]
    allowed_return = ["multi_series","latest"]

    if not isinstance(symbol, str) or symbol.strip() == "":
        _audit("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "symbol must be a non-empty string")

    if interval is not None and interval not in allowed_intervals:
        _audit("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "interval is not allowed", allowed=allowed_intervals)

    if return_kind is not None and return_kind not in allowed_return:
        _audit("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "return_kind is not allowed", allowed=allowed_return)

    if limit is not None and (not isinstance(limit, int) or limit < 1):
        _audit("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer >= 1")

    if period is not None and (not isinstance(period, int) or period < 1):
        _audit("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "period must be an integer >= 1")

    if stddev is not None and (not isinstance(stddev, (int, float)) or float(stddev) < 0):
        _audit("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "stddev must be a number >= 0")

    as_of_dt = None
    if as_of_time is not None:
        as_of_dt = _parse_dt(as_of_time)
        if as_of_dt is None:
            _audit("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "as_of_time must be a valid date-time string")

    if use_cache is not None and not isinstance(use_cache, bool):
        _audit("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "use_cache must be a boolean")

    defs = _load("indicator_definitions.json")
    idef = None
    if isinstance(defs, list):
        for d in defs:
            if d.get("tool_name") == endpoint:
                idef = d
                break
    if not idef:
        _audit("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "indicator definition not found for tool", tool_name=endpoint)

    if not idef.get("is_enabled", False) or idef.get("status") not in ("active", "deprecated"):
        _audit("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "tool is not enabled")

    interval_eff = interval or idef.get("default_interval")
    if interval_eff not in allowed_intervals:
        _audit("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "effective interval is not allowed", allowed=allowed_intervals)

    min_lookback = idef.get("min_lookback_candles")
    if not isinstance(min_lookback, int) or min_lookback < 1:
        _audit("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "indicator definition has invalid min_lookback_candles")

    limit_eff = limit if limit is not None else idef.get("default_limit")
    if not isinstance(limit_eff, int) or limit_eff < 1:
        _audit("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "effective limit must be >= 1")

    period_eff = period if period is not None else 20
    std_eff = float(stddev) if stddev is not None else 2.0
    required_candles = max(min_lookback, period_eff)

    pairs = _load("trading_pairs.json")
    pair = None
    if isinstance(pairs, list):
        for p in pairs:
            if p.get("exchange") == "binance" and p.get("symbol") == symbol:
                pair = p
                break
    if not pair:
        _audit("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "trading pair not found", symbol=symbol, exchange="binance")

    if pair.get("status") != "active":
        jobs = _load("computation_jobs.json")
        if not isinstance(jobs, list): jobs = []
        now = _now_iso()
        fp = hashlib.sha256(f"{endpoint}|{pair.get('id')}|{interval_eff}|{limit_eff}|{period_eff}|{std_eff}|{as_of_dt.isoformat() if as_of_dt else ''}|{return_kind or ''}".encode("utf-8")).hexdigest()
        job_id = "job_" + hashlib.sha256(f"{fp}:{now}".encode("utf-8")).hexdigest()[:16]
        jobs.append({
            "id": job_id,
            "indicator_id": idef.get("id"),
            "pair_id": pair.get("id"),
            "interval": interval_eff,
            "candle_limit": limit_eff,
            "input_start_time": None,
            "input_end_time": as_of_dt.isoformat() if as_of_dt else None,
            "request_fingerprint": fp,
            "cache_hit": False,
            "status": "failed",
            "queued_at": now,
            "started_at": now,
            "finished_at": now,
            "error_code": "PAIR_DISABLED",
            "error_message": "Trading pair is not active",
            "binance_request_count": 0,
            "compute_time_ms": 0,
            "created_at": now,
            "updated_at": now,
        })
        _save("computation_jobs.json", jobs)
        _audit("error", error_code="PAIR_DISABLED")
        return _err("INVALID_TRANSITION", "trading pair is not active for new computations", error_code="PAIR_DISABLED")

    fp_obj = {
        "tool": endpoint,
        "indicator_id": idef.get("id"),
        "pair_id": pair.get("id"),
        "interval": interval_eff,
        "limit": limit_eff,
        "period": period_eff,
        "stddev": std_eff,
        "as_of_time": as_of_dt.isoformat() if as_of_dt else None,
        "return_kind": return_kind or None,
    }
    fp = hashlib.sha256(json.dumps(fp_obj, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()

    use_cache_eff = True if use_cache is None else use_cache
    jobs = _load("computation_jobs.json")
    results = _load("computation_results.json")
    if not isinstance(jobs, list): jobs = []
    if not isinstance(results, list): results = []

    def _result_by_jobid(jid):
        for r in results:
            if r.get("job_id") == jid:
                return r
        return None

    if use_cache_eff:
        now_dt = datetime.datetime.now(datetime.timezone.utc)
        for j in jobs:
            if j.get("request_fingerprint") == fp and j.get("status") == "succeeded" and j.get("finished_at"):
                r = _result_by_jobid(j.get("id"))
                if not r:
                    continue
                exp = _to_dt(r.get("expires_at"))
                if exp is None or exp > now_dt:
                    out = {"symbol": symbol, "interval": interval_eff, "indicator": "bollinger_bands", "cache_hit": True, "job_id": j.get("id"), "as_of_time": r.get("as_of_time")}
                    if (return_kind or "multi_series") == "latest":
                        ms = r.get("multi_series") or {}
                        def _last(series_list):
                            if not isinstance(series_list, list) or not series_list:
                                return None
                            return series_list[-1]
                        out["upper"] = (_last(ms.get("upper")) or {}).get("v")
                        out["middle"] = (_last(ms.get("middle")) or {}).get("v")
                        out["lower"] = (_last(ms.get("lower")) or {}).get("v")
                    else:
                        out["multi_series"] = r.get("multi_series") or {}
                    _audit("ok")
                    return out

    now = _now_iso()
    job_id = "job_" + hashlib.sha256(f"{fp}:{now}".encode("utf-8")).hexdigest()[:16]
    job = {
        "id": job_id,
        "indicator_id": idef.get("id"),
        "pair_id": pair.get("id"),
        "interval": interval_eff,
        "candle_limit": limit_eff,
        "input_start_time": None,
        "input_end_time": as_of_dt.isoformat() if as_of_dt else None,
        "request_fingerprint": fp,
        "cache_hit": False,
        "status": "queued",
        "queued_at": now,
        "started_at": None,
        "finished_at": None,
        "error_code": None,
        "error_message": None,
        "binance_request_count": 0,
        "compute_time_ms": None,
        "created_at": now,
        "updated_at": now,
    }
    jobs.append(job)
    _save("computation_jobs.json", jobs)

    for j in jobs:
        if j.get("id") == job_id:
            j["status"] = "running"
            j["started_at"] = _now_iso()
            j["updated_at"] = j["started_at"]
            break
    _save("computation_jobs.json", jobs)

    candles = _load("ohlcv_candles.json")
    if not isinstance(candles, list):
        candles = []
    pid = pair.get("id")

    filtered = []
    for c in candles:
        if c.get("pair_id") != pid or c.get("interval") != interval_eff:
            continue
        ct = _to_dt(c.get("close_time"))
        ot = _to_dt(c.get("open_time"))
        if ct is None or ot is None:
            continue
        if as_of_dt and ct > as_of_dt:
            continue
        filtered.append(c)
    filtered.sort(key=lambda x: (_to_dt(x.get("open_time")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)))
    if len(filtered) > limit_eff:
        filtered = filtered[-limit_eff:]

    if len(filtered) < required_candles:
        now2 = _now_iso()
        for j in jobs:
            if j.get("id") == job_id:
                j["status"] = "failed"
                j["finished_at"] = now2
                j["updated_at"] = now2
                j["error_code"] = "INSUFFICIENT_DATA"
                j["error_message"] = f"Need at least {required_candles} candles, got {len(filtered)}"
                j["compute_time_ms"] = int((time.time() - t0) * 1000)
                break
        _save("computation_jobs.json", jobs)
        _audit("error", error_code="INSUFFICIENT_DATA")
        return _err("CONFLICT", "insufficient candles to compute indicator", error_code="INSUFFICIENT_DATA", required=required_candles, available=len(filtered))

    start_compute = time.time()
    closes = [float(c["close"]) for c in filtered]
    times = [(_to_dt(c.get("close_time")) or _to_dt(c.get("open_time"))).isoformat() for c in filtered]

    upper_series = []
    middle_series = []
    lower_series = []

    # rolling mean and stddev
    for i in range(len(filtered)):
        if i + 1 < period_eff:
            continue
        w = closes[i+1-period_eff:i+1]
        mean = sum(w) / period_eff
        var = sum((x - mean) ** 2 for x in w) / period_eff
        sd = math.sqrt(var)
        upper = mean + std_eff * sd
        lower = mean - std_eff * sd
        t = times[i]
        middle_series.append({"t": t, "v": mean})
        upper_series.append({"t": t, "v": upper})
        lower_series.append({"t": t, "v": lower})

    as_of_out = (middle_series[-1]["t"] if middle_series else times[-1])
    ttl = idef.get("cache_ttl_seconds", 0)
    expires_at = None
    if isinstance(ttl, int) and ttl > 0:
        expires_at = (datetime.datetime.now(datetime.timezone.utc) + datetime.timedelta(seconds=ttl)).isoformat()

    now3 = _now_iso()
    for j in jobs:
        if j.get("id") == job_id:
            j["status"] = "succeeded"
            j["finished_at"] = now3
            j["updated_at"] = now3
            j["compute_time_ms"] = int((time.time() - start_compute) * 1000)
            break
    _save("computation_jobs.json", jobs)

    for r in results:
        if r.get("job_id") == job_id:
            _audit("error", error_code="CONFLICT")
            return _err("CONFLICT", "result already exists for job", job_id=job_id)

    res_id = "res_" + hashlib.sha256(f"{job_id}:{now3}".encode("utf-8")).hexdigest()[:16]
    ms = {"upper": upper_series, "middle": middle_series, "lower": lower_series}
    res_row = {
        "id": res_id,
        "job_id": job_id,
        "result_kind": "multi_series",
        "as_of_time": as_of_out,
        "value": None,
        "signal": None,
        "series": None,
        "multi_series": ms,
        "metadata": {"period": period_eff, "stddev": std_eff, "limit": limit_eff},
        "expires_at": expires_at,
        "created_at": now3,
        "updated_at": now3,
    }
    results.append(res_row)
    _save("computation_results.json", results)

    rk = return_kind or "multi_series"
    out = {"symbol": symbol, "interval": interval_eff, "indicator": "bollinger_bands", "cache_hit": False, "job_id": job_id, "as_of_time": as_of_out}
    if rk == "latest":
        out["upper"] = upper_series[-1]["v"] if upper_series else None
        out["middle"] = middle_series[-1]["v"] if middle_series else None
        out["lower"] = lower_series[-1]["v"] if lower_series else None
    else:
        out["multi_series"] = ms

    _audit("ok")
    return out

def calculate_bollinger_bands_width(symbol, interval=None, limit=None, period=None, stddev=None, as_of_time=None, return_kind=None, use_cache=None, **_extra):
    import json, os, datetime, time, hashlib, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0416000" if __import__("os").path.isdir("./environment_mix/0416000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    _status = "error"
    _err_out = None
    _tool = "calculate_bollinger_bands_width"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            raise ValueError("as_of_time must be a date-time string")
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            raise ValueError("as_of_time is invalid")

    def _dt_key(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            try:
                return _parse_dt(dt)
            except Exception:
                return None
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        return None

    def _to_float(x):
        if isinstance(x, (int, float)) and not isinstance(x, bool):
            return float(x)
        if isinstance(x, str):
            try:
                return float(x)
            except Exception:
                return None
        return None

    def _to_int(x):
        if isinstance(x, bool):
            return None
        if isinstance(x, int):
            return x
        if isinstance(x, str):
            try:
                return int(x)
            except Exception:
                return None
        return None

    # Basic validation
    allowed_intervals = ["1m","3m","5m","15m","30m","1h","2h","4h","6h","8h","12h","1d","3d","1w","1M"]
    allowed_return = ["value","series","latest"]

    if not isinstance(symbol, str) or symbol.strip() == "":
        _err_out = _err("VALIDATION_ERROR", "symbol must be a non-empty string")
    else:
        symbol = symbol.strip()

    if _err_out is None:
        if interval is not None and interval not in allowed_intervals:
            _err_out = _err("VALIDATION_ERROR", "interval is not allowed", allowed=allowed_intervals)
        if return_kind is not None and return_kind not in allowed_return:
            _err_out = _err("VALIDATION_ERROR", "return_kind is not allowed", allowed=allowed_return)
        if use_cache is not None and not isinstance(use_cache, bool):
            _err_out = _err("VALIDATION_ERROR", "use_cache must be boolean")

    # Resolve indicator definition
    indicators = _load("indicator_definitions.json")
