            break
    if _err_out is None:
        if not ind:
            _err_out = _err("NOT_FOUND", "indicator definition not found for tool", tool_name=_tool)
        else:
            if not ind.get("is_enabled", False) or ind.get("status") not in ("active", "deprecated"):
                _err_out = _err("UNAUTHORIZED", "tool is disabled")

    # Defaults
    if _err_out is None:
        if interval is None:
            interval = ind.get("default_interval")
        if limit is None:
            limit = ind.get("default_limit")
        if return_kind is None:
            return_kind = "latest"
        if use_cache is None:
            use_cache = True
        if period is None:
            period = 20
        if stddev is None:
            stddev = 2.0

        limit_i = _to_int(limit)
        period_i = _to_int(period)
        std_f = _to_float(stddev)

        if limit_i is None or limit_i < 1:
            _err_out = _err("VALIDATION_ERROR", "limit must be an integer >= 1")
        elif period_i is None or period_i < 1:
            _err_out = _err("VALIDATION_ERROR", "period must be an integer >= 1")
        elif std_f is None or std_f < 0:
            _err_out = _err("VALIDATION_ERROR", "stddev must be a number >= 0")
        else:
            limit = limit_i
            period = period_i
            stddev = std_f

        if _err_out is None:
            try:
                as_of_dt = _parse_dt(as_of_time) if as_of_time is not None else None
            except ValueError as e:
                _err_out = _err("VALIDATION_ERROR", str(e))
            except Exception:
                _err_out = _err("VALIDATION_ERROR", "as_of_time is invalid")
        else:
            as_of_dt = None

    # Resolve trading pair (must be active)
    pairs = _load("trading_pairs.json")
    pair = None
    if _err_out is None:
        for p in pairs:
            if isinstance(p, dict) and p.get("exchange") == "binance" and p.get("symbol") == symbol:
                pair = p
                break
        if not pair:
            _err_out = _err("NOT_FOUND", "trading pair not found", symbol=symbol, exchange="binance")
        else:
            if pair.get("status") != "active":
                _err_out = _err("INVALID_TRANSITION", "pair is not active for new computations", error_code="PAIR_DISABLED", pair_status=pair.get("status"))

    jobs = _load("computation_jobs.json")
    results = _load("computation_results.json")
    candles = _load("ohlcv_candles.json")

    def _log_request(status, latency_ms, job_id=None, cache_hit=None, error=None):
        # Best-effort request logging if a request log collection exists.
        # Schema didn't provide one; we do nothing if absent.
        return

    def _fingerprint():
        payload = {
            "tool": _tool,
            "indicator_id": ind.get("id") if ind else None,
            "pair_id": pair.get("id") if pair else None,
            "interval": interval,
            "limit": limit,
            "as_of_time": as_of_dt.isoformat() if as_of_dt else None,
            "params": {"period": period, "stddev": stddev},
            "return_kind": return_kind,
        }
        s = json.dumps(payload, sort_keys=True, separators=(",", ":"))
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _find_cached(fp):
        # Find succeeded job with same fingerprint and non-expired result
        now = datetime.datetime.now(datetime.timezone.utc)
        for j in jobs:
            if not isinstance(j, dict):
                continue
            if j.get("request_fingerprint") != fp:
                continue
            if j.get("status") != "succeeded":
                continue
            if not j.get("finished_at"):
                continue
            # result by job_id
            r = None
            for rr in results:
                if isinstance(rr, dict) and rr.get("job_id") == j.get("id"):
                    r = rr
                    break
            if not r:
                continue
            exp = _dt_key(r.get("expires_at"))
            if exp is None or exp > now:
                return j, r
        return None, None

    def _new_id(prefix, rows):
        mx = 0
        for r in rows:
            if isinstance(r, dict):
                rid = r.get("id")
                if isinstance(rid, str) and rid.startswith(prefix):
                    tail = rid[len(prefix):]
                    try:
                        n = int(tail)
                        if n > mx:
                            mx = n
                    except Exception:
                        continue
        return f"{prefix}{mx+1}"

    def _persist_all():
        _save("computation_jobs.json", jobs)
        _save("computation_results.json", results)

    def _select_candles():
        pid = pair["id"]
        sel = []
        for c in candles:
            if not isinstance(c, dict):
                continue
            if c.get("pair_id") != pid or c.get("interval") != interval:
                continue
            ct = _dt_key(c.get("close_time"))
            ot = _dt_key(c.get("open_time"))
            if ct is None or ot is None:
                continue
            if as_of_dt is not None and ct > as_of_dt:
                continue
            sel.append((ot, ct, c))
        sel.sort(key=lambda x: x[0])
        if limit is not None and len(sel) > limit:
            sel = sel[-limit:]
        return [x[2] for x in sel]

    def _sma(vals, window):
        out = []
        s = 0.0
        q = []
        for v in vals:
            q.append(v)
            s += v
            if len(q) > window:
                s -= q.pop(0)
            if len(q) == window:
                out.append(s / window)
            else:
                out.append(None)
        return out

    def _stdev(vals, window):
        out = []
        q = []
        s = 0.0
        s2 = 0.0
        for v in vals:
            q.append(v)
            s += v
            s2 += v*v
            if len(q) > window:
                old = q.pop(0)
                s -= old
                s2 -= old*old
            if len(q) == window:
                mean = s / window
                var = max(0.0, (s2 / window) - mean*mean)
                out.append(math.sqrt(var))
            else:
                out.append(None)
        return out

    def _compute_bbw(cands):
        # BBW = (upper - lower) / middle = (2*stddev*stdev) / sma
        closes = []
        times = []
        for c in cands:
            cv = _to_float(c.get("close"))
            ct = _dt_key(c.get("close_time"))
            if cv is None or ct is None:
                continue
            closes.append(cv)
            times.append(ct)
        ma = _sma(closes, period)
        sd = _stdev(closes, period)
        series = []
        latest_val = None
        latest_t = None
        for t, m, sdev in zip(times, ma, sd):
            if m is None or sdev is None:
                continue
            if m == 0:
                v = None
            else:
                v = (2.0 * stddev * sdev) / m
            if v is not None:
                latest_val = v
                latest_t = t
                series.append({"t": t.isoformat(), "v": v})
        return latest_t, latest_val, series

    # Compute / cache / job bookkeeping
    resp = None
    job_id = None
    cache_hit = False

    if _err_out is None:
        fp = _fingerprint()
        if use_cache:
            cj, cr = _find_cached(fp)
            if cj and cr:
                cache_hit = True
                # update a new job? Real backend likely still records a job. We'll create a lightweight succeeded job referencing cached result is not allowed by unique(job_id) in results.
                # Instead: return cached result directly without mutation to results; but "observable service dynamics" expects a call record—no log collection exists.
                # We'll still create a new job row marked succeeded with cache_hit=true but without a result row would violate expected envelope.
                # Better: create a new job row with status=succeeded and reference same result? results unique(job_id) prevents. So return cached result without new job row.
                body = {
                    "tool": _tool,
                    "symbol": symbol,
                    "interval": interval,
                    "cache_hit": True,
                    "result": cr
                }
                _status = "ok"
                resp = body

        if resp is None:
            # Create queued -> running -> terminal job
            now = _now_iso()
            job_id = _new_id("job_", jobs)
            job = {
                "id": job_id,
                "indicator_id": ind["id"],
                "pair_id": pair["id"],
                "interval": interval,
                "candle_limit": int(limit),
                "input_start_time": None,
                "input_end_time": as_of_dt.isoformat() if as_of_dt else None,
                "request_fingerprint": fp,
                "cache_hit": False,
                "status": "queued",
                "queued_at": now,
                "started_at": None,
                "finished_at": None,
                "error_code": None,
                "error_message": None,
                "binance_request_count": 0,
                "compute_time_ms": None,
                "created_at": now,
                "updated_at": now
            }
            jobs.append(job)
            _save("computation_jobs.json", jobs)

            # transition to running
            job["status"] = "running"
            job["started_at"] = _now_iso()
            job["updated_at"] = job["started_at"]
            _save("computation_jobs.json", jobs)

            cands = _select_candles()
            min_lb = int(ind.get("min_lookback_candles", 1))
            if len(cands) < min_lb or len(cands) < period:
                job["status"] = "failed"
                job["error_code"] = "INSUFFICIENT_DATA"
                job["error_message"] = "Not enough candles to compute indicator"
                fin = _now_iso()
                job["finished_at"] = fin
                job["updated_at"] = fin
                _save("computation_jobs.json", jobs)
                _status = "error"
                resp = _err("CONFLICT", "insufficient data", error_code="INSUFFICIENT_DATA", required=min_lb, available=len(cands))
            else:
                ct0 = time.time()
                latest_t, latest_val, series = _compute_bbw(cands)
                compute_ms = int((time.time() - ct0) * 1000)

                if latest_t is None or latest_val is None:
                    job["status"] = "failed"
                    job["error_code"] = "INSUFFICIENT_DATA"
                    job["error_message"] = "Not enough stable points to compute indicator"
                    fin = _now_iso()
                    job["finished_at"] = fin
                    job["updated_at"] = fin
                    job["compute_time_ms"] = compute_ms
                    _save("computation_jobs.json", jobs)
                    _status = "error"
                    resp = _err("CONFLICT", "insufficient data", error_code="INSUFFICIENT_DATA")
                else:
                    # create result row
                    res_id = _new_id("res_", results)
                    created = _now_iso()
                    ttl = int(ind.get("cache_ttl_seconds", 0) or 0)
                    expires_at = None
                    if ttl > 0:
                        expires_at = (datetime.datetime.now(datetime.timezone.utc) + datetime.timedelta(seconds=ttl)).isoformat()

                    if return_kind == "value":
                        store_series = None
                    elif return_kind == "series":
                        store_series = series
                    else:  # latest
                        store_series = series

                    result = {
                        "id": res_id,
                        "job_id": job_id,
                        "result_kind": "series",
                        "as_of_time": latest_t.isoformat(),
                        "value": float(latest_val),
                        "signal": None,
                        "series": store_series if store_series is not None else None,
                        "multi_series": None,
                        "metadata": {"period": period, "stddev": stddev, "return_kind": return_kind},
                        "expires_at": expires_at,
                        "created_at": created,
                        "updated_at": created
                    }
                    results.append(result)

                    job["status"] = "succeeded"
                    fin = _now_iso()
                    job["finished_at"] = fin
                    job["updated_at"] = fin
                    job["compute_time_ms"] = compute_ms
                    _persist_all()

                    _status = "ok"
                    resp = {
                        "tool": _tool,
                        "symbol": symbol,
                        "interval": interval,
                        "cache_hit": False,
                        "job": job,
                        "result": result
                    }

    if resp is None:
        resp = _err_out if _err_out is not None else _err("UNAUTHORIZED", "request could not be authorized")

    latency_ms = int((time.time() - _t0) * 1000)
    try:
        _log_request(_status, latency_ms, job_id=job_id, cache_hit=cache_hit, error=_err_out)
    except Exception:
        pass
    return resp

def calculate_chandelier_exit(symbol, interval=None, limit=None, period=None, atr_period=None, atr_multiplier=None, as_of_time=None, return_kind=None, use_cache=None, **_extra):
    import json, os, datetime, time, hashlib, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0416000" if __import__("os").path.isdir("./environment_mix/0416000") else "/app/database")
    def _load(n):
