            sel.append((ot, ct, c))
        sel.sort(key=lambda x: x[0])
        if len(sel) > limit:
            sel = sel[-limit:]
        return [x[2] for x in sel]

    def _atr(cands, window):
        # True range: max(high-low, abs(high-prev_close), abs(low-prev_close))
        trs = []
        prev_close = None
        times = []
        for c in cands:
            h = _to_float(c.get("high"))
            l = _to_float(c.get("low"))
            cl = _to_float(c.get("close"))
            t = _dt_key(c.get("close_time"))
            if h is None or l is None or cl is None or t is None:
                continue
            if prev_close is None:
                tr = h - l
            else:
                tr = max(h - l, abs(h - prev_close), abs(l - prev_close))
            trs.append(tr)
            times.append(t)
            prev_close = cl

        # Wilder's ATR: first ATR = SMA(TR, window), then ATR = (prev_atr*(window-1)+tr)/window
        atrs = [None] * len(trs)
        if len(trs) < window:
            return times, atrs
        first = sum(trs[:window]) / window
        atrs[window-1] = first
        prev = first
        for i in range(window, len(trs)):
            prev = (prev * (window - 1) + trs[i]) / window
            atrs[i] = prev
        return times, atrs

    def _compute_ce(cands):
        # CE Long = HighestHigh(period) - ATR(atr_period)*mult
        # CE Short = LowestLow(period) + ATR(atr_period)*mult
        highs, lows, closes, times = [], [], [], []
        for c in cands:
            h = _to_float(c.get("high"))
            l = _to_float(c.get("low"))
            cl = _to_float(c.get("close"))
            t = _dt_key(c.get("close_time"))
            if None in (h, l, cl) or t is None:
                continue
            highs.append(h); lows.append(l); closes.append(cl); times.append(t)

        atr_times, atrs = _atr(cands, atr_period)
        # Align by index (same candle sequence after filtering)
        n = min(len(times), len(atrs))
        times = times[:n]; highs = highs[:n]; lows = lows[:n]; atrs = atrs[:n]

        long_series = []
        short_series = []
        latest = None

        for i in range(n):
            if atrs[i] is None:
                continue
            if i + 1 < period:
                continue
            hh = max(highs[i+1-period:i+1])
            ll = min(lows[i+1-period:i+1])
            ce_long = hh - atrs[i] * atr_multiplier
            ce_short = ll + atrs[i] * atr_multiplier
            t = times[i]
            latest = (t, ce_long, ce_short)
            long_series.append({"t": t.isoformat(), "v": ce_long})
            short_series.append({"t": t.isoformat(), "v": ce_short})

        if latest is None:
            return None, None, None, {"long": long_series, "short": short_series}
        return latest[0], latest[1], latest[2], {"long": long_series, "short": short_series}

    resp = None
    job_id = None

    if _err_out is None:
