                    ttl = int(ind.get("cache_ttl_seconds", 0) or 0)
                    expires_at = None
                    if ttl > 0:
                        expires_at = (datetime.datetime.now(datetime.timezone.utc) + datetime.timedelta(seconds=ttl)).isoformat()

                    multi_series = ms if return_kind == "multi_series" else ms  # always store for multi_series tools
                    metadata = {"period": period, "atr_period": atr_period, "atr_multiplier": atr_multiplier, "return_kind": return_kind}
                    result = {
