    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _tool = "calculate_donchian_channel"
    _err_out = None

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            raise ValueError("as_of_time must be a date-time string")
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            raise ValueError("as_of_time is invalid")

    def _dt_key(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            try:
                return _parse_dt(dt)
            except Exception:
                return None
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        return None

    def _to_float(x):
        if isinstance(x, (int, float)) and not isinstance(x, bool):
            return float(x)
        if isinstance(x, str):
            try:
                return float(x)
            except Exception:
                return None
        return None

    def _to_int(x):
        if isinstance(x, bool):
            return None
        if isinstance(x, int):
            return x
        if isinstance(x, str):
            try:
                return int(x)
            except Exception:
                return None
        return None

    allowed_intervals = ["1m","3m","5m","15m","30m","1h","2h","4h","6h","8h","12h","1d","3d","1w","1M"]
    allowed_return = ["multi_series","latest"]

    if not isinstance(symbol, str) or symbol.strip() == "":
        _err_out = _err("VALIDATION_ERROR", "symbol must be a non-empty string")
    else:
        symbol = symbol.strip()

    if _err_out is None:
        if interval is not None and interval not in allowed_intervals:
            _err_out = _err("VALIDATION_ERROR", "interval is not allowed", allowed=allowed_intervals)
        if return_kind is not None and return_kind not in allowed_return:
            _err_out = _err("VALIDATION_ERROR", "return_kind is not allowed", allowed=allowed_return)
        if use_cache is not None and not isinstance(use_cache, bool):
            _err_out = _err("VALIDATION_ERROR", "use_cache must be boolean")

    indicators = _load("indicator_definitions.json")
    ind = None
    for row in indicators:
        if isinstance(row, dict) and row.get("tool_name") == _tool:
            ind = row
            break
    if _err_out is None:
        if not ind:
            _err_out = _err("NOT_FOUND", "indicator definition not found for tool", tool_name=_tool)
        else:
            if not ind.get("is_enabled", False) or ind.get("status") not in ("active", "deprecated"):
                _err_out = _err("UNAUTHORIZED", "tool is disabled")

    if _err_out is None:
        if interval is None:
            interval = ind.get("default_interval")
        if limit is None:
            limit = ind.get("default_limit")
        if period is None:
            period = 20
        if return_kind is None:
            return_kind = "latest"
        if use_cache is None:
            use_cache = True

        limit_i = _to_int(limit)
        period_i = _to_int(period)
        if limit_i is None or limit_i < 1:
            _err_out = _err("VALIDATION_ERROR", "limit must be an integer >= 1")
        elif period_i is None or period_i < 1:
            _err_out = _err("VALIDATION_ERROR", "period must be an integer >= 1")
