        s = json.dumps(payload, sort_keys=True, separators=(",", ":"))
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _find_cached(fp):
        now = datetime.datetime.now(datetime.timezone.utc)
        for j in jobs:
            if not isinstance(j, dict):
                continue
            if j.get("request_fingerprint") != fp:
                continue
            if j.get("status") != "succeeded" or not j.get("finished_at"):
                continue
            r = None
            for rr in results:
                if isinstance(rr, dict) and rr.get("job_id") == j.get("id"):
                    r = rr
                    break
            if not r:
                continue
            exp = _dt_key(r.get("expires_at"))
            if exp is None or exp > now:
                return j, r
        return None, None

    def _new_id(prefix, rows):
        mx = 0
        for r in rows:
            if isinstance(r, dict):
                rid = r.get("id")
                if isinstance(rid, str) and rid.startswith(prefix):
                    tail = rid[len(prefix):]
                    try:
                        n = int(tail)
                        if n > mx:
                            mx = n
                    except Exception:
                        continue
        return f"{prefix}{mx+1}"

    def _persist_all():
        _save("computation_jobs.json", jobs)
        _save("computation_results.json", results)

    def _select_candles():
        pid = pair["id"]
        sel = []
        for c in candles:
            if not isinstance(c, dict):
                continue
            if c.get("pair_id") != pid or c.get("interval") != interval:
                continue
            ct = _dt_key(c.get("close_time"))
            ot = _dt_key(c.get("open_time"))
            if ct is None or ot is None:
                continue
            if as_of_dt is not None and ct > as_of_dt:
                continue
            sel.append((ot, ct, c))
        sel.sort(key=lambda x: x[0])
        if len(sel) > limit:
            sel = sel[-limit:]
        return [x[2] for x in sel]

    def _ema(values, window):
        out = []
        if window <= 0:
            return [None] * len(values)
        alpha = 2.0 / (window + 1.0)
        ema_val = None
        for i, v in enumerate(values):
            if v is None:
                out.append(None)
                continue
            if ema_val is None:
                ema_val = v
            else:
                ema_val = alpha * v + (1.0 - alpha) * ema_val
            out.append(ema_val)
        return out

    def _atr_from_arrays(highs, lows, closes, window):
        trs = []
        prev_close = None
        for h, l, c in zip(highs, lows, closes):
            if prev_close is None:
                tr = h - l
            else:
                tr = max(h - l, abs(h - prev_close), abs(l - prev_close))
            trs.append(tr)
            prev_close = c

        atrs = [None] * len(trs)
        if len(trs) < window:
            return atrs
        first = sum(trs[:window]) / window
        atrs[window-1] = first
        prev = first
        for i in range(window, len(trs)):
            prev = (prev * (window - 1) + trs[i]) / window
            atrs[i] = prev
        return atrs

    def _compute_kc(cands):
        highs, lows, closes, times = [], [], [], []
        for c in cands:
            h = _to_float(c.get("high"))
            l = _to_float(c.get("low"))
            cl = _to_float(c.get("close"))
            t = _dt_key(c.get("close_time"))
            if None in (h, l, cl) or t is None:
                continue
            highs.append(h); lows.append(l); closes.append(cl); times.append(t)

        mid = _ema(closes, ema_period)
        atrs = _atr_from_arrays(highs, lows, closes, atr_period)

        upper_s, lower_s, mid_s = [], [], []
        latest = None
        for t, m, a in zip(times, mid, atrs):
            if m is None or a is None:
                continue
            up = m + atr_multiplier * a
            lo = m - atr_multiplier * a
            latest = (t, up, lo, m)
            upper_s.append({"t": t.isoformat(), "v": up})
            lower_s.append({"t": t.isoformat(), "v": lo})
            mid_s.append({"t": t.isoformat(), "v": m})
        return latest, {"upper": upper_s, "lower": lower_s, "middle": mid_s}

    resp = None
    job_id = None

    if _err_out is None:
        fp = _fingerprint()
        if use_cache:
            cj, cr = _find_cached(fp)
            if cj and cr:
                resp = {"tool": _tool, "symbol": symbol, "interval": interval, "cache_hit": True, "result": cr}

        if resp is None:
            now = _now_iso()
            job_id = _new_id("job_", jobs)
            job = {
                "id": job_id,
                "indicator_id": ind["id"],
                "pair_id": pair["id"],
                "interval": interval,
                "candle_limit": int(limit),
                "input_start_time": None,
                "input_end_time": as_of_dt.isoformat() if as_of_dt else None,
                "request_fingerprint": fp,
                "cache_hit": False,
                "status": "queued",
                "queued_at": now,
                "started_at": None,
                "finished_at": None,
                "error_code": None,
                "error_message": None,
                "binance_request_count": 0,
                "compute_time_ms": None,
                "created_at": now,
                "updated_at": now
            }
            jobs.append(job)
            _save("computation_jobs.json", jobs)

            job["status"] = "running"
            job["started_at"] = _now_iso()
            job["updated_at"] = job["started_at"]
            _save("computation_jobs.json", jobs)

            cands = _select_candles()
            min_lb = int(ind.get("min_lookback_candles", 1))
            needed = max(min_lb, ema_period, atr_period)
            if len(cands) < needed:
                job["status"] = "failed"
                job["error_code"] = "INSUFFICIENT_DATA"
                job["error_message"] = "Not enough candles to compute indicator"
                fin = _now_iso()
                job["finished_at"] = fin
                job["updated_at"] = fin
                _save("computation_jobs.json", jobs)
                resp = _err("CONFLICT", "insufficient data", error_code="INSUFFICIENT_DATA", required=needed, available=len(cands))
            else:
                ct0 = time.time()
                latest, ms = _compute_kc(cands)
                compute_ms = int((time.time() - ct0) * 1000)

                if latest is None:
                    job["status"] = "failed"
                    job["error_code"] = "INSUFFICIENT_DATA"
                    job["error_message"] = "Not enough stable points to compute indicator"
                    fin = _now_iso()
                    job["finished_at"] = fin
                    job["updated_at"] = fin
                    job["compute_time_ms"] = compute_ms
                    _save("computation_jobs.json", jobs)
                    resp = _err("CONFLICT", "insufficient data", error_code="INSUFFICIENT_DATA")
                else:
                    res_id = _new_id("res_", results)
                    created = _now_iso()
                    ttl = int(ind.get("cache_ttl_seconds", 0) or 0)
                    expires_at = None
                    if ttl > 0:
                        expires_at = (datetime.datetime.now(datetime.timezone.utc) + datetime.timedelta(seconds=ttl)).isoformat()

                    t, up, lo, midv = latest
                    result = {
                        "id": res_id,
                        "job_id": job_id,
                        "result_kind": "multi_series",
                        "as_of_time": t.isoformat(),
                        "value": None,
                        "signal": None,
                        "series": None,
                        "multi_series": ms if return_kind == "multi_series" else ms,
                        "metadata": {"ema_period": ema_period, "atr_period": atr_period, "atr_multiplier": atr_multiplier, "return_kind": return_kind},
                        "expires_at": expires_at,
                        "created_at": created,
                        "updated_at": created
                    }
                    results.append(result)

                    job["status"] = "succeeded"
                    fin = _now_iso()
                    job["finished_at"] = fin
                    job["updated_at"] = fin
                    job["compute_time_ms"] = compute_ms
                    _persist_all()

                    resp = {
                        "tool": _tool,
                        "symbol": symbol,
                        "interval": interval,
                        "cache_hit": False,
                        "job": job,
                        "latest": {"t": t.isoformat(), "upper": up, "lower": lo, "middle": midv},
                        "result": result
                    }

    if resp is None:
        resp = _err_out if _err_out is not None else _err("UNAUTHORIZED", "request could not be authorized")
    return resp

def calculate_moving_standard_deviation(symbol, interval=None, limit=None, start_time=None, end_time=None, length=None, mamode=None, price_field=None, return_series=None, **_extra):
    import json, os, datetime, time, math, hashlib

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0416000" if __import__("os").path.isdir("./environment_mix/0416000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return None
        v = s.strip()
        try:
            if v.endswith("Z"):
                v = v[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(v)
        except Exception:
            return None

    def _to_float(x):
        try:
            if isinstance(x, bool):
                return None
            return float(x)
        except Exception:
            return None

    def _audit(status, tool_name, credential_id, meta=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "tool": tool_name,
            "credential_id": credential_id,
            "status": status,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _now_iso(),
            "error_code": error_code,
            "meta": meta or {}
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _resolve_auth():
        # Ambient auth: pick any combination; no explicit credentials in tool params.
        # If store has api_keys/workspaces/accounts, select any active row; otherwise anonymous.
        for fn in ("api_keys.json", "keys.json", "credentials.json"):
            rows = _load(fn)
            if isinstance(rows, list):
                for r in rows:
                    if isinstance(r, dict) and r.get("status") in (None, "active", "enabled"):
                        return (r.get("id") or "ambient", r)
        return ("ambient", None)

    def _id(prefix):
        return f"{prefix}_{int(time.time()*1000)}_{os.getpid()}_{int.from_bytes(os.urandom(3),'big')}"

    def _moving_avg(values, mode, length):
        if mode == "sma":
            out = []
            s = 0.0
            for i, v in enumerate(values):
                s += v
                if i >= length:
                    s -= values[i - length]
                if i + 1 >= length:
                    out.append(s / length)
                else:
                    out.append(None)
            return out
        if mode == "ema":
            out = []
            alpha = 2.0 / (length + 1.0)
            ema = None
            for i, v in enumerate(values):
                if ema is None:
                    ema = v
                else:
                    ema = alpha * v + (1 - alpha) * ema
                if i + 1 >= length:
                    out.append(ema)
                else:
                    out.append(None)
            return out
        if mode == "rma":
            out = []
            rma = None
            alpha = 1.0 / float(length)
            for i, v in enumerate(values):
                if rma is None:
                    rma = v
                else:
                    rma = alpha * v + (1 - alpha) * rma
                if i + 1 >= length:
                    out.append(rma)
                else:
                    out.append(None)
            return out
        if mode == "wma":
            out = []
            denom = length * (length + 1) / 2.0
            for i in range(len(values)):
                if i + 1 < length:
                    out.append(None)
                    continue
                wsum = 0.0
                w = 1
                for j in range(i - length + 1, i + 1):
                    wsum += values[j] * w
                    w += 1
                out.append(wsum / denom)
            return out
        return None

    tool = "calculate_moving_standard_deviation"
    credential_id, _cred = _resolve_auth()

    # Validate
    if not isinstance(symbol, str) or not symbol.strip():
        _audit("error", tool, credential_id, meta={"symbol": symbol}, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "symbol is required and must be a non-empty string", field="symbol")

    allowed_intervals = ["1m","3m","5m","15m","30m","1h","2h","4h","6h","8h","12h","1d","3d","1w","1M"]
    interval = interval or "1h"
    if interval not in allowed_intervals:
        _audit("error", tool, credential_id, meta={"interval": interval}, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "interval is unsupported", field="interval", allowed=allowed_intervals)

    if limit is None:
        limit = 200
    if not isinstance(limit, int) or isinstance(limit, bool) or limit < 1 or limit > 500:
        _audit("error", tool, credential_id, meta={"limit": limit}, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer in range 1–500", field="limit")

    if length is None:
        length = 20
    if not isinstance(length, int) or isinstance(length, bool) or length < 1:
        _audit("error", tool, credential_id, meta={"length": length}, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "length must be an integer >= 1", field="length")

    mamode = (mamode or "sma")
    if mamode not in ("sma", "ema", "wma", "rma"):
        _audit("error", tool, credential_id, meta={"mamode": mamode}, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "mamode is invalid", field="mamode", allowed=["sma","ema","wma","rma"])

    price_field = (price_field or "close")
    if price_field not in ("open", "high", "low", "close"):
        _audit("error", tool, credential_id, meta={"price_field": price_field}, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "price_field is invalid", field="price_field", allowed=["open","high","low","close"])

    if return_series is None:
        return_series = False
    if not isinstance(return_series, bool):
        _audit("error", tool, credential_id, meta={"return_series": return_series}, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "return_series must be boolean", field="return_series")

    st = _parse_dt(start_time)
    if start_time is not None and st is None:
        _audit("error", tool, credential_id, meta={"start_time": start_time}, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "start_time must be a valid ISO-8601 datetime", field="start_time")
    et = _parse_dt(end_time)
    if end_time is not None and et is None:
        _audit("error", tool, credential_id, meta={"end_time": end_time}, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "end_time must be a valid ISO-8601 datetime", field="end_time")
    if st is not None and et is not None and st > et:
        _audit("error", tool, credential_id, meta={"start_time": start_time, "end_time": end_time}, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "start_time must be <= end_time", field="start_time")

    # Definition gating
    defs = _load("indicator_definitions.json")
    idef = None
    if isinstance(defs, list):
        for d in defs:
            if isinstance(d, dict) and d.get("tool_name") == tool:
                idef = d
                break
    if not idef:
        _audit("error", tool, credential_id, meta={}, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "indicator definition not found for tool", tool_name=tool)
    if not idef.get("is_enabled") or idef.get("status") not in ("active", "deprecated"):
        _audit("error", tool, credential_id, meta={"indicator_id": idef.get("id")}, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "tool is not enabled", tool_name=tool)

    # Trading pair lookup
    pairs = _load("trading_pairs.json")
    pair = None
    if isinstance(pairs, list):
        for p in pairs:
            if isinstance(p, dict) and p.get("exchange") == "binance" and p.get("symbol") == symbol.strip():
                pair = p
                break
    if not pair:
        _audit("error", tool, credential_id, meta={"symbol": symbol}, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "trading pair not found", symbol=symbol)
    if pair.get("status") != "active":
        # Fail job with PAIR_DISABLED per business rules
        # Create a failed job record
        jobs = _load("computation_jobs.json")
        if not isinstance(jobs, list):
            jobs = []
        now = _now_iso()
        fp_src = {"tool": tool, "pair_id": pair.get("id"), "interval": interval, "limit": limit, "start_time": start_time, "end_time": end_time, "length": length, "mamode": mamode, "price_field": price_field}
        fp = hashlib.sha256(json.dumps(fp_src, sort_keys=True, ensure_ascii=False).encode("utf-8")).hexdigest()
        job = {
            "id": _id("job"),
            "indicator_id": idef.get("id"),
            "pair_id": pair.get("id"),
            "interval": interval,
            "candle_limit": limit,
            "input_start_time": start_time,
            "input_end_time": end_time,
            "request_fingerprint": fp,
            "cache_hit": False,
            "status": "failed",
            "queued_at": now,
            "started_at": now,
            "finished_at": now,
            "error_code": "PAIR_DISABLED",
            "error_message": "Trading pair is not active",
            "binance_request_count": 0,
            "compute_time_ms": 0,
            "created_at": now,
            "updated_at": now
        }
        jobs.append(job)
        _save("computation_jobs.json", jobs)
        _audit("error", tool, credential_id, meta={"job_id": job["id"], "error_code": "PAIR_DISABLED"}, error_code="PAIR_DISABLED")
        return _err("INVALID_TRANSITION", "trading pair is not active for new computations", error_code="PAIR_DISABLED", pair_status=pair.get("status"))

    # Build fingerprint and caching
    fp_src = {"tool": tool, "pair_id": pair.get("id"), "interval": interval, "limit": limit, "start_time": start_time, "end_time": end_time, "length": length, "mamode": mamode, "price_field": price_field, "return_series": bool(return_series)}
    fp = hashlib.sha256(json.dumps(fp_src, sort_keys=True, ensure_ascii=False).encode("utf-8")).hexdigest()

    jobs = _load("computation_jobs.json")
    if not isinstance(jobs, list):
        jobs = []
    results = _load("computation_results.json")
    if not isinstance(results, list):
        results = []

    def _dt_from_iso(s):
        dtx = _parse_dt(s)
        return dtx

    cached_job = None
    cached_result = None
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    for j in jobs:
        if not isinstance(j, dict):
            continue
        if j.get("status") == "succeeded" and j.get("request_fingerprint") == fp and j.get("finished_at"):
            # unique constraint implies at most one, but be safe; choose newest finished_at
            r = next((rr for rr in results if isinstance(rr, dict) and rr.get("job_id") == j.get("id")), None)
            if not r:
                continue
            exp = r.get("expires_at")
            if exp is None:
                cached_job, cached_result = j, r
                break
            exp_dt = _dt_from_iso(exp)
            if exp_dt is not None and exp_dt >= now_dt:
                cached_job, cached_result = j, r
                break

    if cached_job and cached_result:
        # Record a new succeeded job with cache_hit=true? Business rule says subsequent requests must set cache_hit=true and return stored computation_result.
        # We'll enqueue+finish a lightweight job row to observe service dynamics, without duplicating succeeded fingerprint uniqueness in constraints.
        # To respect unique(request_fingerprint) where status='succeeded', we should NOT create another succeeded job with same fingerprint.
        # Instead create a cancelled job? But "must set cache_hit=true" refers to the job for this request. We'll create a 'succeeded' job only if no conflict.
        # Here conflict would happen; so we store a 'succeeded' job is not allowed. We'll store a 'failed' would be wrong.
        # We'll store a 'cancelled' job with cache_hit=true and finished_at set, to track call, while returning cached result.
        now = _now_iso()
        new_job = {
            "id": _id("job"),
            "indicator_id": idef.get("id"),
            "pair_id": pair.get("id"),
            "interval": interval,
            "candle_limit": limit,
            "input_start_time": start_time,
            "input_end_time": end_time,
            "request_fingerprint": fp,
            "cache_hit": True,
            "status": "cancelled",
            "queued_at": now,
            "started_at": now,
            "finished_at": now,
            "error_code": None,
            "error_message": None,
            "binance_request_count": 0,
            "compute_time_ms": 0,
            "created_at": now,
            "updated_at": now
        }
        jobs.append(new_job)
        _save("computation_jobs.json", jobs)

        body = {
            "job": new_job,
            "cached_from_job_id": cached_job.get("id"),
            "pair": {"id": pair.get("id"), "exchange": pair.get("exchange"), "symbol": pair.get("symbol")},
            "interval": interval,
            "indicator": {"id": idef.get("id"), "tool_name": tool},
            "result": cached_result if return_series else {
                **cached_result,
                "series": None,
                "multi_series": None
            }
        }
        _audit("ok", tool, credential_id, meta={"cache_hit": True, "job_id": new_job["id"], "cached_job_id": cached_job.get("id")})
        return body

    # Create job (queued -> running -> terminal)
    now = _now_iso()
    job = {
        "id": _id("job"),
        "indicator_id": idef.get("id"),
        "pair_id": pair.get("id"),
        "interval": interval,
        "candle_limit": limit,
        "input_start_time": start_time,
        "input_end_time": end_time,
        "request_fingerprint": fp,
        "cache_hit": False,
        "status": "queued",
        "queued_at": now,
        "started_at": None,
        "finished_at": None,
        "error_code": None,
        "error_message": None,
        "binance_request_count": 0,
        "compute_time_ms": None,
        "created_at": now,
        "updated_at": now
    }
    jobs.append(job)
    _save("computation_jobs.json", jobs)

    # Transition queued -> running
    job["status"] = "running"
    job["started_at"] = _now_iso()
    job["updated_at"] = job["started_at"]
    _save("computation_jobs.json", jobs)

    # Select candles
    candles = _load("ohlcv_candles.json")
    if not isinstance(candles, list):
        candles = []
    pid = pair.get("id")
    sel = []
    for c in candles:
        if not isinstance(c, dict):
            continue
        if c.get("pair_id") != pid or c.get("interval") != interval:
            continue
        ot = _parse_dt(c.get("open_time"))
        if ot is None:
            continue
        if st is not None and ot < st:
            continue
        if et is not None and ot > et:
            continue
        sel.append((ot, c))
    sel.sort(key=lambda x: x[0])
    if limit is not None and len(sel) > limit:
        sel = sel[-limit:]

    min_need = int(idef.get("min_lookback_candles") or 1)
    if len(sel) < min_need or len(sel) < length:
        # fail job with INSUFFICIENT_DATA
        fin = _now_iso()
        job["status"] = "failed"
        job["finished_at"] = fin
        job["updated_at"] = fin
        job["error_code"] = "INSUFFICIENT_DATA"
        job["error_message"] = "Not enough candles to compute indicator"
        job["binance_request_count"] = 0
        job["compute_time_ms"] = int((time.time() - _t0) * 1000)
        _save("computation_jobs.json", jobs)
        _audit("error", tool, credential_id, meta={"job_id": job["id"], "have": len(sel), "need": max(min_need, length)}, error_code="INSUFFICIENT_DATA")
        return _err("CONFLICT", "insufficient data to compute indicator", error_code="INSUFFICIENT_DATA", candles_available=len(sel), candles_required=max(min_need, length))

    prices = []
    times = []
    for ot, c in sel:
        v = _to_float(c.get(price_field))
        if v is None:
            continue
        prices.append(v)
        times.append(c.get("close_time") or c.get("open_time"))
    if len(prices) < max(min_need, length):
        fin = _now_iso()
        job["status"] = "failed"
        job["finished_at"] = fin
        job["updated_at"] = fin
        job["error_code"] = "INSUFFICIENT_DATA"
        job["error_message"] = "Not enough valid price points"
        job["compute_time_ms"] = int((time.time() - _t0) * 1000)
        _save("computation_jobs.json", jobs)
        _audit("error", tool, credential_id, meta={"job_id": job["id"]}, error_code="INSUFFICIENT_DATA")
        return _err("CONFLICT", "insufficient data to compute indicator", error_code="INSUFFICIENT_DATA")

    # Compute: MSTD (std of (price - MA(price)) over window length)
    t_comp0 = time.time()
    ma = _moving_avg(prices, mamode, length)
    if ma is None:
        fin = _now_iso()
        job["status"] = "failed"
        job["finished_at"] = fin
        job["updated_at"] = fin
        job["error_code"] = "VALIDATION_ERROR"
        job["error_message"] = "Unsupported mamode"
        job["compute_time_ms"] = int((time.time() - t_comp0) * 1000)
        _save("computation_jobs.json", jobs)
        _audit("error", tool, credential_id, meta={"job_id": job["id"]}, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "unsupported mamode", field="mamode")

    # rolling std of residuals
    series = []
    window = []
    for i, p in enumerate(prices):
        m = ma[i]
        if m is None:
            series.append(None)
            window.append(None)
            continue
        r = p - m
        window.append(r)
        if len(window) > length:
            window.pop(0)
        if i + 1 >= length:
            vals = [x for x in window if x is not None]
            if len(vals) != length:
                series.append(None)
            else:
                mean = sum(vals) / length
                var = sum((x - mean) ** 2 for x in vals) / length
                series.append(math.sqrt(var))
        else:
            series.append(None)

    # Latest value
    latest_idx = None
    for i in range(len(series) - 1, -1, -1):
        if series[i] is not None:
            latest_idx = i
            break
    if latest_idx is None:
        fin = _now_iso()
        job["status"] = "failed"
        job["finished_at"] = fin
        job["updated_at"] = fin
        job["error_code"] = "INSUFFICIENT_DATA"
        job["error_message"] = "No computable output within window"
        job["compute_time_ms"] = int((time.time() - t_comp0) * 1000)
        _save("computation_jobs.json", jobs)
        _audit("error", tool, credential_id, meta={"job_id": job["id"]}, error_code="INSUFFICIENT_DATA")
        return _err("CONFLICT", "insufficient data to compute indicator", error_code="INSUFFICIENT_DATA")

    latest_value = float(series[latest_idx])
    as_of_time = times[latest_idx]

    # Create result
    ttl = int(idef.get("cache_ttl_seconds") or 0)
    created = _now_iso()
    expires_at = None
    if ttl > 0:
        expires_at = (datetime.datetime.now(datetime.timezone.utc) + datetime.timedelta(seconds=ttl)).isoformat()

    res = {
        "id": _id("res"),
        "job_id": job["id"],
        "result_kind": "series",
        "as_of_time": as_of_time,
        "value": latest_value,
        "signal": None,
        "series": None,
        "multi_series": None,
        "metadata": {"length": length, "mamode": mamode, "price_field": price_field},
        "expires_at": expires_at,
        "created_at": created,
        "updated_at": created
    }
    if return_series:
        pts = []
        for i, v in enumerate(series):
            if v is None:
                continue
            pts.append({"t": times[i], "v": float(v)})
        res["series"] = pts

    # Persist and finish job
    results.append(res)

    fin = _now_iso()
    job["status"] = "succeeded"
    job["finished_at"] = fin
    job["updated_at"] = fin
    job["error_code"] = None
    job["error_message"] = None
    job["compute_time_ms"] = int((time.time() - t_comp0) * 1000)
    # enforce terminal finished_at set already; updated_at == finished_at ok

    _save("computation_results.json", results)
    _save("computation_jobs.json", jobs)

    _audit("ok", tool, credential_id, meta={"cache_hit": False, "job_id": job["id"]})
    return {
        "job": job,
        "pair": {"id": pair.get("id"), "exchange": pair.get("exchange"), "symbol": pair.get("symbol")},
        "interval": interval,
        "indicator": {"id": idef.get("id"), "tool_name": tool},
        "result": res if return_series else {**res, "series": None, "multi_series": None}
    }

def calculate_projection_oscillator(symbol, interval=None, limit=None, start_time=None, end_time=None, length=None, upper_length=None, lower_length=None, return_series=None, **_extra):
    import json, os, datetime, time, math, hashlib

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0416000" if __import__("os").path.isdir("./environment_mix/0416000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return None
        v = s.strip()
        try:
            if v.endswith("Z"):
                v = v[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(v)
        except Exception:
            return None

    def _to_float(x):
        try:
            if isinstance(x, bool):
                return None
            return float(x)
        except Exception:
            return None

    def _audit(status, tool_name, credential_id, meta=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "tool": tool_name,
            "credential_id": credential_id,
            "status": status,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _now_iso(),
            "error_code": error_code,
            "meta": meta or {}
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _resolve_auth():
        for fn in ("api_keys.json", "keys.json", "credentials.json"):
            rows = _load(fn)
            if isinstance(rows, list):
                for r in rows:
                    if isinstance(r, dict) and r.get("status") in (None, "active", "enabled"):
                        return (r.get("id") or "ambient", r)
        return ("ambient", None)

    def _id(prefix):
        return f"{prefix}_{int(time.time()*1000)}_{os.getpid()}_{int.from_bytes(os.urandom(3),'big')}"

    tool = "calculate_projection_oscillator"
    credential_id, _cred = _resolve_auth()

    if not isinstance(symbol, str) or not symbol.strip():
        _audit("error", tool, credential_id, meta={"symbol": symbol}, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "symbol is required and must be a non-empty string", field="symbol")

    allowed_intervals = ["1m","3m","5m","15m","30m","1h","2h","4h","6h","8h","12h","1d","3d","1w","1M"]
    interval = interval or "1h"
    if interval not in allowed_intervals:
        _audit("error", tool, credential_id, meta={"interval": interval}, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "interval is unsupported", field="interval", allowed=allowed_intervals)

    if limit is None:
        limit = 200
    if not isinstance(limit, int) or isinstance(limit, bool) or limit < 1 or limit > 5000:
        _audit("error", tool, credential_id, meta={"limit": limit}, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer in range 1–5000", field="limit")

    if length is None:
        length = 14
    if not isinstance(length, int) or isinstance(length, bool) or length < 1:
        _audit("error", tool, credential_id, meta={"length": length}, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "length must be an integer >= 1", field="length")

    if upper_length is not None and (not isinstance(upper_length, int) or isinstance(upper_length, bool) or upper_length < 1):
        _audit("error", tool, credential_id, meta={"upper_length": upper_length}, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "upper_length must be an integer >= 1", field="upper_length")
    if lower_length is not None and (not isinstance(lower_length, int) or isinstance(lower_length, bool) or lower_length < 1):
        _audit("error", tool, credential_id, meta={"lower_length": lower_length}, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "lower_length must be an integer >= 1", field="lower_length")

    if return_series is None:
        return_series = False
    if not isinstance(return_series, bool):
        _audit("error", tool, credential_id, meta={"return_series": return_series}, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "return_series must be boolean", field="return_series")

    st = _parse_dt(start_time)
    if start_time is not None and st is None:
        _audit("error", tool, credential_id, meta={"start_time": start_time}, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "start_time must be a valid ISO-8601 datetime", field="start_time")
    et = _parse_dt(end_time)
    if end_time is not None and et is None:
        _audit("error", tool, credential_id, meta={"end_time": end_time}, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "end_time must be a valid ISO-8601 datetime", field="end_time")
    if st is not None and et is not None and st > et:
        _audit("error", tool, credential_id, meta={"start_time": start_time, "end_time": end_time}, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "start_time must be <= end_time", field="start_time")

    defs = _load("indicator_definitions.json")
    idef = None
    if isinstance(defs, list):
        for d in defs:
            if isinstance(d, dict) and d.get("tool_name") == tool:
                idef = d
                break
    if not idef:
        _audit("error", tool, credential_id, meta={}, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "indicator definition not found for tool", tool_name=tool)
    if not idef.get("is_enabled") or idef.get("status") not in ("active", "deprecated"):
        _audit("error", tool, credential_id, meta={"indicator_id": idef.get("id")}, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "tool is not enabled", tool_name=tool)

    pairs = _load("trading_pairs.json")
    pair = None
    if isinstance(pairs, list):
        for p in pairs:
            if isinstance(p, dict) and p.get("exchange") == "binance" and p.get("symbol") == symbol.strip():
                pair = p
                break
    if not pair:
        _audit("error", tool, credential_id, meta={"symbol": symbol}, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "trading pair not found", symbol=symbol)
    if pair.get("status") != "active":
        jobs = _load("computation_jobs.json")
        if not isinstance(jobs, list):
            jobs = []
        now = _now_iso()
        fp_src = {"tool": tool, "pair_id": pair.get("id"), "interval": interval, "limit": limit, "start_time": start_time, "end_time": end_time, "length": length, "upper_length": upper_length, "lower_length": lower_length}
        fp = hashlib.sha256(json.dumps(fp_src, sort_keys=True, ensure_ascii=False).encode("utf-8")).hexdigest()
        job = {
            "id": _id("job"),
            "indicator_id": idef.get("id"),
            "pair_id": pair.get("id"),
            "interval": interval,
            "candle_limit": limit,
            "input_start_time": start_time,
            "input_end_time": end_time,
            "request_fingerprint": fp,
            "cache_hit": False,
            "status": "failed",
            "queued_at": now,
            "started_at": now,
            "finished_at": now,
            "error_code": "PAIR_DISABLED",
            "error_message": "Trading pair is not active",
            "binance_request_count": 0,
            "compute_time_ms": 0,
            "created_at": now,
            "updated_at": now
        }
        jobs.append(job)
        _save("computation_jobs.json", jobs)
        _audit("error", tool, credential_id, meta={"job_id": job["id"], "error_code": "PAIR_DISABLED"}, error_code="PAIR_DISABLED")
        return _err("INVALID_TRANSITION", "trading pair is not active for new computations", error_code="PAIR_DISABLED", pair_status=pair.get("status"))

    fp_src = {"tool": tool, "pair_id": pair.get("id"), "interval": interval, "limit": limit, "start_time": start_time, "end_time": end_time, "length": length, "upper_length": upper_length, "lower_length": lower_length, "return_series": bool(return_series)}
    fp = hashlib.sha256(json.dumps(fp_src, sort_keys=True, ensure_ascii=False).encode("utf-8")).hexdigest()

    jobs = _load("computation_jobs.json")
    if not isinstance(jobs, list):
        jobs = []
    results = _load("computation_results.json")
    if not isinstance(results, list):
        results = []

    now_dt = datetime.datetime.now(datetime.timezone.utc)
    def _dt_from_iso(s):
        return _parse_dt(s)

    cached_job = None
    cached_result = None
    for j in jobs:
        if not isinstance(j, dict):
            continue
        if j.get("status") == "succeeded" and j.get("request_fingerprint") == fp and j.get("finished_at"):
            r = next((rr for rr in results if isinstance(rr, dict) and rr.get("job_id") == j.get("id")), None)
            if not r:
                continue
            exp = r.get("expires_at")
            if exp is None:
                cached_job, cached_result = j, r
                break
            exp_dt = _dt_from_iso(exp)
            if exp_dt is not None and exp_dt >= now_dt:
                cached_job, cached_result = j, r
                break

    if cached_job and cached_result:
        now = _now_iso()
        new_job = {
            "id": _id("job"),
            "indicator_id": idef.get("id"),
            "pair_id": pair.get("id"),
            "interval": interval,
            "candle_limit": limit,
            "input_start_time": start_time,
            "input_end_time": end_time,
            "request_fingerprint": fp,
            "cache_hit": True,
            "status": "cancelled",
            "queued_at": now,
            "started_at": now,
            "finished_at": now,
            "error_code": None,
            "error_message": None,
            "binance_request_count": 0,
            "compute_time_ms": 0,
            "created_at": now,
            "updated_at": now
        }
        jobs.append(new_job)
        _save("computation_jobs.json", jobs)
        _audit("ok", tool, credential_id, meta={"cache_hit": True, "job_id": new_job["id"], "cached_job_id": cached_job.get("id")})
        return {
            "job": new_job,
            "cached_from_job_id": cached_job.get("id"),
            "pair": {"id": pair.get("id"), "exchange": pair.get("exchange"), "symbol": pair.get("symbol")},
            "interval": interval,
            "indicator": {"id": idef.get("id"), "tool_name": tool},
            "result": cached_result if return_series else {**cached_result, "series": None, "multi_series": None}
        }

    now = _now_iso()
    job = {
        "id": _id("job"),
        "indicator_id": idef.get("id"),
        "pair_id": pair.get("id"),
        "interval": interval,
        "candle_limit": limit,
        "input_start_time": start_time,
        "input_end_time": end_time,
        "request_fingerprint": fp,
        "cache_hit": False,
        "status": "queued",
        "queued_at": now,
        "started_at": None,
        "finished_at": None,
        "error_code": None,
        "error_message": None,
        "binance_request_count": 0,
        "compute_time_ms": None,
        "created_at": now,
        "updated_at": now
    }
    jobs.append(job)
    _save("computation_jobs.json", jobs)

    job["status"] = "running"
    job["started_at"] = _now_iso()
    job["updated_at"] = job["started_at"]
    _save("computation_jobs.json", jobs)

    candles = _load("ohlcv_candles.json")
    if not isinstance(candles, list):
        candles = []
    pid = pair.get("id")
    sel = []
    for c in candles:
        if not isinstance(c, dict):
            continue
        if c.get("pair_id") != pid or c.get("interval") != interval:
            continue
        ot = _parse_dt(c.get("open_time"))
        if ot is None:
            continue
        if st is not None and ot < st:
            continue
        if et is not None and ot > et:
            continue
        sel.append((ot, c))
    sel.sort(key=lambda x: x[0])
    if len(sel) > limit:
        sel = sel[-limit:]

    min_need = int(idef.get("min_lookback_candles") or 1)
    need = max(min_need, length, upper_length or 1, lower_length or 1)
    if len(sel) < need:
        fin = _now_iso()
        job["status"] = "failed"
        job["finished_at"] = fin
        job["updated_at"] = fin
        job["error_code"] = "INSUFFICIENT_DATA"
        job["error_message"] = "Not enough candles to compute indicator"
        job["compute_time_ms"] = int((time.time() - _t0) * 1000)
        _save("computation_jobs.json", jobs)
        _audit("error", tool, credential_id, meta={"job_id": job["id"], "have": len(sel), "need": need}, error_code="INSUFFICIENT_DATA")
        return _err("CONFLICT", "insufficient data to compute indicator", error_code="INSUFFICIENT_DATA", candles_available=len(sel), candles_required=need)

    highs = []
    lows = []
    closes = []
    times = []
    for _, c in sel:
        h = _to_float(c.get("high"))
        l = _to_float(c.get("low"))
        cl = _to_float(c.get("close"))
        if h is None or l is None or cl is None:
            continue
        highs.append(h)
        lows.append(l)
        closes.append(cl)
        times.append(c.get("close_time") or c.get("open_time"))

    if len(highs) < need:
        fin = _now_iso()
        job["status"] = "failed"
        job["finished_at"] = fin
        job["updated_at"] = fin
        job["error_code"] = "INSUFFICIENT_DATA"
        job["error_message"] = "Not enough valid OHLC points"
        job["compute_time_ms"] = int((time.time() - _t0) * 1000)
        _save("computation_jobs.json", jobs)
        _audit("error", tool, credential_id, meta={"job_id": job["id"]}, error_code="INSUFFICIENT_DATA")
        return _err("CONFLICT", "insufficient data to compute indicator", error_code="INSUFFICIENT_DATA")

    # Compute Projection Oscillator (approx):
    # PO = 100 * (close - lower_proj) / (upper_proj - lower_proj)
    # Use rolling max(high, window_upper) and rolling min(low, window_lower) as projections.
    t_comp0 = time.time()
    ulen = upper_length or length
    llen = lower_length or length

    po = [None] * len(closes)
    for i in range(len(closes)):
        if i + 1 < max(ulen, llen):
            continue
        hi = max(highs[i - ulen + 1:i + 1]) if ulen > 0 else highs[i]
        lo = min(lows[i - llen + 1:i + 1]) if llen > 0 else lows[i]
        denom = hi - lo
        if denom <= 0:
            po[i] = 0.0
        else:
            po[i] = 100.0 * (closes[i] - lo) / denom

    latest_idx = None
    for i in range(len(po) - 1, -1, -1):
        if po[i] is not None:
            latest_idx = i
            break
    if latest_idx is None:
        fin = _now_iso()
        job["status"] = "failed"
        job["finished_at"] = fin
        job["updated_at"] = fin
        job["error_code"] = "INSUFFICIENT_DATA"
        job["error_message"] = "No computable output within window"
        job["compute_time_ms"] = int((time.time() - t_comp0) * 1000)
        _save("computation_jobs.json", jobs)
        _audit("error", tool, credential_id, meta={"job_id": job["id"]}, error_code="INSUFFICIENT_DATA")
        return _err("CONFLICT", "insufficient data to compute indicator", error_code="INSUFFICIENT_DATA")

    latest_value = float(po[latest_idx])
    as_of_time = times[latest_idx]

    ttl = int(idef.get("cache_ttl_seconds") or 0)
    created = _now_iso()
    expires_at = None
    if ttl > 0:
        expires_at = (datetime.datetime.now(datetime.timezone.utc) + datetime.timedelta(seconds=ttl)).isoformat()

    res = {
        "id": _id("res"),
        "job_id": job["id"],
        "result_kind": "series",
        "as_of_time": as_of_time,
        "value": latest_value,
        "signal": None,
        "series": None,
        "multi_series": None,
        "metadata": {"length": length, "upper_length": ulen, "lower_length": llen},
        "expires_at": expires_at,
        "created_at": created,
        "updated_at": created
    }
    if return_series:
        pts = []
        for i, v in enumerate(po):
            if v is None:
                continue
            pts.append({"t": times[i], "v": float(v)})
        res["series"] = pts

    results.append(res)

    fin = _now_iso()
    job["status"] = "succeeded"
    job["finished_at"] = fin
    job["updated_at"] = fin
    job["compute_time_ms"] = int((time.time() - t_comp0) * 1000)

    _save("computation_results.json", results)
    _save("computation_jobs.json", jobs)

    _audit("ok", tool, credential_id, meta={"cache_hit": False, "job_id": job["id"]})
    return {
        "job": job,
        "pair": {"id": pair.get("id"), "exchange": pair.get("exchange"), "symbol": pair.get("symbol")},
        "interval": interval,
        "indicator": {"id": idef.get("id"), "tool_name": tool},
        "result": res if return_series else {**res, "series": None, "multi_series": None}
    }

def calculate_true_range(symbol, interval=None, limit=None, start_time=None, end_time=None, return_series=None, **_extra):
    import json, os, datetime, time, math, hashlib

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0416000" if __import__("os").path.isdir("./environment_mix/0416000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

