            if not r:
                continue
            exp = r.get("expires_at")
            if exp is None:
                cached_job, cached_result = j, r
                break
            exp_dt = _dt_from_iso(exp)
            if exp_dt is not None and exp_dt >= now_dt:
                cached_job, cached_result = j, r
                break

    if cached_job and cached_result:
        now = _now_iso()
