    need = max(min_need, 2)  # TR needs prev close for stable series; but we can compute first as high-low.
    if len(sel) < need:
        fin = _now_iso()
        job["status"] = "failed"
        job["finished_at"] = fin
        job["updated_at"] = fin
        job["error_code"] = "INSUFFICIENT_DATA"
