    lows = []
    closes = []
    times = []
    for _, c in sel:
        h = _to_float(c.get("high"))
        l = _to_float(c.get("low"))
        cl = _to_float(c.get("close"))
        if h is None or l is None or cl is None:
            continue
        highs.append(h); lows.append(l); closes.append(cl)
        times.append(c.get("close_time") or c.get("open_time"))

