        job["finished_at"] = fin
        job["updated_at"] = fin
        job["error_code"] = "INSUFFICIENT_DATA"
        job["error_message"] = "Not enough valid OHLC points"
        job["compute_time_ms"] = int((time.time() - _t0) * 1000)
        _save("computation_jobs.json", jobs)
        _audit("error", tool, credential_id, meta={"job_id": job["id"]}, error_code="INSUFFICIENT_DATA")
        return _err("CONFLICT", "insufficient data to compute indicator", error_code="INSUFFICIENT_DATA")

    t_comp0 = time.time()
    tr = [None] * len(highs)
    prev_close = None
    for i in range(len(highs)):
        h, l, c = highs[i], lows[i], closes[i]
        if prev_close is None:
            tr[i] = h - l
        else:
            tr[i] = max(h - l, abs(h - prev_close), abs(l - prev_close))
        prev_close = c

    latest_idx = None
    for i in range(len(tr) - 1, -1, -1):
        if tr[i] is not None:
            latest_idx = i
            break
    if latest_idx is None:
        fin = _now_iso()
        job["status"] = "failed"
        job["finished_at"] = fin
        job["updated_at"] = fin
        job["error_code"] = "INSUFFICIENT_DATA"
        job["error_message"] = "No computable output within window"
        job["compute_time_ms"] = int((time.time() - t_comp0) * 1000)
        _save("computation_jobs.json", jobs)
        _audit("error", tool, credential_id, meta={"job_id": job["id"]}, error_code="INSUFFICIENT_DATA")
        return _err("CONFLICT", "insufficient data to compute indicator", error_code="INSUFFICIENT_DATA")

    latest_value = float(tr[latest_idx])
    as_of_time = times[latest_idx]

    ttl = int(idef.get("cache_ttl_seconds") or 0)
    created = _now_iso()
    expires_at = None
    if ttl > 0:
        expires_at = (datetime.datetime.now(datetime.timezone.utc) + datetime.timedelta(seconds=ttl)).isoformat()

    res = {
        "id": _id("res"),
        "job_id": job["id"],
        "result_kind": "series",
        "as_of_time": as_of_time,
        "value": latest_value,
        "signal": None,
        "series": None,
        "multi_series": None,
        "metadata": {},
        "expires_at": expires_at,
        "created_at": created,
        "updated_at": created
    }
    if return_series:
        pts = [{"t": times[i], "v": float(tr[i])} for i in range(len(tr)) if tr[i] is not None]
        res["series"] = pts

    results.append(res)

    fin = _now_iso()
    job["status"] = "succeeded"
    job["finished_at"] = fin
    job["updated_at"] = fin
    job["compute_time_ms"] = int((time.time() - t_comp0) * 1000)

    _save("computation_results.json", results)
    _save("computation_jobs.json", jobs)

    _audit("ok", tool, credential_id, meta={"cache_hit": False, "job_id": job["id"]})
    return {
        "job": job,
        "pair": {"id": pair.get("id"), "exchange": pair.get("exchange"), "symbol": pair.get("symbol")},
        "interval": interval,
        "indicator": {"id": idef.get("id"), "tool_name": tool},
        "result": res if return_series else {**res, "series": None, "multi_series": None}
    }

