    now_dt = datetime.datetime.now(datetime.timezone.utc)
    def _dt_from_iso(s):
        return _parse_dt(s)

    cached_job = None
    cached_result = None
    for j in jobs:
        if not isinstance(j, dict):
            continue
        if j.get("status") == "succeeded" and j.get("request_fingerprint") == fp and j.get("finished_at"):
            r = next((rr for rr in results if isinstance(rr, dict) and rr.get("job_id") == j.get("id")), None)
            if not r:
                continue
            exp = r.get("expires_at")
            if exp is None:
                cached_job, cached_result = j, r
                break
            exp_dt = _dt_from_iso(exp)
            if exp_dt is not None and exp_dt >= now_dt:
                cached_job, cached_result = j, r
                break

    if cached_job and cached_result:
        now = _now_iso()
        new_job = {
            "id": _id("job"),
            "indicator_id": idef.get("id"),
            "pair_id": pair.get("id"),
            "interval": interval,
            "candle_limit": limit,
            "input_start_time": start_time,
            "input_end_time": end_time,
            "request_fingerprint": fp,
            "cache_hit": True,
            "status": "cancelled",
            "queued_at": now,
            "started_at": now,
            "finished_at": now,
            "error_code": None,
            "error_message": None,
            "binance_request_count": 0,
            "compute_time_ms": 0,
            "created_at": now,
            "updated_at": now
        }
        jobs.append(new_job)
        _save("computation_jobs.json", jobs)
        _audit("ok", tool, credential_id, meta={"cache_hit": True, "job_id": new_job["id"], "cached_job_id": cached_job.get("id")})
        return {
            "job": new_job,
            "cached_from_job_id": cached_job.get("id"),
            "pair": {"id": pair.get("id"), "exchange": pair.get("exchange"), "symbol": pair.get("symbol")},
            "interval": interval,
            "indicator": {"id": idef.get("id"), "tool_name": tool},
            "result": cached_result if return_series else {**cached_result, "series": None, "multi_series": None}
        }

    now = _now_iso()
    job = {
        "id": _id("job"),
        "indicator_id": idef.get("id"),
        "pair_id": pair.get("id"),
        "interval": interval,
        "candle_limit": limit,
        "input_start_time": start_time,
        "input_end_time": end_time,
        "request_fingerprint": fp,
        "cache_hit": False,
        "status": "queued",
        "queued_at": now,
        "started_at": None,
        "finished_at": None,
        "error_code": None,
        "error_message": None,
        "binance_request_count": 0,
        "compute_time_ms": None,
        "created_at": now,
        "updated_at": now
    }
    jobs.append(job)
    _save("computation_jobs.json", jobs)

    job["status"] = "running"
    job["started_at"] = _now_iso()
    job["updated_at"] = job["started_at"]
    _save("computation_jobs.json", jobs)

    candles = _load("ohlcv_candles.json")
    if not isinstance(candles, list):
        candles = []
    pid = pair.get("id")
    sel = []
    for c in candles:
        if not isinstance(c, dict):
            continue
        if c.get("pair_id") != pid or c.get("interval") != interval:
            continue
        ot = _parse_dt(c.get("open_time"))
        if ot is None:
            continue
        if st is not None and ot < st:
            continue
        if et is not None and ot > et:
            continue
        sel.append((ot, c))
    sel.sort(key=lambda x: x[0])
    if len(sel) > limit:
        sel = sel[-limit:]

    min_need = int(idef.get("min_lookback_candles") or 1)
    need = max(min_need, length)
    if len(sel) < need:
        fin = _now_iso()
        job["status"] = "failed"
        job["finished_at"] = fin
        job["updated_at"] = fin
        job["error_code"] = "INSUFFICIENT_DATA"
        job["error_message"] = "Not enough candles to compute indicator"
        job["compute_time_ms"] = int((time.time() - _t0) * 1000)
        _save("computation_jobs.json", jobs)
        _audit("error", tool, credential_id, meta={"job_id": job["id"], "have": len(sel), "need": need}, error_code="INSUFFICIENT_DATA")
        return _err("CONFLICT", "insufficient data to compute indicator", error_code="INSUFFICIENT_DATA", candles_available=len(sel), candles_required=need)

    prices = []
    times = []
    for _, c in sel:
        v = _to_float(c.get(price_field))
        if v is None:
            continue
        prices.append(v)
        times.append(c.get("close_time") or c.get("open_time"))

    if len(prices) < need:
        fin = _now_iso()
        job["status"] = "failed"
        job["finished_at"] = fin
        job["updated_at"] = fin
        job["error_code"] = "INSUFFICIENT_DATA"
        job["error_message"] = "Not enough valid price points"
        job["compute_time_ms"] = int((time.time() - _t0) * 1000)
        _save("computation_jobs.json", jobs)
        _audit("error", tool, credential_id, meta={"job_id": job["id"]}, error_code="INSUFFICIENT_DATA")
        return _err("CONFLICT", "insufficient data to compute indicator", error_code="INSUFFICIENT_DATA")

    # Ulcer Index:
    # For each i, compute drawdown% from rolling peak over last length:
    # dd = 100 * (price - peak) / peak (<= 0), then UI = sqrt(mean(dd^2)) over the length window
    t_comp0 = time.time()
    ui = [None] * len(prices)
    dd = [None] * len(prices)
    for i in range(len(prices)):
        if i + 1 < length:
            continue
        window = prices[i - length + 1:i + 1]
        peak = max(window)
        if peak <= 0:
            dd[i] = 0.0
        else:
            dd[i] = 100.0 * (prices[i] - peak) / peak  # negative or zero
        # compute RMS of dd over window
        dws = []
        for j in range(i - length + 1, i + 1):
            # compute dd for each j relative to its own rolling peak window ending at j, common variant uses peak within same window ending at j
            # But classic UI uses rolling peak within the lookback window ending at j; we'll approximate using peak within the window ending at i for all points.
            if peak <= 0:
                dws.append(0.0)
            else:
                dws.append(100.0 * (prices[j] - peak) / peak)
        mse = sum(x * x for x in dws) / float(length)
        ui[i] = math.sqrt(mse)

    latest_idx = None
    for i in range(len(ui) - 1, -1, -1):
        if ui[i] is not None:
            latest_idx = i
            break
    if latest_idx is None:
        fin = _now_iso()
        job["status"] = "failed"
        job["finished_at"] = fin
        job["updated_at"] = fin
        job["error_code"] = "INSUFFICIENT_DATA"
        job["error_message"] = "No computable output within window"
        job["compute_time_ms"] = int((time.time() - t_comp0) * 1000)
        _save("computation_jobs.json", jobs)
        _audit("error", tool, credential_id, meta={"job_id": job["id"]}, error_code="INSUFFICIENT_DATA")
        return _err("CONFLICT", "insufficient data to compute indicator", error_code="INSUFFICIENT_DATA")

    latest_value = float(ui[latest_idx])
    as_of_time = times[latest_idx]

    ttl = int(idef.get("cache_ttl_seconds") or 0)
    created = _now_iso()
    expires_at = None
    if ttl > 0:
        expires_at = (datetime.datetime.now(datetime.timezone.utc) + datetime.timedelta(seconds=ttl)).isoformat()

    res = {
        "id": _id("res"),
        "job_id": job["id"],
        "result_kind": "series",
        "as_of_time": as_of_time,
        "value": latest_value,
        "signal": None,
        "series": None,
        "multi_series": None,
        "metadata": {"length": length, "price_field": price_field},
        "expires_at": expires_at,
        "created_at": created,
        "updated_at": created
    }
    if return_series:
        pts = []
        for i, v in enumerate(ui):
            if v is None:
                continue
            pts.append({"t": times[i], "v": float(v)})
        res["series"] = pts

    results.append(res)

    fin = _now_iso()
    job["status"] = "succeeded"
    job["finished_at"] = fin
    job["updated_at"] = fin
    job["compute_time_ms"] = int((time.time() - t_comp0) * 1000)

    _save("computation_results.json", results)
    _save("computation_jobs.json", jobs)

    _audit("ok", tool, credential_id, meta={"cache_hit": False, "job_id": job["id"]})
    return {
        "job": job,
        "pair": {"id": pair.get("id"), "exchange": pair.get("exchange"), "symbol": pair.get("symbol")},
        "interval": interval,
        "indicator": {"id": idef.get("id"), "tool_name": tool},
        "result": res if return_series else {**res, "series": None, "multi_series": None}
    }

def calculate_accumulation_distribution(symbol, interval=None, limit=None, start_time=None, end_time=None, return_series=None, **_extra):
    import json, os, datetime, hashlib, time, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0416000" if __import__("os").path.isdir("./environment_mix/0416000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "calculate_accumulation_distribution"
    allowed_intervals = ["1m","3m","5m","15m","30m","1h","2h","4h","6h","8h","12h","1d","3d","1w","1M"]

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _isoz(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            dt = v
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        if not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _get_rows(doc):
        if isinstance(doc, dict) and isinstance(doc.get("rows"), list):
            return doc["rows"]
        if isinstance(doc, list):
            return doc
        return []

    def _save_doc(fname, original, rows):
        if isinstance(original, dict) and isinstance(original.get("rows"), list):
            original["rows"] = rows
            _save(fname, original)
        else:
            _save(fname, rows)

    def _new_id(prefix):
        ts = datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%d%H%M%S%f")
        return f"{prefix}_{ts}_{os.urandom(3).hex()}"

    def _fingerprint(obj):
        s = json.dumps(obj, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _log(status, error_code=None, extra=None):
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            return
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": _new_id("req"),
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _isoz(_utcnow()),
        }
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save("request_logs.json", logs)

    try:
        if not isinstance(symbol, str) or not symbol.strip():
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "symbol must be a non-empty string", field="symbol")
        symbol_n = symbol.strip().upper()

        if interval is None:
            interval = "1d"
        if not isinstance(interval, str) or interval not in allowed_intervals:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "interval must be one of the supported Binance intervals", field="interval", allowed=allowed_intervals)

        if limit is None:
            limit = 200
        if not isinstance(limit, int) or limit < 1 or limit > 5000:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit must be an integer in range 1..5000", field="limit")

        st = _parse_dt(start_time) if start_time is not None else None
        et = _parse_dt(end_time) if end_time is not None else None
        if start_time is not None and st is None:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "start_time must be an ISO 8601 date-time string", field="start_time")
        if end_time is not None and et is None:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "end_time must be an ISO 8601 date-time string", field="end_time")
        if st and et and st > et:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "start_time must be <= end_time", field="start_time", start_time=_isoz(st), end_time=_isoz(et))

        if return_series is None:
            return_series = False
        if not isinstance(return_series, bool):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "return_series must be a boolean", field="return_series")

        defs_doc = _load("indicator_definitions.json")
        defs_rows = _get_rows(defs_doc)
        idef = None
        for r in defs_rows:
            if isinstance(r, dict) and r.get("tool_name") == endpoint:
                idef = r
                break
        if not idef:
            _log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "indicator definition not found for tool", tool_name=endpoint)
        if not idef.get("is_enabled", False) or idef.get("status") not in ("active", "deprecated"):
            _log("error", "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Tool is not enabled or not available.", tool_name=endpoint, status=idef.get("status"), is_enabled=idef.get("is_enabled"))

        pairs_doc = _load("trading_pairs.json")
        pairs = _get_rows(pairs_doc)
        pair = None
        for p in pairs:
            if isinstance(p, dict) and p.get("exchange") == "binance" and str(p.get("symbol", "")).upper() == symbol_n:
                pair = p
                break
        if not pair:
            _log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "Trading pair symbol not found on exchange.", symbol=symbol_n, exchange="binance")
        if pair.get("status") != "active":
            _log("error", "INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", "Trading pair is not active; refusing new computation job.", error_code="PAIR_DISABLED", pair_id=pair.get("id"), status=pair.get("status"))

        norm = {
            "tool_name": endpoint,
            "pair_id": pair.get("id"),
            "interval": interval,
            "limit": int(limit),
            "start_time": _isoz(st) if st else None,
            "end_time": _isoz(et) if et else None,
            "return_series": bool(return_series),
        }
        fp = _fingerprint(norm)

        jobs_doc = _load("computation_jobs.json")
        jobs = _get_rows(jobs_doc)
        results_doc = _load("computation_results.json")
        results = _get_rows(results_doc)

        def _find_result_by_job(job_id):
            for rr in results:
                if isinstance(rr, dict) and rr.get("job_id") == job_id:
                    return rr
            return None

        now = _utcnow()
        # Always allow caching per business rule; this tool doesn't include use_cache param
        for j in jobs:
            if not isinstance(j, dict):
                continue
            if j.get("request_fingerprint") != fp:
                continue
            if j.get("status") != "succeeded" or not j.get("finished_at"):
                continue
            r = _find_result_by_job(j.get("id"))
            if not r:
                continue
            exp = _parse_dt(r.get("expires_at"))
            if exp is not None and exp < now:
                continue
            new_job = {
                "id": _new_id("cijob"),
                "indicator_id": idef.get("id"),
                "pair_id": pair.get("id"),
                "interval": interval,
                "candle_limit": int(limit),
                "input_start_time": _isoz(st) if st else None,
                "input_end_time": _isoz(et) if et else None,
                "request_fingerprint": fp,
                "cache_hit": True,
                "status": "succeeded",
                "queued_at": _isoz(now),
                "started_at": _isoz(now),
                "finished_at": _isoz(now),
                "error_code": None,
                "error_message": None,
                "binance_request_count": 0,
                "compute_time_ms": 0,
                "created_at": _isoz(now),
                "updated_at": _isoz(now),
            }
            jobs.append(new_job)
            _save_doc("computation_jobs.json", jobs_doc, jobs)
            _log("ok", extra={"cache_hit": True})
            # Return simplified envelope
            out = {"tool_name": endpoint, "cache_hit": True, "job": new_job, "value": r.get("value")}
            if return_series:
                out["series"] = r.get("series")
            return out

        job = {
            "id": _new_id("cijob"),
            "indicator_id": idef.get("id"),
            "pair_id": pair.get("id"),
            "interval": interval,
            "candle_limit": int(limit),
            "input_start_time": _isoz(st) if st else None,
            "input_end_time": _isoz(et) if et else None,
            "request_fingerprint": fp,
            "cache_hit": False,
            "status": "queued",
            "queued_at": _isoz(now),
            "started_at": None,
            "finished_at": None,
            "error_code": None,
            "error_message": None,
            "binance_request_count": 0,
            "compute_time_ms": None,
            "created_at": _isoz(now),
            "updated_at": _isoz(now),
        }
        jobs.append(job)
        _save_doc("computation_jobs.json", jobs_doc, jobs)

        job["status"] = "running"
        job["started_at"] = _isoz(_utcnow())
        job["updated_at"] = job["started_at"]
        _save_doc("computation_jobs.json", jobs_doc, jobs)

        candles_doc = _load("ohlcv_candles.json")
        candles = _get_rows(candles_doc)
        rows = [c for c in candles if isinstance(c, dict) and c.get("pair_id") == pair.get("id") and c.get("interval") == interval]
        # Time bounds on close_time (inclusive)
        if st or et:
            filt = []
            for c in rows:
                ct = _parse_dt(c.get("close_time")) or _parse_dt(c.get("open_time"))
                if ct is None:
                    continue
                if st and ct < st:
                    continue
                if et and ct > et:
                    continue
                filt.append(c)
            rows = filt
        rows.sort(key=lambda x: str(x.get("open_time") or ""))
        rows = rows[-int(limit):]

        required = int(idef.get("min_lookback_candles") or 1)
        if len(rows) < required:
            fin = _utcnow()
            job["status"] = "failed"
            job["finished_at"] = _isoz(fin)
            job["updated_at"] = _isoz(fin)
            job["error_code"] = "INSUFFICIENT_DATA"
            job["error_message"] = f"Need {required} lookback candles for interval {interval}; only {len(rows)} available."
            _save_doc("computation_jobs.json", jobs_doc, jobs)
            _log("error", "CONFLICT", extra={"error_code": "INSUFFICIENT_DATA"})
            return _err("CONFLICT", "Insufficient data to compute indicator.", error_code="INSUFFICIENT_DATA", required_candles=required, available_candles=len(rows), job_id=job["id"])

        # AD line: cumulative money flow volume
        ad = 0.0
        series = []
        for c in rows:
            h = float(c.get("high"))
            l = float(c.get("low"))
            cl = float(c.get("close"))
            v = float(c.get("volume"))
            denom = (h - l)
            mfm = 0.0 if denom == 0 else ((cl - l) - (h - cl)) / denom  # money flow multiplier
            mfv = mfm * v
            ad += mfv
            t = c.get("close_time") or c.get("open_time")
            series.append({"t": t, "v": ad})

        latest = series[-1]
        as_of = latest["t"]
        latest_val = latest["v"]

        fin = _utcnow()
        job["status"] = "succeeded"
        job["finished_at"] = _isoz(fin)
        job["updated_at"] = _isoz(fin)
        job["compute_time_ms"] = max(0, int((time.time() - t0) * 1000))
        _save_doc("computation_jobs.json", jobs_doc, jobs)

        ttl = idef.get("cache_ttl_seconds")
        expires_at = None
        if isinstance(ttl, int) and ttl > 0:
            expires_at = _isoz(fin + datetime.timedelta(seconds=int(ttl)))

        result_row = {
            "id": _new_id("cires"),
            "job_id": job["id"],
            "result_kind": "series",
            "as_of_time": as_of,
            "value": latest_val,
            "signal": None,
            "series": series if return_series else None,
            "multi_series": None,
            "metadata": {"limit": limit, "start_time": _isoz(st) if st else None, "end_time": _isoz(et) if et else None, "return_series": bool(return_series)},
            "expires_at": expires_at,
            "created_at": _isoz(fin),
            "updated_at": _isoz(fin),
        }
        results.append(result_row)
        _save_doc("computation_results.json", results_doc, results)

        _log("ok")
        out = {"tool_name": endpoint, "cache_hit": False, "job": job, "value": latest_val}
        if return_series:
            out["series"] = series
        return out
    except Exception as e:
        _log("error", "CONFLICT")
        return _err("CONFLICT", "Unexpected server error.", details=str(e), tool_name=endpoint)

def calculate_chaikin_money_flow(symbol, interval=None, limit=None, start_time=None, end_time=None, length=None, return_series=None, **_extra):
    import json, os, datetime, time, hashlib, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0416000" if __import__("os").path.isdir("./environment_mix/0416000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "calculate_chaikin_money_flow"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            return "TYPE", _err("VALIDATION_ERROR", f"{field} must be an ISO-8601 datetime string")
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
