    for p in pairs if isinstance(pairs, list) else []:
        if p.get("exchange") == "binance" and str(p.get("symbol", "")).upper() == symbol:
            pair = p
            break
    if not pair:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "trading pair not found", symbol=symbol, exchange="binance")

    # Pair must be active for new jobs
    jobs = _load("computation_jobs.json")
    if pair.get("status") != "active":
        now = _now_iso()
        fp = hashlib.sha256(json.dumps({
            "tool": endpoint, "pair_id": pair.get("id"), "interval": interval, "limit": int(limit),
            "start_time": start_time, "end_time": end_time, "params": {"length": int(length)}
        }, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()
        job_id = f"job_{uuid.uuid4().hex}"
        job = {
            "id": job_id,
            "indicator_id": idef.get("id"),
            "pair_id": pair.get("id"),
            "interval": interval,
            "candle_limit": int(limit),
            "input_start_time": st.isoformat() if st is not None else None,
            "input_end_time": et.isoformat() if et is not None else None,
            "request_fingerprint": fp,
            "cache_hit": False,
            "status": "failed",
            "queued_at": now,
            "started_at": now,
            "finished_at": now,
            "error_code": "PAIR_DISABLED",
            "error_message": "Trading pair is not active",
            "binance_request_count": 0,
            "compute_time_ms": 0,
            "created_at": now,
            "updated_at": now,
        }
        if not isinstance(jobs, list):
            jobs = []
        jobs.append(job)
        _save("computation_jobs.json", jobs)
        _log("error", used_job_id=job_id, cache_hit=False, error_code="PAIR_DISABLED")
        return _err("INVALID_TRANSITION", "Trading pair is not active for new computation jobs", error_code="PAIR_DISABLED", job_id=job_id)

    # Fingerprint & cache
    norm = {
        "tool": endpoint,
        "indicator_id": idef.get("id"),
        "pair_id": pair.get("id"),
        "interval": interval,
        "limit": int(limit),
        "start_time": st.isoformat() if st is not None else None,
        "end_time": et.isoformat() if et is not None else None,
        "params": {"length": int(length)},
        "return_series": bool(return_series) if return_series is not None else False
    }
    fp = hashlib.sha256(json.dumps(norm, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()

    results = _load("computation_results.json")
    if isinstance(jobs, list) and isinstance(results, list):
        for j in jobs:
            if j.get("request_fingerprint") == fp and j.get("status") == "succeeded" and j.get("finished_at"):
                cached = None
                for r in results:
                    if r.get("job_id") == j.get("id"):
                        cached = r
                        break
                if cached:
                    exp = cached.get("expires_at")
                    fresh = True
                    if exp is not None:
                        exp_dt = _parse_dt(exp, "expires_at")
                        if isinstance(exp_dt, tuple):
                            fresh = False
                        else:
                            fresh = exp_dt >= datetime.datetime.now(datetime.timezone.utc)
                    if fresh:
                        now = _now_iso()
                        job_id = f"job_{uuid.uuid4().hex}"
                        job = {
                            "id": job_id,
                            "indicator_id": idef.get("id"),
                            "pair_id": pair.get("id"),
                            "interval": interval,
                            "candle_limit": int(limit),
                            "input_start_time": st.isoformat() if st is not None else None,
                            "input_end_time": et.isoformat() if et is not None else None,
                            "request_fingerprint": fp,
                            "cache_hit": True,
                            "status": "succeeded",
                            "queued_at": now,
                            "started_at": now,
                            "finished_at": now,
                            "error_code": None,
                            "error_message": None,
                            "binance_request_count": 0,
                            "compute_time_ms": 0,
                            "created_at": now,
                            "updated_at": now,
                        }
