                            "job": job,
                            "pair": {"id": pair.get("id"), "exchange": pair.get("exchange"), "symbol": pair.get("symbol")},
                            "interval": interval,
                            "length": int(length),
                            "cached": True,
                            "as_of_time": cached.get("as_of_time"),
                            "latest": cached.get("value"),
                        }
                        if bool(return_series):
                            out["series"] = cached.get("series")
                        return out

    # Create job queued
    now = _now_iso()
    job_id = f"job_{uuid.uuid4().hex}"
    job = {
        "id": job_id,
        "indicator_id": idef.get("id"),
        "pair_id": pair.get("id"),
        "interval": interval,
        "candle_limit": int(limit),
        "input_start_time": st.isoformat() if st is not None else None,
