                    if exp is not None:
                        exp_dt = _parse_dt(exp, "expires_at")
                        if isinstance(exp_dt, tuple):
                            fresh = False
                        else:
                            fresh = exp_dt >= datetime.datetime.now(datetime.timezone.utc)
                    if fresh:
                        now = _now_iso()
                        job_id = f"job_{uuid.uuid4().hex}"
                        job = {
                            "id": job_id,
                            "indicator_id": idef.get("id"),
                            "pair_id": pair.get("id"),
                            "interval": interval,
                            "candle_limit": int(limit),
                            "input_start_time": st.isoformat() if st is not None else None,
                            "input_end_time": et.isoformat() if et is not None else None,
                            "request_fingerprint": fp,
                            "cache_hit": True,
                            "status": "succeeded",
                            "queued_at": now,
                            "started_at": now,
                            "finished_at": now,
                            "error_code": None,
                            "error_message": None,
                            "binance_request_count": 0,
                            "compute_time_ms": 0,
                            "created_at": now,
                            "updated_at": now,
                        }
                        jobs.append(job)
                        _save("computation_jobs.json", jobs)
                        _log("ok", used_job_id=job_id, cache_hit=True)
                        out = {
                            "job": job,
                            "pair": {"id": pair.get("id"), "exchange": pair.get("exchange"), "symbol": pair.get("symbol")},
                            "interval": interval,
                            "length": int(length),
                            "cached": True,
                            "as_of_time": cached.get("as_of_time"),
                            "latest": cached.get("value"),
                        }
                        if bool(return_series):
                            out["series"] = cached.get("series")
                        return out

    # Create queued job
    now = _now_iso()
    job_id = f"job_{uuid.uuid4().hex}"
    job = {
        "id": job_id,
        "indicator_id": idef.get("id"),
        "pair_id": pair.get("id"),
        "interval": interval,
        "candle_limit": int(limit),
        "input_start_time": st.isoformat() if st is not None else None,
        "input_end_time": et.isoformat() if et is not None else None,
        "request_fingerprint": fp,
        "cache_hit": False,
        "status": "queued",
        "queued_at": now,
        "started_at": None,
        "finished_at": None,
        "error_code": None,
        "error_message": None,
        "binance_request_count": 0,
        "compute_time_ms": None,
        "created_at": now,
        "updated_at": now,
    }
    if not isinstance(jobs, list):
        jobs = []
    jobs.append(job)
    _save("computation_jobs.json", jobs)

    def _update_job(fields):
        nonlocal jobs, job
        for k, v in fields.items():
            job[k] = v
        for i, jj in enumerate(jobs):
            if jj.get("id") == job_id:
                jobs[i] = job
                break
        _save("computation_jobs.json", jobs)

    _update_job({"status": "running", "started_at": _now_iso(), "updated_at": _now_iso()})

    # Candles
    candles = _load("ohlcv_candles.json")
    pid = pair.get("id")
    def _ot(c):
        dt = _parse_dt(c.get("open_time"), "open_time")
        if isinstance(dt, tuple):
            return None
        return dt
    rows = []
    if isinstance(candles, list):
        for c in candles:
            if c.get("pair_id") != pid or c.get("interval") != interval:
                continue
            ot = _ot(c)
            if ot is None:
                continue
            if st is not None and ot < st:
                continue
            if et is not None and ot > et:
                continue
            rows.append(c)
    rows.sort(key=lambda c: _ot(c) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc))
    if len(rows) > int(limit):
        rows = rows[-int(limit):]

    min_lb = idef.get("min_lookback_candles")
    if not isinstance(min_lb, int) or min_lb < 1:
        min_lb = 1
    if len(rows) < max(min_lb, 2):
        fin = _now_iso()
        _update_job({
            "status": "failed",
            "finished_at": fin,
            "updated_at": fin,
            "error_code": "INSUFFICIENT_DATA",
            "error_message": f"Need at least {max(min_lb, 2)} candles, found {len(rows)}",
            "compute_time_ms": 0
        })
        _log("error", used_job_id=job_id, cache_hit=False, error_code="INSUFFICIENT_DATA")
        return _err("CONFLICT", "Insufficient data to compute indicator", error_code="INSUFFICIENT_DATA", job_id=job_id)

    # Compute EMV (raw) then SMA(length)
    compute_start = time.time()
    raw = []
    times = []
    for i in range(1, len(rows)):
        c0 = rows[i-1]
        c1 = rows[i]
        try:
            high0 = float(c0.get("high")); low0 = float(c0.get("low"))
            high1 = float(c1.get("high")); low1 = float(c1.get("low"))
            vol1 = float(c1.get("volume"))
        except (TypeError, ValueError):
            continue
        mid0 = (high0 + low0) / 2.0
        mid1 = (high1 + low1) / 2.0
        dm = mid1 - mid0
        br = (high1 - low1)
        if br == 0:
            emv = 0.0
        else:
            # Common formulation uses volume-scaled box ratio; keep units consistent.
            emv = dm * (br / (vol1 if vol1 != 0 else 1.0))
        ot = _ot(c1) or datetime.datetime.now(datetime.timezone.utc)
        raw.append(emv)
        times.append(ot)

    if not raw:
        fin = _now_iso()
        _update_job({
            "status": "failed",
            "finished_at": fin,
            "updated_at": fin,
            "error_code": "INSUFFICIENT_DATA",
            "error_message": "No usable candles after validation",
            "compute_time_ms": int((time.time() - compute_start) * 1000)
        })
        _log("error", used_job_id=job_id, cache_hit=False, error_code="INSUFFICIENT_DATA")
        return _err("CONFLICT", "Insufficient data to compute indicator", error_code="INSUFFICIENT_DATA", job_id=job_id)

    L = int(length)
    # Need at least L raw points to compute SMA
    if len(raw) < L:
        fin = _now_iso()
        _update_job({
            "status": "failed",
            "finished_at": fin,
            "updated_at": fin,
            "error_code": "INSUFFICIENT_DATA",
            "error_message": f"Need at least {L+1} candles to compute EMV length={L}, found {len(rows)}",
            "compute_time_ms": int((time.time() - compute_start) * 1000)
        })
        _log("error", used_job_id=job_id, cache_hit=False, error_code="INSUFFICIENT_DATA")
        return _err("CONFLICT", "Insufficient data to compute indicator", error_code="INSUFFICIENT_DATA", job_id=job_id)

    series = []
    for i in range(len(raw)):
        if i + 1 < L:
            continue
        v = sum(raw[i+1-L:i+1]) / float(L)
        series.append({"t": times[i].isoformat(), "v": v})

    if not series:
        fin = _now_iso()
        _update_job({
            "status": "failed",
            "finished_at": fin,
            "updated_at": fin,
            "error_code": "INSUFFICIENT_DATA",
            "error_message": "Unable to compute series",
            "compute_time_ms": int((time.time() - compute_start) * 1000)
        })
        _log("error", used_job_id=job_id, cache_hit=False, error_code="INSUFFICIENT_DATA")
        return _err("CONFLICT", "Insufficient data to compute indicator", error_code="INSUFFICIENT_DATA", job_id=job_id)

    compute_ms = int((time.time() - compute_start) * 1000)
    last_asof = _parse_dt(series[-1]["t"], "as_of_time")
    if isinstance(last_asof, tuple):
        last_asof = datetime.datetime.now(datetime.timezone.utc)

    ttl = idef.get("cache_ttl_seconds")
    exp_iso = None
    if isinstance(ttl, int) and ttl > 0:
        exp_iso = (datetime.datetime.now(datetime.timezone.utc) + datetime.timedelta(seconds=ttl)).isoformat()

    if not isinstance(results, list):
        results = []
    for r in results:
        if r.get("job_id") == job_id:
            fin = _now_iso()
            _update_job({
                "status": "failed",
                "finished_at": fin,
                "updated_at": fin,
                "error_code": "CONFLICT",
                "error_message": "Result already exists for job",
                "compute_time_ms": compute_ms
            })
            _log("error", used_job_id=job_id, cache_hit=False, error_code="CONFLICT")
            return _err("CONFLICT", "Result already exists for job", job_id=job_id)

    res = {
        "id": f"res_{uuid.uuid4().hex}",
        "job_id": job_id,
        "result_kind": "series",
        "as_of_time": last_asof.isoformat(),
        "value": float(series[-1]["v"]),
        "signal": None,
        "series": series if bool(return_series) else None,
        "multi_series": None,
        "metadata": {"indicator": "ease_of_movement", "interval": interval, "limit": int(limit), "length": L},
        "expires_at": exp_iso,
        "created_at": _now_iso(),
        "updated_at": _now_iso(),
    }
    results.append(res)
    _save("computation_results.json", results)

    fin = _now_iso()
    _update_job({"status": "succeeded", "finished_at": fin, "updated_at": fin, "compute_time_ms": compute_ms})

    _log("ok", used_job_id=job_id, cache_hit=False)
    out = {
        "job": job,
        "pair": {"id": pair.get("id"), "exchange": pair.get("exchange"), "symbol": pair.get("symbol")},
        "interval": interval,
        "length": L,
        "cached": False,
        "as_of_time": res.get("as_of_time"),
        "latest": res.get("value"),
    }
    if bool(return_series):
        out["series"] = series
    return out

def calculate_force_index(symbol, interval=None, limit=None, start_time=None, end_time=None, length=None, return_series=None, **_extra):
    import json, os, datetime, time, hashlib, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0416000" if __import__("os").path.isdir("./environment_mix/0416000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "calculate_force_index"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            return "TYPE", _err("VALIDATION_ERROR", f"{field} must be an ISO-8601 datetime string")
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return "PARSE", _err("VALIDATION_ERROR", f"{field} must be a valid ISO-8601 datetime")

    def _log(status, used_job_id=None, cache_hit=None, error_code=None):
        logs = _load("request_logs.json")
        row = {
            "id": f"req_{uuid.uuid4().hex}",
            "endpoint": endpoint,
            "timestamp": _now_iso(),
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "job_id": used_job_id,
            "cache_hit": cache_hit,
            "error_code": error_code,
        }
        if isinstance(logs, list):
            logs.append(row)
            _save("request_logs.json", logs)

    # Validate
    if not isinstance(symbol, str) or not symbol.strip():
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "symbol is required and must be a non-empty string")
    symbol = symbol.strip().upper()

    allowed_intervals = ["1m","3m","5m","15m","30m","1h","2h","4h","6h","8h","12h","1d","3d","1w","1M"]
    if interval is not None and (not isinstance(interval, str) or interval not in allowed_intervals):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "interval is unsupported")

    if limit is not None:
        if not isinstance(limit, int):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit must be an integer")
        if limit < 1 or limit > 5000:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit must be between 1 and 5000")

    if length is not None:
        if not isinstance(length, int):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "length must be an integer")
        if length < 1:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "length must be >= 1")

    if return_series is not None and not isinstance(return_series, bool):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "return_series must be a boolean")

    st = _parse_dt(start_time, "start_time")
    if isinstance(st, tuple):
        _log("error", error_code="VALIDATION_ERROR")
        return st[1]
    et = _parse_dt(end_time, "end_time")
    if isinstance(et, tuple):
        _log("error", error_code="VALIDATION_ERROR")
        return et[1]
    if st is not None and et is not None and st > et:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "start_time must be <= end_time")

    # Indicator definition
    defs = _load("indicator_definitions.json")
    idef = None
    for d in defs if isinstance(defs, list) else []:
        if d.get("tool_name") == endpoint:
            idef = d
            break
    if not idef:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "indicator definition not found")
    if not idef.get("is_enabled", False) or idef.get("status") not in ("active", "deprecated"):
        _log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "tool is disabled")

    if interval is None:
        interval = idef.get("default_interval")
    if interval not in allowed_intervals:
        _log("error", error_code="VALIDATION_ERROR")
