        _save("computation_jobs.json", jobs)
        _log("error", used_job_id=job_id, cache_hit=False, error_code="PAIR_DISABLED")
        return _err("INVALID_TRANSITION", "Trading pair is not active for new computation jobs", error_code="PAIR_DISABLED", job_id=job_id)

    # Fingerprint & cache
    norm = {
        "tool": endpoint,
        "indicator_id": idef.get("id"),
        "pair_id": pair.get("id"),
        "interval": interval,
        "limit": int(limit),
        "start_time": st.isoformat() if st is not None else None,
        "end_time": et.isoformat() if et is not None else None,
        "params": {"length": int(length)},
        "return_series": bool(return_series) if return_series is not None else False
    }
    fp = hashlib.sha256(json.dumps(norm, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()

    results = _load("computation_results.json")
    if isinstance(jobs, list) and isinstance(results, list):
        for j in jobs:
            if j.get("request_fingerprint") == fp and j.get("status") == "succeeded" and j.get("finished_at"):
                cached = None
                for r in results:
                    if r.get("job_id") == j.get("id"):
