                        break
                if cached:
                    exp = cached.get("expires_at")
                    fresh = True
                    if exp is not None:
                        exp_dt = _parse_dt(exp, "expires_at")
                        if isinstance(exp_dt, tuple):
                            fresh = False
                        else:
