                            "queued_at": now,
                            "started_at": now,
                            "finished_at": now,
                            "error_code": None,
                            "error_message": None,
                            "binance_request_count": 0,
                            "compute_time_ms": 0,
                            "created_at": now,
                            "updated_at": now,
                        }
                        jobs.append(job)
                        _save("computation_jobs.json", jobs)
                        _log("ok", used_job_id=job_id, cache_hit=True)
                        out = {
                            "job": job,
                            "pair": {"id": pair.get("id"), "exchange": pair.get("exchange"), "symbol": pair.get("symbol")},
                            "interval": interval,
                            "length": int(length),
                            "cached": True,
                            "as_of_time": cached.get("as_of_time"),
                            "latest": cached.get("value"),
                        }
                        if bool(return_series):
                            out["series"] = cached.get("series")
