    # Create queued job
    now = _now_iso()
    job_id = f"job_{uuid.uuid4().hex}"
    job = {
        "id": job_id,
        "indicator_id": idef.get("id"),
        "pair_id": pair.get("id"),
        "interval": interval,
        "candle_limit": int(limit),
        "input_start_time": st.isoformat() if st is not None else None,
        "input_end_time": et.isoformat() if et is not None else None,
        "request_fingerprint": fp,
        "cache_hit": False,
        "status": "queued",
        "queued_at": now,
        "started_at": None,
        "finished_at": None,
        "error_code": None,
        "error_message": None,
        "binance_request_count": 0,
        "compute_time_ms": None,
        "created_at": now,
        "updated_at": now,
    }
    if not isinstance(jobs, list):
        jobs = []
    jobs.append(job)
    _save("computation_jobs.json", jobs)

    def _update_job(fields):
        nonlocal jobs, job
        for k, v in fields.items():
            job[k] = v
        for i, jj in enumerate(jobs):
            if jj.get("id") == job_id:
                jobs[i] = job
                break
        _save("computation_jobs.json", jobs)

    _update_job({"status": "running", "started_at": _now_iso(), "updated_at": _now_iso()})

    # Candles
    candles = _load("ohlcv_candles.json")
    pid = pair.get("id")
    def _ot(c):
        dt = _parse_dt(c.get("open_time"), "open_time")
        if isinstance(dt, tuple):
            return None
        return dt
    rows = []
    if isinstance(candles, list):
        for c in candles:
            if c.get("pair_id") != pid or c.get("interval") != interval:
                continue
            ot = _ot(c)
            if ot is None:
                continue
            if st is not None and ot < st:
                continue
            if et is not None and ot > et:
                continue
            rows.append(c)
    rows.sort(key=lambda c: _ot(c) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc))
    if len(rows) > int(limit):
        rows = rows[-int(limit):]

    min_lb = idef.get("min_lookback_candles")
    if not isinstance(min_lb, int) or min_lb < 1:
        min_lb = 1
    if len(rows) < max(min_lb, 2):
        fin = _now_iso()
        _update_job({
            "status": "failed",
            "finished_at": fin,
            "updated_at": fin,
            "error_code": "INSUFFICIENT_DATA",
            "error_message": f"Need at least {max(min_lb, 2)} candles, found {len(rows)}",
            "compute_time_ms": 0
        })
        _log("error", used_job_id=job_id, cache_hit=False, error_code="INSUFFICIENT_DATA")
        return _err("CONFLICT", "Insufficient data to compute indicator", error_code="INSUFFICIENT_DATA", job_id=job_id)

    # Compute Force Index: FI = (close_t - close_{t-1}) * volume_t; then EMA(length)
    compute_start = time.time()
    raw = []
    times = []
    prev_close = None
    for c in rows:
        try:
            close = float(c.get("close"))
            vol = float(c.get("volume"))
        except (TypeError, ValueError):
            continue
        if prev_close is None:
            prev_close = close
            continue
        fi = (close - prev_close) * vol
        prev_close = close
        raw.append(fi)
        times.append((_ot(c) or datetime.datetime.now(datetime.timezone.utc)))

    if len(raw) < int(length):
        fin = _now_iso()
        _update_job({
            "status": "failed",
            "finished_at": fin,
            "updated_at": fin,
            "error_code": "INSUFFICIENT_DATA",
            "error_message": f"Need at least {int(length)+1} candles to compute FI length={int(length)}, found {len(rows)}",
            "compute_time_ms": int((time.time() - compute_start) * 1000)
        })
        _log("error", used_job_id=job_id, cache_hit=False, error_code="INSUFFICIENT_DATA")
        return _err("CONFLICT", "Insufficient data to compute indicator", error_code="INSUFFICIENT_DATA", job_id=job_id)

    L = int(length)
    alpha = 2.0 / (L + 1.0)
    ema = None
    series = []
    for i, v in enumerate(raw):
        if ema is None:
            ema = v
        else:
            ema = alpha * v + (1.0 - alpha) * ema
        series.append({"t": times[i].isoformat(), "v": ema})

    compute_ms = int((time.time() - compute_start) * 1000)
    last_asof = _parse_dt(series[-1]["t"], "as_of_time")
    if isinstance(last_asof, tuple):
        last_asof = datetime.datetime.now(datetime.timezone.utc)

    ttl = idef.get("cache_ttl_seconds")
    exp_iso = None
    if isinstance(ttl, int) and ttl > 0:
        exp_iso = (datetime.datetime.now(datetime.timezone.utc) + datetime.timedelta(seconds=ttl)).isoformat()

    if not isinstance(results, list):
        results = []
    for r in results:
        if r.get("job_id") == job_id:
            fin = _now_iso()
            _update_job({
                "status": "failed",
                "finished_at": fin,
                "updated_at": fin,
                "error_code": "CONFLICT",
                "error_message": "Result already exists for job",
                "compute_time_ms": compute_ms
            })
            _log("error", used_job_id=job_id, cache_hit=False, error_code="CONFLICT")
            return _err("CONFLICT", "Result already exists for job", job_id=job_id)

    res = {
        "id": f"res_{uuid.uuid4().hex}",
        "job_id": job_id,
        "result_kind": "series",
        "as_of_time": last_asof.isoformat(),
        "value": float(series[-1]["v"]) if series else None,
        "signal": None,
        "series": series if bool(return_series) else None,
        "multi_series": None,
        "metadata": {"indicator": "force_index", "interval": interval, "limit": int(limit), "length": L, "smoothing": "ema"},
        "expires_at": exp_iso,
        "created_at": _now_iso(),
        "updated_at": _now_iso(),
    }
    results.append(res)
    _save("computation_results.json", results)

    fin = _now_iso()
    _update_job({"status": "succeeded", "finished_at": fin, "updated_at": fin, "compute_time_ms": compute_ms})

    _log("ok", used_job_id=job_id, cache_hit=False)
    out = {
        "job": job,
        "pair": {"id": pair.get("id"), "exchange": pair.get("exchange"), "symbol": pair.get("symbol")},
        "interval": interval,
        "length": L,
        "cached": False,
        "as_of_time": res.get("as_of_time"),
        "latest": res.get("value"),
    }
    if bool(return_series):
        out["series"] = series
    return out

def calculate_negative_volume_index(interval, symbol=None, limit=None, pair_id=None, **_extra):
    import json, os, datetime, hashlib, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0416000" if __import__("os").path.isdir("./environment_mix/0416000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "calculate_negative_volume_index"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except ValueError:
            return None

    def _gen_id(prefix):
        raw = f"{prefix}|{datetime.datetime.now(datetime.timezone.utc).isoformat()}|{os.getpid()}|{time.time_ns()}"
        h = hashlib.sha1(raw.encode("utf-8")).hexdigest().upper()
        return f"{prefix}_{h[:20]}"

    jobs_file = "computation_jobs.json"
    results_file = "computation_results.json"
    pairs_file = "trading_pairs.json"
    candles_file = "ohlcv_candles.json"
    defs_file = "indicator_definitions.json"

    allowed_intervals = {"1m","3m","5m","15m","30m","1h","2h","4h","6h","8h","12h","1d","3d","1w","1M"}
    if not isinstance(interval, str) or interval not in allowed_intervals:
        return _err("VALIDATION_ERROR", "interval is required and must be a supported Binance interval.", field="interval")
    if limit is not None:
        if not isinstance(limit, int) or limit < 1:
            return _err("VALIDATION_ERROR", "limit must be an integer >= 1.", field="limit")
    has_symbol = symbol is not None
    has_pair_id = pair_id is not None
    if has_symbol and has_pair_id:
        return _err("VALIDATION_ERROR", "Provide exactly one of symbol or pair_id.", field="symbol/pair_id")
    if (not has_symbol) and (not has_pair_id):
        return _err("VALIDATION_ERROR", "Provide exactly one of symbol or pair_id.", field="symbol/pair_id")
    if has_symbol:
        if not isinstance(symbol, str) or not symbol.strip():
            return _err("VALIDATION_ERROR", "symbol must be a non-empty string.", field="symbol")
        symbol_norm = symbol.strip().upper()
    else:
        if not isinstance(pair_id, str) or not re.match(r"^cipair_[0-9A-Z]{18,}$", pair_id):
            return _err("VALIDATION_ERROR", "pair_id must match ^cipair_[0-9A-Z]{18,}$.", field="pair_id")
        symbol_norm = None

    defs = _load(defs_file)
    ind = None
    for d in defs:
        if d.get("tool_name") == endpoint:
            ind = d
            break
    if not ind:
        return _err("NOT_FOUND", "Indicator definition not found for this tool.")
    if not bool(ind.get("is_enabled")):
        return _err("UNAUTHORIZED", "This tool is not enabled.")
    if ind.get("status") not in ("active", "deprecated"):
        return _err("UNAUTHORIZED", "This tool is not available in its current status.", status=ind.get("status"))

    pairs = _load(pairs_file)
    pair = None
    if has_pair_id:
        for p in pairs:
            if p.get("id") == pair_id:
                pair = p
                break
    else:
        for p in pairs:
            if p.get("exchange") == "binance" and (p.get("symbol") or "").upper() == symbol_norm:
                pair = p
                break
    if not pair:
        return _err("NOT_FOUND", "Trading pair not found.")
    if pair.get("status") != "active":
        return _err("INVALID_TRANSITION", "Trading pair is not active and cannot be used for new computations.", error_code="PAIR_DISABLED")

    min_lb = ind.get("min_lookback_candles")
    default_limit = ind.get("default_limit")
    if not isinstance(min_lb, int) or min_lb < 1:
        min_lb = 1
    if not isinstance(default_limit, int) or default_limit < min_lb:
        default_limit = min_lb
    candle_limit = default_limit if limit is None else limit

    norm = {
        "tool": endpoint,
        "indicator_id": ind.get("id"),
        "pair_id": pair.get("id"),
        "interval": interval,
        "limit": candle_limit
    }
    fp = hashlib.sha256(json.dumps(norm, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()

    jobs = _load(jobs_file)
    results = _load(results_file)

    now = datetime.datetime.now(datetime.timezone.utc)
    cached_job = None
    cached_res = None
    for j in jobs:
        if j.get("request_fingerprint") == fp and j.get("status") == "succeeded" and j.get("finished_at") is not None:
            r = None
            for rr in results:
                if rr.get("job_id") == j.get("id"):
                    r = rr
                    break
            if not r:
                continue
            exp = _parse_dt(r.get("expires_at"))
            if exp is None or exp > now:
                cached_job = j
                cached_res = r
                break
    if cached_job and cached_res:
        now_iso = _now_iso()
        job_id = _gen_id("cijob")
        new_job = {
            "id": job_id,
            "indicator_id": ind.get("id"),
            "pair_id": pair.get("id"),
            "interval": interval,
            "candle_limit": candle_limit,
            "input_start_time": None,
            "input_end_time": None,
            "request_fingerprint": fp,
            "cache_hit": True,
            "status": "succeeded",
            "queued_at": now_iso,
            "started_at": now_iso,
            "finished_at": now_iso,
            "error_code": None,
            "error_message": None,
            "binance_request_count": 0,
            "compute_time_ms": 0,
            "created_at": now_iso,
            "updated_at": now_iso
        }
        jobs.append(new_job)
        _save(jobs_file, jobs)
        latency_ms = int((time.time() - t0) * 1000)
        return {
            "job": new_job,
            "result": cached_res,
            "cached_from_job_id": cached_job.get("id"),
            "status": "succeeded",
            "latency_ms": latency_ms
        }

    now_iso = _now_iso()
    job_id = _gen_id("cijob")
    job = {
        "id": job_id,
        "indicator_id": ind.get("id"),
        "pair_id": pair.get("id"),
        "interval": interval,
        "candle_limit": candle_limit,
        "input_start_time": None,
        "input_end_time": None,
        "request_fingerprint": fp,
        "cache_hit": False,
        "status": "queued",
        "queued_at": now_iso,
        "started_at": None,
        "finished_at": None,
        "error_code": None,
        "error_message": None,
        "binance_request_count": 0,
        "compute_time_ms": None,
        "created_at": now_iso,
        "updated_at": now_iso
    }
    jobs.append(job)
    _save(jobs_file, jobs)

    job["status"] = "running"
    job["started_at"] = _now_iso()
    job["updated_at"] = job["started_at"]
    _save(jobs_file, jobs)

    candles = _load(candles_file)
    pair_id_res = pair.get("id")
    scoped = [c for c in candles if c.get("pair_id") == pair_id_res and c.get("interval") == interval]
    def _key(c):
        dt = _parse_dt(c.get("open_time"))
        return dt or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
    scoped.sort(key=_key)
    if len(scoped) < min_lb or len(scoped) < candle_limit:
        finished = _now_iso()
        job["status"] = "failed"
        job["finished_at"] = finished
        job["updated_at"] = finished
        job["error_code"] = "INSUFFICIENT_DATA"
        job["error_message"] = f"Need at least {max(min_lb, candle_limit)} candles for NVI; have {len(scoped)}."
        _save(jobs_file, jobs)
        latency_ms = int((time.time() - t0) * 1000)
        return {"job": job, "result": None, "status": "failed", "error_code": job["error_code"], "error_message": job["error_message"], "latency_ms": latency_ms}

    window = scoped[-candle_limit:]
    compute_start = time.time()

    # NVI baseline 1000, updated only when volume decreases vs previous
    closes = []
    vols = []
    times = []
    for c in window:
        try:
            closes.append(float(c["close"]))
            vols.append(float(c["volume"]))
        except (KeyError, TypeError, ValueError):
            continue
        times.append(c.get("close_time") or c.get("open_time"))
    if len(closes) < 2:
        finished = _now_iso()
        job["status"] = "failed"
        job["finished_at"] = finished
        job["updated_at"] = finished
        job["error_code"] = "INSUFFICIENT_DATA"
        job["error_message"] = "Need at least 2 valid candles to compute NVI."
        _save(jobs_file, jobs)
        latency_ms = int((time.time() - t0) * 1000)
        return {"job": job, "result": None, "status": "failed", "error_code": job["error_code"], "error_message": job["error_message"], "latency_ms": latency_ms}

    nvi = 1000.0
    series = [{"t": times[0], "v": nvi}]
    for i in range(1, len(closes)):
        if vols[i] < vols[i - 1]:
            prev = closes[i - 1]
            if prev != 0:
                nvi = nvi + nvi * ((closes[i] - prev) / prev)
        series.append({"t": times[i], "v": nvi})

    latest = series[-1]["v"]
    as_of_time = series[-1]["t"]
    compute_ms = int((time.time() - compute_start) * 1000)

    for j in jobs:
        if j.get("id") != job_id and j.get("request_fingerprint") == fp and j.get("status") == "succeeded" and j.get("finished_at") is not None:
            finished = _now_iso()
            job["status"] = "cancelled"
            job["finished_at"] = finished
            job["updated_at"] = finished
            _save(jobs_file, jobs)
            return _err("CONFLICT", "An identical succeeded job already exists for this request_fingerprint.", request_fingerprint=fp)

    expires_at = None
    ttl = ind.get("cache_ttl_seconds")
    if isinstance(ttl, int) and ttl > 0:
        exp = datetime.datetime.now(datetime.timezone.utc) + datetime.timedelta(seconds=ttl)
        expires_at = exp.isoformat()

    created = _now_iso()
    res_id = _gen_id("cires")
    result = {
        "id": res_id,
        "job_id": job_id,
        "result_kind": "series",
        "as_of_time": as_of_time,
        "value": latest,
        "signal": None,
        "series": series,
        "multi_series": None,
        "metadata": {"indicator": "NVI", "baseline": 1000.0},
        "expires_at": expires_at,
        "created_at": created,
        "updated_at": created
    }
    results.append(result)
    _save(results_file, results)

    finished = _now_iso()
    job["status"] = "succeeded"
    job["finished_at"] = finished
    job["compute_time_ms"] = compute_ms
    job["updated_at"] = finished
    _save(jobs_file, jobs)

    latency_ms = int((time.time() - t0) * 1000)
    return {"job": job, "result": result, "status": "succeeded", "latency_ms": latency_ms}

