    as_of_time = series[-1]["t"]
    compute_ms = int((time.time() - compute_start) * 1000)

    for j in jobs:
        if j.get("id") != job_id and j.get("request_fingerprint") == fp and j.get("status") == "succeeded" and j.get("finished_at") is not None:
            finished = _now_iso()
            job["status"] = "cancelled"
            job["finished_at"] = finished
            job["updated_at"] = finished
            _save(jobs_file, jobs)
            return _err("CONFLICT", "An identical succeeded job already exists for this request_fingerprint.", request_fingerprint=fp)

    expires_at = None
    ttl = ind.get("cache_ttl_seconds")
    if isinstance(ttl, int) and ttl > 0:
        exp = datetime.datetime.now(datetime.timezone.utc) + datetime.timedelta(seconds=ttl)
        expires_at = exp.isoformat()

    created = _now_iso()
    res_id = _gen_id("cires")
    result = {
        "id": res_id,
        "job_id": job_id,
        "result_kind": "series",
        "as_of_time": as_of_time,
        "value": latest,
        "signal": None,
        "series": series,
        "multi_series": None,
        "metadata": {"indicator": "OBV"},
        "expires_at": expires_at,
        "created_at": created,
        "updated_at": created
    }
    results.append(result)
    _save(results_file, results)

    finished = _now_iso()
    job["status"] = "succeeded"
    job["finished_at"] = finished
    job["compute_time_ms"] = compute_ms
    job["updated_at"] = finished
    _save(jobs_file, jobs)

    latency_ms = int((time.time() - t0) * 1000)
    return {"job": job, "result": result, "status": "succeeded", "latency_ms": latency_ms}

def calculate_volume_price_trend(interval, symbol=None, limit=None, pair_id=None, **_extra):
    import json, os, datetime, hashlib, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0416000" if __import__("os").path.isdir("./environment_mix/0416000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "calculate_volume_price_trend"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except ValueError:
            return None

    def _gen_id(prefix):
        raw = f"{prefix}|{datetime.datetime.now(datetime.timezone.utc).isoformat()}|{os.getpid()}|{time.time_ns()}"
        h = hashlib.sha1(raw.encode("utf-8")).hexdigest().upper()
        return f"{prefix}_{h[:20]}"

    jobs_file = "computation_jobs.json"
    results_file = "computation_results.json"
    pairs_file = "trading_pairs.json"
    candles_file = "ohlcv_candles.json"
    defs_file = "indicator_definitions.json"

    allowed_intervals = {"1m","3m","5m","15m","30m","1h","2h","4h","6h","8h","12h","1d","3d","1w","1M"}
    if not isinstance(interval, str) or interval not in allowed_intervals:
        return _err("VALIDATION_ERROR", "interval is required and must be a supported Binance interval.", field="interval")
    if limit is not None:
        if not isinstance(limit, int) or limit < 1:
            return _err("VALIDATION_ERROR", "limit must be an integer >= 1.", field="limit")
    has_symbol = symbol is not None
    has_pair_id = pair_id is not None
    if has_symbol and has_pair_id:
        return _err("VALIDATION_ERROR", "Provide exactly one of symbol or pair_id.", field="symbol/pair_id")
    if (not has_symbol) and (not has_pair_id):
        return _err("VALIDATION_ERROR", "Provide exactly one of symbol or pair_id.", field="symbol/pair_id")
    if has_symbol:
        if not isinstance(symbol, str) or not symbol.strip():
            return _err("VALIDATION_ERROR", "symbol must be a non-empty string.", field="symbol")
        symbol_norm = symbol.strip().upper()
    else:
        if not isinstance(pair_id, str) or not re.match(r"^cipair_[0-9A-Z]{18,}$", pair_id):
            return _err("VALIDATION_ERROR", "pair_id must match ^cipair_[0-9A-Z]{18,}$.", field="pair_id")
        symbol_norm = None

    defs = _load(defs_file)
    ind = None
    for d in defs:
        if d.get("tool_name") == endpoint:
            ind = d
            break
    if not ind:
        return _err("NOT_FOUND", "Indicator definition not found for this tool.")
    if not bool(ind.get("is_enabled")):
        return _err("UNAUTHORIZED", "This tool is not enabled.")
    if ind.get("status") not in ("active", "deprecated"):
        return _err("UNAUTHORIZED", "This tool is not available in its current status.", status=ind.get("status"))

    pairs = _load(pairs_file)
    pair = None
    if has_pair_id:
        for p in pairs:
            if p.get("id") == pair_id:
                pair = p
                break
    else:
        for p in pairs:
            if p.get("exchange") == "binance" and (p.get("symbol") or "").upper() == symbol_norm:
                pair = p
                break
    if not pair:
        return _err("NOT_FOUND", "Trading pair not found.")
    if pair.get("status") != "active":
        return _err("INVALID_TRANSITION", "Trading pair is not active and cannot be used for new computations.", error_code="PAIR_DISABLED")

    min_lb = ind.get("min_lookback_candles")
    default_limit = ind.get("default_limit")
    if not isinstance(min_lb, int) or min_lb < 1:
        min_lb = 1
    if not isinstance(default_limit, int) or default_limit < min_lb:
        default_limit = min_lb
    candle_limit = default_limit if limit is None else limit

    norm = {"tool": endpoint, "indicator_id": ind.get("id"), "pair_id": pair.get("id"), "interval": interval, "limit": candle_limit}
    fp = hashlib.sha256(json.dumps(norm, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()

    jobs = _load(jobs_file)
    results = _load(results_file)

    now = datetime.datetime.now(datetime.timezone.utc)
    cached_job = None
    cached_res = None
    for j in jobs:
        if j.get("request_fingerprint") == fp and j.get("status") == "succeeded" and j.get("finished_at") is not None:
            r = None
            for rr in results:
                if rr.get("job_id") == j.get("id"):
                    r = rr
                    break
            if not r:
                continue
            exp = _parse_dt(r.get("expires_at"))
            if exp is None or exp > now:
                cached_job = j
                cached_res = r
                break
    if cached_job and cached_res:
        now_iso = _now_iso()
        job_id = _gen_id("cijob")
        new_job = {
            "id": job_id,
            "indicator_id": ind.get("id"),
            "pair_id": pair.get("id"),
            "interval": interval,
            "candle_limit": candle_limit,
            "input_start_time": None,
            "input_end_time": None,
            "request_fingerprint": fp,
            "cache_hit": True,
            "status": "succeeded",
            "queued_at": now_iso,
            "started_at": now_iso,
            "finished_at": now_iso,
            "error_code": None,
            "error_message": None,
            "binance_request_count": 0,
            "compute_time_ms": 0,
            "created_at": now_iso,
            "updated_at": now_iso
        }
        jobs.append(new_job)
        _save(jobs_file, jobs)
        latency_ms = int((time.time() - t0) * 1000)
        return {"job": new_job, "result": cached_res, "cached_from_job_id": cached_job.get("id"), "status": "succeeded", "latency_ms": latency_ms}

    now_iso = _now_iso()
    job_id = _gen_id("cijob")
    job = {
        "id": job_id,
        "indicator_id": ind.get("id"),
        "pair_id": pair.get("id"),
        "interval": interval,
        "candle_limit": candle_limit,
        "input_start_time": None,
        "input_end_time": None,
        "request_fingerprint": fp,
        "cache_hit": False,
        "status": "queued",
        "queued_at": now_iso,
        "started_at": None,
        "finished_at": None,
        "error_code": None,
        "error_message": None,
        "binance_request_count": 0,
        "compute_time_ms": None,
        "created_at": now_iso,
        "updated_at": now_iso
    }
    jobs.append(job)
    _save(jobs_file, jobs)

    job["status"] = "running"
    job["started_at"] = _now_iso()
    job["updated_at"] = job["started_at"]
    _save(jobs_file, jobs)

    candles = _load(candles_file)
    pair_id_res = pair.get("id")
    scoped = [c for c in candles if c.get("pair_id") == pair_id_res and c.get("interval") == interval]
    def _key(c):
        dt = _parse_dt(c.get("open_time"))
        return dt or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
    scoped.sort(key=_key)
    if len(scoped) < min_lb or len(scoped) < candle_limit:
        finished = _now_iso()
        job["status"] = "failed"
        job["finished_at"] = finished
        job["updated_at"] = finished
        job["error_code"] = "INSUFFICIENT_DATA"
        job["error_message"] = f"Need at least {max(min_lb, candle_limit)} candles for VPT; have {len(scoped)}."
        _save(jobs_file, jobs)
        latency_ms = int((time.time() - t0) * 1000)
        return {"job": job, "result": None, "status": "failed", "error_code": job["error_code"], "error_message": job["error_message"], "latency_ms": latency_ms}

    window = scoped[-candle_limit:]
    compute_start = time.time()

    closes = []
    vols = []
    times = []
    for c in window:
        try:
            closes.append(float(c["close"]))
            vols.append(float(c["volume"]))
        except (KeyError, TypeError, ValueError):
            continue
        times.append(c.get("close_time") or c.get("open_time"))
    if len(closes) < 2:
        finished = _now_iso()
        job["status"] = "failed"
        job["finished_at"] = finished
        job["updated_at"] = finished
        job["error_code"] = "INSUFFICIENT_DATA"
        job["error_message"] = "Need at least 2 valid candles to compute VPT."
        _save(jobs_file, jobs)
        latency_ms = int((time.time() - t0) * 1000)
        return {"job": job, "result": None, "status": "failed", "error_code": job["error_code"], "error_message": job["error_message"], "latency_ms": latency_ms}

    vpt = 0.0
    series = [{"t": times[0], "v": vpt}]
    for i in range(1, len(closes)):
        prev = closes[i - 1]
        if prev != 0:
            vpt += vols[i] * ((closes[i] - prev) / prev)
        series.append({"t": times[i], "v": vpt})

    latest = series[-1]["v"]
    as_of_time = series[-1]["t"]
    compute_ms = int((time.time() - compute_start) * 1000)

    for j in jobs:
        if j.get("id") != job_id and j.get("request_fingerprint") == fp and j.get("status") == "succeeded" and j.get("finished_at") is not None:
            finished = _now_iso()
            job["status"] = "cancelled"
            job["finished_at"] = finished
            job["updated_at"] = finished
            _save(jobs_file, jobs)
            return _err("CONFLICT", "An identical succeeded job already exists for this request_fingerprint.", request_fingerprint=fp)

    expires_at = None
    ttl = ind.get("cache_ttl_seconds")
    if isinstance(ttl, int) and ttl > 0:
        exp = datetime.datetime.now(datetime.timezone.utc) + datetime.timedelta(seconds=ttl)
        expires_at = exp.isoformat()

    created = _now_iso()
    res_id = _gen_id("cires")
    result = {
        "id": res_id,
        "job_id": job_id,
        "result_kind": "series",
        "as_of_time": as_of_time,
        "value": latest,
        "signal": None,
        "series": series,
        "multi_series": None,
        "metadata": {"indicator": "VPT"},
        "expires_at": expires_at,
        "created_at": created,
        "updated_at": created
    }
    results.append(result)
    _save(results_file, results)

    finished = _now_iso()
    job["status"] = "succeeded"
    job["finished_at"] = finished
    job["compute_time_ms"] = compute_ms
    job["updated_at"] = finished
    _save(jobs_file, jobs)

    latency_ms = int((time.time() - t0) * 1000)
    return {"job": job, "result": result, "status": "succeeded", "latency_ms": latency_ms}

def calculate_absolute_price_oscillator_strategy(symbol=None, interval=None, limit=None, pair_id=None, **_extra):
    import json, os, datetime, hashlib, time, re, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0416000" if __import__("os").path.isdir("./environment_mix/0416000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "calculate_absolute_price_oscillator_strategy"
    allowed_intervals = ["1m","3m","5m","15m","30m","1h","2h","4h","6h","8h","12h","1d","3d","1w","1M"]

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _isoz(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            dt = v
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        if not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _get_rows(doc):
        if isinstance(doc, dict) and isinstance(doc.get("rows"), list):
            return doc["rows"]
        if isinstance(doc, list):
            return doc
        return []

    def _save_doc(fname, original, rows):
        if isinstance(original, dict) and isinstance(original.get("rows"), list):
            original["rows"] = rows
            _save(fname, original)
        else:
            _save(fname, rows)

    def _new_id(prefix):
        ts = datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%d%H%M%S%f")
        return f"{prefix}_{ts}_{os.urandom(3).hex()}"

    def _fingerprint(obj):
        s = json.dumps(obj, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _log(status, error_code=None, extra=None):
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            return
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": _new_id("req"),
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _isoz(_utcnow()),
        }
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save("request_logs.json", logs)

    try:
        # oneOf validation: exactly one of symbol, pair_id
        has_symbol = symbol is not None and isinstance(symbol, str) and symbol.strip() != ""
        has_pair = pair_id is not None and isinstance(pair_id, str) and pair_id.strip() != ""
        if has_symbol and has_pair:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Provide either symbol or pair_id, not both.", field="symbol/pair_id")
        if not has_symbol and not has_pair:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Either symbol or pair_id is required.", field="symbol/pair_id")

        if interval is None or not isinstance(interval, str) or interval not in allowed_intervals:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "interval must be one of the supported Binance intervals", field="interval", allowed=allowed_intervals)

        if limit is None:
            limit = 200
        if not isinstance(limit, int) or limit < 1:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit must be an integer >= 1", field="limit")

        defs_doc = _load("indicator_definitions.json")
        defs_rows = _get_rows(defs_doc)
        idef = None
        for r in defs_rows:
            if isinstance(r, dict) and r.get("tool_name") == endpoint:
                idef = r
                break
        if not idef:
            _log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "indicator definition not found for tool", tool_name=endpoint)
        if not idef.get("is_enabled", False) or idef.get("status") not in ("active", "deprecated"):
            _log("error", "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Tool is not enabled or not available.", tool_name=endpoint, status=idef.get("status"), is_enabled=idef.get("is_enabled"))

        pairs_doc = _load("trading_pairs.json")
        pairs = _get_rows(pairs_doc)
        pair = None
        if has_pair:
            pid = pair_id.strip()
            for p in pairs:
                if isinstance(p, dict) and p.get("id") == pid:
                    pair = p
                    break
            if not pair:
                _log("error", "NOT_FOUND")
                return _err("NOT_FOUND", "pair_id not found.", pair_id=pid)
        else:
            sym = symbol.strip().upper()
            for p in pairs:
                if isinstance(p, dict) and p.get("exchange") == "binance" and str(p.get("symbol", "")).upper() == sym:
                    pair = p
                    break
            if not pair:
                _log("error", "NOT_FOUND")
                return _err("NOT_FOUND", "Trading pair symbol not found on exchange.", symbol=sym, exchange="binance")

        if pair.get("status") != "active":
            _log("error", "INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", "Trading pair is not active; refusing new computation job.", error_code="PAIR_DISABLED", pair_id=pair.get("id"), status=pair.get("status"))

        # Strategy: use APO value sign as signal (buy if >0, sell if <0)
        norm = {"tool_name": endpoint, "pair_id": pair.get("id"), "interval": interval, "limit": int(limit)}
        fp = _fingerprint(norm)

        jobs_doc = _load("computation_jobs.json")
        jobs = _get_rows(jobs_doc)
        results_doc = _load("computation_results.json")
        results = _get_rows(results_doc)

        def _find_result_by_job(job_id):
            for rr in results:
                if isinstance(rr, dict) and rr.get("job_id") == job_id:
                    return rr
            return None

        now = _utcnow()
        for j in jobs:
            if not isinstance(j, dict):
                continue
            if j.get("request_fingerprint") != fp:
                continue
            if j.get("status") != "succeeded" or not j.get("finished_at"):
                continue
            r = _find_result_by_job(j.get("id"))
            if not r:
                continue
            exp = _parse_dt(r.get("expires_at"))
            if exp is not None and exp < now:
                continue
            # Return cached signal
            new_job = {
                "id": _new_id("cijob"),
                "indicator_id": idef.get("id"),
                "pair_id": pair.get("id"),
                "interval": interval,
                "candle_limit": int(limit),
                "input_start_time": None,
                "input_end_time": None,
                "request_fingerprint": fp,
                "cache_hit": True,
                "status": "succeeded",
                "queued_at": _isoz(now),
                "started_at": _isoz(now),
                "finished_at": _isoz(now),
                "error_code": None,
                "error_message": None,
                "binance_request_count": 0,
                "compute_time_ms": 0,
                "created_at": _isoz(now),
                "updated_at": _isoz(now),
            }
            jobs.append(new_job)
            _save_doc("computation_jobs.json", jobs_doc, jobs)
            _log("ok", extra={"cache_hit": True})
            return {"tool_name": endpoint, "cache_hit": True, "job": new_job, "signal": r.get("signal"), "result": r}

        job = {
            "id": _new_id("cijob"),
            "indicator_id": idef.get("id"),
            "pair_id": pair.get("id"),
            "interval": interval,
            "candle_limit": int(limit),
            "input_start_time": None,
            "input_end_time": None,
            "request_fingerprint": fp,
            "cache_hit": False,
            "status": "queued",
            "queued_at": _isoz(now),
            "started_at": None,
            "finished_at": None,
            "error_code": None,
            "error_message": None,
            "binance_request_count": 0,
            "compute_time_ms": None,
            "created_at": _isoz(now),
            "updated_at": _isoz(now),
        }
        jobs.append(job)
        _save_doc("computation_jobs.json", jobs_doc, jobs)

        job["status"] = "running"
        job["started_at"] = _isoz(_utcnow())
        job["updated_at"] = job["started_at"]
        _save_doc("computation_jobs.json", jobs_doc, jobs)

        candles_doc = _load("ohlcv_candles.json")
        candles = _get_rows(candles_doc)
        rows = [c for c in candles if isinstance(c, dict) and c.get("pair_id") == pair.get("id") and c.get("interval") == interval]
        rows.sort(key=lambda x: str(x.get("open_time") or ""))
        rows = rows[-int(limit):]

        required = int(idef.get("min_lookback_candles") or 1)
        if len(rows) < required:
            fin = _utcnow()
            job["status"] = "failed"
            job["finished_at"] = _isoz(fin)
            job["updated_at"] = _isoz(fin)
            job["error_code"] = "INSUFFICIENT_DATA"
            job["error_message"] = f"Need {required} lookback candles for interval {interval}; only {len(rows)} available."
            _save_doc("computation_jobs.json", jobs_doc, jobs)
            _log("error", "CONFLICT", extra={"error_code": "INSUFFICIENT_DATA"})
            return _err("CONFLICT", "Insufficient data to compute strategy.", error_code="INSUFFICIENT_DATA", required_candles=required, available_candles=len(rows), job_id=job["id"])

        closes = [float(c.get("close")) for c in rows]
        times = [c.get("close_time") or c.get("open_time") for c in rows]

        def _ema(series, period):
            n = int(period)
            if n <= 0 or len(series) < n:
                return []
            sma = sum(series[:n]) / n
            out = [sma]
            k = 2.0 / (n + 1.0)
            prev = sma
            for v in series[n:]:
                prev = (v - prev) * k + prev
                out.append(prev)
            return out

        # Use default typical APO params for strategy
        fast_period = 12
        slow_period = 26
        ema_fast = _ema(closes, fast_period)
        ema_slow = _ema(closes, slow_period)
        start_idx = (slow_period - 1) - (fast_period - 1)
        overlap_len = min(len(ema_slow), len(ema_fast) - start_idx)
        apo = ema_fast[start_idx + overlap_len - 1] - ema_slow[overlap_len - 1]
        as_of = times[-1]

        signal = 0
        if apo > 0:
            signal = 1
        elif apo < 0:
            signal = -1

        fin = _utcnow()
        job["status"] = "succeeded"
        job["finished_at"] = _isoz(fin)
        job["updated_at"] = _isoz(fin)
        job["compute_time_ms"] = max(0, int((time.time() - t0) * 1000))
        _save_doc("computation_jobs.json", jobs_doc, jobs)

        ttl = idef.get("cache_ttl_seconds")
        expires_at = None
        if isinstance(ttl, int) and ttl > 0:
            expires_at = _isoz(fin + datetime.timedelta(seconds=int(ttl)))

        result_row = {
            "id": _new_id("cires"),
            "job_id": job["id"],
            "result_kind": "signal",
            "as_of_time": as_of,
            "value": float(signal),
            "signal": int(signal),
            "series": None,
            "multi_series": None,
            "metadata": {"limit": limit, "fast_period": fast_period, "slow_period": slow_period},
            "expires_at": expires_at,
            "created_at": _isoz(fin),
            "updated_at": _isoz(fin),
        }
        results.append(result_row)
        _save_doc("computation_results.json", results_doc, results)

        _log("ok")
        return {"tool_name": endpoint, "cache_hit": False, "job": job, "signal": signal, "result": result_row}
    except Exception as e:
        _log("error", "CONFLICT")
        return _err("CONFLICT", "Unexpected server error.", details=str(e), tool_name=endpoint)

def calculate_aroon_strategy(symbol=None, interval=None, limit=None, pair_id=None, **_extra):
    import json, os, datetime, hashlib, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0416000" if __import__("os").path.isdir("./environment_mix/0416000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "calculate_aroon_strategy"
    allowed_intervals = {"1m","3m","5m","15m","30m","1h","2h","4h","6h","8h","12h","1d","3d","1w","1M"}

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _isoz(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            dt = v
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        if not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _get_rows(doc):
        if isinstance(doc, dict) and isinstance(doc.get("rows"), list):
            return doc["rows"]
        if isinstance(doc, list):
            return doc
        return []

    def _save_doc(fname, original, rows):
        if isinstance(original, dict) and isinstance(original.get("rows"), list):
            original["rows"] = rows
            _save(fname, original)
        else:
            _save(fname, rows)

    def _new_id(prefix):
        ts = datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%d%H%M%S%f")
        return f"{prefix}_{ts}_{os.urandom(3).hex()}"

    def _fingerprint(obj):
        s = json.dumps(obj, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _log(status, error_code=None, extra=None):
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            return
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": _new_id("req"),
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _isoz(_utcnow()),
        }
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save("request_logs.json", logs)

    try:
        has_symbol = symbol is not None and isinstance(symbol, str) and symbol.strip() != ""
        has_pair = pair_id is not None and isinstance(pair_id, str) and pair_id.strip() != ""
        if has_symbol and has_pair:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Provide either symbol or pair_id, not both.", field="symbol/pair_id")
        if not has_symbol and not has_pair:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Either symbol or pair_id is required.", field="symbol/pair_id")

        if interval is None or not isinstance(interval, str) or interval not in allowed_intervals:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "interval must be one of the supported Binance intervals", field="interval", allowed=sorted(list(allowed_intervals)))

        if limit is None:
            limit = 200
        if not isinstance(limit, int) or limit < 1:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit must be an integer >= 1", field="limit")

        defs_doc = _load("indicator_definitions.json")
        defs_rows = _get_rows(defs_doc)
        idef = None
        for r in defs_rows:
            if isinstance(r, dict) and r.get("tool_name") == endpoint:
                idef = r
                break
        if not idef:
            _log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "indicator definition not found for tool", tool_name=endpoint)
        if not idef.get("is_enabled", False) or idef.get("status") not in ("active", "deprecated"):
            _log("error", "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Tool is not enabled or not available.", tool_name=endpoint, status=idef.get("status"), is_enabled=idef.get("is_enabled"))

        pairs_doc = _load("trading_pairs.json")
        pairs = _get_rows(pairs_doc)
        pair = None
        if has_pair:
            pid = pair_id.strip()
            for p in pairs:
                if isinstance(p, dict) and p.get("id") == pid:
                    pair = p
                    break
            if not pair:
                _log("error", "NOT_FOUND")
                return _err("NOT_FOUND", "pair_id not found.", pair_id=pid)
        else:
            sym = symbol.strip().upper()
            for p in pairs:
                if isinstance(p, dict) and p.get("exchange") == "binance" and str(p.get("symbol", "")).upper() == sym:
                    pair = p
                    break
            if not pair:
                _log("error", "NOT_FOUND")
                return _err("NOT_FOUND", "Trading pair symbol not found on exchange.", symbol=sym, exchange="binance")

        if pair.get("status") != "active":
            _log("error", "INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", "Trading pair is not active; refusing new computation job.", error_code="PAIR_DISABLED", pair_id=pair.get("id"), status=pair.get("status"))

        norm = {"tool_name": endpoint, "pair_id": pair.get("id"), "interval": interval, "limit": int(limit)}
        fp = _fingerprint(norm)

        jobs_doc = _load("computation_jobs.json")
        jobs = _get_rows(jobs_doc)
        results_doc = _load("computation_results.json")
        results = _get_rows(results_doc)

        def _find_result_by_job(job_id):
            for rr in results:
                if isinstance(rr, dict) and rr.get("job_id") == job_id:
                    return rr
            return None

        now = _utcnow()
        for j in jobs:
            if not isinstance(j, dict):
                continue
            if j.get("request_fingerprint") != fp:
                continue
            if j.get("status") != "succeeded" or not j.get("finished_at"):
                continue
            r = _find_result_by_job(j.get("id"))
            if not r:
                continue
            exp = _parse_dt(r.get("expires_at"))
            if exp is not None and exp < now:
                continue
            new_job = {
                "id": _new_id("cijob"),
                "indicator_id": idef.get("id"),
                "pair_id": pair.get("id"),
                "interval": interval,
                "candle_limit": int(limit),
                "input_start_time": None,
                "input_end_time": None,
                "request_fingerprint": fp,
                "cache_hit": True,
                "status": "succeeded",
                "queued_at": _isoz(now),
                "started_at": _isoz(now),
                "finished_at": _isoz(now),
                "error_code": None,
                "error_message": None,
                "binance_request_count": 0,
                "compute_time_ms": 0,
                "created_at": _isoz(now),
                "updated_at": _isoz(now),
            }
            jobs.append(new_job)
            _save_doc("computation_jobs.json", jobs_doc, jobs)
            _log("ok", extra={"cache_hit": True})
            return {"tool_name": endpoint, "cache_hit": True, "job": new_job, "signal": r.get("signal"), "result": r}

        job = {
            "id": _new_id("cijob"),
            "indicator_id": idef.get("id"),
            "pair_id": pair.get("id"),
            "interval": interval,
            "candle_limit": int(limit),
            "input_start_time": None,
            "input_end_time": None,
            "request_fingerprint": fp,
            "cache_hit": False,
            "status": "queued",
            "queued_at": _isoz(now),
            "started_at": None,
            "finished_at": None,
            "error_code": None,
            "error_message": None,
            "binance_request_count": 0,
            "compute_time_ms": None,
            "created_at": _isoz(now),
            "updated_at": _isoz(now),
        }
        jobs.append(job)
        _save_doc("computation_jobs.json", jobs_doc, jobs)

        job["status"] = "running"
        job["started_at"] = _isoz(_utcnow())
        job["updated_at"] = job["started_at"]
        _save_doc("computation_jobs.json", jobs_doc, jobs)

        candles_doc = _load("ohlcv_candles.json")
        candles = _get_rows(candles_doc)
        rows = [c for c in candles if isinstance(c, dict) and c.get("pair_id") == pair.get("id") and c.get("interval") == interval]
        rows.sort(key=lambda x: str(x.get("open_time") or ""))
        rows = rows[-int(limit):]

        required = int(idef.get("min_lookback_candles") or 1)
        if len(rows) < required:
            fin = _utcnow()
            job["status"] = "failed"
            job["finished_at"] = _isoz(fin)
            job["updated_at"] = _isoz(fin)
            job["error_code"] = "INSUFFICIENT_DATA"
            job["error_message"] = f"Need {required} lookback candles for interval {interval}; only {len(rows)} available."
            _save_doc("computation_jobs.json", jobs_doc, jobs)
            _log("error", "CONFLICT", extra={"error_code": "INSUFFICIENT_DATA"})
            return _err("CONFLICT", "Insufficient data to compute strategy.", error_code="INSUFFICIENT_DATA", required_candles=required, available_candles=len(rows), job_id=job["id"])

        # Simple strategy: signal based on Aroon up/down dominance over last 25
        length = 25
        if len(rows) < length:
            length = len(rows)
        highs = [float(c.get("high")) for c in rows]
        lows = [float(c.get("low")) for c in rows]
        times = [c.get("close_time") or c.get("open_time") for c in rows]

        window_highs = highs[-length:]
        window_lows = lows[-length:]
        idx_high = window_highs.index(max(window_highs))
        idx_low = window_lows.index(min(window_lows))
        periods_since_high = (length - 1) - idx_high
        periods_since_low = (length - 1) - idx_low
        aroon_up = 100.0 * (length - periods_since_high) / float(length)
        aroon_down = 100.0 * (length - periods_since_low) / float(length)

        signal = 0
        if aroon_up > aroon_down + 10:
            signal = 1
        elif aroon_down > aroon_up + 10:
            signal = -1

        as_of = times[-1]
        fin = _utcnow()
        job["status"] = "succeeded"
        job["finished_at"] = _isoz(fin)
        job["updated_at"] = _isoz(fin)
        job["compute_time_ms"] = max(0, int((time.time() - t0) * 1000))
        _save_doc("computation_jobs.json", jobs_doc, jobs)

        ttl = idef.get("cache_ttl_seconds")
        expires_at = None
        if isinstance(ttl, int) and ttl > 0:
            expires_at = _isoz(fin + datetime.timedelta(seconds=int(ttl)))

        result_row = {
            "id": _new_id("cires"),
            "job_id": job["id"],
            "result_kind": "signal",
            "as_of_time": as_of,
            "value": float(signal),
            "signal": int(signal),
            "series": None,
            "multi_series": None,
            "metadata": {"limit": limit, "length": length, "aroon_up": aroon_up, "aroon_down": aroon_down},
            "expires_at": expires_at,
            "created_at": _isoz(fin),
            "updated_at": _isoz(fin),
        }
        results.append(result_row)
        _save_doc("computation_results.json", results_doc, results)
        _log("ok")
        return {"tool_name": endpoint, "cache_hit": False, "job": job, "signal": signal, "result": result_row}
    except Exception as e:
        _log("error", "CONFLICT")
        return _err("CONFLICT", "Unexpected server error.", details=str(e), tool_name=endpoint)

def calculate_balance_of_power_strategy(symbol=None, interval=None, limit=None, pair_id=None, **_extra):
