    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "calculate_balance_of_power_strategy"
    status_for_log = "ok"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(x):
        if x is None:
            return None
        if isinstance(x, datetime.datetime):
            return x
        if not isinstance(x, str):
            return None
        s = x.strip()
        if not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _dt_iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        return dt.replace(microsecond=0).isoformat() + "Z"

    def _sma(values, period):
        if period <= 0:
            return []
        out = []
        s = 0.0
        for i, v in enumerate(values):
            s += v
            if i >= period:
                s -= values[i - period]
            if i >= period - 1:
                out.append(s / period)
        return out

    def _log_call(status, latency_ms, meta=None):
        return

    try:
        allowed_intervals = {"1m","3m","5m","15m","30m","1h","2h","4h","6h","8h","12h","1d","3d","1w","1M"}
