        def _ot(c):
            dt = _parse_dt(c.get("open_time"))
            return dt or datetime.datetime.min
        scoped.sort(key=_ot)
        if len(scoped) < min_lb or len(scoped) < use_limit:
            job["status"] = "failed"
            fin = _now_iso()
            job["finished_at"] = fin
            job["updated_at"] = fin
            job["error_code"] = "INSUFFICIENT_DATA"
            job["error_message"] = "Not enough candles available to compute strategy."
            job["compute_time_ms"] = int((time.time() - t0) * 1000)
            _save("computation_jobs.json", jobs)
            status_for_log = "error"
            return _err("CONFLICT", "Insufficient OHLCV data.", error_code="INSUFFICIENT_DATA", job=job)

        use = scoped[-use_limit:]

        # Balance of Power (BOP) per candle: (close - open) / (high - low), handle zero range => 0.
        bops = []
        for c in use:
            o = float(c.get("open"))
            h = float(c.get("high"))
            l = float(c.get("low"))
            cl = float(c.get("close"))
            rng = h - l
            bop = ((cl - o) / rng) if rng != 0 else 0.0
            bops.append(bop)

        # Smooth with SMA(14) if possible; else use last raw bop.
        window = 14
        smoothed = None
        if len(bops) >= window:
            smoothed = _sma(bops, window)[-1]
        else:
            smoothed = bops[-1]

        # Strategy: BUY if smoothed > 0, SELL if < 0, HOLD if == 0
        sig = 0
        if smoothed > 0:
            sig = 1
        elif smoothed < 0:
            sig = -1

        as_of_time = use[-1].get("close_time") or use[-1].get("open_time")

        fin = _now_iso()
        job["status"] = "succeeded"
        job["finished_at"] = fin
        job["updated_at"] = fin
        job["error_code"] = None
        job["error_message"] = None
        job["compute_time_ms"] = int((time.time() - t0) * 1000)

        ttl = idef.get("cache_ttl_seconds")
        expires_at = None
        if isinstance(ttl, int) and ttl > 0:
            expires_at = _dt_iso(datetime.datetime.utcnow() + datetime.timedelta(seconds=ttl))

        rid = "cires_" + hashlib.sha256((fin + "|RESULT|" + jid).encode("utf-8")).hexdigest()[:24].upper()
        result = {
            "id": rid,
            "job_id": jid,
            "result_kind": "signal",
            "as_of_time": as_of_time,
            "value": float(sig),
            "signal": int(sig),
            "series": None,
            "multi_series": None,
            "metadata": {
                "strategy": "balance_of_power",
                "interval": interval,
                "candle_limit": use_limit,
                "window": window,
                "bop": smoothed,
            },
            "expires_at": expires_at,
            "created_at": fin,
            "updated_at": fin,
        }

        replaced = False
        for i, r in enumerate(results):
            if r.get("job_id") == jid:
                results[i] = result
                replaced = True
                break
        if not replaced:
            results.append(result)

        _save("computation_jobs.json", jobs)
        _save("computation_results.json", results)

        return {"job": job, "result": result, "cache_hit": False}
    finally:
        latency_ms = int((time.time() - t0) * 1000)
        _log_call(status_for_log, latency_ms)

def calculate_kdj_strategy(symbol, exchange=None, interval=None, limit=None, **_extra):
    import json, os, datetime, time, hashlib, re, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0416000" if __import__("os").path.isdir("./environment_mix/0416000") else "/app/database")
