        now_dt = datetime.datetime.now(datetime.timezone.utc)
        for j in jobs:
            if j.get("request_fingerprint") == fp and j.get("status") == "succeeded" and j.get("finished_at") is not None:
                r = _find_result_by_job(j.get("id"))
                if r:
                    exp = _parse_dt(r.get("expires_at"))
                    if exp is None or exp > now_dt:
                        # Return cached result, but also record a new job? Business rule says subsequent identical requests must set cache_hit=true and return stored result without recomputation.
                        # Create a new succeeded job that points to existing result is impossible due to unique(job_id) on results.
                        # Instead create a new job marked succeeded with cache_hit=true but no result would violate "no success without effect".
                        # So: return cached result directly and do not mutate jobs; but we must have observable dynamics -> request log.
                        _log("ok")
                        return {
                            "tool": endpoint,
                            "exchange": exchange,
                            "symbol": symbol_n,
                            "interval": interval,
                            "pair_id": pair_id,
                            "cache_hit": True,
                            "job_id": j.get("id"),
                            "result": r
                        }

        # Create a new job row (queued -> running -> terminal)
        ts = _now_iso()
        job_id = "job_" + datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%d%H%M%S%f")
        job = {
            "id": job_id,
            "indicator_id": idef.get("id"),
            "pair_id": pair_id,
            "interval": interval,
            "candle_limit": int(limit),
            "input_start_time": None,
            "input_end_time": None,
            "request_fingerprint": fp,
            "cache_hit": False,
            "status": "queued",
            "queued_at": ts,
            "started_at": None,
            "finished_at": None,
            "error_code": None,
            "error_message": None,
            "binance_request_count": 0,
            "compute_time_ms": None,
            "created_at": ts,
            "updated_at": ts
        }
        jobs.append(job)
        _save("computation_jobs.json", jobs)

        # Transition to running
        job["status"] = "running"
        job["started_at"] = _now_iso()
        job["updated_at"] = job["started_at"]
        _save("computation_jobs.json", jobs)

        # Reject disabled pair for new jobs (fail job with PAIR_DISABLED)
        if pair.get("status") != "active":
            fin = _now_iso()
            job["status"] = "failed"
            job["finished_at"] = fin
            job["updated_at"] = fin
            job["error_code"] = "PAIR_DISABLED"
            job["error_message"] = "Trading pair is not active"
            _save("computation_jobs.json", jobs)
            _log("error", error_code="PAIR_DISABLED")
            return _err("CONFLICT", "trading pair is not active", error_code="PAIR_DISABLED", exchange=exchange, symbol=symbol_n)

        # Load OHLCV candles for pair/interval ordered by open_time and take most recent limit
        candles = _load("ohlcv_candles.json")
        scoped = [c for c in candles if c.get("pair_id") == pair_id and c.get("interval") == interval]
        def _candle_time(c):
            dt = _parse_dt(c.get("open_time"))
            return dt or datetime.datetime(1970,1,1,tzinfo=datetime.timezone.utc)
        scoped.sort(key=_candle_time)
        if limit is not None:
            scoped = scoped[-int(limit):]

        # Must have at least min_lookback candles
        if len(scoped) < int(min_lookback):
            fin = _now_iso()
            job["status"] = "failed"
            job["finished_at"] = fin
            job["updated_at"] = fin
            job["error_code"] = "INSUFFICIENT_DATA"
            job["error_message"] = f"Need at least {min_lookback} candles, found {len(scoped)}"
            _save("computation_jobs.json", jobs)
            _log("error", error_code="INSUFFICIENT_DATA")
            return _err("CONFLICT", "insufficient candle data", error_code="INSUFFICIENT_DATA", required=min_lookback, found=len(scoped))

        # Compute Typical Price series: (high+low+close)/3 ; strategy signal: compare last TP to previous TP
        t_comp0 = time.time()
        tps = []
        times = []
        for c in scoped:
            h, l, cl = c.get("high"), c.get("low"), c.get("close")
            if not isinstance(h, (int, float)) or not isinstance(l, (int, float)) or not isinstance(cl, (int, float)):
                continue
            tp = (float(h) + float(l) + float(cl)) / 3.0
            ot = _parse_dt(c.get("open_time"))
            tps.append(tp)
            times.append((ot or now_dt).isoformat())
        if len(tps) < 2:
            fin = _now_iso()
            job["status"] = "failed"
            job["finished_at"] = fin
            job["updated_at"] = fin
            job["error_code"] = "INSUFFICIENT_DATA"
            job["error_message"] = "Not enough valid candle points"
            _save("computation_jobs.json", jobs)
            _log("error", error_code="INSUFFICIENT_DATA")
            return _err("CONFLICT", "insufficient candle data", error_code="INSUFFICIENT_DATA", required=2, found=len(tps))

        last_tp = tps[-1]
        prev_tp = tps[-2]
        if last_tp > prev_tp:
            sig = 1
        elif last_tp < prev_tp:
            sig = -1
        else:
            sig = 0

        as_of_dt = _parse_dt(scoped[-1].get("close_time")) or _parse_dt(scoped[-1].get("open_time")) or now_dt
        as_of_time = as_of_dt.isoformat()

        compute_ms = int((time.time() - t_comp0) * 1000)

        # Persist result (signal kind)
        res_id = "res_" + datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%d%H%M%S%f")
        ttl = idef.get("cache_ttl_seconds")
        expires_at = None
        if isinstance(ttl, int) and ttl > 0:
            expires_at = (now_dt + datetime.timedelta(seconds=int(ttl))).isoformat()

        result = {
            "id": res_id,
            "job_id": job_id,
            "result_kind": "signal",
            "as_of_time": as_of_time,
            "value": float(sig),
            "signal": int(sig),
            "series": None,
            "multi_series": None,
            "metadata": {
                "strategy": "typical_price",
                "definition_id": idef.get("id"),
                "inputs": {"exchange": exchange, "symbol": symbol_n, "interval": interval, "limit": int(limit)},
                "latest_typical_price": last_tp,
                "prev_typical_price": prev_tp
            },
            "expires_at": expires_at,
            "created_at": _now_iso(),
            "updated_at": _now_iso()
        }
        results.append(result)
        _save("computation_results.json", results)

        # Transition job to succeeded (running -> succeeded)
        fin = _now_iso()
        job["status"] = "succeeded"
        job["finished_at"] = fin
        job["updated_at"] = fin
        job["compute_time_ms"] = compute_ms
        _save("computation_jobs.json", jobs)

        _log("ok")
        return {
            "tool": endpoint,
            "exchange": exchange,
            "symbol": symbol_n,
            "interval": interval,
            "pair_id": pair_id,
            "cache_hit": False,
            "job_id": job_id,
            "signal": int(sig),
            "result": result
        }
    except Exception as e:
        _log("error", error_code="FAILED")
        return _err("CONFLICT", "unexpected error", detail=str(e))

