        if exchange is None:
            exchange = "binance"
        if not isinstance(exchange, str) or exchange not in ("binance",):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "exchange must be one of: binance", field="exchange")

        allowed_intervals = {"1m","3m","5m","15m","30m","1h","2h","4h","6h","8h","12h","1d","3d","1w","1M"}
        if interval is not None and (not isinstance(interval, str) or interval not in allowed_intervals):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "interval is invalid", field="interval", allowed=sorted(allowed_intervals))

        if limit is not None:
            if not isinstance(limit, int) or isinstance(limit, bool) or limit < 1:
                _log("error", error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "limit must be an integer >= 1", field="limit")

        defs = _load("indicator_definitions.json")
        idef = None
        for d in defs:
            if d.get("tool_name") == endpoint:
                idef = d
                break
        if idef is None:
            _log("error", error_code="NOT_FOUND")
            return _err("NOT_FOUND", "indicator definition not found", tool_name=endpoint)

        if not idef.get("is_enabled", False) or idef.get("status") not in ("active", "deprecated"):
            _log("error", error_code="UNAUTHORIZED")
            return _err("UNAUTHORIZED", "tool is not enabled", tool_name=endpoint)

        if interval is None:
            interval = idef.get("default_interval")
        if interval not in allowed_intervals:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "interval is invalid", field="interval", allowed=sorted(allowed_intervals))

        min_lookback = idef.get("min_lookback_candles")
