        for p in pairs:
            if p.get("exchange") == exchange and p.get("symbol") == symbol_n:
                pair = p
                break
        if pair is None:
            _log("error", error_code="NOT_FOUND")
            return _err("NOT_FOUND", "trading pair not found", exchange=exchange, symbol=symbol_n)

        pair_id = pair.get("id")

        norm = {
            "tool_name": endpoint,
            "indicator_id": idef.get("id"),
            "exchange": exchange,
            "symbol": symbol_n,
            "pair_id": pair_id,
            "interval": interval,
            "limit": int(limit),
            "input_start_time": None,
            "input_end_time": None
        }
        fp = hashlib.sha256(json.dumps(norm, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()

        jobs = _load("computation_jobs.json")
        results = _load("computation_results.json")

        def _find_result_by_job(job_id):
            for r in results:
                if r.get("job_id") == job_id:
                    return r
            return None

        now_dt = datetime.datetime.now(datetime.timezone.utc)
        for j in jobs:
            if j.get("request_fingerprint") == fp and j.get("status") == "succeeded" and j.get("finished_at") is not None:
                r = _find_result_by_job(j.get("id"))
                if r:
                    exp = _parse_dt(r.get("expires_at"))
                    if exp is None or exp > now_dt:
                        _log("ok")
                        return {
                            "tool": endpoint,
                            "exchange": exchange,
                            "symbol": symbol_n,
                            "interval": interval,
                            "pair_id": pair_id,
                            "cache_hit": True,
                            "job_id": j.get("id"),
                            "result": r
                        }

        ts = _now_iso()
        job_id = "job_" + datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%d%H%M%S%f")
        job = {
            "id": job_id,
            "indicator_id": idef.get("id"),
