            "status": "queued",
            "queued_at": ts,
            "started_at": None,
            "finished_at": None,
            "error_code": None,
            "error_message": None,
            "binance_request_count": 0,
            "compute_time_ms": None,
            "created_at": ts,
            "updated_at": ts
        }
        jobs.append(job)
        _save("computation_jobs.json", jobs)

        job["status"] = "running"
        job["started_at"] = _now_iso()
        job["updated_at"] = job["started_at"]
