            job["status"] = "failed"
            job["finished_at"] = fin
            job["updated_at"] = fin
            job["error_code"] = "PAIR_DISABLED"
            job["error_message"] = "Trading pair is not active"
            _save("computation_jobs.json", jobs)
            _log("error", error_code="PAIR_DISABLED")
