        candles = _load("ohlcv_candles.json")
        scoped = [c for c in candles if c.get("pair_id") == pair_id and c.get("interval") == interval]

        def _candle_time(c):
            dt = _parse_dt(c.get("open_time"))
            return dt or datetime.datetime(1970,1,1,tzinfo=datetime.timezone.utc)
        scoped.sort(key=_candle_time)
