        if len(scoped) < int(min_lookback):
            fin = _now_iso()
            job["status"] = "failed"
            job["finished_at"] = fin
            job["updated_at"] = fin
            job["error_code"] = "INSUFFICIENT_DATA"
            job["error_message"] = f"Need at least {min_lookback} candles, found {len(scoped)}"
            _save("computation_jobs.json", jobs)
            _log("error", error_code="INSUFFICIENT_DATA")
            return _err("CONFLICT", "insufficient candle data", error_code="INSUFFICIENT_DATA", required=min_lookback, found=len(scoped))

        t_comp0 = time.time()

        # VWMA over the loaded candles: sum(close*volume)/sum(volume)
        num = 0.0
        den = 0.0
        closes = []
        for c in scoped:
            cl = c.get("close")
            vol = c.get("volume")
            if isinstance(cl, (int, float)) and isinstance(vol, (int, float)):
                cl = float(cl); vol = float(vol)
                if vol >= 0:
                    num += cl * vol
                    den += vol
                    closes.append(cl)

        if den <= 0 or len(closes) < 2:
            fin = _now_iso()
            job["status"] = "failed"
            job["finished_at"] = fin
            job["updated_at"] = fin
            job["error_code"] = "INSUFFICIENT_DATA"
            job["error_message"] = "Not enough volume/close data to compute VWMA"
            _save("computation_jobs.json", jobs)
            _log("error", error_code="INSUFFICIENT_DATA")
            return _err("CONFLICT", "insufficient candle data", error_code="INSUFFICIENT_DATA")

        vwma = num / den
        last_close = float(scoped[-1].get("close"))
        # Strategy signal: price above vwma => BUY, below => SELL, else HOLD
        if last_close > vwma:
            sig = 1
        elif last_close < vwma:
            sig = -1
        else:
            sig = 0

        as_of_dt = _parse_dt(scoped[-1].get("close_time")) or _parse_dt(scoped[-1].get("open_time")) or now_dt
        as_of_time = as_of_dt.isoformat()

        compute_ms = int((time.time() - t_comp0) * 1000)

        res_id = "res_" + datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%d%H%M%S%f")
        ttl = idef.get("cache_ttl_seconds")
        expires_at = None
        if isinstance(ttl, int) and ttl > 0:
            expires_at = (now_dt + datetime.timedelta(seconds=int(ttl))).isoformat()

        result = {
            "id": res_id,
            "job_id": job_id,
            "result_kind": "signal",
            "as_of_time": as_of_time,
            "value": float(sig),
            "signal": int(sig),
            "series": None,
            "multi_series": None,
            "metadata": {
                "strategy": "vwma",
                "definition_id": idef.get("id"),
                "inputs": {"exchange": exchange, "symbol": symbol_n, "interval": interval, "limit": int(limit)},
                "vwma": vwma,
                "last_close": last_close
            },
            "expires_at": expires_at,
            "created_at": _now_iso(),
            "updated_at": _now_iso()
        }
        results.append(result)
        _save("computation_results.json", results)

        fin = _now_iso()
        job["status"] = "succeeded"
        job["finished_at"] = fin
        job["updated_at"] = fin
        job["compute_time_ms"] = compute_ms
        _save("computation_jobs.json", jobs)

        _log("ok")
        return {
            "tool": endpoint,
            "exchange": exchange,
            "symbol": symbol_n,
            "interval": interval,
            "pair_id": pair_id,
            "cache_hit": False,
            "job_id": job_id,
            "signal": int(sig),
            "result": result
        }
    except Exception as e:
        _log("error", error_code="FAILED")
        return _err("CONFLICT", "unexpected error", detail=str(e))

