        jobs = _load("computation_jobs.json")
        results = _load("computation_results.json")

        def _find_result_by_job(job_id):
            for r in results:
                if r.get("job_id") == job_id:
                    return r
            return None

        now_dt = datetime.datetime.now(datetime.timezone.utc)
        for j in jobs:
            if j.get("request_fingerprint") == fp and j.get("status") == "succeeded" and j.get("finished_at") is not None:
                r = _find_result_by_job(j.get("id"))
                if r:
                    exp = _parse_dt(r.get("expires_at"))
                    if exp is None or exp > now_dt:
                        _log("ok")
                        return {
                            "tool": endpoint,
                            "exchange": exchange,
                            "symbol": symbol_n,
                            "interval": interval,
                            "pair_id": pair_id,
                            "cache_hit": True,
                            "job_id": j.get("id"),
                            "result": r
                        }

        ts = _now_iso()
        job_id = "job_" + datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%d%H%M%S%f")
        job = {
            "id": job_id,
            "indicator_id": idef.get("id"),
            "pair_id": pair_id,
            "interval": interval,
            "candle_limit": int(limit),
            "input_start_time": None,
            "input_end_time": None,
            "request_fingerprint": fp,
            "cache_hit": False,
            "status": "queued",
            "queued_at": ts,
            "started_at": None,
            "finished_at": None,
            "error_code": None,
            "error_message": None,
            "binance_request_count": 0,
            "compute_time_ms": None,
            "created_at": ts,
            "updated_at": ts
        }
        jobs.append(job)
        _save("computation_jobs.json", jobs)

