            job["error_message"] = "Trading pair is not active"
            _save("computation_jobs.json", jobs)
            _log("error", error_code="PAIR_DISABLED")
            return _err("CONFLICT", "trading pair is not active", error_code="PAIR_DISABLED", exchange=exchange, symbol=symbol_n)

        candles = _load("ohlcv_candles.json")
        scoped = [c for c in candles if c.get("pair_id") == pair_id and c.get("interval") == interval]

        def _candle_time(c):
            dt = _parse_dt(c.get("open_time"))
            return dt or datetime.datetime(1970,1,1,tzinfo=datetime.timezone.utc)
        scoped.sort(key=_candle_time)
        scoped = scoped[-int(limit):]

        if len(scoped) < max(int(min_lookback), 2):
            fin = _now_iso()
            job["status"] = "failed"
            job["finished_at"] = fin
            job["updated_at"] = fin
            job["error_code"] = "INSUFFICIENT_DATA"
            job["error_message"] = f"Need at least {max(min_lookback,2)} candles, found {len(scoped)}"
            _save("computation_jobs.json", jobs)
            _log("error", error_code="INSUFFICIENT_DATA")
            return _err("CONFLICT", "insufficient candle data", error_code="INSUFFICIENT_DATA", required=max(min_lookback,2), found=len(scoped))

        t_comp0 = time.time()

        # Vortex Indicator basics:
        # VM+ = |high_t - low_{t-1}|
        # VM- = |low_t - high_{t-1}|
        # TR  = max(high_t-low_t, |high_t-close_{t-1}|, |low_t-close_{t-1}|)
        # VI+ = sum(VM+)/sum(TR), VI- = sum(VM-)/sum(TR) over window.
        # We use window = min_lookback_candles (typical).
        window = int(min_lookback)
        if len(scoped) < window + 1:
            # Need prev candle for first TR reference
            window = max(1, len(scoped) - 1)

        vmp = 0.0
        vmm = 0.0
        trsum = 0.0

        # Use last (window) transitions ending at last candle
        start_idx = max(1, len(scoped) - window)
        for i in range(start_idx, len(scoped)):
            c = scoped[i]
            p = scoped[i - 1]
            h = float(c.get("high")); l = float(c.get("low")); cl_prev = float(p.get("close"))
            h_prev = float(p.get("high")); l_prev = float(p.get("low"))
            vmp += abs(h - l_prev)
            vmm += abs(l - h_prev)
            tr = max(h - l, abs(h - cl_prev), abs(l - cl_prev))
            trsum += tr

        if trsum <= 0:
            fin = _now_iso()
            job["status"] = "failed"
            job["finished_at"] = fin
            job["updated_at"] = fin
            job["error_code"] = "INSUFFICIENT_DATA"
            job["error_message"] = "TR sum is zero; cannot compute Vortex"
            _save("computation_jobs.json", jobs)
            _log("error", error_code="INSUFFICIENT_DATA")
            return _err("CONFLICT", "insufficient candle data", error_code="INSUFFICIENT_DATA")

        vi_plus = vmp / trsum
        vi_minus = vmm / trsum

        # Strategy signal: VI+ above VI- => BUY, below => SELL, else HOLD
        if vi_plus > vi_minus:
            sig = 1
        elif vi_plus < vi_minus:
            sig = -1
        else:
            sig = 0

        as_of_dt = _parse_dt(scoped[-1].get("close_time")) or _parse_dt(scoped[-1].get("open_time")) or now_dt
        as_of_time = as_of_dt.isoformat()

        compute_ms = int((time.time() - t_comp0) * 1000)

        res_id = "res_" + datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%d%H%M%S%f")
        ttl = idef.get("cache_ttl_seconds")
        expires_at = None
        if isinstance(ttl, int) and ttl > 0:
            expires_at = (now_dt + datetime.timedelta(seconds=int(ttl))).isoformat()

        result = {
            "id": res_id,
            "job_id": job_id,
            "result_kind": "signal",
            "as_of_time": as_of_time,
            "value": float(sig),
            "signal": int(sig),
            "series": None,
            "multi_series": None,
            "metadata": {
                "strategy": "vortex",
                "definition_id": idef.get("id"),
                "inputs": {"exchange": exchange, "symbol": symbol_n, "interval": interval, "limit": int(limit), "window": int(window)},
                "vi_plus": vi_plus,
                "vi_minus": vi_minus
            },
            "expires_at": expires_at,
            "created_at": _now_iso(),
            "updated_at": _now_iso()
        }
        results.append(result)
        _save("computation_results.json", results)

        fin = _now_iso()
        job["status"] = "succeeded"
        job["finished_at"] = fin
        job["updated_at"] = fin
        job["compute_time_ms"] = compute_ms
        _save("computation_jobs.json", jobs)

        _log("ok")
        return {
            "tool": endpoint,
            "exchange": exchange,
            "symbol": symbol_n,
            "interval": interval,
            "pair_id": pair_id,
            "cache_hit": False,
            "job_id": job_id,
            "signal": int(sig),
            "result": result
        }
    except Exception as e:
        _log("error", error_code="FAILED")
        return _err("CONFLICT", "unexpected error", detail=str(e))

