        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Resolved limit is invalid")

    # Resolve trading pair (binance, symbol)
    pairs = _load("trading_pairs.json")
    pair = None
    for p in pairs:
        if p.get("exchange") == "binance" and p.get("symbol") == symbol:
            pair = p
            break
    if not pair:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Trading pair not found", symbol=symbol, exchange="binance")
    if pair.get("status") != "active":
        # Must fail job with PAIR_DISABLED (business rule)
        # Create failed job row (mutation must have effect)
        jobs = _load("computation_jobs.json")
        job_id = f"job_{int(now.timestamp()*1000)}_{hashlib.sha256(f'{endpoint}:{symbol}:{now.timestamp()}'.encode()).hexdigest()[:12]}"
        fp_obj = {
            "tool": endpoint,
            "pair_id": pair.get("id"),
            "interval": interval,
            "limit": limit,
            "start_time": _to_iso(st),
            "end_time": _to_iso(et),
        }
        fp = hashlib.sha256(json.dumps(fp_obj, sort_keys=True, separators=(",",":")).encode("utf-8")).hexdigest()
        job = {
            "id": job_id,
            "indicator_id": idef.get("id"),
            "pair_id": pair.get("id"),
            "interval": interval,
            "candle_limit": int(limit),
            "input_start_time": _to_iso(st),
            "input_end_time": _to_iso(et),
            "request_fingerprint": fp,
            "cache_hit": False,
            "status": "failed",
            "queued_at": _to_iso(now),
            "started_at": _to_iso(now),
            "finished_at": _to_iso(now),
            "error_code": "PAIR_DISABLED",
            "error_message": "Trading pair is not active",
            "binance_request_count": 0,
            "compute_time_ms": 0,
            "created_at": _to_iso(now),
            "updated_at": _to_iso(now),
        }
        jobs.append(job)
        _save("computation_jobs.json", jobs)
        _log("error", "INVALID_TRANSITION")
        return {
            "job": job,
            "result": None,
            "error": {"code": "PAIR_DISABLED", "message": "Trading pair is not active"}
        }

    # Build request fingerprint for caching/dedup
    fp_obj = {
        "tool": endpoint,
        "pair_id": pair.get("id"),
        "interval": interval,
        "limit": int(limit),
        "start_time": _to_iso(st),
        "end_time": _to_iso(et),
    }
    request_fingerprint = hashlib.sha256(json.dumps(fp_obj, sort_keys=True, separators=(",",":")).encode("utf-8")).hexdigest()

    jobs = _load("computation_jobs.json")
    results = _load("computation_results.json")

    def _find_cached():
        # succeeded job with same fingerprint and non-expired result
        for j in jobs:
            if j.get("request_fingerprint") == request_fingerprint and j.get("status") == "succeeded" and j.get("finished_at"):
                # find result by job_id
                r = None
                for rr in results:
                    if rr.get("job_id") == j.get("id"):
                        r = rr
                        break
                if not r:
                    continue
                exp = _as_dt(r.get("expires_at"))
                if exp is None or exp > now:
                    return j, r
        return None, None

    if use_cache is True:
        cj, cr = _find_cached()
        if cj and cr:
            # Record a new job indicating cache_hit=true? Business rule: "subsequent identical requests must set cache_hit=true and return that stored computation_result without recomputation."
            job_id = f"job_{int(now.timestamp()*1000)}_{hashlib.sha256(f'cache:{request_fingerprint}:{now.timestamp()}'.encode()).hexdigest()[:12]}"
            job = {
                "id": job_id,
                "indicator_id": idef.get("id"),
                "pair_id": pair.get("id"),
                "interval": interval,
                "candle_limit": int(limit),
                "input_start_time": _to_iso(st),
                "input_end_time": _to_iso(et),
                "request_fingerprint": request_fingerprint,
                "cache_hit": True,
                "status": "succeeded",
                "queued_at": _to_iso(now),
                "started_at": _to_iso(now),
                "finished_at": _to_iso(now),
                "error_code": None,
                "error_message": None,
                "binance_request_count": 0,
                "compute_time_ms": 0,
                "created_at": _to_iso(now),
                "updated_at": _to_iso(now),
            }
            jobs.append(job)
            _save("computation_jobs.json", jobs)
            _log("ok")
            return {"job": job, "cached_from_job_id": cj.get("id"), "result": cr}

    # Create job queued -> running
    job_id = f"job_{int(now.timestamp()*1000)}_{hashlib.sha256(f'{request_fingerprint}:{now.timestamp()}'.encode()).hexdigest()[:12]}"
    queued_at = now
    job = {
        "id": job_id,
        "indicator_id": idef.get("id"),
        "pair_id": pair.get("id"),
        "interval": interval,
        "candle_limit": int(limit),
        "input_start_time": _to_iso(st),
        "input_end_time": _to_iso(et),
        "request_fingerprint": request_fingerprint,
        "cache_hit": False,
        "status": "queued",
        "queued_at": _to_iso(queued_at),
        "started_at": None,
        "finished_at": None,
        "error_code": None,
        "error_message": None,
        "binance_request_count": 0,
        "compute_time_ms": None,
        "created_at": _to_iso(now),
        "updated_at": _to_iso(now),
    }
    jobs.append(job)
    _save("computation_jobs.json", jobs)

    def _transition(j, new_status):
        transitions = {
            "queued": {"running", "cancelled"},
            "running": {"succeeded", "failed", "cancelled"},
            "succeeded": set(),
            "failed": set(),
            "cancelled": set(),
        }
        cur = j.get("status")
        if new_status not in transitions.get(cur, set()):
            return False
        j["status"] = new_status
        j["updated_at"] = _to_iso(datetime.datetime.now(datetime.timezone.utc))
        return True

    # queued -> running
    job = next((x for x in jobs if x.get("id") == job_id), None)
    if not job:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Job disappeared")
    if not _transition(job, "running"):
        _log("error", "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Illegal job transition")
    job["started_at"] = _to_iso(datetime.datetime.now(datetime.timezone.utc))
    _save("computation_jobs.json", jobs)

    # Select candles
    candles = _load("ohlcv_candles.json")
    pid = pair.get("id")
    selected = []
    for c in candles:
        if c.get("pair_id") != pid or c.get("interval") != interval:
            continue
        ot = _as_dt(c.get("open_time"))
        if ot is None:
            continue
        if st and ot < st:
            continue
        if et and ot >= et:
            continue
        selected.append(c)
    selected.sort(key=lambda x: _as_dt(x.get("open_time")) or datetime.datetime(1970,1,1,tzinfo=datetime.timezone.utc))

    if st is None and et is None:
        selected = selected[-int(limit):]
    else:
        # windowed: still cap to limit most recent if too many
        if len(selected) > int(limit):
            selected = selected[-int(limit):]

    min_lb = int(idef.get("min_lookback_candles") or 1)
    if len(selected) < min_lb:
        # fail job with INSUFFICIENT_DATA
        if not _transition(job, "failed"):
            _log("error", "INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", "Illegal job transition")
        fin = datetime.datetime.now(datetime.timezone.utc)
        job["finished_at"] = _to_iso(fin)
        job["updated_at"] = _to_iso(fin)
        job["error_code"] = "INSUFFICIENT_DATA"
        job["error_message"] = f"Need at least {min_lb} candles, found {len(selected)}"
        job["compute_time_ms"] = 0
        _save("computation_jobs.json", jobs)
        _log("ok")
        return {"job": job, "result": None, "error": {"code": "INSUFFICIENT_DATA", "message": job["error_message"]}}

    # Compute Awesome Oscillator: AO = SMA(5, median) - SMA(34, median); strategy signal via zero-line cross of AO
    t_compute0 = time.time()
    med = []
    times = []
    for c in selected:
        hi = c.get("high"); lo = c.get("low")
        try:
            m = (float(hi) + float(lo)) / 2.0
        except Exception:
            m = None
        if m is None or not math.isfinite(m):
            continue
        med.append(m)
        times.append(_as_dt(c.get("close_time")) or _as_dt(c.get("open_time")) or now)

    def _sma(arr, n):
        if len(arr) < n:
            return None
        return sum(arr[-n:]) / float(n)

    ao_now = _sma(med, 5)
    ao_long = _sma(med, 34)
    ao = None
    if ao_now is not None and ao_long is not None:
        ao = ao_now - ao_long

    # previous AO for cross
    ao_prev = None
    if len(med) >= 35:
        ao_now_p = sum(med[-6:-1]) / 5.0
        ao_long_p = sum(med[-35:-1]) / 34.0
        ao_prev = ao_now_p - ao_long_p

    signal = 0
    if ao is None or ao_prev is None:
        signal = 0
    else:
        if ao_prev <= 0 and ao > 0:
            signal = 1
        elif ao_prev >= 0 and ao < 0:
            signal = -1
        else:
            signal = 0

    if signal not in (-1, 0, 1):
        signal = 0

    compute_ms = int((time.time() - t_compute0) * 1000)
    as_of = times[-1] if times else now

    # succeed job + write result (unique job_id)
    if not _transition(job, "succeeded"):
        _log("error", "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Illegal job transition")
    fin = datetime.datetime.now(datetime.timezone.utc)
    job["finished_at"] = _to_iso(fin)
    job["updated_at"] = _to_iso(fin)
    job["compute_time_ms"] = compute_ms
    job["error_code"] = None
    job["error_message"] = None
    _save("computation_jobs.json", jobs)

    # result TTL
    ttl = int(idef.get("cache_ttl_seconds") or 0)
    expires_at = None
    if ttl > 0:
        expires_at = _to_iso(fin + datetime.timedelta(seconds=ttl))

    # Ensure no existing result for this job
    if any(r.get("job_id") == job_id for r in results):
        _log("error", "CONFLICT")
        return _err("CONFLICT", "Result already exists for job_id", job_id=job_id)

    res_id = f"res_{int(fin.timestamp()*1000)}_{hashlib.sha256(f'{job_id}'.encode()).hexdigest()[:12]}"
    result = {
        "id": res_id,
        "job_id": job_id,
        "result_kind": "signal",
        "as_of_time": _to_iso(as_of),
        "value": float(signal),
        "signal": int(signal),
        "series": None,
        "multi_series": None,
        "metadata": {"strategy": "awesome_oscillator", "computed_on": {"interval": interval, "limit": int(limit)}},
        "expires_at": expires_at,
        "created_at": _to_iso(fin),
        "updated_at": _to_iso(fin),
    }
    results.append(result)
    _save("computation_results.json", results)

    _log("ok")
    return {"job": job, "result": result, "latency_ms": int((time.time() - t0) * 1000)}

def calculate_ichimoku_cloud_strategy(symbol, interval=None, limit=None, start_time=None, end_time=None, use_cache=None, **_extra):
    import json, os, datetime, time, hashlib, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0416000" if __import__("os").path.isdir("./environment_mix/0416000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    endpoint = "calculate_ichimoku_cloud_strategy"
    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _parse_dt(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str) or not s.strip():
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO 8601 datetime string")
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                dt = datetime.datetime.fromisoformat(ss[:-1] + "+00:00")
            else:
                dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc), None
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO 8601 datetime string")

    def _to_iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _as_dt(x):
        if x is None:
            return None
        if isinstance(x, datetime.datetime):
            dt = x
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        if isinstance(x, str):
            dt, e = _parse_dt(x, "datetime")
            return dt if not e else None
        return None

    # Validate inputs
    if not isinstance(symbol, str) or not symbol.strip():
        return _err("VALIDATION_ERROR", "symbol is required and must be a non-empty string")
    symbol = symbol.strip()

    allowed_intervals = {"1m","3m","5m","15m","30m","1h","2h","4h","6h","8h","12h","1d","3d","1w","1M"}
    if interval is not None and (not isinstance(interval, str) or interval not in allowed_intervals):
        return _err("VALIDATION_ERROR", "interval must be one of the supported Binance intervals")
    if limit is not None and (not isinstance(limit, int) or limit < 1):
        return _err("VALIDATION_ERROR", "limit must be an integer >= 1")
    if use_cache is not None and not isinstance(use_cache, bool):
        return _err("VALIDATION_ERROR", "use_cache must be a boolean")

    st, e = _parse_dt(start_time, "start_time")
    if e: return e
    et, e = _parse_dt(end_time, "end_time")
    if e: return e
    if st and et and st > et:
        return _err("VALIDATION_ERROR", "start_time must be <= end_time")

    defs = _load("indicator_definitions.json")
    idef = next((d for d in defs if d.get("tool_name") == endpoint), None)
    if not idef:
        return _err("NOT_FOUND", "Indicator definition not found for this tool")
    if not idef.get("is_enabled", False) or idef.get("status") not in ("active", "deprecated"):
        return _err("UNAUTHORIZED", "This tool is not enabled")

    if interval is None:
        interval = idef.get("default_interval")
    if limit is None:
        limit = idef.get("default_limit")
    if interval not in allowed_intervals:
        return _err("VALIDATION_ERROR", "Resolved interval is invalid")
    if not isinstance(limit, int) or limit < 1:
        return _err("VALIDATION_ERROR", "Resolved limit is invalid")

    pairs = _load("trading_pairs.json")
    pair = next((p for p in pairs if p.get("exchange") == "binance" and p.get("symbol") == symbol), None)
    if not pair:
        return _err("NOT_FOUND", "Trading pair not found", symbol=symbol, exchange="binance")

    jobs = _load("computation_jobs.json")
    results = _load("computation_results.json")

    def _fingerprint():
        fp_obj = {
            "tool": endpoint,
            "pair_id": pair.get("id"),
            "interval": interval,
            "limit": int(limit),
            "start_time": _to_iso(st),
            "end_time": _to_iso(et),
        }
        return hashlib.sha256(json.dumps(fp_obj, sort_keys=True, separators=(",",":")).encode("utf-8")).hexdigest()

    request_fingerprint = _fingerprint()

    def _find_cached():
        for j in jobs:
            if j.get("request_fingerprint") == request_fingerprint and j.get("status") == "succeeded" and j.get("finished_at"):
                r = next((rr for rr in results if rr.get("job_id") == j.get("id")), None)
                if not r:
                    continue
                exp = _as_dt(r.get("expires_at"))
                if exp is None or exp > now:
                    return j, r
        return None, None

    def _transition(j, new_status):
        transitions = {
            "queued": {"running", "cancelled"},
            "running": {"succeeded", "failed", "cancelled"},
            "succeeded": set(),
            "failed": set(),
            "cancelled": set(),
        }
        cur = j.get("status")
        if new_status not in transitions.get(cur, set()):
            return False
        j["status"] = new_status
        j["updated_at"] = _to_iso(datetime.datetime.now(datetime.timezone.utc))
        return True

    if pair.get("status") != "active":
        job_id = f"job_{int(now.timestamp()*1000)}_{hashlib.sha256(f'{endpoint}:{symbol}:{now.timestamp()}'.encode()).hexdigest()[:12]}"
        job = {
            "id": job_id,
            "indicator_id": idef.get("id"),
            "pair_id": pair.get("id"),
            "interval": interval,
            "candle_limit": int(limit),
            "input_start_time": _to_iso(st),
            "input_end_time": _to_iso(et),
            "request_fingerprint": request_fingerprint,
            "cache_hit": False,
            "status": "failed",
            "queued_at": _to_iso(now),
            "started_at": _to_iso(now),
            "finished_at": _to_iso(now),
            "error_code": "PAIR_DISABLED",
            "error_message": "Trading pair is not active",
            "binance_request_count": 0,
            "compute_time_ms": 0,
            "created_at": _to_iso(now),
            "updated_at": _to_iso(now),
        }
        jobs.append(job)
        _save("computation_jobs.json", jobs)
        return {"job": job, "result": None, "error": {"code": "PAIR_DISABLED", "message": "Trading pair is not active"}}

    if use_cache is True:
        cj, cr = _find_cached()
        if cj and cr:
            job_id = f"job_{int(now.timestamp()*1000)}_{hashlib.sha256(f'cache:{request_fingerprint}:{now.timestamp()}'.encode()).hexdigest()[:12]}"
            job = {
                "id": job_id,
                "indicator_id": idef.get("id"),
                "pair_id": pair.get("id"),
                "interval": interval,
                "candle_limit": int(limit),
                "input_start_time": _to_iso(st),
                "input_end_time": _to_iso(et),
                "request_fingerprint": request_fingerprint,
                "cache_hit": True,
                "status": "succeeded",
                "queued_at": _to_iso(now),
                "started_at": _to_iso(now),
                "finished_at": _to_iso(now),
                "error_code": None,
                "error_message": None,
                "binance_request_count": 0,
                "compute_time_ms": 0,
                "created_at": _to_iso(now),
                "updated_at": _to_iso(now),
            }
            jobs.append(job)
            _save("computation_jobs.json", jobs)
            return {"job": job, "cached_from_job_id": cj.get("id"), "result": cr, "latency_ms": int((time.time() - t0) * 1000)}

    job_id = f"job_{int(now.timestamp()*1000)}_{hashlib.sha256(f'{request_fingerprint}:{now.timestamp()}'.encode()).hexdigest()[:12]}"
    job = {
        "id": job_id,
        "indicator_id": idef.get("id"),
        "pair_id": pair.get("id"),
        "interval": interval,
        "candle_limit": int(limit),
        "input_start_time": _to_iso(st),
        "input_end_time": _to_iso(et),
        "request_fingerprint": request_fingerprint,
        "cache_hit": False,
        "status": "queued",
        "queued_at": _to_iso(now),
        "started_at": None,
        "finished_at": None,
        "error_code": None,
        "error_message": None,
        "binance_request_count": 0,
        "compute_time_ms": None,
        "created_at": _to_iso(now),
        "updated_at": _to_iso(now),
    }
    jobs.append(job)
    _save("computation_jobs.json", jobs)

    job = next((x for x in jobs if x.get("id") == job_id), None)
    if not job:
        return _err("NOT_FOUND", "Job disappeared")
    if not _transition(job, "running"):
        return _err("INVALID_TRANSITION", "Illegal job transition")
    job["started_at"] = _to_iso(datetime.datetime.now(datetime.timezone.utc))
    _save("computation_jobs.json", jobs)

    candles = _load("ohlcv_candles.json")
    pid = pair.get("id")
    selected = []
    for c in candles:
        if c.get("pair_id") != pid or c.get("interval") != interval:
            continue
        ot = _as_dt(c.get("open_time"))
        if ot is None:
            continue
        if st and ot < st:
            continue
        if et and ot >= et:
            continue
        selected.append(c)
    selected.sort(key=lambda x: _as_dt(x.get("open_time")) or datetime.datetime(1970,1,1,tzinfo=datetime.timezone.utc))
    if st is None and et is None:
        selected = selected[-int(limit):]
    else:
        if len(selected) > int(limit):
            selected = selected[-int(limit):]

    min_lb = int(idef.get("min_lookback_candles") or 1)
    if len(selected) < min_lb:
        if not _transition(job, "failed"):
            return _err("INVALID_TRANSITION", "Illegal job transition")
        fin = datetime.datetime.now(datetime.timezone.utc)
        job["finished_at"] = _to_iso(fin)
        job["updated_at"] = _to_iso(fin)
        job["error_code"] = "INSUFFICIENT_DATA"
        job["error_message"] = f"Need at least {min_lb} candles, found {len(selected)}"
        job["compute_time_ms"] = 0
        _save("computation_jobs.json", jobs)
        return {"job": job, "result": None, "error": {"code": "INSUFFICIENT_DATA", "message": job["error_message"]}}

    # Ichimoku components: Tenkan(9), Kijun(26), SpanA=(T+K)/2, SpanB(52)
    t_compute0 = time.time()
    highs = [float(c.get("high")) for c in selected]
    lows = [float(c.get("low")) for c in selected]
    closes = [float(c.get("close")) for c in selected]
    times = [(_as_dt(c.get("close_time")) or _as_dt(c.get("open_time")) or now) for c in selected]

    def _midpoint(n):
        if len(highs) < n:
            return None
        hh = max(highs[-n:])
        ll = min(lows[-n:])
        return (hh + ll) / 2.0

    tenkan = _midpoint(9)
    kijun = _midpoint(26)
    span_a = None if (tenkan is None or kijun is None) else (tenkan + kijun) / 2.0
    span_b = _midpoint(52)
    last_close = closes[-1] if closes else None

    # Simple strategy rule:
    # BUY if close > max(span_a, span_b) and tenkan > kijun
    # SELL if close < min(span_a, span_b) and tenkan < kijun
    # else HOLD
    signal = 0
    if last_close is None or span_a is None or span_b is None or tenkan is None or kijun is None:
        signal = 0
    else:
        cloud_top = max(span_a, span_b)
        cloud_bot = min(span_a, span_b)
        if last_close > cloud_top and tenkan > kijun:
            signal = 1
        elif last_close < cloud_bot and tenkan < kijun:
            signal = -1
        else:
            signal = 0

    compute_ms = int((time.time() - t_compute0) * 1000)
    as_of = times[-1] if times else now

    if not _transition(job, "succeeded"):
        return _err("INVALID_TRANSITION", "Illegal job transition")
    fin = datetime.datetime.now(datetime.timezone.utc)
