        return _err("VALIDATION_ERROR", "use_cache must be a boolean")
    st, e = _parse_dt(start_time, "start_time")
    if e: return e
    et, e = _parse_dt(end_time, "end_time")
    if e: return e
    if st and et and st > et:
        return _err("VALIDATION_ERROR", "start_time must be <= end_time")

