    if limit is None:
        limit = idef.get("default_limit")
    if interval not in allowed_intervals:
        return _err("VALIDATION_ERROR", "Resolved interval is invalid")
    if not isinstance(limit, int) or limit < 1:
        return _err("VALIDATION_ERROR", "Resolved limit is invalid")

    pairs = _load("trading_pairs.json")
    pair = next((p for p in pairs if p.get("exchange") == "binance" and p.get("symbol") == symbol), None)
    if not pair:
        return _err("NOT_FOUND", "Trading pair not found", symbol=symbol, exchange="binance")

    jobs = _load("computation_jobs.json")
    results = _load("computation_results.json")

    fp_obj = {
        "tool": endpoint,
        "pair_id": pair.get("id"),
        "interval": interval,
        "limit": int(limit),
        "start_time": _to_iso(st),
        "end_time": _to_iso(et),
    }
    request_fingerprint = hashlib.sha256(json.dumps(fp_obj, sort_keys=True, separators=(",",":")).encode("utf-8")).hexdigest()

    def _find_cached():
        for j in jobs:
            if j.get("request_fingerprint") == request_fingerprint and j.get("status") == "succeeded" and j.get("finished_at"):
                r = next((rr for rr in results if rr.get("job_id") == j.get("id")), None)
                if not r:
                    continue
                exp = _as_dt(r.get("expires_at"))
                if exp is None or exp > now:
                    return j, r
        return None, None

    def _transition(j, new_status):
        transitions = {
            "queued": {"running", "cancelled"},
            "running": {"succeeded", "failed", "cancelled"},
            "succeeded": set(),
            "failed": set(),
            "cancelled": set(),
        }
        cur = j.get("status")
        if new_status not in transitions.get(cur, set()):
            return False
        j["status"] = new_status
        j["updated_at"] = _to_iso(datetime.datetime.now(datetime.timezone.utc))
        return True

    if pair.get("status") != "active":
        job_id = f"job_{int(now.timestamp()*1000)}_{hashlib.sha256(f'{endpoint}:{symbol}:{now.timestamp()}'.encode()).hexdigest()[:12]}"
        job = {
            "id": job_id,
            "indicator_id": idef.get("id"),
            "pair_id": pair.get("id"),
            "interval": interval,
            "candle_limit": int(limit),
            "input_start_time": _to_iso(st),
            "input_end_time": _to_iso(et),
            "request_fingerprint": request_fingerprint,
            "cache_hit": False,
            "status": "failed",
            "queued_at": _to_iso(now),
            "started_at": _to_iso(now),
            "finished_at": _to_iso(now),
            "error_code": "PAIR_DISABLED",
            "error_message": "Trading pair is not active",
            "binance_request_count": 0,
            "compute_time_ms": 0,
            "created_at": _to_iso(now),
            "updated_at": _to_iso(now),
        }
        jobs.append(job)
        _save("computation_jobs.json", jobs)
        return {"job": job, "result": None, "error": {"code": "PAIR_DISABLED", "message": "Trading pair is not active"}}

    if use_cache is True:
        cj, cr = _find_cached()
        if cj and cr:
            job_id = f"job_{int(now.timestamp()*1000)}_{hashlib.sha256(f'cache:{request_fingerprint}:{now.timestamp()}'.encode()).hexdigest()[:12]}"
            job = {
                "id": job_id,
                "indicator_id": idef.get("id"),
                "pair_id": pair.get("id"),
                "interval": interval,
                "candle_limit": int(limit),
                "input_start_time": _to_iso(st),
                "input_end_time": _to_iso(et),
                "request_fingerprint": request_fingerprint,
                "cache_hit": True,
                "status": "succeeded",
                "queued_at": _to_iso(now),
                "started_at": _to_iso(now),
                "finished_at": _to_iso(now),
                "error_code": None,
                "error_message": None,
                "binance_request_count": 0,
                "compute_time_ms": 0,
                "created_at": _to_iso(now),
                "updated_at": _to_iso(now),
            }
            jobs.append(job)
            _save("computation_jobs.json", jobs)
            return {"job": job, "cached_from_job_id": cj.get("id"), "result": cr, "latency_ms": int((time.time() - t0) * 1000)}

    job_id = f"job_{int(now.timestamp()*1000)}_{hashlib.sha256(f'{request_fingerprint}:{now.timestamp()}'.encode()).hexdigest()[:12]}"
    job = {
        "id": job_id,
        "indicator_id": idef.get("id"),
        "pair_id": pair.get("id"),
        "interval": interval,
        "candle_limit": int(limit),
        "input_start_time": _to_iso(st),
        "input_end_time": _to_iso(et),
        "request_fingerprint": request_fingerprint,
        "cache_hit": False,
        "status": "queued",
        "queued_at": _to_iso(now),
        "started_at": None,
        "finished_at": None,
        "error_code": None,
        "error_message": None,
        "binance_request_count": 0,
        "compute_time_ms": None,
        "created_at": _to_iso(now),
        "updated_at": _to_iso(now),
    }
    jobs.append(job)
    _save("computation_jobs.json", jobs)

    job = next((x for x in jobs if x.get("id") == job_id), None)
    if not job:
        return _err("NOT_FOUND", "Job disappeared")
    if not _transition(job, "running"):
        return _err("INVALID_TRANSITION", "Illegal job transition")
    job["started_at"] = _to_iso(datetime.datetime.now(datetime.timezone.utc))
    _save("computation_jobs.json", jobs)

    candles = _load("ohlcv_candles.json")
    pid = pair.get("id")
    selected = []
    for c in candles:
        if c.get("pair_id") != pid or c.get("interval") != interval:
            continue
        ot = _as_dt(c.get("open_time"))
        if ot is None:
            continue
        if st and ot < st:
            continue
        if et and ot >= et:
            continue
        selected.append(c)
    selected.sort(key=lambda x: _as_dt(x.get("open_time")) or datetime.datetime(1970,1,1,tzinfo=datetime.timezone.utc))
    if st is None and et is None:
        selected = selected[-int(limit):]
    else:
        if len(selected) > int(limit):
            selected = selected[-int(limit):]

    min_lb = int(idef.get("min_lookback_candles") or 1)
    if len(selected) < min_lb:
        if not _transition(job, "failed"):
            return _err("INVALID_TRANSITION", "Illegal job transition")
        fin = datetime.datetime.now(datetime.timezone.utc)
        job["finished_at"] = _to_iso(fin)
        job["updated_at"] = _to_iso(fin)
        job["error_code"] = "INSUFFICIENT_DATA"
        job["error_message"] = f"Need at least {min_lb} candles, found {len(selected)}"
        job["compute_time_ms"] = 0
        _save("computation_jobs.json", jobs)
        return {"job": job, "result": None, "error": {"code": "INSUFFICIENT_DATA", "message": job["error_message"]}}

    # RSI(2), Wilder smoothing; strategy thresholds: BUY if RSI2 < 10, SELL if RSI2 > 90 else HOLD
    t_compute0 = time.time()
    closes = [float(c.get("close")) for c in selected]
    times = [(_as_dt(c.get("close_time")) or _as_dt(c.get("open_time")) or now) for c in selected]

    period = 2
    if len(closes) < period + 1:
        rsi = None
    else:
        gains = []
        losses = []
        for i in range(1, len(closes)):
            ch = closes[i] - closes[i-1]
            gains.append(max(ch, 0.0))
            losses.append(max(-ch, 0.0))
        # initial average over first period
        if len(gains) < period:
            rsi = None
        else:
            avg_gain = sum(gains[:period]) / period
            avg_loss = sum(losses[:period]) / period
            for i in range(period, len(gains)):
                avg_gain = (avg_gain * (period - 1) + gains[i]) / period
                avg_loss = (avg_loss * (period - 1) + losses[i]) / period
            if avg_loss == 0:
                rsi = 100.0 if avg_gain > 0 else 50.0
            else:
                rs = avg_gain / avg_loss
                rsi = 100.0 - (100.0 / (1.0 + rs))

    signal = 0
    if rsi is None or not math.isfinite(rsi):
        signal = 0
    else:
        if rsi < 10.0:
            signal = 1
        elif rsi > 90.0:
            signal = -1
        else:
            signal = 0

    compute_ms = int((time.time() - t_compute0) * 1000)
    as_of = times[-1] if times else now

    if not _transition(job, "succeeded"):
        return _err("INVALID_TRANSITION", "Illegal job transition")
    fin = datetime.datetime.now(datetime.timezone.utc)
    job["finished_at"] = _to_iso(fin)
    job["updated_at"] = _to_iso(fin)
    job["compute_time_ms"] = compute_ms
    _save("computation_jobs.json", jobs)

    ttl = int(idef.get("cache_ttl_seconds") or 0)
    expires_at = _to_iso(fin + datetime.timedelta(seconds=ttl)) if ttl > 0 else None

    if any(r.get("job_id") == job_id for r in results):
        return _err("CONFLICT", "Result already exists for job_id", job_id=job_id)

    res_id = f"res_{int(fin.timestamp()*1000)}_{hashlib.sha256(job_id.encode()).hexdigest()[:12]}"
    result = {
        "id": res_id,
        "job_id": job_id,
        "result_kind": "signal",
        "as_of_time": _to_iso(as_of),
        "value": float(int(signal)),
        "signal": int(signal),
        "series": None,
        "multi_series": None,
        "metadata": {"strategy": "rsi2", "rsi_period": 2, "rsi": rsi, "computed_on": {"interval": interval, "limit": int(limit)}},
        "expires_at": expires_at,
        "created_at": _to_iso(fin),
        "updated_at": _to_iso(fin),
    }
    results.append(result)
    _save("computation_results.json", results)

    return {"job": job, "result": result, "latency_ms": int((time.time() - t0) * 1000)}

