        "finished_at": None,
        "error_code": None,
        "error_message": None,
        "binance_request_count": 0,
        "compute_time_ms": None,
        "created_at": _to_iso(now),
        "updated_at": _to_iso(now),
    }
    jobs.append(job)
    _save("computation_jobs.json", jobs)

    job = next((x for x in jobs if x.get("id") == job_id), None)
    if not job:
        return _err("NOT_FOUND", "Job disappeared")
    if not _transition(job, "running"):
        return _err("INVALID_TRANSITION", "Illegal job transition")
    job["started_at"] = _to_iso(datetime.datetime.now(datetime.timezone.utc))
    _save("computation_jobs.json", jobs)

    candles = _load("ohlcv_candles.json")
    pid = pair.get("id")
    selected = []
    for c in candles:
        if c.get("pair_id") != pid or c.get("interval") != interval:
            continue
        ot = _as_dt(c.get("open_time"))
        if ot is None:
            continue
        if st and ot < st:
            continue
        if et and ot >= et:
            continue
        selected.append(c)
    selected.sort(key=lambda x: _as_dt(x.get("open_time")) or datetime.datetime(1970,1,1,tzinfo=datetime.timezone.utc))
    if st is None and et is None:
        selected = selected[-int(limit):]
    else:
        if len(selected) > int(limit):
            selected = selected[-int(limit):]

    min_lb = int(idef.get("min_lookback_candles") or 1)
    if len(selected) < min_lb:
        if not _transition(job, "failed"):
            return _err("INVALID_TRANSITION", "Illegal job transition")
        fin = datetime.datetime.now(datetime.timezone.utc)
        job["finished_at"] = _to_iso(fin)
        job["updated_at"] = _to_iso(fin)
        job["error_code"] = "INSUFFICIENT_DATA"
        job["error_message"] = f"Need at least {min_lb} candles, found {len(selected)}"
        job["compute_time_ms"] = 0
        _save("computation_jobs.json", jobs)
        return {"job": job, "result": None, "error": {"code": "INSUFFICIENT_DATA", "message": job["error_message"]}}

    # Stochastic %K(14) and %D(3 SMA of %K); signal by cross and overbought/oversold.
    t_compute0 = time.time()
    highs = [float(c.get("high")) for c in selected]
    lows = [float(c.get("low")) for c in selected]
    closes = [float(c.get("close")) for c in selected]
    times = [(_as_dt(c.get("close_time")) or _as_dt(c.get("open_time")) or now) for c in selected]

    k_period = 14
    d_period = 3

    def _k_at(idx):
        if idx + 1 < k_period:
            return None
        hh = max(highs[idx+1-k_period:idx+1])
        ll = min(lows[idx+1-k_period:idx+1])
        if hh == ll:
            return 50.0
        return 100.0 * (closes[idx] - ll) / (hh - ll)

    ks = []
    for i in range(len(closes)):
        kv = _k_at(i)
        if kv is not None:
            ks.append(kv)
    k_now = ks[-1] if ks else None

    d_now = None
    if ks and len(ks) >= d_period:
        d_now = sum(ks[-d_period:]) / d_period

    # prev values for cross
    k_prev = ks[-2] if len(ks) >= 2 else None
    d_prev = (sum(ks[-(d_period+1):-1]) / d_period) if len(ks) >= (d_period + 1) else None

    signal = 0
    if k_now is None or d_now is None or k_prev is None or d_prev is None:
        signal = 0
    else:
        # BUY: bullish cross in oversold zone
        if k_prev <= d_prev and k_now > d_now and k_now < 20.0:
            signal = 1
        # SELL: bearish cross in overbought zone
        elif k_prev >= d_prev and k_now < d_now and k_now > 80.0:
            signal = -1
        else:
            signal = 0

    compute_ms = int((time.time() - t_compute0) * 1000)
    as_of = times[-1] if times else now

    if not _transition(job, "succeeded"):
        return _err("INVALID_TRANSITION", "Illegal job transition")
    fin = datetime.datetime.now(datetime.timezone.utc)
    job["finished_at"] = _to_iso(fin)
    job["updated_at"] = _to_iso(fin)
    job["compute_time_ms"] = compute_ms
    _save("computation_jobs.json", jobs)

    ttl = int(idef.get("cache_ttl_seconds") or 0)
    expires_at = _to_iso(fin + datetime.timedelta(seconds=ttl)) if ttl > 0 else None

    if any(r.get("job_id") == job_id for r in results):
        return _err("CONFLICT", "Result already exists for job_id", job_id=job_id)

    res_id = f"res_{int(fin.timestamp()*1000)}_{hashlib.sha256(job_id.encode()).hexdigest()[:12]}"
    result = {
        "id": res_id,
        "job_id": job_id,
        "result_kind": "signal",
        "as_of_time": _to_iso(as_of),
        "value": float(int(signal)),
        "signal": int(signal),
        "series": None,
        "multi_series": None,
        "metadata": {
            "strategy": "stochastic_oscillator",
            "params": {"k_period": k_period, "d_period": d_period},
            "components": {"k": k_now, "d": d_now},
            "computed_on": {"interval": interval, "limit": int(limit)}
        },
        "expires_at": expires_at,
        "created_at": _to_iso(fin),
        "updated_at": _to_iso(fin),
    }
    results.append(result)
    _save("computation_results.json", results)

    return {"job": job, "result": result, "latency_ms": int((time.time() - t0) * 1000)}

def calculate_williams_r_strategy(symbol, interval=None, limit=None, start_time=None, end_time=None, use_cache=None, **_extra):
    import json, os, datetime, time, hashlib, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0416000" if __import__("os").path.isdir("./environment_mix/0416000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "calculate_williams_r_strategy"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            raise ValueError(f"{field} must be an ISO 8601 string")
        try:
            # Support trailing Z
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            raise ValueError(f"{field} must be ISO 8601 date-time")

    def _log(status, credential_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
        }
        logs.append(row)
        _save("request_logs.json", logs)

    # Validate inputs
    if not isinstance(symbol, str) or not symbol.strip():
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "symbol must be a non-empty string", field="symbol")
    symbol = symbol.strip()

    allowed_intervals = ["1m","3m","5m","15m","30m","1h","2h","4h","6h","8h","12h","1d","3d","1w","1M"]
    if interval is not None:
        if not isinstance(interval, str) or interval not in allowed_intervals:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "interval must be one of the supported Binance intervals", field="interval")
    if limit is not None:
        if not isinstance(limit, int) or limit < 1:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit must be an integer >= 1", field="limit")
    if use_cache is not None and not isinstance(use_cache, bool):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "use_cache must be a boolean", field="use_cache")

    try:
        st = _parse_dt(start_time, "start_time")
        et = _parse_dt(end_time, "end_time")
    except ValueError as e:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", str(e))
    if st is not None and et is not None and st > et:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "start_time must be <= end_time", field="start_time")

    # Resolve indicator definition
    defs = _load("indicator_definitions.json")
    idef = None
    for d in defs:
        if isinstance(d, dict) and d.get("tool_name") == endpoint:
            idef = d
            break
    if not idef:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Indicator definition not found for tool", tool_name=endpoint)
    if not idef.get("is_enabled", False) or idef.get("status") not in ("active", "deprecated"):
        _log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Tool is not enabled or not available", tool_name=endpoint)

    if idef.get("category") != "strategy":
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Indicator definition is not a strategy", tool_name=endpoint)

    interval_eff = interval if interval is not None else idef.get("default_interval")
    if interval_eff not in allowed_intervals:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Resolved interval is invalid", field="interval")
    limit_eff = limit if limit is not None else idef.get("default_limit")
    if not isinstance(limit_eff, int) or limit_eff < 1:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Resolved limit is invalid", field="limit")

    min_lb = idef.get("min_lookback_candles")
    if not isinstance(min_lb, int) or min_lb < 1:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Indicator definition has invalid min_lookback_candles")

    # Resolve trading pair by symbol on binance
    pairs = _load("trading_pairs.json")
    pair = None
    for p in pairs:
        if isinstance(p, dict) and p.get("exchange") == "binance" and p.get("symbol") == symbol:
            pair = p
            break
    if not pair:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Trading pair not found", symbol=symbol, exchange="binance")
    if pair.get("status") != "active":
        # Must fail job with PAIR_DISABLED
        pass

    # Normalize fingerprint inputs
    fp_payload = {
        "tool": endpoint,
        "indicator_id": idef.get("id"),
        "symbol": symbol,
        "pair_id": pair.get("id"),
        "interval": interval_eff,
        "limit": limit_eff,
        "start_time": st.isoformat() if st else None,
        "end_time": et.isoformat() if et else None,
    }
    fp = hashlib.sha256(json.dumps(fp_payload, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()

    jobs = _load("computation_jobs.json")
    results = _load("computation_results.json")

    def _find_result_by_job(job_id):
        for r in results:
            if isinstance(r, dict) and r.get("job_id") == job_id:
                return r
        return None

    def _dt_from_row(val):
        if val is None:
            return None
        if not isinstance(val, str):
            return None
        try:
            s = val[:-1] + "+00:00" if val.endswith("Z") else val
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    now = datetime.datetime.now(datetime.timezone.utc)

    # Caching: return existing succeeded job w/ unexpired result
    if use_cache:
        for j in jobs:
            if not isinstance(j, dict):
                continue
            if j.get("request_fingerprint") != fp:
                continue
            if j.get("status") != "succeeded":
                continue
            if not j.get("finished_at"):
                continue
            r = _find_result_by_job(j.get("id"))
            if not r:
                continue
            exp = _dt_from_row(r.get("expires_at"))
            if exp is None or exp > now:
                # Log request; do not mutate anything else except optional stats
                _log("ok", error_code=None)
                return {
                    "tool": endpoint,
                    "symbol": symbol,
                    "interval": interval_eff,
                    "limit": limit_eff,
                    "start_time": fp_payload["start_time"],
                    "end_time": fp_payload["end_time"],
                    "cache_hit": True,
                    "job_id": j.get("id"),
                    "as_of_time": r.get("as_of_time"),
                    "signal": r.get("signal"),
                    "value": r.get("value"),
                    "result_kind": r.get("result_kind"),
                    "metadata": r.get("metadata"),
                }

    # Create job (queued -> running -> terminal)
    if pair.get("status") != "active":
        # Create failed job with PAIR_DISABLED
        job_id = f"job_{int(time.time()*1000)}_{len(jobs)+1}"
        ts = _now_iso()
        job = {
            "id": job_id,
            "indicator_id": idef.get("id"),
            "pair_id": pair.get("id"),
            "interval": interval_eff,
            "candle_limit": int(limit_eff),
            "input_start_time": fp_payload["start_time"],
            "input_end_time": fp_payload["end_time"],
            "request_fingerprint": fp,
            "cache_hit": False,
            "status": "failed",
            "queued_at": ts,
            "started_at": ts,
            "finished_at": ts,
            "error_code": "PAIR_DISABLED",
            "error_message": "Trading pair is not active",
            "binance_request_count": 0,
            "compute_time_ms": 0,
            "created_at": ts,
            "updated_at": ts,
        }
        jobs.append(job)
        _save("computation_jobs.json", jobs)
        _log("error", error_code="PAIR_DISABLED")
        return _err("INVALID_TRANSITION", "Trading pair is not active for new computation jobs", error_code="PAIR_DISABLED", job_id=job_id)

    # Build input candles set
    candles = _load("ohlcv_candles.json")
    scoped = []
    for c in candles:
        if not isinstance(c, dict):
            continue
        if c.get("pair_id") != pair.get("id"):
            continue
        if c.get("interval") != interval_eff:
            continue
        ot = _dt_from_row(c.get("open_time"))
        if ot is None:
            continue
        if st is not None and ot < st:
            continue
        if et is not None and ot >= et:
            continue
        scoped.append((ot, c))
    scoped.sort(key=lambda x: x[0])

    if limit_eff is not None and len(scoped) > limit_eff:
        scoped = scoped[-limit_eff:]

    # Create job record: queued then running
    job_id = f"job_{int(time.time()*1000)}_{len(jobs)+1}"
    queued_ts = _now_iso()
    job = {
        "id": job_id,
        "indicator_id": idef.get("id"),
        "pair_id": pair.get("id"),
        "interval": interval_eff,
        "candle_limit": int(limit_eff),
        "input_start_time": fp_payload["start_time"],
        "input_end_time": fp_payload["end_time"],
        "request_fingerprint": fp,
        "cache_hit": False,
        "status": "queued",
        "queued_at": queued_ts,
        "started_at": None,
        "finished_at": None,
        "error_code": None,
        "error_message": None,
        "binance_request_count": 0,
        "compute_time_ms": None,
        "created_at": queued_ts,
        "updated_at": queued_ts,
    }
    jobs.append(job)
    _save("computation_jobs.json", jobs)

    # Transition to running
    started = datetime.datetime.now(datetime.timezone.utc)
    for j in jobs:
        if j.get("id") == job_id:
            if j.get("status") != "queued":
                _log("error", error_code="INVALID_TRANSITION")
                return _err("INVALID_TRANSITION", "Job not in queued state")
            j["status"] = "running"
            j["started_at"] = started.isoformat()
            j["updated_at"] = j["started_at"]
            break
    _save("computation_jobs.json", jobs)

    compute_start = time.time()

    # Check sufficient data
    if len(scoped) < min_lb:
        finished = datetime.datetime.now(datetime.timezone.utc).isoformat()
        for j in jobs:
            if j.get("id") == job_id:
                j["status"] = "failed"
                j["finished_at"] = finished
                j["updated_at"] = finished
                j["error_code"] = "INSUFFICIENT_DATA"
                j["error_message"] = f"Need at least {min_lb} candles, found {len(scoped)}"
                j["compute_time_ms"] = int((time.time() - compute_start) * 1000)
                break
        _save("computation_jobs.json", jobs)
        _log("error", error_code="INSUFFICIENT_DATA")
        return _err("CONFLICT", "Insufficient OHLCV data to compute strategy", error_code="INSUFFICIENT_DATA", job_id=job_id)

    # Williams %R strategy (simple): compute %R over last 14 candles (or min_lb if larger), signal thresholds
    window = max(14, min_lb)
    tail = scoped[-window:] if len(scoped) >= window else scoped
    highs = [float(x[1].get("high")) for x in tail]
    lows = [float(x[1].get("low")) for x in tail]
    closes = [float(x[1].get("close")) for x in tail]
    hh = max(highs)
    ll = min(lows)
    c_last = closes[-1]
    if hh == ll:
        wr = 0.0
    else:
        wr = -100.0 * (hh - c_last) / (hh - ll)

    # Strategy mapping:
    # BUY if oversold (wr <= -80), SELL if overbought (wr >= -20), else HOLD
    if wr <= -80.0:
        sig = 1
    elif wr >= -20.0:
        sig = -1
    else:
        sig = 0

    as_of = tail[-1][1].get("close_time") or tail[-1][1].get("open_time")
    ttl = idef.get("cache_ttl_seconds", 0)
    expires_at = None
    if isinstance(ttl, int) and ttl > 0:
        expires_at = (datetime.datetime.now(datetime.timezone.utc) + datetime.timedelta(seconds=ttl)).isoformat()

    finished_dt = datetime.datetime.now(datetime.timezone.utc)
    finished = finished_dt.isoformat()

    # Enforce unique succeeded request_fingerprint (idempotency): if another succeeded exists, mark this job cancelled and return cached
    # (race-like; in local store this is best-effort)
    for j in jobs:
        if j.get("id") == job_id:
            continue
        if j.get("request_fingerprint") == fp and j.get("status") == "succeeded" and j.get("finished_at"):
            r = _find_result_by_job(j.get("id"))
            if r:
                exp = _dt_from_row(r.get("expires_at"))
                if exp is None or exp > now:
                    for jj in jobs:
                        if jj.get("id") == job_id:
                            jj["status"] = "cancelled"
                            jj["finished_at"] = finished
                            jj["updated_at"] = finished
                            jj["error_code"] = None
                            jj["error_message"] = "Duplicate request; served from cache"
                            jj["compute_time_ms"] = int((time.time() - compute_start) * 1000)
                            break
                    _save("computation_jobs.json", jobs)
                    _log("ok")
                    return {
                        "tool": endpoint,
                        "symbol": symbol,
                        "interval": interval_eff,
                        "limit": limit_eff,
                        "start_time": fp_payload["start_time"],
                        "end_time": fp_payload["end_time"],
                        "cache_hit": True,
                        "job_id": j.get("id"),
                        "as_of_time": r.get("as_of_time"),
                        "signal": r.get("signal"),
                        "value": r.get("value"),
                        "result_kind": r.get("result_kind"),
                        "metadata": r.get("metadata"),
                    }

    # Write result
    res_id = f"res_{int(time.time()*1000)}_{len(results)+1}"
    created = _now_iso()
    result = {
        "id": res_id,
        "job_id": job_id,
        "result_kind": "signal",
        "as_of_time": as_of,
        "value": float(sig),
        "signal": int(sig),
        "series": None,
        "multi_series": None,
        "metadata": {"williams_r": wr, "window": window, "thresholds": {"buy_le": -80.0, "sell_ge": -20.0}},
        "expires_at": expires_at,
        "created_at": created,
        "updated_at": created,
    }
    results.append(result)
    _save("computation_results.json", results)

    # Transition job to succeeded (terminal => finished_at set)
    for j in jobs:
        if j.get("id") == job_id:
            j["status"] = "succeeded"
            j["finished_at"] = finished
            j["updated_at"] = finished
            j["compute_time_ms"] = int((time.time() - compute_start) * 1000)
            break
    _save("computation_jobs.json", jobs)

    _log("ok")
    return {
        "tool": endpoint,
        "symbol": symbol,
        "interval": interval_eff,
        "limit": limit_eff,
        "start_time": fp_payload["start_time"],
        "end_time": fp_payload["end_time"],
        "cache_hit": False,
        "job_id": job_id,
        "as_of_time": as_of,
        "signal": int(sig),
        "value": float(sig),
        "result_kind": "signal",
        "metadata": result.get("metadata"),
    }

