                break
        _save("computation_jobs.json", jobs)
        _log("error", error_code="INSUFFICIENT_DATA")
        return _err("CONFLICT", "Insufficient OHLCV data to compute strategy", error_code="INSUFFICIENT_DATA", job_id=job_id)

    # Acceleration Bands (ABANDS) simplified:
    # upper = high*(1+4*(high-low)/(high+low))
    # lower = low*(1-4*(high-low)/(high+low))
    # Use last N (window=max(20,min_lb)) and compare close to bands for signal.
    window = max(20, min_lb)
    tail = scoped[-window:] if len(scoped) >= window else scoped
    def _band(c):
        h = float(c.get("high"))
        l = float(c.get("low"))
        denom = (h + l)
        if denom == 0:
            k = 0.0
        else:
            k = 4.0 * (h - l) / denom
        upper = h * (1.0 + k)
        lower = l * (1.0 - k)
        return upper, lower

    uppers = []
    lowers = []
    closes = []
    for _, c in tail:
        u, lo = _band(c)
        uppers.append(u)
        lowers.append(lo)
        closes.append(float(c.get("close")))
    upper_last = sum(uppers[-5:]) / min(5, len(uppers))
    lower_last = sum(lowers[-5:]) / min(5, len(lowers))
    close_last = closes[-1]

    # Signal rules:
    # BUY if close crosses above lower band from below over last 2 points; SELL if crosses below upper from above; else HOLD
    prev_close = closes[-2] if len(closes) >= 2 else closes[-1]
    prev_upper = sum(uppers[-6:-1]) / min(5, max(1, len(uppers)-1)) if len(uppers) >= 2 else upper_last
    prev_lower = sum(lowers[-6:-1]) / min(5, max(1, len(lowers)-1)) if len(lowers) >= 2 else lower_last

    if prev_close < prev_lower and close_last >= lower_last:
        sig = 1
    elif prev_close > prev_upper and close_last <= upper_last:
        sig = -1
    else:
        sig = 0

    as_of = tail[-1][1].get("close_time") or tail[-1][1].get("open_time")
    ttl = idef.get("cache_ttl_seconds", 0)
    expires_at = None
    if isinstance(ttl, int) and ttl > 0:
        expires_at = (datetime.datetime.now(datetime.timezone.utc) + datetime.timedelta(seconds=ttl)).isoformat()

    # Best-effort dedup on succeeded fingerprint
    finished = _now_iso()
    for j in jobs:
        if j.get("id") == job_id:
            continue
        if j.get("request_fingerprint") == fp and j.get("status") == "succeeded" and j.get("finished_at"):
            r = _find_result(j.get("id"))
