                    for jj in jobs:
                        if jj.get("id") == job_id:
                            jj["status"] = "cancelled"
                            jj["finished_at"] = finished
                            jj["updated_at"] = finished
                            jj["error_message"] = "Duplicate request; served from cache"
                            jj["compute_time_ms"] = int((time.time() - compute_start) * 1000)
                            break
                    _save("computation_jobs.json", jobs)
                    _log("ok")
                    return {
                        "tool": endpoint,
                        "symbol": symbol,
                        "interval": interval_eff,
                        "limit": limit_eff,
                        "start_time": fp_payload["start_time"],
                        "end_time": fp_payload["end_time"],
                        "cache_hit": True,
                        "job_id": j.get("id"),
                        "as_of_time": r.get("as_of_time"),
                        "signal": r.get("signal"),
                        "value": r.get("value"),
                        "result_kind": r.get("result_kind"),
                        "metadata": r.get("metadata"),
                    }

    res_id = f"res_{int(time.time()*1000)}_{len(results)+1}"
    created = _now_iso()
    results.append({
        "id": res_id,
        "job_id": job_id,
        "result_kind": "signal",
        "as_of_time": as_of,
        "value": float(sig),
        "signal": int(sig),
        "series": None,
        "multi_series": None,
        "metadata": {
            "window": window,
            "upper_last": upper_last,
            "lower_last": lower_last,
            "rule": "cross_lower_buy_cross_upper_sell",
        },
        "expires_at": expires_at,
        "created_at": created,
        "updated_at": created,
    })
    _save("computation_results.json", results)

    for j in jobs:
        if j.get("id") == job_id:
            j["status"] = "succeeded"
            j["finished_at"] = finished
            j["updated_at"] = finished
            j["compute_time_ms"] = int((time.time() - compute_start) * 1000)
            break
    _save("computation_jobs.json", jobs)

    _log("ok")
    return {
        "tool": endpoint,
        "symbol": symbol,
        "interval": interval_eff,
        "limit": limit_eff,
        "start_time": fp_payload["start_time"],
        "end_time": fp_payload["end_time"],
        "cache_hit": False,
        "job_id": job_id,
        "as_of_time": as_of,
        "signal": int(sig),
        "value": float(sig),
        "result_kind": "signal",
        "metadata": results[-1].get("metadata"),
    }

