        if j.get("id") == job_id:
            if j.get("status") != "queued":
                _log("error", error_code="INVALID_TRANSITION")
                return _err("INVALID_TRANSITION", "Job not in queued state")
            j["status"] = "running"
            j["started_at"] = started
            j["updated_at"] = started
            break
    _save("computation_jobs.json", jobs)

    compute_start = time.time()
    if len(scoped) < min_lb:
        finished = _now_iso()
        for j in jobs:
            if j.get("id") == job_id:
                j["status"] = "failed"
                j["finished_at"] = finished
                j["updated_at"] = finished
                j["error_code"] = "INSUFFICIENT_DATA"
                j["error_message"] = f"Need at least {min_lb} candles, found {len(scoped)}"
                j["compute_time_ms"] = int((time.time() - compute_start) * 1000)
                break
        _save("computation_jobs.json", jobs)
        _log("error", error_code="INSUFFICIENT_DATA")
        return _err("CONFLICT", "Insufficient OHLCV data to compute strategy", error_code="INSUFFICIENT_DATA", job_id=job_id)

    # Bollinger Bands: window=max(20,min_lb), k=2
    window = max(20, min_lb)
    tail = scoped[-window:] if len(scoped) >= window else scoped
    closes = [float(c.get("close")) for _, c in tail]
    ma = sum(closes) / len(closes)
    sd = statistics.pstdev(closes) if len(closes) > 1 else 0.0
    upper = ma + 2.0 * sd
    lower = ma - 2.0 * sd
    close_last = closes[-1]
    prev_close = closes[-2] if len(closes) >= 2 else closes[-1]

    # Signal: BUY if cross above lower from below; SELL if cross below upper from above; else HOLD
    if prev_close < lower and close_last >= lower:
        sig = 1
    elif prev_close > upper and close_last <= upper:
        sig = -1
    else:
        sig = 0

    as_of = tail[-1][1].get("close_time") or tail[-1][1].get("open_time")
    ttl = idef.get("cache_ttl_seconds", 0)
    expires_at = None
    if isinstance(ttl, int) and ttl > 0:
        expires_at = (datetime.datetime.now(datetime.timezone.utc) + datetime.timedelta(seconds=ttl)).isoformat()

    finished = _now_iso()

    # Dedup best-effort
    for j in jobs:
        if j.get("id") == job_id:
            continue
        if j.get("request_fingerprint") == fp and j.get("status") == "succeeded" and j.get("finished_at"):
            r = _find_result(j.get("id"))
            if r:
                exp = _dt_from_row(r.get("expires_at"))
                if exp is None or exp > now:
                    for jj in jobs:
                        if jj.get("id") == job_id:
                            jj["status"] = "cancelled"
                            jj["finished_at"] = finished
                            jj["updated_at"] = finished
                            jj["error_message"] = "Duplicate request; served from cache"
                            jj["compute_time_ms"] = int((time.time() - compute_start) * 1000)
                            break
                    _save("computation_jobs.json", jobs)
                    _log("ok")
                    return {
                        "tool": endpoint,
                        "symbol": symbol,
                        "interval": interval_eff,
                        "limit": limit_eff,
                        "start_time": fp_payload["start_time"],
                        "end_time": fp_payload["end_time"],
                        "cache_hit": True,
                        "job_id": j.get("id"),
                        "as_of_time": r.get("as_of_time"),
                        "signal": r.get("signal"),
                        "value": r.get("value"),
                        "result_kind": r.get("result_kind"),
                        "metadata": r.get("metadata"),
                    }

    res_id = f"res_{int(time.time()*1000)}_{len(results)+1}"
    created = _now_iso()
    results.append({
        "id": res_id,
        "job_id": job_id,
        "result_kind": "signal",
        "as_of_time": as_of,
        "value": float(sig),
        "signal": int(sig),
        "series": None,
        "multi_series": None,
        "metadata": {"window": window, "ma": ma, "sd": sd, "upper": upper, "lower": lower, "k": 2.0},
        "expires_at": expires_at,
        "created_at": created,
        "updated_at": created,
    })
    _save("computation_results.json", results)

    for j in jobs:
        if j.get("id") == job_id:
            j["status"] = "succeeded"
            j["finished_at"] = finished
            j["updated_at"] = finished
            j["compute_time_ms"] = int((time.time() - compute_start) * 1000)
            break
    _save("computation_jobs.json", jobs)

    _log("ok")
    return {
        "tool": endpoint,
        "symbol": symbol,
        "interval": interval_eff,
        "limit": limit_eff,
        "start_time": fp_payload["start_time"],
        "end_time": fp_payload["end_time"],
        "cache_hit": False,
        "job_id": job_id,
        "as_of_time": as_of,
        "signal": int(sig),
        "value": float(sig),
        "result_kind": "signal",
        "metadata": results[-1].get("metadata"),
    }

def calculate_projection_oscillator_strategy(symbol, interval=None, limit=None, start_time=None, end_time=None, use_cache=None, **_extra):
    import json, os, datetime, time, hashlib, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0416000" if __import__("os").path.isdir("./environment_mix/0416000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "calculate_projection_oscillator_strategy"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            raise ValueError(f"{field} must be an ISO 8601 string")
        try:
            s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            raise ValueError(f"{field} must be ISO 8601 date-time")

    def _log(status, credential_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
        })
        _save("request_logs.json", logs)

    if not isinstance(symbol, str) or not symbol.strip():
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "symbol must be a non-empty string", field="symbol")
    symbol = symbol.strip()

    allowed_intervals = ["1m","3m","5m","15m","30m","1h","2h","4h","6h","8h","12h","1d","3d","1w","1M"]
    if interval is not None and (not isinstance(interval, str) or interval not in allowed_intervals):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "interval must be one of the supported Binance intervals", field="interval")
    if limit is not None and (not isinstance(limit, int) or limit < 1):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer >= 1", field="limit")
    if use_cache is not None and not isinstance(use_cache, bool):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "use_cache must be a boolean", field="use_cache")
    try:
        st = _parse_dt(start_time, "start_time")
        et = _parse_dt(end_time, "end_time")
    except ValueError as e:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", str(e))
    if st is not None and et is not None and st > et:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "start_time must be <= end_time", field="start_time")

    defs = _load("indicator_definitions.json")
    idef = None
    for d in defs:
        if isinstance(d, dict) and d.get("tool_name") == endpoint:
            idef = d
            break
    if not idef:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Indicator definition not found for tool", tool_name=endpoint)
    if not idef.get("is_enabled", False) or idef.get("status") not in ("active", "deprecated"):
        _log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Tool is not enabled or not available", tool_name=endpoint)
    if idef.get("category") != "strategy":
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Indicator definition is not a strategy", tool_name=endpoint)

    interval_eff = interval if interval is not None else idef.get("default_interval")
    limit_eff = limit if limit is not None else idef.get("default_limit")
    min_lb = idef.get("min_lookback_candles")
    if interval_eff not in allowed_intervals:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Resolved interval is invalid", field="interval")
    if not isinstance(limit_eff, int) or limit_eff < 1:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Resolved limit is invalid", field="limit")
    if not isinstance(min_lb, int) or min_lb < 1:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Indicator definition has invalid min_lookback_candles")

    pairs = _load("trading_pairs.json")
    pair = None
    for p in pairs:
        if isinstance(p, dict) and p.get("exchange") == "binance" and p.get("symbol") == symbol:
            pair = p
            break
    if not pair:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Trading pair not found", symbol=symbol, exchange="binance")

    fp_payload = {
        "tool": endpoint,
        "indicator_id": idef.get("id"),
        "symbol": symbol,
        "pair_id": pair.get("id"),
        "interval": interval_eff,
        "limit": limit_eff,
        "start_time": st.isoformat() if st else None,
        "end_time": et.isoformat() if et else None,
    }
    fp = hashlib.sha256(json.dumps(fp_payload, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()

    jobs = _load("computation_jobs.json")
    results = _load("computation_results.json")

    def _dt_from_row(val):
        if val is None or not isinstance(val, str):
            return None
        try:
            s = val[:-1] + "+00:00" if val.endswith("Z") else val
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _find_result(job_id):
        for r in results:
            if isinstance(r, dict) and r.get("job_id") == job_id:
                return r
        return None

    now = datetime.datetime.now(datetime.timezone.utc)
    if use_cache:
        for j in jobs:
            if not isinstance(j, dict):
                continue
            if j.get("request_fingerprint") == fp and j.get("status") == "succeeded" and j.get("finished_at"):
                r = _find_result(j.get("id"))
                if not r:
                    continue
                exp = _dt_from_row(r.get("expires_at"))
                if exp is None or exp > now:
                    _log("ok")
                    return {
                        "tool": endpoint,
                        "symbol": symbol,
                        "interval": interval_eff,
                        "limit": limit_eff,
                        "start_time": fp_payload["start_time"],
