            "queued_at": ts,
            "started_at": ts,
            "finished_at": ts,
            "error_code": "PAIR_DISABLED",
            "error_message": "Trading pair is not active",
            "binance_request_count": 0,
            "compute_time_ms": 0,
            "created_at": ts,
            "updated_at": ts,
        })
        _save("computation_jobs.json", jobs)
        _log("error", error_code="PAIR_DISABLED")
        return _err("INVALID_TRANSITION", "Trading pair is not active for new computation jobs", error_code="PAIR_DISABLED", job_id=job_id)

    candles = _load("ohlcv_candles.json")
    scoped = []
    for c in candles:
        if not isinstance(c, dict):
            continue
        if c.get("pair_id") != pair.get("id") or c.get("interval") != interval_eff:
            continue
        ot = _dt_from_row(c.get("open_time"))
        if ot is None:
            continue
        if st is not None and ot < st:
            continue
        if et is not None and ot >= et:
            continue
        scoped.append((ot, c))
    scoped.sort(key=lambda x: x[0])
    if len(scoped) > limit_eff:
        scoped = scoped[-limit_eff:]

    job_id = f"job_{int(time.time()*1000)}_{len(jobs)+1}"
    queued_ts = _now_iso()
    jobs.append({
        "id": job_id,
        "indicator_id": idef.get("id"),
        "pair_id": pair.get("id"),
        "interval": interval_eff,
        "candle_limit": int(limit_eff),
        "input_start_time": fp_payload["start_time"],
        "input_end_time": fp_payload["end_time"],
        "request_fingerprint": fp,
        "cache_hit": False,
        "status": "queued",
        "queued_at": queued_ts,
        "started_at": None,
        "finished_at": None,
        "error_code": None,
        "error_message": None,
        "binance_request_count": 0,
        "compute_time_ms": None,
        "created_at": queued_ts,
        "updated_at": queued_ts,
    })
    _save("computation_jobs.json", jobs)

    # queued -> running
    started = _now_iso()
    for j in jobs:
        if j.get("id") == job_id:
            if j.get("status") != "queued":
                _log("error", error_code="INVALID_TRANSITION")
                return _err("INVALID_TRANSITION", "Job not in queued state")
            j["status"] = "running"
            j["started_at"] = started
            j["updated_at"] = started
            break
    _save("computation_jobs.json", jobs)

    compute_start = time.time()
    if len(scoped) < min_lb:
        finished = _now_iso()
        for j in jobs:
            if j.get("id") == job_id:
                j["status"] = "failed"
                j["finished_at"] = finished
                j["updated_at"] = finished
                j["error_code"] = "INSUFFICIENT_DATA"
                j["error_message"] = f"Need at least {min_lb} candles, found {len(scoped)}"
                j["compute_time_ms"] = int((time.time() - compute_start) * 1000)
                break
        _save("computation_jobs.json", jobs)
        _log("error", error_code="INSUFFICIENT_DATA")
        return _err("CONFLICT", "Insufficient OHLCV data to compute strategy", error_code="INSUFFICIENT_DATA", job_id=job_id)

    # Projection Oscillator simplified:
    # Over window=max(14,min_lb):
    # PPO = 100 * (close - min(low)) / (max(high)-min(low)) in window
    # Signal: BUY if PPO < 20 and rising; SELL if PPO > 80 and falling; else HOLD
    window = max(14, min_lb)
    tail = scoped[-window:] if len(scoped) >= window else scoped
    highs = [float(c.get("high")) for _, c in tail]
    lows = [float(c.get("low")) for _, c in tail]
    closes = [float(c.get("close")) for _, c in tail]
    hh = max(highs)
    ll = min(lows)
    denom = (hh - ll)
    if denom == 0:
        ppo = 50.0
    else:
        ppo = 100.0 * (closes[-1] - ll) / denom

    # Previous ppo using window-1 tail (if possible)
    if len(tail) >= 2:
        highs2 = highs[:-1]
        lows2 = lows[:-1]
        closes2 = closes[:-1]
        hh2 = max(highs2)
        ll2 = min(lows2)
        denom2 = (hh2 - ll2)
        ppo_prev = 50.0 if denom2 == 0 else 100.0 * (closes2[-1] - ll2) / denom2
    else:
        ppo_prev = ppo

    rising = ppo > ppo_prev
    falling = ppo < ppo_prev

    if ppo < 20.0 and rising:
        sig = 1
    elif ppo > 80.0 and falling:
        sig = -1
    else:
        sig = 0

    as_of = tail[-1][1].get("close_time") or tail[-1][1].get("open_time")
    ttl = idef.get("cache_ttl_seconds", 0)
    expires_at = None
    if isinstance(ttl, int) and ttl > 0:
        expires_at = (datetime.datetime.now(datetime.timezone.utc) + datetime.timedelta(seconds=ttl)).isoformat()

    finished = _now_iso()

    # Dedup best-effort
    for j in jobs:
        if j.get("id") == job_id:
            continue
        if j.get("request_fingerprint") == fp and j.get("status") == "succeeded" and j.get("finished_at"):
            r = _find_result(j.get("id"))
            if r:
                exp = _dt_from_row(r.get("expires_at"))
                if exp is None or exp > now:
                    for jj in jobs:
                        if jj.get("id") == job_id:
                            jj["status"] = "cancelled"
                            jj["finished_at"] = finished
                            jj["updated_at"] = finished
                            jj["error_message"] = "Duplicate request; served from cache"
                            jj["compute_time_ms"] = int((time.time() - compute_start) * 1000)
                            break
                    _save("computation_jobs.json", jobs)
                    _log("ok")
                    return {
                        "tool": endpoint,
                        "symbol": symbol,
                        "interval": interval_eff,
                        "limit": limit_eff,
                        "start_time": fp_payload["start_time"],
                        "end_time": fp_payload["end_time"],
                        "cache_hit": True,
                        "job_id": j.get("id"),
                        "as_of_time": r.get("as_of_time"),
                        "signal": r.get("signal"),
                        "value": r.get("value"),
                        "result_kind": r.get("result_kind"),
                        "metadata": r.get("metadata"),
                    }

    res_id = f"res_{int(time.time()*1000)}_{len(results)+1}"
    created = _now_iso()
    results.append({
        "id": res_id,
        "job_id": job_id,
        "result_kind": "signal",
        "as_of_time": as_of,
        "value": float(sig),
        "signal": int(sig),
        "series": None,
        "multi_series": None,
        "metadata": {"window": window, "ppo": ppo, "ppo_prev": ppo_prev, "thresholds": {"buy_lt": 20.0, "sell_gt": 80.0}},
        "expires_at": expires_at,
        "created_at": created,
        "updated_at": created,
    })
    _save("computation_results.json", results)

    for j in jobs:
        if j.get("id") == job_id:
            j["status"] = "succeeded"
            j["finished_at"] = finished
            j["updated_at"] = finished
            j["compute_time_ms"] = int((time.time() - compute_start) * 1000)
            break
    _save("computation_jobs.json", jobs)

    _log("ok")
    return {
        "tool": endpoint,
        "symbol": symbol,
        "interval": interval_eff,
        "limit": limit_eff,
        "start_time": fp_payload["start_time"],
        "end_time": fp_payload["end_time"],
        "cache_hit": False,
        "job_id": job_id,
        "as_of_time": as_of,
        "signal": int(sig),
        "value": float(sig),
        "result_kind": "signal",
        "metadata": results[-1].get("metadata"),
    }

