        st = _parse_dt(start_time, "start_time")
        if isinstance(st, tuple) and st and st[0] == "__bad__":
            _record_request("error")
            return st[1]
        et = _parse_dt(end_time, "end_time")
        if isinstance(et, tuple) and et and et[0] == "__bad__":
            _record_request("error")
            return et[1]
        if st is not None and et is not None and st > et:
            _record_request("error")
            return _err("VALIDATION_ERROR", "start_time must be <= end_time")

        # ---- Resolve indicator definition ----
        defs = _load("indicator_definitions.json")
        if not isinstance(defs, list):
            defs = []
        idef = None
        for d in defs:
            if isinstance(d, dict) and d.get("tool_name") == "calculate_chaikin_money_flow_strategy":
                idef = d
                break
        if idef is None:
            _record_request("error")
            return _err("NOT_FOUND", "Indicator definition not found for this tool")
        if not idef.get("is_enabled", False) or idef.get("status") not in ("active", "deprecated"):
            _record_request("error")
            return _err("INVALID_TRANSITION", "Tool is disabled")

        use_interval = interval if interval is not None else idef.get("default_interval")
        if use_interval not in allowed_intervals:
            _record_request("error")
            return _err("VALIDATION_ERROR", "Resolved interval is invalid")

        min_lookback = idef.get("min_lookback_candles")
        if not isinstance(min_lookback, int) or min_lookback < 1:
            _record_request("error")
            return _err("VALIDATION_ERROR", "Indicator definition misconfigured: min_lookback_candles invalid")

        resolved_limit = limit if limit is not None else idef.get("default_limit")
        if not isinstance(resolved_limit, int) or resolved_limit < 1:
            _record_request("error")
            return _err("VALIDATION_ERROR", "Resolved limit is invalid")
        candle_limit = max(resolved_limit, min_lookback)

        # ---- Resolve trading pair ----
        pairs = _load("trading_pairs.json")
        if not isinstance(pairs, list):
            pairs = []
        pair = None
        if pair_id is not None:
            for p in pairs:
                if isinstance(p, dict) and p.get("id") == pair_id:
                    pair = p
                    break
            if pair is None:
                _record_request("error")
                return _err("NOT_FOUND", "Trading pair not found", pair_id=pair_id)
        else:
            for p in pairs:
                if isinstance(p, dict) and p.get("exchange") == "binance" and str(p.get("symbol", "")).upper() == symbol_n:
                    pair = p
                    break
            if pair is None:
                _record_request("error")
                return _err("NOT_FOUND", "Trading pair not found for symbol", symbol=symbol_n, exchange="binance")

        if pair.get("status") != "active":
            # Must fail with error_code PAIR_DISABLED (via a failed job)
            pass

        # ---- Fingerprint & caching ----
        norm = {
            "tool": "calculate_chaikin_money_flow_strategy",
            "indicator_id": idef.get("id"),
            "pair_id": pair.get("id"),
            "interval": use_interval,
            "limit": candle_limit,
            "start_time": (st.isoformat() if st else None),
            "end_time": (et.isoformat() if et else None),
        }
        fp = hashlib.sha256(json.dumps(norm, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()

        jobs = _load("computation_jobs.json")
        if not isinstance(jobs, list):
            jobs = []
        results = _load("computation_results.json")
        if not isinstance(results, list):
            results = []

        def _find_result_by_job(job_id):
            for r in results:
                if isinstance(r, dict) and r.get("job_id") == job_id:
                    return r
            return None

        def _is_not_expired(res_row):
            if not isinstance(res_row, dict):
                return False
            exp = res_row.get("expires_at")
            if exp is None:
                return True
            if not isinstance(exp, str):
                return False
            px = _parse_dt(exp, "expires_at")
            if isinstance(px, tuple):
                return False
            return px >= datetime.datetime.now(datetime.timezone.utc)

        if not force_refresh:
            for j in jobs:
                if not isinstance(j, dict):
                    continue
                if j.get("request_fingerprint") == fp and j.get("status") == "succeeded" and j.get("finished_at") is not None:
                    r = _find_result_by_job(j.get("id"))
                    if r and _is_not_expired(r):
                        # Record a cache-hit job row for observability
                        now = _now_iso()
                        new_job_id = f"cijob_{int(time.time()*1000)}_{len(jobs)+1}"
                        job_row = {
                            "id": new_job_id,
                            "indicator_id": idef.get("id"),
                            "pair_id": pair.get("id"),
                            "interval": use_interval,
                            "candle_limit": candle_limit,
                            "input_start_time": (st.isoformat() if st else None),
                            "input_end_time": (et.isoformat() if et else None),
                            "request_fingerprint": fp,
                            "cache_hit": True,
                            "status": "succeeded",
                            "queued_at": now,
                            "started_at": now,
                            "finished_at": now,
                            "error_code": None,
                            "error_message": None,
                            "binance_request_count": 0,
                            "compute_time_ms": 0,
                            "created_at": now,
                            "updated_at": now,
                        }
                        jobs.append(job_row)
                        _save("computation_jobs.json", jobs)
                        _record_request("ok", {"cache_hit": True})
                        return {
                            "job": job_row,
                            "result": r,
                            "cached_from_job_id": j.get("id"),
                        }

        # ---- Create job (queued -> running) ----
        now = _now_iso()
        job_id = f"cijob_{int(time.time()*1000)}_{len(jobs)+1}"
        job_row = {
            "id": job_id,
            "indicator_id": idef.get("id"),
            "pair_id": pair.get("id"),
            "interval": use_interval,
            "candle_limit": candle_limit,
            "input_start_time": (st.isoformat() if st else None),
            "input_end_time": (et.isoformat() if et else None),
            "request_fingerprint": fp,
            "cache_hit": False,
            "status": "queued",
            "queued_at": now,
            "started_at": None,
            "finished_at": None,
            "error_code": None,
            "error_message": None,
            "binance_request_count": 0,
            "compute_time_ms": None,
            "created_at": now,
            "updated_at": now,
        }
        jobs.append(job_row)
        _save("computation_jobs.json", jobs)

        # Transition to running
        job_row["status"] = "running"
        job_row["started_at"] = _now_iso()
        job_row["updated_at"] = job_row["started_at"]
        _save("computation_jobs.json", jobs)

        # Pair status rule enforced for new jobs: fail the job
        if pair.get("status") != "active":
            fin = _now_iso()
            job_row["status"] = "failed"
            job_row["finished_at"] = fin
            job_row["updated_at"] = fin
            job_row["error_code"] = "PAIR_DISABLED"
            job_row["error_message"] = "Trading pair is not active"
            job_row["compute_time_ms"] = 0
            _save("computation_jobs.json", jobs)
            _record_request("error")
            return _err("INVALID_TRANSITION", "PAIR_DISABLED", job_id=job_id)

        # ---- Load & filter candles ----
        candles = _load("ohlcv_candles.json")
        if not isinstance(candles, list):
            candles = []
        scoped = []
        for c in candles:
            if not isinstance(c, dict):
                continue
            if c.get("pair_id") != pair.get("id") or c.get("interval") != use_interval:
                continue
            ot = c.get("open_time")
            if not isinstance(ot, str):
                continue
            dt_ot = _parse_dt(ot, "open_time")
            if isinstance(dt_ot, tuple):
                continue
            if st is not None and dt_ot < st:
                continue
            if et is not None and dt_ot > et:
                continue
            scoped.append((dt_ot, c))
        scoped.sort(key=lambda x: x[0])
        if candle_limit is not None:
            scoped = scoped[-candle_limit:]
        candle_rows = [c for _, c in scoped]

        if len(candle_rows) < min_lookback:
            fin = _now_iso()
            job_row["status"] = "failed"
            job_row["finished_at"] = fin
            job_row["updated_at"] = fin
            job_row["error_code"] = "INSUFFICIENT_DATA"
            job_row["error_message"] = f"Need at least {min_lookback} candles, found {len(candle_rows)}"
            job_row["compute_time_ms"] = 0
            _save("computation_jobs.json", jobs)
            _record_request("error")
            return _err("CONFLICT", "INSUFFICIENT_DATA", job_id=job_id, required=min_lookback, found=len(candle_rows))

        # ---- Compute CMF & signal ----
        # Default CMF window if not provided by definition: 20
        window = 20
        meta = {"window": window}

        def _to_float(x):
            try:
                return float(x)
            except Exception:
                return None

        def _cmf_last(crows, win):
            mfmv = []
            vols = []
            for c in crows:
                h = _to_float(c.get("high"))
                l = _to_float(c.get("low"))
                cl = _to_float(c.get("close"))
                v = _to_float(c.get("volume"))
                if h is None or l is None or cl is None or v is None:
                    return None
                den = (h - l)
                if den == 0:
                    mfm = 0.0
                else:
                    mfm = ((cl - l) - (h - cl)) / den
                mfmv.append(mfm * v)
                vols.append(v)
            if len(mfmv) < win:
                return None
            s_mfmv = sum(mfmv[-win:])
            s_vol = sum(vols[-win:])
            if s_vol == 0:
                return 0.0
            return s_mfmv / s_vol

        compute_start = time.time()
        cmf = _cmf_last(candle_rows, window)
        if cmf is None:
            fin = _now_iso()
            job_row["status"] = "failed"
            job_row["finished_at"] = fin
            job_row["updated_at"] = fin
            job_row["error_code"] = "INSUFFICIENT_DATA"
            job_row["error_message"] = f"Need at least {window} candles to compute CMF"
            job_row["compute_time_ms"] = int((time.time() - compute_start) * 1000)
            _save("computation_jobs.json", jobs)
            _record_request("error")
            return _err("CONFLICT", "INSUFFICIENT_DATA", job_id=job_id, required=window, found=len(candle_rows))

        # Strategy signal rule of thumb: buy if CMF > 0.05, sell if CMF < -0.05 else hold
        thr = 0.05
        if cmf > thr:
            sig = 1
        elif cmf < -thr:
            sig = -1
        else:
            sig = 0

        as_of_time = candle_rows[-1].get("close_time") or candle_rows[-1].get("open_time")
        if not isinstance(as_of_time, str):
            as_of_time = _now_iso()

        # ---- Persist succeeded job and result ----
        fin = _now_iso()
        job_row["status"] = "succeeded"
        job_row["finished_at"] = fin
        job_row["updated_at"] = fin
        job_row["error_code"] = None
        job_row["error_message"] = None
        job_row["binance_request_count"] = 0
        job_row["compute_time_ms"] = int((time.time() - compute_start) * 1000)
        _save("computation_jobs.json", jobs)

        # unique(job_id)
        for r in results:
            if isinstance(r, dict) and r.get("job_id") == job_id:
                _record_request("error")
                return _err("CONFLICT", "Computation result already exists for job_id", job_id=job_id)

        ttl = idef.get("cache_ttl_seconds")
        expires_at = None
        if isinstance(ttl, int) and ttl > 0:
            expires_at = (datetime.datetime.now(datetime.timezone.utc) + datetime.timedelta(seconds=ttl)).isoformat()

        res_id = f"cires_{int(time.time()*1000)}_{len(results)+1}"
        res_row = {
            "id": res_id,
            "job_id": job_id,
            "result_kind": "signal",
            "as_of_time": as_of_time,
            "value": float(sig),
            "signal": int(sig),
            "series": None,
            "multi_series": None,
            "metadata": {"indicator": "CMF", **meta, "threshold": thr},
            "expires_at": expires_at,
            "created_at": fin,
            "updated_at": fin,
        }
        results.append(res_row)
        _save("computation_results.json", results)

        _record_request("ok", {"cache_hit": False})
        return {"job": job_row, "result": res_row}
    except Exception as e:
        try:
            _record_request("error", {"exception": type(e).__name__})
        except Exception:
            pass
        return _err("CONFLICT", "Unexpected server error", detail=str(e))

