            _save("computation_jobs.json", jobs)
            _record_request("error")
            return _err("CONFLICT", "INSUFFICIENT_DATA", job_id=job_id, required=min_lookback, found=len(candle_rows))

        # EOM: ((midpoint - prev_midpoint) / (high-low)) * (volume scaling)
        # We'll compute last EOM (1-period) and a simple signal: buy if >0, sell if <0 else hold.
        def _to_float(x):
            try:
                return float(x)
            except Exception:
                return None

        compute_start = time.time()
        prev = candle_rows[-2] if len(candle_rows) >= 2 else None
        last = candle_rows[-1]
        if prev is None:
            fin = _now_iso()
            job_row["status"] = "failed"
            job_row["finished_at"] = fin
            job_row["updated_at"] = fin
            job_row["error_code"] = "INSUFFICIENT_DATA"
            job_row["error_message"] = "Need at least 2 candles to compute EOM"
            job_row["compute_time_ms"] = int((time.time() - compute_start) * 1000)
            _save("computation_jobs.json", jobs)
            _record_request("error")
            return _err("CONFLICT", "INSUFFICIENT_DATA", job_id=job_id, required=2, found=len(candle_rows))

        h0 = _to_float(prev.get("high")); l0 = _to_float(prev.get("low"))
        h1 = _to_float(last.get("high")); l1 = _to_float(last.get("low"))
        v1 = _to_float(last.get("volume"))
        if None in (h0, l0, h1, l1, v1):
            fin = _now_iso()
            job_row["status"] = "failed"
            job_row["finished_at"] = fin
            job_row["updated_at"] = fin
            job_row["error_code"] = "INVALID_DATA"
            job_row["error_message"] = "Candle data missing numeric fields"
            job_row["compute_time_ms"] = int((time.time() - compute_start) * 1000)
            _save("computation_jobs.json", jobs)
            _record_request("error")
            return _err("CONFLICT", "INVALID_DATA", job_id=job_id)

        mid0 = (h0 + l0) / 2.0
        mid1 = (h1 + l1) / 2.0
        box = (h1 - l1)
        if box == 0:
            eom = 0.0
        else:
            # scale volume to avoid huge magnitudes; typical EOM uses volume/(high-low), sometimes /1e8
            eom = (mid1 - mid0) * (box / max(v1, 1e-12))

        if eom > 0:
            sig = 1
        elif eom < 0:
            sig = -1
        else:
            sig = 0

        as_of_time = last.get("close_time") or last.get("open_time")
        if not isinstance(as_of_time, str):
            as_of_time = _now_iso()

        fin = _now_iso()
        job_row["status"] = "succeeded"
        job_row["finished_at"] = fin
        job_row["updated_at"] = fin
        job_row["compute_time_ms"] = int((time.time() - compute_start) * 1000)
        _save("computation_jobs.json", jobs)

        ttl = idef.get("cache_ttl_seconds")
        expires_at = None
        if isinstance(ttl, int) and ttl > 0:
            expires_at = (datetime.datetime.now(datetime.timezone.utc) + datetime.timedelta(seconds=ttl)).isoformat()

        res_id = f"cires_{int(time.time()*1000)}_{len(results)+1}"
        res_row = {
            "id": res_id,
            "job_id": job_id,
            "result_kind": "signal",
            "as_of_time": as_of_time,
            "value": float(sig),
            "signal": int(sig),
            "series": None,
            "multi_series": None,
            "metadata": {"indicator": "EOM", "eom_last": eom},
            "expires_at": expires_at,
            "created_at": fin,
            "updated_at": fin,
        }
        results.append(res_row)
        _save("computation_results.json", results)

        _record_request("ok", {"cache_hit": False})
        return {"job": job_row, "result": res_row}
    except Exception as e:
        try:
            _record_request("error", {"exception": type(e).__name__})
        except Exception:
            pass
        return _err("CONFLICT", "Unexpected server error", detail=str(e))

def calculate_force_index_strategy(symbol, interval=None, limit=None, start_time=None, end_time=None, pair_id=None, force_refresh=None, **_extra):
    import json, os, datetime, time, re, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0416000" if __import__("os").path.isdir("./environment_mix/0416000") else "/app/database")
    def _load(n):
