                _record_request("error")
                return _err("NOT_FOUND", "Trading pair not found", pair_id=pair_id)
        else:
            for p in pairs:
                if isinstance(p, dict) and p.get("exchange") == "binance" and str(p.get("symbol", "")).upper() == symbol_n:
                    pair = p
                    break
            if pair is None:
                _record_request("error")
                return _err("NOT_FOUND", "Trading pair not found for symbol", symbol=symbol_n, exchange="binance")

        norm = {
            "tool": "calculate_money_flow_index_strategy",
            "indicator_id": idef.get("id"),
            "pair_id": pair.get("id"),
            "interval": use_interval,
            "limit": candle_limit,
            "start_time": (st.isoformat() if st else None),
            "end_time": (et.isoformat() if et else None),
        }
        fp = hashlib.sha256(json.dumps(norm, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()

        jobs = _load("computation_jobs.json")
        if not isinstance(jobs, list):
            jobs = []
        results = _load("computation_results.json")
        if not isinstance(results, list):
            results = []

        def _find_result_by_job(job_id):
            for r in results:
                if isinstance(r, dict) and r.get("job_id") == job_id:
                    return r
            return None

        def _is_not_expired(res_row):
            exp = res_row.get("expires_at")
            if exp is None:
                return True
            if not isinstance(exp, str):
                return False
            px = _parse_dt(exp, "expires_at")
            if isinstance(px, tuple):
                return False
            return px >= datetime.datetime.now(datetime.timezone.utc)

        if not force_refresh:
            for j in jobs:
                if not isinstance(j, dict):
                    continue
                if j.get("request_fingerprint") == fp and j.get("status") == "succeeded" and j.get("finished_at") is not None:
                    r = _find_result_by_job(j.get("id"))
                    if r and _is_not_expired(r):
                        now = _now_iso()
                        new_job_id = f"cijob_{int(time.time()*1000)}_{len(jobs)+1}"
                        job_row = {
                            "id": new_job_id,
                            "indicator_id": idef.get("id"),
                            "pair_id": pair.get("id"),
                            "interval": use_interval,
                            "candle_limit": candle_limit,
                            "input_start_time": (st.isoformat() if st else None),
                            "input_end_time": (et.isoformat() if et else None),
                            "request_fingerprint": fp,
                            "cache_hit": True,
                            "status": "succeeded",
                            "queued_at": now,
                            "started_at": now,
                            "finished_at": now,
                            "error_code": None,
                            "error_message": None,
                            "binance_request_count": 0,
                            "compute_time_ms": 0,
                            "created_at": now,
                            "updated_at": now,
                        }
                        jobs.append(job_row)
                        _save("computation_jobs.json", jobs)
                        _record_request("ok", {"cache_hit": True})
                        return {"job": job_row, "result": r, "cached_from_job_id": j.get("id")}

        now = _now_iso()
        job_id = f"cijob_{int(time.time()*1000)}_{len(jobs)+1}"
        job_row = {
            "id": job_id,
            "indicator_id": idef.get("id"),
            "pair_id": pair.get("id"),
            "interval": use_interval,
            "candle_limit": candle_limit,
            "input_start_time": (st.isoformat() if st else None),
            "input_end_time": (et.isoformat() if et else None),
            "request_fingerprint": fp,
            "cache_hit": False,
            "status": "queued",
            "queued_at": now,
            "started_at": None,
            "finished_at": None,
            "error_code": None,
            "error_message": None,
            "binance_request_count": 0,
            "compute_time_ms": None,
            "created_at": now,
            "updated_at": now,
        }
        jobs.append(job_row)
        _save("computation_jobs.json", jobs)

        job_row["status"] = "running"
        job_row["started_at"] = _now_iso()
        job_row["updated_at"] = job_row["started_at"]
        _save("computation_jobs.json", jobs)

        if pair.get("status") != "active":
            fin = _now_iso()
            job_row["status"] = "failed"
            job_row["finished_at"] = fin
            job_row["updated_at"] = fin
            job_row["error_code"] = "PAIR_DISABLED"
            job_row["error_message"] = "Trading pair is not active"
            job_row["compute_time_ms"] = 0
            _save("computation_jobs.json", jobs)
            _record_request("error")
            return _err("INVALID_TRANSITION", "PAIR_DISABLED", job_id=job_id)

        candles = _load("ohlcv_candles.json")
        if not isinstance(candles, list):
            candles = []
        scoped = []
        for c in candles:
            if not isinstance(c, dict):
                continue
            if c.get("pair_id") != pair.get("id") or c.get("interval") != use_interval:
                continue
            ot = c.get("open_time")
            if not isinstance(ot, str):
                continue
            dt_ot = _parse_dt(ot, "open_time")
            if isinstance(dt_ot, tuple):
                continue
            if st is not None and dt_ot < st:
                continue
            if et is not None and dt_ot > et:
                continue
            scoped.append((dt_ot, c))
        scoped.sort(key=lambda x: x[0])
        scoped = scoped[-candle_limit:]
        candle_rows = [c for _, c in scoped]

        if len(candle_rows) < min_lookback:
            fin = _now_iso()
            job_row["status"] = "failed"
            job_row["finished_at"] = fin
            job_row["updated_at"] = fin
            job_row["error_code"] = "INSUFFICIENT_DATA"
            job_row["error_message"] = f"Need at least {min_lookback} candles, found {len(candle_rows)}"
            job_row["compute_time_ms"] = 0
            _save("computation_jobs.json", jobs)
            _record_request("error")
            return _err("CONFLICT", "INSUFFICIENT_DATA", job_id=job_id, required=min_lookback, found=len(candle_rows))

        # MFI window default 14
        window = 14

        def _to_float(x):
            try:
                return float(x)
            except Exception:
                return None

        compute_start = time.time()

        if len(candle_rows) < window + 1:
            fin = _now_iso()
            job_row["status"] = "failed"
            job_row["finished_at"] = fin
            job_row["updated_at"] = fin
            job_row["error_code"] = "INSUFFICIENT_DATA"
            job_row["error_message"] = f"Need at least {window+1} candles to compute MFI"
            job_row["compute_time_ms"] = int((time.time() - compute_start) * 1000)
            _save("computation_jobs.json", jobs)
            _record_request("error")
            return _err("CONFLICT", "INSUFFICIENT_DATA", job_id=job_id, required=window+1, found=len(candle_rows))

        # Compute typical price and raw money flow
        tps = []
        rms = []
        for c in candle_rows:
            h = _to_float(c.get("high")); l = _to_float(c.get("low")); cl = _to_float(c.get("close"))
            v = _to_float(c.get("volume"))
            if None in (h, l, cl, v):
                fin = _now_iso()
                job_row["status"] = "failed"
                job_row["finished_at"] = fin
                job_row["updated_at"] = fin
                job_row["error_code"] = "INVALID_DATA"
                job_row["error_message"] = "Candle data missing numeric fields"
                job_row["compute_time_ms"] = int((time.time() - compute_start) * 1000)
                _save("computation_jobs.json", jobs)
                _record_request("error")
                return _err("CONFLICT", "INVALID_DATA", job_id=job_id)
            tp = (h + l + cl) / 3.0
            tps.append(tp)
            rms.append(tp * v)

        pos = 0.0
        neg = 0.0
        # Use last window transitions
        start_idx = len(candle_rows) - window
        for i in range(start_idx, len(candle_rows)):
            if i == 0:
                continue
            if tps[i] > tps[i - 1]:
                pos += rms[i]
            elif tps[i] < tps[i - 1]:
                neg += rms[i]
            else:
                pass

        if neg == 0 and pos == 0:
            mfi = 50.0
        elif neg == 0:
            mfi = 100.0
        else:
            mr = pos / neg
            mfi = 100.0 - (100.0 / (1.0 + mr))

        # Strategy: sell if MFI > 80, buy if MFI < 20 else hold
        if mfi < 20:
            sig = 1
        elif mfi > 80:
            sig = -1
        else:
            sig = 0

        last = candle_rows[-1]
        as_of_time = last.get("close_time") or last.get("open_time")
        if not isinstance(as_of_time, str):
            as_of_time = _now_iso()

        fin = _now_iso()
        job_row["status"] = "succeeded"
        job_row["finished_at"] = fin
        job_row["updated_at"] = fin
        job_row["compute_time_ms"] = int((time.time() - compute_start) * 1000)
        _save("computation_jobs.json", jobs)

        ttl = idef.get("cache_ttl_seconds")
        expires_at = None
        if isinstance(ttl, int) and ttl > 0:
            expires_at = (datetime.datetime.now(datetime.timezone.utc) + datetime.timedelta(seconds=ttl)).isoformat()

        res_id = f"cires_{int(time.time()*1000)}_{len(results)+1}"
        res_row = {
            "id": res_id,
            "job_id": job_id,
            "result_kind": "signal",
            "as_of_time": as_of_time,
            "value": float(sig),
            "signal": int(sig),
            "series": None,
            "multi_series": None,
            "metadata": {"indicator": "MFI", "window": window, "mfi_last": mfi, "buy_below": 20, "sell_above": 80},
            "expires_at": expires_at,
            "created_at": fin,
            "updated_at": fin,
        }
        results.append(res_row)
        _save("computation_results.json", results)

        _record_request("ok", {"cache_hit": False})
        return {"job": job_row, "result": res_row}
    except Exception as e:
        try:
            _record_request("error", {"exception": type(e).__name__})
        except Exception:
            pass
        return _err("CONFLICT", "Unexpected server error", detail=str(e))

def calculate_negative_volume_index_strategy(symbol, interval=None, limit=None, start_time=None, end_time=None, pair_id=None, force_refresh=None, **_extra):
    import json, os, datetime, time, hashlib, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0416000" if __import__("os").path.isdir("./environment_mix/0416000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _ensure_logs():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            try:
                _save("request_logs.json", [])
            except Exception:
                pass

    def _log(endpoint, status, credential_id=None, meta=None):
        _ensure_logs()
        logs = _load("request_logs.json")
        latency_ms = int((time.time() - t0) * 1000)
        row = {
            "id": "req_" + hashlib.sha256((endpoint + "|" + now + "|" + str(time.time())).encode("utf-8")).hexdigest()[:24],
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "latency_ms": latency_ms,
            "ts": datetime.datetime.now(datetime.timezone.utc).isoformat(),
        }
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        try:
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _auth_any():
        # Ambient authentication: accept if any credential exists; else treat as unauthenticated.
        creds = _load("api_keys.json")
        if isinstance(creds, list) and creds:
            return creds[0]
        return None

    def _validate():
        if not isinstance(symbol, str) or not symbol.strip():
            return _err("VALIDATION_ERROR", "symbol must be a non-empty string")
        if interval is not None:
            if not isinstance(interval, str):
                return _err("VALIDATION_ERROR", "interval must be a string")
            if interval not in ["1m","3m","5m","15m","30m","1h","2h","4h","6h","8h","12h","1d","3d","1w","1M"]:
                return _err("VALIDATION_ERROR", "invalid interval")
        if limit is not None:
            if not isinstance(limit, int) or limit < 1:
                return _err("VALIDATION_ERROR", "limit must be an integer >= 1")
        if start_time is not None:
            dt = _parse_dt(start_time)
            if dt is None:
                return _err("VALIDATION_ERROR", "start_time must be ISO 8601 date-time")
        if end_time is not None:
            dt = _parse_dt(end_time)
            if dt is None:
                return _err("VALIDATION_ERROR", "end_time must be ISO 8601 date-time")
        if start_time is not None and end_time is not None:
            a = _parse_dt(start_time); b = _parse_dt(end_time)
            if a is not None and b is not None and a > b:
                return _err("VALIDATION_ERROR", "start_time must be <= end_time")
        if pair_id is not None:
            if not isinstance(pair_id, str) or not re.match(r"^cipair_[0-9A-Z]{18,}$", pair_id):
                return _err("VALIDATION_ERROR", "pair_id has invalid format")
        if force_refresh is not None and not isinstance(force_refresh, bool):
            return _err("VALIDATION_ERROR", "force_refresh must be a boolean")
        return None

    v = _validate()
    if v:
        _log("calculate_negative_volume_index_strategy", "error", meta={"code": v["error"]["code"]})
        return v

    cred = _auth_any()
    if cred is None:
        e = _err("UNAUTHORIZED", "No authenticated context available")
        _log("calculate_negative_volume_index_strategy", "error", meta={"code": e["error"]["code"]})
        return e

    defs = _load("indicator_definitions.json")
    idef = None
    for d in defs:
        if d.get("tool_name") == "calculate_negative_volume_index_strategy":
            idef = d
            break
    if not idef:
        e = _err("NOT_FOUND", "Indicator definition not found")
        _log("calculate_negative_volume_index_strategy", "error", cred.get("id"), meta={"code": e["error"]["code"]})
        return e
    if not idef.get("is_enabled", False) or idef.get("status") not in ("active", "deprecated"):
        e = _err("CONFLICT", "Tool is disabled")
        _log("calculate_negative_volume_index_strategy", "error", cred.get("id"), meta={"code": e["error"]["code"]})
        return e

    pairs = _load("trading_pairs.json")
    pair = None
    if pair_id:
        for p in pairs:
            if p.get("id") == pair_id:
                pair = p
                break
        if not pair:
            e = _err("NOT_FOUND", "Trading pair not found")
            _log("calculate_negative_volume_index_strategy", "error", cred.get("id"), meta={"code": e["error"]["code"]})
            return e
    else:
        sym = symbol.strip().upper()
        for p in pairs:
            if p.get("exchange") == "binance" and (p.get("symbol") or "").upper() == sym:
                pair = p
                break
        if not pair:
            e = _err("NOT_FOUND", "Trading pair not found for symbol")
            _log("calculate_negative_volume_index_strategy", "error", cred.get("id"), meta={"code": e["error"]["code"]})
            return e

    if pair.get("status") != "active":
        # Must fail job with PAIR_DISABLED
        jobs = _load("computation_jobs.json")
        jid = "cijob_" + hashlib.sha256((pair["id"] + "|nvi|" + now + "|" + str(time.time())).encode("utf-8")).hexdigest()[:24].upper()
        fp = hashlib.sha256((idef["id"] + "|" + pair["id"] + "|" + str(interval or idef.get("default_interval")) + "|" + str(limit or idef.get("default_limit")) + "|" + str(start_time) + "|" + str(end_time)).encode("utf-8")).hexdigest()
        job = {
            "id": jid,
            "indicator_id": idef["id"],
            "pair_id": pair["id"],
            "interval": interval or idef.get("default_interval"),
            "candle_limit": int(limit or idef.get("default_limit")),
            "input_start_time": start_time,
            "input_end_time": end_time,
            "request_fingerprint": fp,
            "cache_hit": False,
            "status": "failed",
            "queued_at": now,
            "started_at": now,
            "finished_at": now,
            "error_code": "PAIR_DISABLED",
            "error_message": "Trading pair is not active",
            "binance_request_count": 0,
            "compute_time_ms": 0,
            "created_at": now,
            "updated_at": now,
        }
        jobs.append(job)
        try:
            _save("computation_jobs.json", jobs)
        except Exception:
            pass
        out = {
            "job": job,
            "result": None
        }
        _log("calculate_negative_volume_index_strategy", "ok", cred.get("id"), meta={"cache_hit": False, "status": "failed"})
        return out

    use_interval = interval or idef.get("default_interval")
    use_limit = int(limit or idef.get("default_limit"))
    start_dt = _parse_dt(start_time)
    end_dt = _parse_dt(end_time)

    # Fingerprint for caching
    fp_payload = {
        "tool": "calculate_negative_volume_index_strategy",
        "indicator_id": idef.get("id"),
        "pair_id": pair.get("id"),
        "interval": use_interval,
        "limit": use_limit,
        "start_time": start_dt.isoformat() if start_dt else None,
        "end_time": end_dt.isoformat() if end_dt else None,
    }
    fp = hashlib.sha256(json.dumps(fp_payload, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()

    jobs = _load("computation_jobs.json")
    results = _load("computation_results.json")

    def _dt_from_row(v):
        if isinstance(v, str):
            return _parse_dt(v)
        return None

    def _find_cached():
        if force_refresh:
            return None, None
        # Find succeeded job with same fingerprint and valid result expiry
        for j in jobs:
            if j.get("request_fingerprint") == fp and j.get("status") == "succeeded" and j.get("finished_at"):
                r = None
                for rr in results:
                    if rr.get("job_id") == j.get("id"):
                        r = rr
                        break
                if not r:
                    continue
                exp = _dt_from_row(r.get("expires_at")) if r.get("expires_at") else None
                if exp is None or exp >= datetime.datetime.now(datetime.timezone.utc):
                    return j, r
        return None, None

    cached_job, cached_res = _find_cached()
    if cached_job and cached_res:
        # mark a new job? Real API would likely not create a new job; return cached result and set cache_hit true on existing job is immutable.
        out = {
            "job": cached_job,
            "result": cached_res,
            "cache": {"hit": True}
        }
        _log("calculate_negative_volume_index_strategy", "ok", cred.get("id"), meta={"cache_hit": True})
        return out

    # Create a new job (queued -> running -> terminal)
    jid = "cijob_" + hashlib.sha256((pair["id"] + "|nvi|" + now + "|" + str(time.time())).encode("utf-8")).hexdigest()[:24].upper()
    job = {
        "id": jid,
        "indicator_id": idef["id"],
        "pair_id": pair["id"],
        "interval": use_interval,
        "candle_limit": use_limit,
        "input_start_time": start_dt.isoformat() if start_dt else None,
        "input_end_time": end_dt.isoformat() if end_dt else None,
        "request_fingerprint": fp,
        "cache_hit": False,
        "status": "queued",
        "queued_at": now,
        "started_at": None,
        "finished_at": None,
        "error_code": None,
        "error_message": None,
        "binance_request_count": 0,
        "compute_time_ms": None,
        "created_at": now,
        "updated_at": now,
    }
    jobs.append(job)
    try:
        _save("computation_jobs.json", jobs)
    except Exception:
        pass

    # Transition queued -> running
    job["status"] = "running"
    job["started_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
    job["updated_at"] = job["started_at"]
    for i in range(len(jobs)):
        if jobs[i].get("id") == jid:
            jobs[i] = job
            break
    try:
        _save("computation_jobs.json", jobs)
    except Exception:
        pass

    # Select candles
    candles = _load("ohlcv_candles.json")
    scoped = []
    for c in candles:
        if c.get("pair_id") != pair["id"] or c.get("interval") != use_interval:
            continue
        ot = _parse_dt(c.get("open_time")) if isinstance(c.get("open_time"), str) else None
        if ot is None:
            continue
        if start_dt and ot < start_dt:
            continue
        if end_dt and ot > end_dt:
            continue
        scoped.append((ot, c))
    scoped.sort(key=lambda x: x[0])
    if use_limit is not None and len(scoped) > use_limit:
        scoped = scoped[-use_limit:]
    candle_rows = [c for _, c in scoped]

    min_req = int(idef.get("min_lookback_candles") or 1)
    if len(candle_rows) < min_req:
        fin = datetime.datetime.now(datetime.timezone.utc).isoformat()
        job["status"] = "failed"
        job["finished_at"] = fin
        job["updated_at"] = fin
        job["compute_time_ms"] = 0
        job["error_code"] = "INSUFFICIENT_DATA"
        job["error_message"] = f"Need at least {min_req} candles, found {len(candle_rows)}"
        for i in range(len(jobs)):
            if jobs[i].get("id") == jid:
                jobs[i] = job
                break
        try:
            _save("computation_jobs.json", jobs)
        except Exception:
            pass
        out = {"job": job, "result": None}
        _log("calculate_negative_volume_index_strategy", "ok", cred.get("id"), meta={"cache_hit": False, "status": "failed", "error_code": "INSUFFICIENT_DATA"})
        return out

    # Compute NVI (classic): start at 1000, update only when volume decreases.
    ct0 = time.time()
    nvi = 1000.0
    prev_close = float(candle_rows[0]["close"])
    prev_vol = float(candle_rows[0]["volume"])
    for c in candle_rows[1:]:
        close = float(c["close"])
        vol = float(c["volume"])
        if vol < prev_vol and prev_close != 0:
            nvi = nvi + (close - prev_close) / prev_close * nvi
        prev_close = close
        prev_vol = vol

    last_close = float(candle_rows[-1]["close"])
    # Simple signal heuristic: BUY if price above NVI (bullish), SELL if below, else HOLD
    if last_close > nvi:
        sig = 1
    elif last_close < nvi:
        sig = -1
    else:
        sig = 0

    compute_ms = int((time.time() - ct0) * 1000)
    fin = datetime.datetime.now(datetime.timezone.utc).isoformat()
    job["status"] = "succeeded"
    job["finished_at"] = fin
    job["updated_at"] = fin
    job["compute_time_ms"] = compute_ms
    job["binance_request_count"] = 0
    job["error_code"] = None
    job["error_message"] = None

    # persist job update
    for i in range(len(jobs)):
        if jobs[i].get("id") == jid:
            jobs[i] = job
            break
    try:
        _save("computation_jobs.json", jobs)
    except Exception:
        pass

    # upsert result unique(job_id)
    ttl = int(idef.get("cache_ttl_seconds") or 0)
    created_at = fin
    expires_at = None
    if ttl > 0:
        expires_at = (datetime.datetime.now(datetime.timezone.utc) + datetime.timedelta(seconds=ttl)).isoformat()

    rid = "cires_" + hashlib.sha256((jid + "|result|" + fin).encode("utf-8")).hexdigest()[:24].upper()
    result_row = {
        "id": rid,
        "job_id": jid,
        "result_kind": "signal",
        "as_of_time": candle_rows[-1].get("close_time") or candle_rows[-1].get("open_time"),
        "value": float(sig),
        "signal": int(sig),
        "series": None,
        "multi_series": None,
        "metadata": {
            "nvi": nvi,
            "last_close": last_close,
            "interval": use_interval,
            "candles_used": len(candle_rows)
        },
        "expires_at": expires_at,
        "created_at": created_at,
        "updated_at": created_at
    }
    replaced = False
    for i in range(len(results)):
        if results[i].get("job_id") == jid:
            results[i] = result_row
            replaced = True
            break
    if not replaced:
        results.append(result_row)
    try:
        _save("computation_results.json", results)
    except Exception:
        pass

    out = {"job": job, "result": result_row, "cache": {"hit": False}}
    _log("calculate_negative_volume_index_strategy", "ok", cred.get("id"), meta={"cache_hit": False})
    return out

def calculate_volume_weighted_average_price_strategy(symbol, interval=None, limit=None, start_time=None, end_time=None, pair_id=None, force_refresh=None, **_extra):
    import json, os, datetime, time, hashlib, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0416000" if __import__("os").path.isdir("./environment_mix/0416000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _ensure_logs():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            try:
                _save("request_logs.json", [])
            except Exception:
                pass

    def _log(endpoint, status, credential_id=None, meta=None):
        _ensure_logs()
        logs = _load("request_logs.json")
        latency_ms = int((time.time() - t0) * 1000)
        row = {
            "id": "req_" + hashlib.sha256((endpoint + "|" + now + "|" + str(time.time())).encode("utf-8")).hexdigest()[:24],
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "latency_ms": latency_ms,
            "ts": datetime.datetime.now(datetime.timezone.utc).isoformat(),
        }
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        try:
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _auth_any():
        creds = _load("api_keys.json")
        if isinstance(creds, list) and creds:
            return creds[0]
        return None

    def _validate():
        if not isinstance(symbol, str) or not symbol.strip():
            return _err("VALIDATION_ERROR", "symbol must be a non-empty string")
        if interval is not None:
            if not isinstance(interval, str):
                return _err("VALIDATION_ERROR", "interval must be a string")
            if interval not in ["1m","3m","5m","15m","30m","1h","2h","4h","6h","8h","12h","1d","3d","1w","1M"]:
                return _err("VALIDATION_ERROR", "invalid interval")
        if limit is not None:
            if not isinstance(limit, int) or limit < 1:
                return _err("VALIDATION_ERROR", "limit must be an integer >= 1")
        if start_time is not None:
            dt = _parse_dt(start_time)
            if dt is None:
                return _err("VALIDATION_ERROR", "start_time must be ISO 8601 date-time")
        if end_time is not None:
            dt = _parse_dt(end_time)
            if dt is None:
                return _err("VALIDATION_ERROR", "end_time must be ISO 8601 date-time")
        if start_time is not None and end_time is not None:
            a = _parse_dt(start_time); b = _parse_dt(end_time)
            if a is not None and b is not None and a > b:
                return _err("VALIDATION_ERROR", "start_time must be <= end_time")
        if pair_id is not None:
            if not isinstance(pair_id, str) or not re.match(r"^cipair_[0-9A-Z]{18,}$", pair_id):
                return _err("VALIDATION_ERROR", "pair_id has invalid format")
        if force_refresh is not None and not isinstance(force_refresh, bool):
            return _err("VALIDATION_ERROR", "force_refresh must be a boolean")
        return None

    v = _validate()
    if v:
        _log("calculate_volume_weighted_average_price_strategy", "error", meta={"code": v["error"]["code"]})
        return v

    cred = _auth_any()
    if cred is None:
        e = _err("UNAUTHORIZED", "No authenticated context available")
        _log("calculate_volume_weighted_average_price_strategy", "error", meta={"code": e["error"]["code"]})
        return e

    defs = _load("indicator_definitions.json")
    idef = None
    for d in defs:
        if d.get("tool_name") == "calculate_volume_weighted_average_price_strategy":
            idef = d
            break
    if not idef:
        e = _err("NOT_FOUND", "Indicator definition not found")
        _log("calculate_volume_weighted_average_price_strategy", "error", cred.get("id"), meta={"code": e["error"]["code"]})
        return e
    if not idef.get("is_enabled", False) or idef.get("status") not in ("active", "deprecated"):
        e = _err("CONFLICT", "Tool is disabled")
        _log("calculate_volume_weighted_average_price_strategy", "error", cred.get("id"), meta={"code": e["error"]["code"]})
        return e

    pairs = _load("trading_pairs.json")
    pair = None
    if pair_id:
        for p in pairs:
            if p.get("id") == pair_id:
                pair = p
                break
        if not pair:
            e = _err("NOT_FOUND", "Trading pair not found")
            _log("calculate_volume_weighted_average_price_strategy", "error", cred.get("id"), meta={"code": e["error"]["code"]})
            return e
    else:
        sym = symbol.strip().upper()
        for p in pairs:
            if p.get("exchange") == "binance" and (p.get("symbol") or "").upper() == sym:
                pair = p
                break
        if not pair:
            e = _err("NOT_FOUND", "Trading pair not found for symbol")
            _log("calculate_volume_weighted_average_price_strategy", "error", cred.get("id"), meta={"code": e["error"]["code"]})
            return e

    if pair.get("status") != "active":
        jobs = _load("computation_jobs.json")
        jid = "cijob_" + hashlib.sha256((pair["id"] + "|vwap|" + now + "|" + str(time.time())).encode("utf-8")).hexdigest()[:24].upper()
        fp = hashlib.sha256((idef["id"] + "|" + pair["id"] + "|" + str(interval or idef.get("default_interval")) + "|" + str(limit or idef.get("default_limit")) + "|" + str(start_time) + "|" + str(end_time)).encode("utf-8")).hexdigest()
        job = {
            "id": jid,
            "indicator_id": idef["id"],
            "pair_id": pair["id"],
            "interval": interval or idef.get("default_interval"),
            "candle_limit": int(limit or idef.get("default_limit")),
            "input_start_time": start_time,
            "input_end_time": end_time,
            "request_fingerprint": fp,
            "cache_hit": False,
            "status": "failed",
            "queued_at": now,
            "started_at": now,
            "finished_at": now,
            "error_code": "PAIR_DISABLED",
            "error_message": "Trading pair is not active",
            "binance_request_count": 0,
            "compute_time_ms": 0,
            "created_at": now,
            "updated_at": now,
        }
        jobs.append(job)
        try:
            _save("computation_jobs.json", jobs)
        except Exception:
            pass
        out = {"job": job, "result": None}
        _log("calculate_volume_weighted_average_price_strategy", "ok", cred.get("id"), meta={"cache_hit": False, "status": "failed"})
        return out

    use_interval = interval or idef.get("default_interval")
    use_limit = int(limit or idef.get("default_limit"))
    start_dt = _parse_dt(start_time)
    end_dt = _parse_dt(end_time)

    fp_payload = {
        "tool": "calculate_volume_weighted_average_price_strategy",
        "indicator_id": idef.get("id"),
        "pair_id": pair.get("id"),
        "interval": use_interval,
        "limit": use_limit,
        "start_time": start_dt.isoformat() if start_dt else None,
        "end_time": end_dt.isoformat() if end_dt else None,
    }
    fp = hashlib.sha256(json.dumps(fp_payload, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()

    jobs = _load("computation_jobs.json")
    results = _load("computation_results.json")

    def _dt_from_row(v):
        if isinstance(v, str):
            return _parse_dt(v)
        return None

    def _find_cached():
        if force_refresh:
            return None, None
        for j in jobs:
            if j.get("request_fingerprint") == fp and j.get("status") == "succeeded" and j.get("finished_at"):
                r = None
                for rr in results:
                    if rr.get("job_id") == j.get("id"):
                        r = rr
                        break
                if not r:
                    continue
                exp = _dt_from_row(r.get("expires_at")) if r.get("expires_at") else None
                if exp is None or exp >= datetime.datetime.now(datetime.timezone.utc):
                    return j, r
        return None, None

    cached_job, cached_res = _find_cached()
    if cached_job and cached_res:
        out = {"job": cached_job, "result": cached_res, "cache": {"hit": True}}
        _log("calculate_volume_weighted_average_price_strategy", "ok", cred.get("id"), meta={"cache_hit": True})
        return out

    # new job
    jid = "cijob_" + hashlib.sha256((pair["id"] + "|vwap|" + now + "|" + str(time.time())).encode("utf-8")).hexdigest()[:24].upper()
    job = {
        "id": jid,
        "indicator_id": idef["id"],
        "pair_id": pair["id"],
        "interval": use_interval,
        "candle_limit": use_limit,
        "input_start_time": start_dt.isoformat() if start_dt else None,
        "input_end_time": end_dt.isoformat() if end_dt else None,
        "request_fingerprint": fp,
        "cache_hit": False,
        "status": "queued",
        "queued_at": now,
        "started_at": None,
        "finished_at": None,
        "error_code": None,
        "error_message": None,
        "binance_request_count": 0,
        "compute_time_ms": None,
        "created_at": now,
        "updated_at": now,
    }
    jobs.append(job)
    try:
        _save("computation_jobs.json", jobs)
    except Exception:
        pass

    job["status"] = "running"
    job["started_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
    job["updated_at"] = job["started_at"]
    for i in range(len(jobs)):
        if jobs[i].get("id") == jid:
            jobs[i] = job
            break
    try:
        _save("computation_jobs.json", jobs)
    except Exception:
        pass

    candles = _load("ohlcv_candles.json")
    scoped = []
    for c in candles:
        if c.get("pair_id") != pair["id"] or c.get("interval") != use_interval:
            continue
        ot = _parse_dt(c.get("open_time")) if isinstance(c.get("open_time"), str) else None
        if ot is None:
            continue
        if start_dt and ot < start_dt:
            continue
        if end_dt and ot > end_dt:
            continue
        scoped.append((ot, c))
    scoped.sort(key=lambda x: x[0])
    if len(scoped) > use_limit:
        scoped = scoped[-use_limit:]
    candle_rows = [c for _, c in scoped]

    min_req = int(idef.get("min_lookback_candles") or 1)
    if len(candle_rows) < min_req:
        fin = datetime.datetime.now(datetime.timezone.utc).isoformat()
        job["status"] = "failed"
        job["finished_at"] = fin
        job["updated_at"] = fin
        job["compute_time_ms"] = 0
        job["error_code"] = "INSUFFICIENT_DATA"
        job["error_message"] = f"Need at least {min_req} candles, found {len(candle_rows)}"
        for i in range(len(jobs)):
            if jobs[i].get("id") == jid:
                jobs[i] = job
                break
        try:
            _save("computation_jobs.json", jobs)
        except Exception:
            pass
        out = {"job": job, "result": None}
        _log("calculate_volume_weighted_average_price_strategy", "ok", cred.get("id"), meta={"cache_hit": False, "status": "failed", "error_code": "INSUFFICIENT_DATA"})
        return out

    ct0 = time.time()
    # VWAP across selected window using typical price * volume
    pv = 0.0
    vv = 0.0
    for c in candle_rows:
        high = float(c["high"]); low = float(c["low"]); close = float(c["close"])
        vol = float(c["volume"])
        typical = (high + low + close) / 3.0
        pv += typical * vol
        vv += vol
    vwap = pv / vv if vv != 0 else float(candle_rows[-1]["close"])
    last_close = float(candle_rows[-1]["close"])
    # Strategy signal: BUY if close > vwap, SELL if close < vwap, else HOLD
    if last_close > vwap:
        sig = 1
    elif last_close < vwap:
        sig = -1
    else:
        sig = 0
    compute_ms = int((time.time() - ct0) * 1000)

    fin = datetime.datetime.now(datetime.timezone.utc).isoformat()
    job["status"] = "succeeded"
    job["finished_at"] = fin
    job["updated_at"] = fin
    job["compute_time_ms"] = compute_ms
    job["binance_request_count"] = 0

    for i in range(len(jobs)):
        if jobs[i].get("id") == jid:
            jobs[i] = job
            break
    try:
        _save("computation_jobs.json", jobs)
    except Exception:
        pass

    ttl = int(idef.get("cache_ttl_seconds") or 0)
    expires_at = None
    if ttl > 0:
        expires_at = (datetime.datetime.now(datetime.timezone.utc) + datetime.timedelta(seconds=ttl)).isoformat()

    rid = "cires_" + hashlib.sha256((jid + "|result|" + fin).encode("utf-8")).hexdigest()[:24].upper()
    result_row = {
        "id": rid,
        "job_id": jid,
        "result_kind": "signal",
        "as_of_time": candle_rows[-1].get("close_time") or candle_rows[-1].get("open_time"),
        "value": float(sig),
        "signal": int(sig),
        "series": None,
        "multi_series": None,
        "metadata": {
            "vwap": vwap,
            "last_close": last_close,
            "interval": use_interval,
            "candles_used": len(candle_rows)
        },
        "expires_at": expires_at,
        "created_at": fin,
        "updated_at": fin
    }
    replaced = False
    for i in range(len(results)):
        if results[i].get("job_id") == jid:
            results[i] = result_row
            replaced = True
            break
    if not replaced:
        results.append(result_row)
    try:
        _save("computation_results.json", results)
    except Exception:
        pass

    out = {"job": job, "result": result_row, "cache": {"hit": False}}
    _log("calculate_volume_weighted_average_price_strategy", "ok", cred.get("id"), meta={"cache_hit": False})
    return out

def get_auth_context(api_key, **_extra):
    import json, os, datetime, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0416000" if __import__("os").path.isdir("./environment_mix/0416000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _ensure_logs():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            try:
                _save("request_logs.json", [])
            except Exception:
                pass

    def _log(endpoint, status, credential_id=None, meta=None):
        _ensure_logs()
        logs = _load("request_logs.json")
        latency_ms = int((time.time() - t0) * 1000)
        row = {
            "id": "req_" + hashlib.sha256((endpoint + "|" + now + "|" + str(time.time())).encode("utf-8")).hexdigest()[:24],
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "latency_ms": latency_ms,
            "ts": datetime.datetime.now(datetime.timezone.utc).isoformat(),
        }
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        try:
            _save("request_logs.json", logs)
        except Exception:
            pass

    if not isinstance(api_key, str) or not api_key.strip():
        e = _err("VALIDATION_ERROR", "api_key must be a non-empty string")
        _log("get_auth_context", "error", meta={"code": e["error"]["code"]})
        return e

    creds = _load("api_keys.json")
    cred = None
    for c in creds:
        if c.get("id") == api_key or c.get("api_key") == api_key or c.get("key") == api_key or c.get("value") == api_key:
            cred = c
            break
    if cred is None:
        e = _err("UNAUTHORIZED", "Invalid API key")
        _log("get_auth_context", "error", meta={"code": e["error"]["code"]})
        return e

    # Quota/rate: infer from request_logs if present; otherwise report best-effort.
    _ensure_logs()
    logs = _load("request_logs.json")
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    one_min_ago = now_dt - datetime.timedelta(seconds=60)
    one_day_ago = now_dt - datetime.timedelta(days=1)

    def _parse_ts(s):
        if not isinstance(s, str):
            return None
        try:
            ss = s
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    per_min = 0
    per_day = 0
    for r in logs:
        if r.get("credential_id") != cred.get("id"):
            continue
        ts = _parse_ts(r.get("ts"))
        if ts is None:
            continue
        if ts >= one_min_ago:
            per_min += 1
        if ts >= one_day_ago:
            per_day += 1

    ctx = {
        "credential": {k: v for k, v in cred.items() if k not in ("secret", "hashed_secret", "ciphertext")},
        "scopes": cred.get("scopes") or ["read", "compute"],
        "usage": {
            "requests_last_60s": per_min,
            "requests_last_24h": per_day
        },
        "limits": {
            "rate_limit_per_60s": cred.get("rate_limit_per_60s"),
            "quota_per_24h": cred.get("quota_per_24h")
        },
        "now": now
    }

    _log("get_auth_context", "ok", cred.get("id"))
    return ctx

