        e = _err("VALIDATION_ERROR", "page must be an integer >= 1")
        _log("list_trading_pairs", "error", cred.get("id"), meta={"code": e["error"]["code"]})
        return e
    if not isinstance(page_size, int) or page_size < 1 or page_size > 200:
