        _log("list_trading_pairs", "error", cred.get("id"), meta={"code": e["error"]["code"]})
        return e

    rows = _load("trading_pairs.json")
    q = symbol_query.strip().upper() if isinstance(symbol_query, str) else None
    ba = base_asset.strip().upper() if isinstance(base_asset, str) else None
    qa = quote_asset.strip().upper() if isinstance(quote_asset, str) else None

    out_rows = []
    for r in rows:
        if exchange is not None and r.get("exchange") != exchange:
            continue
        if status is not None and r.get("status") != status:
            continue
        if ba is not None and (r.get("base_asset") or "").upper() != ba:
            continue
        if qa is not None and (r.get("quote_asset") or "").upper() != qa:
            continue
        if q is not None:
            sym = (r.get("symbol") or "").upper()
            if q not in sym:
                continue
        out_rows.append(r)

    out_rows.sort(key=lambda x: (x.get("symbol") or ""))

    total = len(out_rows)
    start = (page - 1) * page_size
    end = start + page_size
    page_items = out_rows[start:end]
    has_more = end < total

    resp = {
        "data": page_items,
        "pagination": {
