            logs.append({
                "id": f"req_{dt.strftime('%Y%m%d%H%M%S%f')}",
                "endpoint": endpoint,
                "credential": credential,
                "status": status_code,
                "error_code": error_code,
                "latency_ms": latency_ms,
                "timestamp": dt.replace(microsecond=0).isoformat() + "Z"
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _authenticate(api_key_value):
        if not isinstance(api_key_value, str) or not api_key_value.strip():
            return None
        keys = _load("api_keys.json")
        if not isinstance(keys, list) or len(keys) == 0:
            return {"id": api_key_value, "value": api_key_value}
        for k in keys:
            if not isinstance(k, dict):
                continue
            if k.get("value") == api_key_value or k.get("id") == api_key_value:
                if "is_active" in k and k.get("is_active") is False:
                    continue
                if "status" in k and isinstance(k.get("status"), str) and k.get("status") not in ("active", "enabled"):
                    continue
                return k
        return None

    # Validate inputs
    allowed = {"active", "disabled", "delisted"}
    if not isinstance(api_key, str) or not api_key.strip():
        _log("update_trading_pair_status", None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(id, str) or not id.strip():
        _log("update_trading_pair_status", api_key, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "id must be a non-empty string")
    if not isinstance(status, str) or status not in allowed:
        _log("update_trading_pair_status", api_key, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status must be one of: active, disabled, delisted")

    cred_row = _authenticate(api_key)
    if cred_row is None:
        _log("update_trading_pair_status", api_key, 401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Invalid API key")

    pairs = _load("trading_pairs.json")
    if not isinstance(pairs, list):
        pairs = []

    idx = None
    for i, r in enumerate(pairs):
        if isinstance(r, dict) and r.get("id") == id:
            idx = i
            break
    if idx is None:
        _log("update_trading_pair_status", cred_row.get("id", api_key), 404, "NOT_FOUND")
        return _err("NOT_FOUND", "Trading pair not found", id=id)

    current = pairs[idx].get("status")
    if current == status:
        _log("update_trading_pair_status", cred_row.get("id", api_key), 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status is unchanged")

    transitions = {
        "active": {"disabled", "delisted"},
        "disabled": {"active", "delisted"},
        "delisted": set()
    }
    if current not in transitions:
        _log("update_trading_pair_status", cred_row.get("id", api_key), 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Current trading pair status is invalid", current_status=current)

    if status not in transitions[current]:
        _log("update_trading_pair_status", cred_row.get("id", api_key), 400, "VALIDATION_ERROR")
        return _err(
            "VALIDATION_ERROR",
            "Transition not allowed",
            from_status=current,
            to_status=status
        )

    now = _iso_now()
    pairs[idx]["status"] = status
    pairs[idx]["updated_at"] = now
    _save("trading_pairs.json", pairs)

    _log("update_trading_pair_status", cred_row.get("id", api_key), 200, None)
    return {"trading_pair": pairs[idx]}

