def cancel_computation_job(api_key, id, reason=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0416000" if __import__("os").path.isdir("./environment_mix/0416000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.utcnow()

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, credential, status_code, error_code=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            dt = datetime.datetime.utcnow()
            latency_ms = int((dt - t0).total_seconds() * 1000)
            logs.append({
                "id": f"req_{dt.strftime('%Y%m%d%H%M%S%f')}",
                "endpoint": endpoint,
                "credential": credential,
                "status": status_code,
                "error_code": error_code,
                "latency_ms": latency_ms,
                "timestamp": dt.replace(microsecond=0).isoformat() + "Z"
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _authenticate(api_key_value):
        if not isinstance(api_key_value, str) or not api_key_value.strip():
            return None
        keys = _load("api_keys.json")
        if not isinstance(keys, list) or len(keys) == 0:
            return {"id": api_key_value, "value": api_key_value}
        for k in keys:
            if not isinstance(k, dict):
                continue
            if k.get("value") == api_key_value or k.get("id") == api_key_value:
                if "is_active" in k and k.get("is_active") is False:
                    continue
                if "status" in k and isinstance(k.get("status"), str) and k.get("status") not in ("active", "enabled"):
                    continue
                return k
        return None

    # Validate
    if not isinstance(api_key, str) or not api_key.strip():
        _log("cancel_computation_job", None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(id, str) or not id.strip():
        _log("cancel_computation_job", api_key, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "id must be a non-empty string")
    if reason is not None and not isinstance(reason, str):
        _log("cancel_computation_job", api_key, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "reason must be a string when provided")

    cred_row = _authenticate(api_key)
    if cred_row is None:
        _log("cancel_computation_job", api_key, 401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Invalid API key")

    jobs = _load("computation_jobs.json")
    if not isinstance(jobs, list):
        jobs = []

    idx = None
    for i, j in enumerate(jobs):
        if isinstance(j, dict) and j.get("id") == id:
            idx = i
            break
    if idx is None:
        _log("cancel_computation_job", cred_row.get("id", api_key), 404, "NOT_FOUND")
        return _err("NOT_FOUND", "Computation job not found", id=id)

    job = jobs[idx]
    current = job.get("status")
    transitions = {
        "queued": {"running", "cancelled"},
        "running": {"succeeded", "failed", "cancelled"},
        "succeeded": set(),
        "failed": set(),
        "cancelled": set()
    }

    if current not in transitions:
        _log("cancel_computation_job", cred_row.get("id", api_key), 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Job has invalid current status", current_status=current)

    if current in ("succeeded", "failed", "cancelled"):
        _log("cancel_computation_job", cred_row.get("id", api_key), 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Job is already terminal and cannot be cancelled", status=current)

    if "cancelled" not in transitions[current]:
        _log("cancel_computation_job", cred_row.get("id", api_key), 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Transition to cancelled is not allowed", from_status=current, to_status="cancelled")

    now = _iso_now()
    job["status"] = "cancelled"
    job["finished_at"] = now
    job["updated_at"] = now
    if reason is not None and reason.strip():
        # No schema field for cancellation reason; store in error_message for auditability.
        job["error_code"] = job.get("error_code") or "CANCELLED"
        job["error_message"] = reason.strip()
    else:
        job["error_code"] = job.get("error_code") or "CANCELLED"
        job["error_message"] = job.get("error_message") or "Job cancelled"

    jobs[idx] = job
    _save("computation_jobs.json", jobs)

    _log("cancel_computation_job", cred_row.get("id", api_key), 200, None)
    return {"computation_job": job}
